        // 추천: 트리거별 흑자 보장 가드+TP/SL
        Console.WriteLine();
        Console.WriteLine("=== 흑자 가능 조합만 (PnL > 0, n >= 30) ===");
        foreach (var r in results.Where(r => r.pnl > 0 && r.n >= 30).OrderByDescending(r => r.avg))
