    {
        Console.WriteLine("=================================================================");
        Console.WriteLine("  v5.20.8 REDESIGN BACKTEST (chart, 30 syms × 14 days)");
        Console.WriteLine("  진단 기반: Lorentzian 제거 / EMA20↑ + RSI<70 + ATR 0.7~1.5%");
