        else
            foreach (var r in profitable)
                Console.WriteLine($"  ✅ {r.gate,-40} | {r.tp,-22} | n={r.n}, WR={r.wr:F2}%, PnL=${r.pnl:F2} ({r.roi:F2}%)");

        Console.WriteLine();
        Console.WriteLine("=== TOP 5 손실 조합 ===");
        foreach (var r in results.OrderBy(r => r.pnl).Take(5))
