                    if (kl[i].OpenTime < since) continue;
                    if (kl[i].OpenTime < nextSlotFreeUtc) continue;
                    if (!ShouldEnterGoldenV2(kl, i)) continue;
                    IsGoldenTime(kl[i].OpenTime, out _, out DateTime sessionStart);
