                    decimal pctNet = pctRaw - (decimal)(feeRate * 2m * 100m) - (slippagePct * 2m);
                    totalPnl += notional * pctNet / 100m;
                    n++;
                    if (kind == "SL") sl_++;
                    else if (kind.StartsWith("TP1")) tp_++;
                    else force++;
                    nextSlotFreeUtc = sessionStart.AddMinutes(20);
                }
            }
            return (totalPnl, n, sl_, tp_, force);
        }

