        Console.WriteLine();
        Console.WriteLine($"{"기간",-7} {"카테",-6} {"진입",6} {"SL",5} {"TP1+Tr",7} {"중립",5} {"타임",5} {"PnL",10} {"ROI(시드$400)",16}");
