                    for (int e = j + 1; e < kl.Count && e <= j + maxHold; e++) if (sig[e] == -1) { ei = e; break; }
                    decimal net = (kl[ei].ClosePrice - entry) / entry - cost; decimal pnl = net * lev * 100m;
