            double e12 = (double)kl[0].ClosePrice, e26 = e12, sg9 = 0; bool s9 = false;
            for (int j = 1; j < n; j++) { double c = (double)kl[j].ClosePrice; e12 += (c - e12) * (2.0 / 13); e26 += (c - e26) * (2.0 / 27); double md = e12 - e26; if (!s9) { sg9 = md; s9 = true; } else sg9 += (md - sg9) * (2.0 / 10); macdH[j] = md - sg9; }
            for (int j = 200; j < n; j++) { ema20[j] = CalcEMA(kl, j, 20); ema50[j] = CalcEMA(kl, j, 50); ema200[j] = CalcEMA(kl, j, 200); }
            var engine = new LorentzianAnnEngine(sym, neighborsCount: K, maxBarsBack: 2000, featureCount: LorentzianFeatures.FeatureCount);
            var sg = new int[n];
            for (int j = 65; j < n; j++) { int s = j - 5; if (feats[s] != null) engine.AddSample(feats[s], labels[s]); if (feats[j] == null) continue; var p = engine.Predict(feats[j]); if (!p.IsReady || p.K == 0) continue; sg[j] = p.Prediction > 0 ? 1 : (p.Prediction < 0 ? -1 : 0); }
            var busy = new int[C]; for (int c = 0; c < C; c++) busy[c] = -1;
            for (int j = 250; j < n - 1; j++)
            {
                if (sg[j] != 1) continue;
                double c0 = (double)kl[j].ClosePrice;
                if (!(c0 > ema20[j] && c0 > ema200[j])) continue;
                if (!(mkUp.TryGetValue(kl[j].OpenTime, out var bu) && bu)) continue;
                bool slopeUp = j >= 6 && ema20[j] > ema20[j - 6];
                bool align = ema20[j] > ema50[j] && ema50[j] > ema200[j];
                double hhN = 0, hhP = 0; for (int q = j - 5; q <= j; q++) if (q >= 0 && (double)kl[q].HighPrice > hhN) hhN = (double)kl[q].HighPrice; for (int q = j - 11; q <= j - 6; q++) if (q >= 0 && (double)kl[q].HighPrice > hhP) hhP = (double)kl[q].HighPrice;
                bool hh = hhN > hhP; bool macdPos = macdH[j] > 0;
                if (!(slopeUp && align && hh && macdPos)) continue;               // F 진입
                // 4h 전봉 양봉 (1h→4h 블록, UTC 4h경계): 현재 블록 직전 완성 4h봉
                int off = kl[j].OpenTime.Hour % 4; int bs = j - off;              // 현재 4h블록 시작 1h인덱스
                if (bs - 4 < 0) continue;
                bool prev4hBull = (double)kl[bs - 1].ClosePrice > (double)kl[bs - 4].OpenPrice;
                if (!prev4hBull) continue;                                        // 4h 전봉 음봉이면 진입 금지
                if (kl[j + 1].OpenPrice <= 0) continue;
                decimal entry = kl[j + 1].OpenPrice;
                for (int c = 0; c < C; c++)
                {
                    if (j <= busy[c]) continue;
                    decimal sl = c == 2 || c == 4 ? entry * 0.98m : entry * 0.97m;   // SL2 or SL3
                    decimal tp4 = entry * 1.04m; decimal net = 0m; bool done = false; int ei = Math.Min(n - 1, j + maxHold);
                    if (c == 3) // 트레일
                    {
                        decimal peak = entry, stop = entry * 0.97m; bool tp1 = false; decimal remain = 1m, real = 0m;
                        for (int e = j + 1; e < n && e <= j + maxHold; e++) { if (kl[e].HighPrice > peak) peak = kl[e].HighPrice; if (kl[e].LowPrice <= stop) { real += remain * ((stop - entry) / entry); remain = 0; ei = e; done = true; break; } if (!tp1 && kl[e].HighPrice >= entry * 1.03m) { real += 0.5m * 0.03m; remain = 0.5m; tp1 = true; if (stop < entry) stop = entry; } if (tp1) { decimal pg = (peak - entry) / entry; decimal ts = entry * (1m + pg - Math.Max(0.015m, 0.4m * pg)); if (ts > stop) stop = ts; } if (sg[e] == -1) { real += remain * ((kl[e].ClosePrice - entry) / entry); remain = 0; ei = e; done = true; break; } }
                        if (!done) real += remain * ((kl[ei].ClosePrice - entry) / entry); net = real - cost;
                    }
                    else
                    {
                        for (int e = j + 1; e < n && e <= j + maxHold; e++)
                        {
                            if (kl[e].LowPrice <= sl) { net = (sl - entry) / entry - cost; ei = e; done = true; break; }
                            if (c == 4 && kl[e].HighPrice >= tp4) { net = 0.04m - cost; ei = e; done = true; break; }
                            if ((c == 1 || c == 2) && (double)kl[e].ClosePrice < ema20[e]) { net = (kl[e].ClosePrice - entry) / entry - cost; ei = e; done = true; break; }   // EMA20 이탈 종가청산
                            if (sg[e] == -1) { net = (kl[e].ClosePrice - entry) / entry - cost; ei = e; done = true; break; }
                        }
                        if (!done) net = (kl[ei].ClosePrice - entry) / entry - cost;
                    }
                    busy[c] = ei;
                    candByCfg[c].Add((kl[j + 1].OpenTime, kl[ei].OpenTime, net * margin * lev));
                }
            }
        }
        Console.WriteLine($"\n=== 결과 (F진입+4h양봉, 6슬롯, ${margin}·{lev}x) ===");
        Console.WriteLine($"  {"청산방식",-26}{"진입",7}{"승률",8}{"총손익$",12}{"월평균%",9}");
        for (int c = 0; c < C; c++)
        {
            var cs = candByCfg[c]; cs.Sort((a, b) => a.ent.CompareTo(b.ent));
            var open = new List<DateTime>(); int tn = 0, tw = 0; decimal tp = 0m; var mset = new HashSet<string>();
            foreach (var t in cs) { open.RemoveAll(x => x <= t.ent); if (open.Count >= maxSlots) continue; open.Add(t.ex); tn++; if (t.pnl > 0) tw++; tp += t.pnl; mset.Add(t.ent.ToString("yyyy-MM")); }
            double mo = mset.Count > 0 ? (double)(tp / capital * 100m) / mset.Count : 0;
            Console.WriteLine($"  {exitNames[c],-26}{tn,7}{(tn > 0 ? 100.0 * tw / tn : 0),7:F1}%{tp,12:F2}{mo,8:F2}% {(tp > 0 ? "✅" : "❌")}");
        }
    }

    // --knn-worst5m : 개선로직(F진입+4h양봉+EMA20이탈청산) 최대손실 10건 → 5분봉 + 볼린저밴드 + 진입/청산 → JSON (5m 진입실패 진단).
    private static async Task RunKnnWorst5mAsync()
    {
        const int featureWindow = 500, maxHold = 96, K = 8, L = 8, pages = 20;
        const decimal cost = 0.0004m * 2m + 0.0005m;
        decimal lev = 10m, margin = 500m; int maxSlots = 6;
        var inv = System.Globalization.CultureInfo.InvariantCulture;
        var universe = new[] {
            "BTCUSDT","ETHUSDT","BNBUSDT","SOLUSDT","XRPUSDT","DOGEUSDT","ADAUSDT","TRXUSDT","AVAXUSDT","LINKUSDT",
            "DOTUSDT","LTCUSDT","BCHUSDT","ATOMUSDT","UNIUSDT","NEARUSDT","APTUSDT","ARBUSDT","OPUSDT","SUIUSDT",
            "INJUSDT","FILUSDT","XLMUSDT","AAVEUSDT","ICPUSDT","ETCUSDT","HBARUSDT","VETUSDT","ALGOUSDT","SEIUSDT" };
        Console.WriteLine("=== 개선로직 최대손실 10건 → 5m+BB 진단 ===");
        var btc = await FetchKlines1hAsync("BTCUSDT", pages);
        var mkUp = new Dictionary<DateTime, bool>();
        { double m = 2.0 / 201, e = (double)btc[0].ClosePrice; for (int j = 1; j < btc.Count; j++) { e = (double)btc[j].ClosePrice * m + e * (1 - m); if (j >= 200) mkUp[btc[j].OpenTime] = (double)btc[j].ClosePrice > e; } }
        var allCands = new List<(string sym, DateTime ent, DateTime ex, decimal pnl, double rsi, string macd)>();
        int idx = 0;
        foreach (var sym in universe)
        {
            idx++; Console.Write($"[{idx}/{universe.Length}] {sym} ");
            List<IBinanceKline> kl;
            try { kl = await FetchKlines1hAsync(sym, pages); } catch { Console.WriteLine("fail"); continue; }
            if (kl.Count < 800) { Console.WriteLine("skip"); continue; }
            int n = kl.Count; Console.WriteLine($"1h={n}");
            var feats = new float[n][];
            for (int j = 60; j < n; j++) { int ws = Math.Max(0, j - (featureWindow - 1)); feats[j] = LorentzianFeatures.Extract(kl.GetRange(ws, j - ws + 1))!; }
            var labels = new int[n];
            for (int j = L; j < n; j++) { decimal nc = kl[j].ClosePrice, pc = kl[j - L].ClosePrice; labels[j] = nc > pc ? 1 : (nc < pc ? -1 : 0); }
            var ema20 = new double[n]; var ema50 = new double[n]; var ema200 = new double[n]; var macdH = new double[n]; var rsi = new double[n];
            double e12 = (double)kl[0].ClosePrice, e26 = e12, sg9 = 0; bool s9 = false;
            for (int j = 1; j < n; j++) { double c = (double)kl[j].ClosePrice; e12 += (c - e12) * (2.0 / 13); e26 += (c - e26) * (2.0 / 27); double md = e12 - e26; if (!s9) { sg9 = md; s9 = true; } else sg9 += (md - sg9) * (2.0 / 10); macdH[j] = md - sg9; }
            for (int j = 200; j < n; j++) { ema20[j] = CalcEMA(kl, j, 20); ema50[j] = CalcEMA(kl, j, 50); ema200[j] = CalcEMA(kl, j, 200); rsi[j] = CalcRsi14(kl, j); }
            var engine = new LorentzianAnnEngine(sym, neighborsCount: K, maxBarsBack: 2000, featureCount: LorentzianFeatures.FeatureCount);
            var sg = new int[n];
            for (int j = 65; j < n; j++) { int s = j - 5; if (feats[s] != null) engine.AddSample(feats[s], labels[s]); if (feats[j] == null) continue; var p = engine.Predict(feats[j]); if (!p.IsReady || p.K == 0) continue; sg[j] = p.Prediction > 0 ? 1 : (p.Prediction < 0 ? -1 : 0); }
            int busy = -1;
            for (int j = 250; j < n - 1; j++)
            {
                if (j <= busy) continue;
                if (sg[j] != 1) continue;
                double c0 = (double)kl[j].ClosePrice;
                if (!(c0 > ema20[j] && c0 > ema200[j])) continue;
                if (!(mkUp.TryGetValue(kl[j].OpenTime, out var bu) && bu)) continue;
                bool slopeUp = j >= 6 && ema20[j] > ema20[j - 6];
                bool align = ema20[j] > ema50[j] && ema50[j] > ema200[j];
                double hhN = 0, hhP = 0; for (int q = j - 5; q <= j; q++) if (q >= 0 && (double)kl[q].HighPrice > hhN) hhN = (double)kl[q].HighPrice; for (int q = j - 11; q <= j - 6; q++) if (q >= 0 && (double)kl[q].HighPrice > hhP) hhP = (double)kl[q].HighPrice;
                if (!(slopeUp && align && hhN > hhP && macdH[j] > 0)) continue;
                int off = kl[j].OpenTime.Hour % 4; int bs = j - off; if (bs - 4 < 0) continue;
                if (!((double)kl[bs - 1].ClosePrice > (double)kl[bs - 4].OpenPrice)) continue;
                if (kl[j + 1].OpenPrice <= 0) continue;
                decimal entry = kl[j + 1].OpenPrice, sl = entry * 0.97m; decimal net = 0m; bool done = false; int ei = Math.Min(n - 1, j + maxHold);
                for (int e = j + 1; e < n && e <= j + maxHold; e++) { if (kl[e].LowPrice <= sl) { net = (sl - entry) / entry - cost; ei = e; done = true; break; } if ((double)kl[e].ClosePrice < ema20[e]) { net = (kl[e].ClosePrice - entry) / entry - cost; ei = e; done = true; break; } if (sg[e] == -1) { net = (kl[e].ClosePrice - entry) / entry - cost; ei = e; done = true; break; } }
                if (!done) net = (kl[ei].ClosePrice - entry) / entry - cost;
                busy = ei;
                allCands.Add((sym, kl[j + 1].OpenTime, kl[ei].OpenTime, net * margin * lev, rsi[j], macdH[j] >= 0 ? "+" : "-"));
            }
        }
        allCands.Sort((a, b) => a.ent.CompareTo(b.ent));
        var open = new List<DateTime>(); var taken = new List<(string sym, DateTime ent, DateTime ex, decimal pnl, double rsi, string macd)>();
        foreach (var c in allCands) { open.RemoveAll(x => x <= c.ent); if (open.Count >= maxSlots) continue; open.Add(c.ex); taken.Add(c); }
        var worst = taken.OrderBy(t => t.pnl).Take(10).ToList();
        Console.WriteLine($"\n최대손실 10건 → 5m+BB 페치...");

        var sb = new System.Text.StringBuilder(); sb.Append("[");
        for (int w = 0; w < worst.Count; w++)
        {
            var t = worst[w];
            long endMs = ((DateTimeOffset)t.ent.AddHours(8)).ToUnixTimeMilliseconds();
            var k5 = await FetchKlines5mWindowAsync(t.sym, endMs, 180);   // 진입±, 15h창
            if (k5.Count < 40) continue;
            // BB(20,2)
            int m5 = k5.Count; var bbU = new double[m5]; var bbM = new double[m5]; var bbL = new double[m5];
            for (int i = 19; i < m5; i++) { double s = 0; for (int q = i - 19; q <= i; q++) s += (double)k5[q].ClosePrice; double mean = s / 20; double sd = 0; for (int q = i - 19; q <= i; q++) { double d = (double)k5[q].ClosePrice - mean; sd += d * d; } sd = Math.Sqrt(sd / 20); bbM[i] = mean; bbU[i] = mean + 2 * sd; bbL[i] = mean - 2 * sd; }
            int entIdx = 0; for (int i = 0; i < m5; i++) { if (k5[i].OpenTime >= t.ent) { entIdx = i; break; } }
            int exIdx = m5 - 1; for (int i = entIdx; i < m5; i++) { if (k5[i].OpenTime >= t.ex) { exIdx = i; break; } }
            if (w > 0) sb.Append(",");
            sb.Append("{\"sym\":\"").Append(t.sym).Append("\",\"pnl\":").Append(t.pnl.ToString("F2", inv)).Append(",\"roe\":").Append(((double)t.pnl / (double)margin * 100).ToString("F0", inv))
              .Append(",\"entT\":\"").Append(t.ent.AddHours(9).ToString("MM-dd HH:mm")).Append("\",\"rsi\":").Append(t.rsi.ToString("F0", inv)).Append(",\"macd\":\"").Append(t.macd).Append("\"")
              .Append(",\"entIdx\":").Append(entIdx).Append(",\"exIdx\":").Append(exIdx).Append(",\"bars\":[");
            int from = Math.Max(19, entIdx - 60), to = Math.Min(m5 - 1, exIdx + 12);
            for (int b = from; b <= to; b++) { if (b > from) sb.Append(","); sb.Append("[").Append(((double)k5[b].OpenPrice).ToString("R", inv)).Append(",").Append(((double)k5[b].HighPrice).ToString("R", inv)).Append(",").Append(((double)k5[b].LowPrice).ToString("R", inv)).Append(",").Append(((double)k5[b].ClosePrice).ToString("R", inv)).Append(",").Append(bbU[b].ToString("R", inv)).Append(",").Append(bbM[b].ToString("R", inv)).Append(",").Append(bbL[b].ToString("R", inv)).Append("]"); }
            sb.Append("],\"entIdx0\":").Append(entIdx - from).Append(",\"exIdx0\":").Append(exIdx - from).Append("}");
            Console.Write($" {t.sym}");
        }
        sb.Append("]");
        System.IO.File.WriteAllText("knn-worst5m.json", sb.ToString());
        Console.WriteLine($"\n→ knn-worst5m.json 작성 완료");
    }

    // --knn-5mreclaim : 1h KNN F방향 + 5m EMA20(볼밴중심) 재돌파 확인 진입. "하락중 눌림오판 진입" 차단이 흑자로 돌리는지.
    private static async Task RunKnn5mReclaimAsync()
    {
        const int featureWindow = 500, K = 8, L = 8, pages1h = 20, pages5m = 40;   // 5m×1500×40≈208일
        const decimal cost = 0.0004m * 2m + 0.0005m, slPct = 0.03m;
        decimal lev = 10m, margin = 500m; int maxSlots = 6; decimal capital = margin * maxSlots; int maxHold5 = 288;  // 24h
        var universe = new[] {
            "BTCUSDT","ETHUSDT","BNBUSDT","SOLUSDT","XRPUSDT","DOGEUSDT","ADAUSDT","TRXUSDT","AVAXUSDT","LINKUSDT",
            "DOTUSDT","LTCUSDT","BCHUSDT","ATOMUSDT","UNIUSDT","NEARUSDT","APTUSDT","ARBUSDT","OPUSDT","SUIUSDT" };
        string[] names = { "A.5m양봉(현행)", "B.5m종가>EMA20", "C.5m EMA20 재돌파(cross-up)", "D.5m상승추세(EMA20위+기울기↑)" };
        int C2 = names.Length;
        Console.WriteLine($"=== 1h KNN F방향 + 5m EMA20재돌파 진입 (20종·${margin}·{lev}x, ~7개월) ===");
        var btc = await FetchKlines1hAsync("BTCUSDT", pages1h);
        var mkUp = new Dictionary<DateTime, bool>();
        { double m = 2.0 / 201, e = (double)btc[0].ClosePrice; for (int j = 1; j < btc.Count; j++) { e = (double)btc[j].ClosePrice * m + e * (1 - m); if (j >= 200) mkUp[btc[j].OpenTime] = (double)btc[j].ClosePrice > e; } }
        bool BtcBull(DateTime t) { var hk = new DateTime(t.Year, t.Month, t.Day, t.Hour, 0, 0, DateTimeKind.Utc).AddHours(-1); return mkUp.TryGetValue(hk, out var b) && b; }

        var candByCfg = new List<(DateTime ent, DateTime ex, decimal pnl)>[C2];
        for (int c = 0; c < C2; c++) candByCfg[c] = new List<(DateTime, DateTime, decimal)>();
        int idx = 0;
        foreach (var sym in universe)
        {
            idx++; Console.Write($"[{idx}/{universe.Length}] {sym} ");
            List<IBinanceKline> h1; List<IBinanceKline> k5;
            try { h1 = await FetchKlines1hAsync(sym, pages1h); k5 = await FetchKlines5mWindowFullAsync(sym, pages5m); } catch { Console.WriteLine("fail"); continue; }
            if (h1.Count < 500 || k5.Count < 500) { Console.WriteLine("skip"); continue; }
            int n = h1.Count; Console.WriteLine($"1h={n} 5m={k5.Count}");
            // 1h F 방향 계산
            var feats = new float[n][];
            for (int j = 60; j < n; j++) { int ws = Math.Max(0, j - (featureWindow - 1)); feats[j] = LorentzianFeatures.Extract(h1.GetRange(ws, j - ws + 1))!; }
            var labels = new int[n];
            for (int j = L; j < n; j++) { decimal nc = h1[j].ClosePrice, pc = h1[j - L].ClosePrice; labels[j] = nc > pc ? 1 : (nc < pc ? -1 : 0); }
            var ema20 = new double[n]; var ema50 = new double[n]; var ema200 = new double[n]; var macdH = new double[n];
            double e12 = (double)h1[0].ClosePrice, e26 = e12, sg9 = 0; bool s9 = false;
            for (int j = 1; j < n; j++) { double c = (double)h1[j].ClosePrice; e12 += (c - e12) * (2.0 / 13); e26 += (c - e26) * (2.0 / 27); double md = e12 - e26; if (!s9) { sg9 = md; s9 = true; } else sg9 += (md - sg9) * (2.0 / 10); macdH[j] = md - sg9; }
            for (int j = 200; j < n; j++) { ema20[j] = CalcEMA(h1, j, 20); ema50[j] = CalcEMA(h1, j, 50); ema200[j] = CalcEMA(h1, j, 200); }
            var engine = new LorentzianAnnEngine(sym, neighborsCount: K, maxBarsBack: 2000, featureCount: LorentzianFeatures.FeatureCount);
            var sg = new int[n];
            for (int j = 65; j < n; j++) { int s = j - 5; if (feats[s] != null) engine.AddSample(feats[s], labels[s]); if (feats[j] == null) continue; var p = engine.Predict(feats[j]); if (!p.IsReady || p.K == 0) continue; sg[j] = p.Prediction > 0 ? 1 : (p.Prediction < 0 ? -1 : 0); }
            var longFByHour = new Dictionary<DateTime, bool>();
            for (int j = 250; j < n; j++)
            {
                double c0 = (double)h1[j].ClosePrice;
                bool slopeUp = j >= 6 && ema20[j] > ema20[j - 6];
                bool align = ema20[j] > ema50[j] && ema50[j] > ema200[j];
                double hhN = 0, hhP = 0; for (int q = j - 5; q <= j; q++) if (q >= 0 && (double)h1[q].HighPrice > hhN) hhN = (double)h1[q].HighPrice; for (int q = j - 11; q <= j - 6; q++) if (q >= 0 && (double)h1[q].HighPrice > hhP) hhP = (double)h1[q].HighPrice;
                bool f = sg[j] == 1 && c0 > ema20[j] && c0 > ema200[j] && slopeUp && align && hhN > hhP && macdH[j] > 0 && BtcBull(h1[j].OpenTime);
                longFByHour[h1[j].OpenTime] = f;
            }
            bool Long1hAt(DateTime t) { var hk = new DateTime(t.Year, t.Month, t.Day, t.Hour, 0, 0, DateTimeKind.Utc).AddHours(-1); return longFByHour.TryGetValue(hk, out var b) && b; }
            // 5m EMA20
            int m5 = k5.Count; var e20_5 = new double[m5];
            { double e = (double)k5[0].ClosePrice; double kk = 2.0 / 21; e20_5[0] = e; for (int i = 1; i < m5; i++) { e = (double)k5[i].ClosePrice * kk + e * (1 - kk); e20_5[i] = e; } }
            var busy = new int[C2]; for (int c = 0; c < C2; c++) busy[c] = -1;
            for (int i = 30; i < m5 - 1; i++)
            {
                if (!Long1hAt(k5[i].OpenTime)) continue;
                double c = (double)k5[i].ClosePrice, o = (double)k5[i].OpenPrice, cp = (double)k5[i - 1].ClosePrice;
                bool bull = c > o;
                bool above = c > e20_5[i];
                bool crossUp = c > e20_5[i] && cp <= e20_5[i - 1];
                bool slope5Up = i >= 6 && e20_5[i] > e20_5[i - 6];              // 5m EMA20 기울기↑ = 5m 상승추세
                bool trend5 = above && slope5Up;                                // 5m 상승추세 (하락중 진입 차단)
                if (k5[i + 1].OpenPrice <= 0) continue;
                decimal entry = k5[i + 1].OpenPrice, slPx = entry * (1m - slPct);
                for (int cc = 0; cc < C2; cc++)
                {
                    if (i <= busy[cc]) continue;
                    bool ok = cc == 0 ? bull : cc == 1 ? above : cc == 2 ? crossUp : trend5;
                    if (!ok) continue;
                    decimal net = 0m; bool done = false; int ei = Math.Min(m5 - 1, i + maxHold5);
                    for (int e = i + 1; e < m5 && e <= i + maxHold5; e++) { if (k5[e].LowPrice <= slPx) { net = (slPx - entry) / entry - cost; ei = e; done = true; break; } if ((double)k5[e].ClosePrice < e20_5[e]) { net = (k5[e].ClosePrice - entry) / entry - cost; ei = e; done = true; break; } if (!Long1hAt(k5[e].OpenTime)) { net = (k5[e].ClosePrice - entry) / entry - cost; ei = e; done = true; break; } }
                    if (!done) net = (k5[ei].ClosePrice - entry) / entry - cost;
                    busy[cc] = ei;
                    candByCfg[cc].Add((k5[i + 1].OpenTime, k5[ei].OpenTime, net * margin * lev));
                }
            }
        }
        Console.WriteLine($"\n=== 결과 (6슬롯, ${margin}·{lev}x, ~7개월, 20종) ===");
        Console.WriteLine($"  {"5m 진입조건",-26}{"진입",7}{"승률",8}{"총손익$",12}{"월평균%",9}");
        for (int c = 0; c < C2; c++)
        {
            var cs = candByCfg[c]; cs.Sort((a, b) => a.ent.CompareTo(b.ent));
            var open = new List<DateTime>(); int tn = 0, tw = 0; decimal tp = 0m; var mset = new HashSet<string>();
            foreach (var t in cs) { open.RemoveAll(x => x <= t.ent); if (open.Count >= maxSlots) continue; open.Add(t.ex); tn++; if (t.pnl > 0) tw++; tp += t.pnl; mset.Add(t.ent.ToString("yyyy-MM")); }
            double mo = mset.Count > 0 ? (double)(tp / capital * 100m) / mset.Count : 0;
            Console.WriteLine($"  {names[c],-26}{tn,7}{(tn > 0 ? 100.0 * tw / tn : 0),7:F1}%{tp,12:F2}{mo,8:F2}% {(tp > 0 ? "✅" : "❌")}");
        }
        Console.WriteLine("\n  ▶ 5m EMA20 재돌파(C)가 '하락중 눌림오판'을 걸러 흑자로 돌리는지 확인.");
    }
    // 5m 전체(pages) 페치
    private static async Task<List<IBinanceKline>> FetchKlines5mWindowFullAsync(string sym, int pages)
    {
        var cached = LoadKlineCache($"{sym}_5m_{pages}"); if (cached != null && cached.Count > 0) return cached;
        var all = new List<List<IBinanceKline>>(); long endMs = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
        for (int p = 0; p < pages; p++) { var page = await FetchKlines5mWindowAsync(sym, endMs, BARS_PER_REQ); if (page == null || page.Count == 0) break; all.Insert(0, page); endMs = ((DateTimeOffset)page[0].OpenTime).ToUnixTimeMilliseconds() - 1; if (page.Count < BARS_PER_REQ) break; }
        var res = all.SelectMany(c => c).ToList(); if (res.Count > 0) SaveKlineCache($"{sym}_5m_{pages}", res); return res;
    }

    // --knn-bodytop : F진입 + [1h 마지막봉 몸통상단이 직전5봉 몸통상단 돌파] + [1h 저점깨짐 없음] 이 손실 줄이는지.
    private static async Task RunKnnBodyTopAsync()
    {
        const int featureWindow = 500, maxHold = 96, K = 8, L = 8, pages = 20;
        const decimal cost = 0.0004m * 2m + 0.0005m, slPct = 0.03m;
        decimal lev = 10m, margin = 500m; int maxSlots = 6; decimal capital = margin * maxSlots;
        var universe = new[] {
            "BTCUSDT","ETHUSDT","BNBUSDT","SOLUSDT","XRPUSDT","DOGEUSDT","ADAUSDT","TRXUSDT","AVAXUSDT","LINKUSDT",
            "DOTUSDT","LTCUSDT","BCHUSDT","ATOMUSDT","UNIUSDT","NEARUSDT","APTUSDT","ARBUSDT","OPUSDT","SUIUSDT",
            "INJUSDT","FILUSDT","XLMUSDT","AAVEUSDT","ICPUSDT","ETCUSDT","HBARUSDT","VETUSDT","ALGOUSDT","SEIUSDT" };
        // (이름, 몸통상단돌파, 저점깨짐없음(higher-low), EMA20이탈청산)
        var cfgs = new (string name, bool bodyTop, bool hlIntact, bool ema20Exit)[]
        {
            ("A.F진입(baseline)",          false, false, false),
            ("B.+몸통상단돌파",            true,  false, false),
            ("C.+저점깨짐없음(HL)",        false, true,  false),
            ("D.몸통상단+HL",              true,  true,  false),
            ("E.D+EMA20이탈청산",          true,  true,  true),
        };
        int C2 = cfgs.Length;
        Console.WriteLine($"=== F진입 + 몸통상단돌파 + 저점깨짐없음 (30종·1h·{maxSlots}·${margin}·{lev}x) ===");
        var btc = await FetchKlines1hAsync("BTCUSDT", pages);
        var mkUp = new Dictionary<DateTime, bool>();
        { double m = 2.0 / 201, e = (double)btc[0].ClosePrice; for (int j = 1; j < btc.Count; j++) { e = (double)btc[j].ClosePrice * m + e * (1 - m); if (j >= 200) mkUp[btc[j].OpenTime] = (double)btc[j].ClosePrice > e; } }
        var candByCfg = new List<(DateTime ent, DateTime ex, decimal pnl)>[C2];
        for (int c = 0; c < C2; c++) candByCfg[c] = new List<(DateTime, DateTime, decimal)>();
        int idx = 0;
        foreach (var sym in universe)
        {
            idx++; Console.Write($"[{idx}/{universe.Length}] {sym} ");
            List<IBinanceKline> kl;
            try { kl = await FetchKlines1hAsync(sym, pages); } catch { Console.WriteLine("fail"); continue; }
            if (kl.Count < 800) { Console.WriteLine("skip"); continue; }
            int n = kl.Count; Console.WriteLine($"1h={n}");
            var feats = new float[n][];
            for (int j = 60; j < n; j++) { int ws = Math.Max(0, j - (featureWindow - 1)); feats[j] = LorentzianFeatures.Extract(kl.GetRange(ws, j - ws + 1))!; }
            var labels = new int[n];
            for (int j = L; j < n; j++) { decimal nc = kl[j].ClosePrice, pc = kl[j - L].ClosePrice; labels[j] = nc > pc ? 1 : (nc < pc ? -1 : 0); }
            var ema20 = new double[n]; var ema50 = new double[n]; var ema200 = new double[n]; var macdH = new double[n];
            double e12 = (double)kl[0].ClosePrice, e26 = e12, sg9 = 0; bool s9 = false;
            for (int j = 1; j < n; j++) { double c = (double)kl[j].ClosePrice; e12 += (c - e12) * (2.0 / 13); e26 += (c - e26) * (2.0 / 27); double md = e12 - e26; if (!s9) { sg9 = md; s9 = true; } else sg9 += (md - sg9) * (2.0 / 10); macdH[j] = md - sg9; }
            for (int j = 200; j < n; j++) { ema20[j] = CalcEMA(kl, j, 20); ema50[j] = CalcEMA(kl, j, 50); ema200[j] = CalcEMA(kl, j, 200); }
            var engine = new LorentzianAnnEngine(sym, neighborsCount: K, maxBarsBack: 2000, featureCount: LorentzianFeatures.FeatureCount);
            var sg = new int[n];
            for (int j = 65; j < n; j++) { int s = j - 5; if (feats[s] != null) engine.AddSample(feats[s], labels[s]); if (feats[j] == null) continue; var p = engine.Predict(feats[j]); if (!p.IsReady || p.K == 0) continue; sg[j] = p.Prediction > 0 ? 1 : (p.Prediction < 0 ? -1 : 0); }
            var busy = new int[C2]; for (int c = 0; c < C2; c++) busy[c] = -1;
            for (int j = 250; j < n - 1; j++)
            {
                if (sg[j] != 1) continue;
                double c0 = (double)kl[j].ClosePrice;
                if (!(c0 > ema20[j] && c0 > ema200[j])) continue;
                if (!(mkUp.TryGetValue(kl[j].OpenTime, out var bu) && bu)) continue;
                bool slopeUp = j >= 6 && ema20[j] > ema20[j - 6];
                bool align = ema20[j] > ema50[j] && ema50[j] > ema200[j];
                double hhN = 0, hhP = 0; for (int q = j - 5; q <= j; q++) if (q >= 0 && (double)kl[q].HighPrice > hhN) hhN = (double)kl[q].HighPrice; for (int q = j - 11; q <= j - 6; q++) if (q >= 0 && (double)kl[q].HighPrice > hhP) hhP = (double)kl[q].HighPrice;
                if (!(slopeUp && align && hhN > hhP && macdH[j] > 0)) continue;    // F 진입
                // 몸통상단 돌파: 현재봉 몸통상단 >= 직전 5봉 몸통상단 최대
                double bodyNow = Math.Max((double)kl[j].OpenPrice, (double)kl[j].ClosePrice);
                double prevMaxBody = 0; for (int q = j - 5; q <= j - 1; q++) { double bt = Math.Max((double)kl[q].OpenPrice, (double)kl[q].ClosePrice); if (bt > prevMaxBody) prevMaxBody = bt; }
                bool bodyTopBreak = bodyNow >= prevMaxBody;
                // 저점 깨짐 없음(higher-low): 최근스윙저점 > 직전스윙저점 & 현재저점 > 최근스윙저점
                double swLoNow = 1e18, swLoPrev = 1e18; for (int q = j - 5; q <= j - 1; q++) if ((double)kl[q].LowPrice < swLoNow) swLoNow = (double)kl[q].LowPrice; for (int q = j - 11; q <= j - 6; q++) if ((double)kl[q].LowPrice < swLoPrev) swLoPrev = (double)kl[q].LowPrice;
                bool hlIntact = swLoNow > swLoPrev && (double)kl[j].LowPrice > swLoPrev;
                if (kl[j + 1].OpenPrice <= 0) continue;
                decimal entry = kl[j + 1].OpenPrice, slPx = entry * (1m - slPct);
                for (int c = 0; c < C2; c++)
                {
                    if (j <= busy[c]) continue;
                    var cf = cfgs[c];
                    if (cf.bodyTop && !bodyTopBreak) continue;
                    if (cf.hlIntact && !hlIntact) continue;
                    decimal net = 0m; bool done = false; int ei = Math.Min(n - 1, j + maxHold);
                    for (int e = j + 1; e < n && e <= j + maxHold; e++) { if (kl[e].LowPrice <= slPx) { net = (slPx - entry) / entry - cost; ei = e; done = true; break; } if (cf.ema20Exit && (double)kl[e].ClosePrice < ema20[e]) { net = (kl[e].ClosePrice - entry) / entry - cost; ei = e; done = true; break; } if (sg[e] == -1) { net = (kl[e].ClosePrice - entry) / entry - cost; ei = e; done = true; break; } }
                    if (!done) net = (kl[ei].ClosePrice - entry) / entry - cost;
                    busy[c] = ei;
                    candByCfg[c].Add((kl[j + 1].OpenTime, kl[ei].OpenTime, net * margin * lev));
                }
            }
        }
        Console.WriteLine($"\n=== 결과 (6슬롯, ${margin}·{lev}x, ~3.4년) ===");
        Console.WriteLine($"  {"조건",-24}{"진입",7}{"승률",8}{"총손익$",12}{"월평균%",9}");
        for (int c = 0; c < C2; c++)
        {
            var cs = candByCfg[c]; cs.Sort((a, b) => a.ent.CompareTo(b.ent));
            var open = new List<DateTime>(); int tn = 0, tw = 0; decimal tp = 0m; var mset = new HashSet<string>();
            foreach (var t in cs) { open.RemoveAll(x => x <= t.ent); if (open.Count >= maxSlots) continue; open.Add(t.ex); tn++; if (t.pnl > 0) tw++; tp += t.pnl; mset.Add(t.ent.ToString("yyyy-MM")); }
            double mo = mset.Count > 0 ? (double)(tp / capital * 100m) / mset.Count : 0;
            Console.WriteLine($"  {cfgs[c].name,-24}{tn,7}{(tn > 0 ? 100.0 * tw / tn : 0),7:F1}%{tp,12:F2}{mo,8:F2}% {(tp > 0 ? "✅" : "❌")}");
        }
    }

    // --knn-fullspec : 사용자 완전스펙. KNN+1h방향(롱숏)+몸통상단돌파+꼬리음봉패스+이전봉음봉패스+5m12봉기울기.
    private static async Task RunKnnFullSpecAsync()
    {
        const int featureWindow = 500, maxHold = 96, K = 8, L = 8, pages1h = 20, pages5m = 40;
        const decimal cost = 0.0004m * 2m + 0.0005m, slPct = 0.03m;
        decimal lev = 10m, margin = 500m; int maxSlots = 6; decimal capital = margin * maxSlots;
        var universe = new[] {
            "BTCUSDT","ETHUSDT","BNBUSDT","SOLUSDT","XRPUSDT","DOGEUSDT","ADAUSDT","TRXUSDT","AVAXUSDT","LINKUSDT",
            "DOTUSDT","LTCUSDT","BCHUSDT","ATOMUSDT","UNIUSDT","NEARUSDT","APTUSDT","ARBUSDT","OPUSDT","SUIUSDT" };
        Console.WriteLine($"=== 완전스펙 KNN+1h방향(롱숏)+몸통상단+꼬리음봉+이전봉+5m기울기 (20종·${margin}·{lev}x) ===");
        var cands = new List<(DateTime ent, DateTime ex, decimal pnl, bool isShort)>();
        int idx = 0;
        foreach (var sym in universe)
        {
            idx++; Console.Write($"[{idx}/{universe.Length}] {sym} ");
            List<IBinanceKline> kl; List<IBinanceKline> k5;
            try { kl = await FetchKlines1hAsync(sym, pages1h); k5 = await FetchKlines5mWindowFullAsync(sym, pages5m); } catch { Console.WriteLine("fail"); continue; }
            if (kl.Count < 500 || k5.Count < 500) { Console.WriteLine("skip"); continue; }
            int n = kl.Count; Console.WriteLine($"1h={n} 5m={k5.Count}");
            var feats = new float[n][];
            for (int j = 60; j < n; j++) { int ws = Math.Max(0, j - (featureWindow - 1)); feats[j] = LorentzianFeatures.Extract(kl.GetRange(ws, j - ws + 1))!; }
            var labels = new int[n];
            for (int j = L; j < n; j++) { decimal nc = kl[j].ClosePrice, pc = kl[j - L].ClosePrice; labels[j] = nc > pc ? 1 : (nc < pc ? -1 : 0); }
            var ema20 = new double[n];
            for (int j = 20; j < n; j++) ema20[j] = CalcEMA(kl, j, 20);
            var engine = new LorentzianAnnEngine(sym, neighborsCount: K, maxBarsBack: 2000, featureCount: LorentzianFeatures.FeatureCount);
            var sg = new int[n];
            for (int j = 65; j < n; j++) { int s = j - 5; if (feats[s] != null) engine.AddSample(feats[s], labels[s]); if (feats[j] == null) continue; var p = engine.Predict(feats[j]); if (!p.IsReady || p.K == 0) continue; sg[j] = p.Prediction > 0 ? 1 : (p.Prediction < 0 ? -1 : 0); }
            // 5m 기울기 판정용 인덱스 포인터
            int p5 = 0;
            double Slope5At(DateTime t)   // t 이전 마지막 12개 5m 종가 기울기 (마지막-처음)
            {
                while (p5 + 1 < k5.Count && k5[p5 + 1].OpenTime < t) p5++;
                if (p5 < 12) return 0; return (double)(k5[p5].ClosePrice - k5[p5 - 11].ClosePrice);
            }
            int busy = -1;
            for (int j = 250; j < n - 1; j++)
            {
                if (j <= busy) continue;
                double o = (double)kl[j].OpenPrice, c = (double)kl[j].ClosePrice, h = (double)kl[j].HighPrice, lo = (double)kl[j].LowPrice;
                double body = Math.Abs(c - o), rng = h - lo, upWick = h - Math.Max(o, c), dnWick = Math.Min(o, c) - lo;
                bool up1h = c > ema20[j] && j >= 6 && ema20[j] > ema20[j - 6];
                bool dn1h = c < ema20[j] && j >= 6 && ema20[j] < ema20[j - 6];
                bool isShort;
                if (sg[j] == 1 && up1h) isShort = false; else if (sg[j] == -1 && dn1h) isShort = true; else continue;   // 1·2 KNN+1h방향
                // 3: 상승(롱)일때 꼬리>몸통 음봉 패스 / 숏이면 미러(양봉 꼬리김)
                if (!isShort) { if (c < o && (upWick + dnWick) > body) continue; } else { if (c > o && (upWick + dnWick) > body) continue; }
                // 4: 이전봉 음봉이면 롱 패스 / 숏은 이전봉 양봉이면 패스
                double pc = (double)kl[j - 1].ClosePrice, po = (double)kl[j - 1].OpenPrice;
                if (!isShort) { if (pc < po) continue; } else { if (pc > po) continue; }
                // 5: 몸통상단 돌파(롱) / 몸통하단 이탈(숏)
                if (!isShort) { double bt = Math.Max(o, c), mx = 0; for (int q = j - 5; q <= j - 1; q++) { double b2 = Math.Max((double)kl[q].OpenPrice, (double)kl[q].ClosePrice); if (b2 > mx) mx = b2; } if (bt < mx) continue; }
                else { double bb = Math.Min(o, c), mn = 1e18; for (int q = j - 5; q <= j - 1; q++) { double b2 = Math.Min((double)kl[q].OpenPrice, (double)kl[q].ClosePrice); if (b2 < mn) mn = b2; } if (bb > mn) continue; }
                // 6: 5m 12봉 기울기 (롱=상승, 숏=하락)
                double sl5 = Slope5At(kl[j + 1].OpenTime);
                if (!isShort) { if (sl5 <= 0) continue; } else { if (sl5 >= 0) continue; }
                if (kl[j + 1].OpenPrice <= 0) continue;
                decimal entry = kl[j + 1].OpenPrice; decimal net = 0m; bool done = false; int ei = Math.Min(n - 1, j + maxHold);
                if (!isShort)
                {
                    decimal slPx = entry * (1m - slPct);
                    for (int e = j + 1; e < n && e <= j + maxHold; e++) { if (kl[e].LowPrice <= slPx) { net = -slPct - cost; ei = e; done = true; break; } if (sg[e] == -1) { net = (kl[e].ClosePrice - entry) / entry - cost; ei = e; done = true; break; } }
                    if (!done) net = (kl[ei].ClosePrice - entry) / entry - cost;
                }
                else
                {
                    decimal slPx = entry * (1m + slPct);
                    for (int e = j + 1; e < n && e <= j + maxHold; e++) { if (kl[e].HighPrice >= slPx) { net = -slPct - cost; ei = e; done = true; break; } if (sg[e] == 1) { net = (entry - kl[e].ClosePrice) / entry - cost; ei = e; done = true; break; } }
                    if (!done) net = (entry - kl[ei].ClosePrice) / entry - cost;
                }
                busy = ei;
                cands.Add((kl[j + 1].OpenTime, kl[ei].OpenTime, net * margin * lev, isShort));
            }
        }
        cands.Sort((a, b) => a.ent.CompareTo(b.ent));
        var open = new List<DateTime>(); int tn = 0, tw = 0, ls = 0, lw = 0, ss = 0, sw = 0; decimal tp = 0m, lp = 0m, sp = 0m; var mset = new HashSet<string>();
        foreach (var t in cands) { open.RemoveAll(x => x <= t.ent); if (open.Count >= maxSlots) continue; open.Add(t.ex); tn++; if (t.pnl > 0) tw++; tp += t.pnl; mset.Add(t.ent.ToString("yyyy-MM")); if (t.isShort) { ss++; if (t.pnl > 0) sw++; sp += t.pnl; } else { ls++; if (t.pnl > 0) lw++; lp += t.pnl; } }
        Console.WriteLine($"\n=== 완전스펙 결과 (6슬롯, ${margin}·{lev}x, ~7개월, 20종) ===");
        Console.WriteLine($"  [전체] 진입 {tn} · 승률 {(tn > 0 ? 100.0 * tw / tn : 0):F1}% · 총손익 ${tp:F2} · 월평균 {(mset.Count > 0 ? (double)(tp / capital * 100m) / mset.Count : 0):F2}%");
        Console.WriteLine($"  [롱]   진입 {ls} · 승률 {(ls > 0 ? 100.0 * lw / ls : 0):F1}% · 손익 ${lp:F2}");
        Console.WriteLine($"  [숏]   진입 {ss} · 승률 {(ss > 0 ? 100.0 * sw / ss : 0):F1}% · 손익 ${sp:F2}");
    }

    // --knn-strong : 완전스펙 + (A)추세강도 임계로 약추세 제거 + (B)진입후 반전청산(EMA20 이탈+EMA하향전환 → SL 전 청산).
    //                strengthThr × reversalExit 스윕으로 두 효과를 분리 측정.
    private static async Task RunKnnStrongAsync()
    {
        const int featureWindow = 500, maxHold = 96, K = 8, L = 8, pages1h = 20, pages5m = 40;
        const decimal cost = 0.0004m * 2m + 0.0005m, slPct = 0.03m;
        decimal lev = 10m, margin = 500m; int maxSlots = 6; decimal capital = margin * maxSlots;
        var universe = new[] {
            "BTCUSDT","ETHUSDT","BNBUSDT","SOLUSDT","XRPUSDT","DOGEUSDT","ADAUSDT","TRXUSDT","AVAXUSDT","LINKUSDT",
            "DOTUSDT","LTCUSDT","BCHUSDT","ATOMUSDT","UNIUSDT","NEARUSDT","APTUSDT","ARBUSDT","OPUSDT","SUIUSDT" };
        // 스윕: 추세강도 임계(6봉 EMA20 변화율) × 반전청산 on/off
        double[] strengths = { 0.0, 0.003, 0.005, 0.008, 0.012 };
        bool[] revModes = { false, true };
        Console.WriteLine($"=== 강한추세+반전청산 스윕 (완전스펙, 20종·${margin}·{lev}x) ===");
        Console.WriteLine($"    A=추세강도임계(6봉 EMA20 변화율)  B=진입후 반전청산(종가<EMA20 & EMA하향)\n");

        // 각 심볼별로 시그널/피처를 1회만 계산 후 조합별로 재사용
        var symData = new List<(string sym, List<IBinanceKline> kl, int[] sg, double[] ema20)>();
        int idx = 0;
        foreach (var sym in universe)
        {
            idx++; Console.Write($"[{idx}/{universe.Length}] {sym} ");
            List<IBinanceKline> kl; List<IBinanceKline> k5;
            try { kl = await FetchKlines1hAsync(sym, pages1h); k5 = await FetchKlines5mWindowFullAsync(sym, pages5m); } catch { Console.WriteLine("fail"); continue; }
            if (kl.Count < 500 || k5.Count < 500) { Console.WriteLine("skip"); continue; }
            int n = kl.Count; Console.WriteLine($"1h={n} 5m={k5.Count}");
            var feats = new float[n][];
            for (int j = 60; j < n; j++) { int ws = Math.Max(0, j - (featureWindow - 1)); feats[j] = LorentzianFeatures.Extract(kl.GetRange(ws, j - ws + 1))!; }
            var labels = new int[n];
            for (int j = L; j < n; j++) { decimal nc = kl[j].ClosePrice, pc = kl[j - L].ClosePrice; labels[j] = nc > pc ? 1 : (nc < pc ? -1 : 0); }
            var ema20 = new double[n];
            for (int j = 20; j < n; j++) ema20[j] = CalcEMA(kl, j, 20);
            var engine = new LorentzianAnnEngine(sym, neighborsCount: K, maxBarsBack: 2000, featureCount: LorentzianFeatures.FeatureCount);
            var sg = new int[n];
            for (int j = 65; j < n; j++) { int s = j - 5; if (feats[s] != null) engine.AddSample(feats[s], labels[s]); if (feats[j] == null) continue; var p = engine.Predict(feats[j]); if (!p.IsReady || p.K == 0) continue; sg[j] = p.Prediction > 0 ? 1 : (p.Prediction < 0 ? -1 : 0); }
            symData.Add((sym, kl, sg, ema20));
        }
        Console.WriteLine();

        // 결과표 헤더
        Console.WriteLine($"  {"A강도",6} {"B반전",6} {"진입",5} {"승률%",7} {"총손익$",11} {"월평균%",8} {"롱WR%",7} {"숏WR%",7} {"SL청산",6} {"반전청산",7}");
        (double strength, bool rev, int tn, double wr, decimal tp, double mo, double lwr, double swr, int slHit, int revHit) best = default; decimal bestPnl = decimal.MinValue;
        foreach (double strThr in strengths)
        foreach (bool rev in revModes)
        {
            var cands = new List<(DateTime ent, DateTime ex, decimal pnl, bool isShort, int exitKind)>(); // exitKind: 0=maxhold,1=SL,2=KNN반전,3=EMA반전청산
            foreach (var (sym, kl, sg, ema20) in symData)
            {
                int n = kl.Count; int busy = -1;
                for (int j = 250; j < n - 1; j++)
                {
                    if (j <= busy) continue;
                    double o = (double)kl[j].OpenPrice, c = (double)kl[j].ClosePrice, h = (double)kl[j].HighPrice, lo = (double)kl[j].LowPrice;
                    double body = Math.Abs(c - o), upWick = h - Math.Max(o, c), dnWick = Math.Min(o, c) - lo;
                    if (j < 6) continue;
                    double slope6 = (ema20[j] - ema20[j - 6]) / ema20[j - 6];
                    bool up1h = c > ema20[j] && slope6 >= strThr;
                    bool dn1h = c < ema20[j] && slope6 <= -strThr;
                    bool isShort;
                    if (sg[j] == 1 && up1h) isShort = false; else if (sg[j] == -1 && dn1h) isShort = true; else continue;
                    if (!isShort) { if (c < o && (upWick + dnWick) > body) continue; } else { if (c > o && (upWick + dnWick) > body) continue; }
                    double pc = (double)kl[j - 1].ClosePrice, po = (double)kl[j - 1].OpenPrice;
                    if (!isShort) { if (pc < po) continue; } else { if (pc > po) continue; }
                    if (!isShort) { double bt = Math.Max(o, c), mx = 0; for (int q = j - 5; q <= j - 1; q++) { double b2 = Math.Max((double)kl[q].OpenPrice, (double)kl[q].ClosePrice); if (b2 > mx) mx = b2; } if (bt < mx) continue; }
                    else { double bb = Math.Min(o, c), mn = 1e18; for (int q = j - 5; q <= j - 1; q++) { double b2 = Math.Min((double)kl[q].OpenPrice, (double)kl[q].ClosePrice); if (b2 < mn) mn = b2; } if (bb > mn) continue; }
                    if (kl[j + 1].OpenPrice <= 0) continue;
                    decimal entry = kl[j + 1].OpenPrice; decimal net = 0m; bool done = false; int ei = Math.Min(n - 1, j + maxHold); int ek = 0;
                    if (!isShort)
                    {
                        decimal slPx = entry * (1m - slPct);
                        for (int e = j + 1; e < n && e <= j + maxHold; e++)
                        {
                            if (kl[e].LowPrice <= slPx) { net = -slPct - cost; ei = e; done = true; ek = 1; break; }
                            if (sg[e] == -1) { net = (kl[e].ClosePrice - entry) / entry - cost; ei = e; done = true; ek = 2; break; }
                            // B: 진입후 반전청산 — 1h종가 EMA20 하향이탈 + EMA20 자체 하향전환
                            if (rev && (double)kl[e].ClosePrice < ema20[e] && ema20[e] < ema20[e - 1]) { net = (kl[e].ClosePrice - entry) / entry - cost; ei = e; done = true; ek = 3; break; }
                        }
                        if (!done) net = (kl[ei].ClosePrice - entry) / entry - cost;
                    }
                    else
                    {
                        decimal slPx = entry * (1m + slPct);
                        for (int e = j + 1; e < n && e <= j + maxHold; e++)
                        {
                            if (kl[e].HighPrice >= slPx) { net = -slPct - cost; ei = e; done = true; ek = 1; break; }
                            if (sg[e] == 1) { net = (entry - kl[e].ClosePrice) / entry - cost; ei = e; done = true; ek = 2; break; }
                            if (rev && (double)kl[e].ClosePrice > ema20[e] && ema20[e] > ema20[e - 1]) { net = (entry - kl[e].ClosePrice) / entry - cost; ei = e; done = true; ek = 3; break; }
                        }
                        if (!done) net = (entry - kl[ei].ClosePrice) / entry - cost;
                    }
                    busy = ei;
                    cands.Add((kl[j + 1].OpenTime, kl[ei].OpenTime, net * margin * lev, isShort, ek));
                }
            }
            cands.Sort((a, b) => a.ent.CompareTo(b.ent));
            var open = new List<DateTime>(); int tn = 0, tw = 0, ls = 0, lw = 0, ss = 0, sw = 0, slHit = 0, revHit = 0; decimal tp = 0m; var mset = new HashSet<string>();
            foreach (var t in cands)
            {
                open.RemoveAll(x => x <= t.ent); if (open.Count >= maxSlots) continue; open.Add(t.ex);
                tn++; if (t.pnl > 0) tw++; tp += t.pnl; mset.Add(t.ent.ToString("yyyy-MM"));
                if (t.exitKind == 1) slHit++; else if (t.exitKind == 3) revHit++;
                if (t.isShort) { ss++; if (t.pnl > 0) sw++; } else { ls++; if (t.pnl > 0) lw++; }
            }
            double mo = mset.Count > 0 ? (double)(tp / capital * 100m) / mset.Count : 0;
            double lwr = ls > 0 ? 100.0 * lw / ls : 0, swr = ss > 0 ? 100.0 * sw / ss : 0;
            Console.WriteLine($"  {strThr * 100,5:F1}% {(rev ? "ON" : "off"),6} {tn,5} {(tn > 0 ? 100.0 * tw / tn : 0),7:F1} {tp,11:F2} {mo,8:F2} {lwr,7:F1} {swr,7:F1} {slHit,6} {revHit,7}");
            if (tp > bestPnl) { bestPnl = tp; best = (strThr, rev, tn, tn > 0 ? 100.0 * tw / tn : 0, tp, mo, lwr, swr, slHit, revHit); }
        }
        Console.WriteLine($"\n  ★최고: A강도 {best.strength * 100:F1}% · 반전청산 {(best.rev ? "ON" : "off")} · 진입 {best.tn} · 승률 {best.wr:F1}% · 총손익 ${best.tp:F2} · 월평균 {best.mo:F2}% (SL청산 {best.slHit} / 반전청산 {best.revHit})");
    }

    // --knn-structure : 완전스펙 진입 전부를 진입시점 구조(볼밴위치·EMA이격ATR·눌림깊이·추세강도)로 버킷팅 →
    //                   승자 vs 패자의 구조 차이를 찾는다. 덧대기 필터가 아니라 "이기는 진입 구조" 발굴용.
    private static async Task RunKnnStructureAsync()
    {
        const int featureWindow = 500, maxHold = 96, K = 8, L = 8, pages1h = 20;
        const decimal cost = 0.0004m * 2m + 0.0005m, slPct = 0.03m;
        decimal lev = 10m, margin = 500m;
        var universe = new[] {
            "BTCUSDT","ETHUSDT","BNBUSDT","SOLUSDT","XRPUSDT","DOGEUSDT","ADAUSDT","TRXUSDT","AVAXUSDT","LINKUSDT",
            "DOTUSDT","LTCUSDT","BCHUSDT","ATOMUSDT","UNIUSDT","NEARUSDT","APTUSDT","ARBUSDT","OPUSDT","SUIUSDT" };
        Console.WriteLine($"=== 진입구조 발굴: 승자 vs 패자 (완전6룰, 20종, 3.4년, ${margin}·{lev}x) ===\n");
        // 진입건: (isShort, pnl, bbPos, extAtr, slope6, pullDepth)
        var recs = new List<(bool isShort, decimal pnl, double bbPos, double extAtr, double slope6, double pull)>();
        int idx = 0;
        foreach (var sym in universe)
        {
            idx++; Console.Write($"[{idx}/{universe.Length}] {sym} ");
            List<IBinanceKline> kl;
            try { kl = await FetchKlines1hAsync(sym, pages1h); } catch { Console.WriteLine("fail"); continue; }
            if (kl.Count < 500) { Console.WriteLine("skip"); continue; }
            int n = kl.Count; Console.WriteLine($"1h={n}");
            var feats = new float[n][];
            for (int j = 60; j < n; j++) { int ws = Math.Max(0, j - (featureWindow - 1)); feats[j] = LorentzianFeatures.Extract(kl.GetRange(ws, j - ws + 1))!; }
            var labels = new int[n];
            for (int j = L; j < n; j++) { decimal nc = kl[j].ClosePrice, pc = kl[j - L].ClosePrice; labels[j] = nc > pc ? 1 : (nc < pc ? -1 : 0); }
            var ema20 = new double[n]; var atr = new double[n]; var bbUp = new double[n]; var bbLo = new double[n]; var bbMid = new double[n];
            for (int j = 20; j < n; j++) ema20[j] = CalcEMA(kl, j, 20);
            for (int j = 14; j < n; j++) { double tr = 0; for (int q = j - 13; q <= j; q++) { double h = (double)kl[q].HighPrice, l = (double)kl[q].LowPrice, pc = (double)kl[q - 1].ClosePrice; tr += Math.Max(h - l, Math.Max(Math.Abs(h - pc), Math.Abs(l - pc))); } atr[j] = tr / 14.0; }
            for (int j = 20; j < n; j++) { double sum = 0; for (int q = j - 19; q <= j; q++) sum += (double)kl[q].ClosePrice; double mid = sum / 20.0; double v = 0; for (int q = j - 19; q <= j; q++) { double dd = (double)kl[q].ClosePrice - mid; v += dd * dd; } double sd = Math.Sqrt(v / 20.0); bbMid[j] = mid; bbUp[j] = mid + 2 * sd; bbLo[j] = mid - 2 * sd; }
            var engine = new LorentzianAnnEngine(sym, neighborsCount: K, maxBarsBack: 2000, featureCount: LorentzianFeatures.FeatureCount);
            var sg = new int[n];
            for (int j = 65; j < n; j++) { int s = j - 5; if (feats[s] != null) engine.AddSample(feats[s], labels[s]); if (feats[j] == null) continue; var p = engine.Predict(feats[j]); if (!p.IsReady || p.K == 0) continue; sg[j] = p.Prediction > 0 ? 1 : (p.Prediction < 0 ? -1 : 0); }
            int busy = -1;
            for (int j = 250; j < n - 1; j++)
            {
                if (j <= busy) continue;
                double o = (double)kl[j].OpenPrice, c = (double)kl[j].ClosePrice, h = (double)kl[j].HighPrice, lo = (double)kl[j].LowPrice;
                double body = Math.Abs(c - o), upWick = h - Math.Max(o, c), dnWick = Math.Min(o, c) - lo;
                if (j < 6 || atr[j] <= 0 || bbUp[j] <= bbLo[j]) continue;
                bool up1h = c > ema20[j] && ema20[j] > ema20[j - 6];
                bool dn1h = c < ema20[j] && ema20[j] < ema20[j - 6];
                bool isShort;
                if (sg[j] == 1 && up1h) isShort = false; else if (sg[j] == -1 && dn1h) isShort = true; else continue;
                if (!isShort) { if (c < o && (upWick + dnWick) > body) continue; } else { if (c > o && (upWick + dnWick) > body) continue; }
                double pcl = (double)kl[j - 1].ClosePrice, po = (double)kl[j - 1].OpenPrice;
                if (!isShort) { if (pcl < po) continue; } else { if (pcl > po) continue; }
                if (!isShort) { double bt = Math.Max(o, c), mx = 0; for (int q = j - 5; q <= j - 1; q++) { double b2 = Math.Max((double)kl[q].OpenPrice, (double)kl[q].ClosePrice); if (b2 > mx) mx = b2; } if (bt < mx) continue; }
                else { double bb2 = Math.Min(o, c), mn = 1e18; for (int q = j - 5; q <= j - 1; q++) { double b2 = Math.Min((double)kl[q].OpenPrice, (double)kl[q].ClosePrice); if (b2 < mn) mn = b2; } if (bb2 > mn) continue; }
                if (kl[j + 1].OpenPrice <= 0) continue;
                // 구조 특징
                double bbPos = (c - bbLo[j]) / (bbUp[j] - bbLo[j]);
                double extAtr = (c - ema20[j]) / atr[j];       // EMA 위로 몇 ATR 이격(과열)
                double slope6 = (ema20[j] - ema20[j - 6]) / ema20[j - 6] * 100;
                double recentHi = 0, recentLo = 1e18; for (int q = j - 10; q <= j; q++) { if ((double)kl[q].HighPrice > recentHi) recentHi = (double)kl[q].HighPrice; if ((double)kl[q].LowPrice < recentLo) recentLo = (double)kl[q].LowPrice; }
                double pull = isShort ? (c - recentLo) / recentLo * 100 : (recentHi - c) / recentHi * 100;  // 최근 극값 대비 되돌림 깊이
                // 결과
                decimal entry = kl[j + 1].OpenPrice; decimal net = 0m; bool done = false; int ei = Math.Min(n - 1, j + maxHold);
                if (!isShort) { decimal slPx = entry * (1m - slPct); for (int e = j + 1; e < n && e <= j + maxHold; e++) { if (kl[e].LowPrice <= slPx) { net = -slPct - cost; ei = e; done = true; break; } if (sg[e] == -1) { net = (kl[e].ClosePrice - entry) / entry - cost; ei = e; done = true; break; } } if (!done) net = (kl[ei].ClosePrice - entry) / entry - cost; }
                else { decimal slPx = entry * (1m + slPct); for (int e = j + 1; e < n && e <= j + maxHold; e++) { if (kl[e].HighPrice >= slPx) { net = -slPct - cost; ei = e; done = true; break; } if (sg[e] == 1) { net = (entry - kl[e].ClosePrice) / entry - cost; ei = e; done = true; break; } } if (!done) net = (entry - kl[ei].ClosePrice) / entry - cost; }
                busy = ei;
                recs.Add((isShort, net * margin * lev, bbPos, extAtr, slope6, pull));
            }
        }
        Console.WriteLine($"\n총 진입 {recs.Count}건 (롱 {recs.Count(r => !r.isShort)} / 숏 {recs.Count(r => r.isShort)})\n");

        void Bucket(string title, Func<(bool isShort, decimal pnl, double bbPos, double extAtr, double slope6, double pull), double> sel, double[] edges, string fmt)
        {
            Console.WriteLine($"── {title} (롱만) ──");
            var L2 = recs.Where(r => !r.isShort).ToList();
            for (int b = 0; b <= edges.Length; b++)
            {
                double lo = b == 0 ? double.NegativeInfinity : edges[b - 1];
                double hi = b == edges.Length ? double.PositiveInfinity : edges[b];
                var g = L2.Where(r => sel(r) >= lo && sel(r) < hi).ToList();
                if (g.Count == 0) { continue; }
                int w = g.Count(r => r.pnl > 0); decimal sp = g.Sum(r => r.pnl);
                string lab = b == 0 ? $"<{edges[0]:0.##}" : b == edges.Length ? $">={edges[^1]:0.##}" : $"{edges[b - 1]:0.##}~{edges[b]:0.##}";
                Console.WriteLine($"   {lab,12}  n={g.Count,4}  승률 {100.0 * w / g.Count,5:F1}%  손익 ${sp,9:F0}  건당 ${sp / g.Count,6:F1}");
            }
            Console.WriteLine();
        }
        Bucket("볼밴 위치 bbPos (0=하단 1=상단)", r => r.bbPos, new[] { 0.2, 0.4, 0.6, 0.8 }, "F2");
        Bucket("EMA 이격 extAtr (ATR단위, 과열도)", r => r.extAtr, new[] { 0.0, 0.5, 1.0, 2.0 }, "F2");
        Bucket("추세강도 slope6 (6봉 EMA20 %)", r => r.slope6, new[] { 0.0, 0.3, 0.6, 1.2 }, "F2");
        Bucket("눌림깊이 pull (최근고점 대비 %)", r => r.pull, new[] { 0.0, 0.5, 1.5, 3.0 }, "F2");
    }

    // --knn-pullback : 몸통상단 돌파(꼭대기 추격) → 눌림목 진입으로 교체. 승자구조(1.5~3% 눌림·EMA근처·볼밴중하단) 적용.
    //                  KNN+1h추세방향은 유지. 진입 "위치"를 고점→눌림으로 이동. pull밴드×extCap 스윕.
    private static async Task RunKnnPullbackAsync()
    {
        const int featureWindow = 500, maxHold = 96, K = 8, L = 8, pages1h = 20;
        const decimal cost = 0.0004m * 2m + 0.0005m, slPct = 0.03m;
        decimal lev = 10m, margin = 500m; int maxSlots = 6; decimal capital = margin * maxSlots;
        var universe = new[] {
            "BTCUSDT","ETHUSDT","BNBUSDT","SOLUSDT","XRPUSDT","DOGEUSDT","ADAUSDT","TRXUSDT","AVAXUSDT","LINKUSDT",
            "DOTUSDT","LTCUSDT","BCHUSDT","ATOMUSDT","UNIUSDT","NEARUSDT","APTUSDT","ARBUSDT","OPUSDT","SUIUSDT" };
        Console.WriteLine($"=== 눌림목 진입 (몸통상단돌파 폐기) — 승자구조 적용 (20종·3.4년·${margin}·{lev}x) ===\n");
        // 심볼별 1회 계산
        var symData = new List<(string sym, List<IBinanceKline> kl, int[] sg, double[] ema20, double[] atr, double[] bbUp, double[] bbLo)>();
        int idx = 0;
        foreach (var sym in universe)
        {
            idx++; Console.Write($"[{idx}/{universe.Length}] {sym} ");
            List<IBinanceKline> kl;
            try { kl = await FetchKlines1hAsync(sym, pages1h); } catch { Console.WriteLine("fail"); continue; }
            if (kl.Count < 500) { Console.WriteLine("skip"); continue; }
            int n = kl.Count; Console.WriteLine($"1h={n}");
            var feats = new float[n][];
            for (int j = 60; j < n; j++) { int ws = Math.Max(0, j - (featureWindow - 1)); feats[j] = LorentzianFeatures.Extract(kl.GetRange(ws, j - ws + 1))!; }
            var labels = new int[n];
            for (int j = L; j < n; j++) { decimal nc = kl[j].ClosePrice, pc = kl[j - L].ClosePrice; labels[j] = nc > pc ? 1 : (nc < pc ? -1 : 0); }
            var ema20 = new double[n]; var atr = new double[n]; var bbUp = new double[n]; var bbLo = new double[n];
            for (int j = 20; j < n; j++) ema20[j] = CalcEMA(kl, j, 20);
            for (int j = 14; j < n; j++) { double tr = 0; for (int q = j - 13; q <= j; q++) { double h = (double)kl[q].HighPrice, l = (double)kl[q].LowPrice, pc = (double)kl[q - 1].ClosePrice; tr += Math.Max(h - l, Math.Max(Math.Abs(h - pc), Math.Abs(l - pc))); } atr[j] = tr / 14.0; }
            for (int j = 20; j < n; j++) { double sum = 0; for (int q = j - 19; q <= j; q++) sum += (double)kl[q].ClosePrice; double mid = sum / 20.0; double v = 0; for (int q = j - 19; q <= j; q++) { double dd = (double)kl[q].ClosePrice - mid; v += dd * dd; } double sd = Math.Sqrt(v / 20.0); bbUp[j] = mid + 2 * sd; bbLo[j] = mid - 2 * sd; }
            var engine = new LorentzianAnnEngine(sym, neighborsCount: K, maxBarsBack: 2000, featureCount: LorentzianFeatures.FeatureCount);
            var sg = new int[n];
            for (int j = 65; j < n; j++) { int s = j - 5; if (feats[s] != null) engine.AddSample(feats[s], labels[s]); if (feats[j] == null) continue; var p = engine.Predict(feats[j]); if (!p.IsReady || p.K == 0) continue; sg[j] = p.Prediction > 0 ? 1 : (p.Prediction < 0 ? -1 : 0); }
            symData.Add((sym, kl, sg, ema20, atr, bbUp, bbLo));
        }
        Console.WriteLine();
        Console.WriteLine($"  {"눌림밴드%",10} {"EMA이격Cap",9} {"진입",5} {"승률%",7} {"총손익$",11} {"월평균%",8} {"롱WR%",7} {"숏WR%",7}");
        (double pMin, double pMax, double extCap, decimal tp) best = default; decimal bestPnl = decimal.MinValue;
        // 눌림 밴드(min~max %) × EMA이격 상한(ATR)
        var bands = new (double lo, double hi)[] { (1.0, 3.0), (1.5, 4.0), (0.8, 2.5), (1.5, 3.0) };
        var extCaps = new[] { 0.5, 1.0, 1.5 };
        foreach (var (pMin, pMax) in bands)
        foreach (var extCap in extCaps)
        {
            var cands = new List<(DateTime ent, DateTime ex, decimal pnl, bool isShort)>();
            foreach (var (sym, kl, sg, ema20, atr, bbUp, bbLo) in symData)
            {
                int n = kl.Count; int busy = -1;
                for (int j = 250; j < n - 1; j++)
                {
                    if (j <= busy) continue;
                    double o = (double)kl[j].OpenPrice, c = (double)kl[j].ClosePrice, h = (double)kl[j].HighPrice, lo = (double)kl[j].LowPrice;
                    double body = Math.Abs(c - o), upWick = h - Math.Max(o, c), dnWick = Math.Min(o, c) - lo;
                    if (j < 6 || atr[j] <= 0 || bbUp[j] <= bbLo[j]) continue;
                    bool up1h = c > ema20[j] && ema20[j] > ema20[j - 6];
                    bool dn1h = c < ema20[j] && ema20[j] < ema20[j - 6];
                    bool isShort;
                    if (sg[j] == 1 && up1h) isShort = false; else if (sg[j] == -1 && dn1h) isShort = true; else continue;
                    // 현재봉이 되돌림 반전(롱=양봉으로 턴업, 숏=음봉으로 턴다운) + 긴꼬리 반전캔들 배제
                    if (!isShort) { if (c <= o) continue; if ((upWick + dnWick) > body * 1.5) continue; } else { if (c >= o) continue; if ((upWick + dnWick) > body * 1.5) continue; }
                    // 승자구조: 최근10봉 극값 대비 눌림/되돌림 pMin~pMax%
                    double recentHi = 0, recentLo = 1e18; for (int q = j - 10; q <= j; q++) { if ((double)kl[q].HighPrice > recentHi) recentHi = (double)kl[q].HighPrice; if ((double)kl[q].LowPrice < recentLo) recentLo = (double)kl[q].LowPrice; }
                    double pull = isShort ? (c - recentLo) / recentLo * 100 : (recentHi - c) / recentHi * 100;
                    if (pull < pMin || pull > pMax) continue;
                    // EMA 근처(과열 아님): |close-EMA| <= extCap*ATR
                    double extAtr = Math.Abs(c - ema20[j]) / atr[j];
                    if (extAtr > extCap) continue;
                    if (kl[j + 1].OpenPrice <= 0) continue;
                    decimal entry = kl[j + 1].OpenPrice; decimal net = 0m; bool done = false; int ei = Math.Min(n - 1, j + maxHold);
                    if (!isShort) { decimal slPx = entry * (1m - slPct); for (int e = j + 1; e < n && e <= j + maxHold; e++) { if (kl[e].LowPrice <= slPx) { net = -slPct - cost; ei = e; done = true; break; } if (sg[e] == -1) { net = (kl[e].ClosePrice - entry) / entry - cost; ei = e; done = true; break; } } if (!done) net = (kl[ei].ClosePrice - entry) / entry - cost; }
                    else { decimal slPx = entry * (1m + slPct); for (int e = j + 1; e < n && e <= j + maxHold; e++) { if (kl[e].HighPrice >= slPx) { net = -slPct - cost; ei = e; done = true; break; } if (sg[e] == 1) { net = (entry - kl[e].ClosePrice) / entry - cost; ei = e; done = true; break; } } if (!done) net = (entry - kl[ei].ClosePrice) / entry - cost; }
                    busy = ei;
                    cands.Add((kl[j + 1].OpenTime, kl[ei].OpenTime, net * margin * lev, isShort));
                }
            }
            cands.Sort((a, b) => a.ent.CompareTo(b.ent));
            var open = new List<DateTime>(); int tn = 0, tw = 0, ls = 0, lw = 0, ss = 0, sw = 0; decimal tp = 0m, winSum = 0m, lossSum = 0m; var mset = new HashSet<string>();
            foreach (var t in cands) { open.RemoveAll(x => x <= t.ent); if (open.Count >= maxSlots) continue; open.Add(t.ex); tn++; if (t.pnl > 0) { tw++; winSum += t.pnl; } else lossSum += t.pnl; tp += t.pnl; mset.Add(t.ent.ToString("yyyy-MM")); if (t.isShort) { ss++; if (t.pnl > 0) sw++; } else { ls++; if (t.pnl > 0) lw++; } }
            double mo = mset.Count > 0 ? (double)(tp / capital * 100m) / mset.Count : 0;
            decimal avgW = tw > 0 ? winSum / tw : 0m, avgL = (tn - tw) > 0 ? lossSum / (tn - tw) : 0m;
            Console.WriteLine($"  {pMin:F1}~{pMax:F1}%{"",3} {extCap,9:F1} {tn,5} {(tn > 0 ? 100.0 * tw / tn : 0),7:F1} {tp,11:F2} {mo,8:F2} {(ls > 0 ? 100.0 * lw / ls : 0),7:F1} {(ss > 0 ? 100.0 * sw / ss : 0),7:F1}  이익${avgW,6:F1} 손실${avgL,7:F1} 비{(avgL != 0 ? (double)(avgW / -avgL) : 0),4:F2}");
            if (tp > bestPnl) { bestPnl = tp; best = (pMin, pMax, extCap, tp); }
        }
        Console.WriteLine($"\n  ★최고: 눌림 {best.pMin:F1}~{best.pMax:F1}% · EMA이격 {best.extCap:F1}ATR · 총손익 ${best.tp:F2}");
    }

    // --trend-confluence : 방향 판단을 지표 합의로. EMA정배열·MACD방향·ADX/DI·RSI regime 4개가 상승/하락을 몇개 동의하는지로
    //                      방향을 정하고 그 방향으로 진입. 합의개수별 승률(=방향 정확도)을 본다. 차단필터 아님 — 방향판정 로직.
    private static async Task RunTrendConfluenceAsync()
    {
        const int featureWindow = 500, maxHold = 96, K = 8, L = 8, pages1h = 20;
        const decimal cost = 0.0004m * 2m + 0.0005m, slPct = 0.03m;
        decimal lev = 10m, margin = 500m; int maxSlots = 6; decimal capital = margin * maxSlots;
        var universe = new[] {
            "BTCUSDT","ETHUSDT","BNBUSDT","SOLUSDT","XRPUSDT","DOGEUSDT","ADAUSDT","TRXUSDT","AVAXUSDT","LINKUSDT",
            "DOTUSDT","LTCUSDT","BCHUSDT","ATOMUSDT","UNIUSDT","NEARUSDT","APTUSDT","ARBUSDT","OPUSDT","SUIUSDT" };
        Console.WriteLine($"=== 방향판정: 지표 합의(EMA정배열·MACD·ADX/DI·RSI) — 합의개수별 방향정확도 (20종·3.4년) ===\n");
        // (방향dir(+1/-1), 합의개수agree, knnAgree, pnl)
        var recs = new List<(int dir, int agree, bool knnAgree, decimal pnl)>();
        int idx = 0;
        foreach (var sym in universe)
        {
            idx++; Console.Write($"[{idx}/{universe.Length}] {sym} ");
            List<IBinanceKline> kl;
            try { kl = await FetchKlines1hAsync(sym, pages1h); } catch { Console.WriteLine("fail"); continue; }
            if (kl.Count < 500) { Console.WriteLine("skip"); continue; }
            int n = kl.Count; Console.WriteLine($"1h={n}");
            var feats = new float[n][];
            for (int j = 60; j < n; j++) { int ws = Math.Max(0, j - (featureWindow - 1)); feats[j] = LorentzianFeatures.Extract(kl.GetRange(ws, j - ws + 1))!; }
            var labels = new int[n];
            for (int j = L; j < n; j++) { decimal nc = kl[j].ClosePrice, pc = kl[j - L].ClosePrice; labels[j] = nc > pc ? 1 : (nc < pc ? -1 : 0); }
            // 지표들
            var ema20 = new double[n]; var ema50 = new double[n]; var ema200 = new double[n];
            for (int j = 20; j < n; j++) ema20[j] = CalcEMA(kl, j, 20);
            for (int j = 50; j < n; j++) ema50[j] = CalcEMA(kl, j, 50);
            for (int j = 200; j < n; j++) ema200[j] = CalcEMA(kl, j, 200);
            // MACD(12,26,9) 히스토그램
            var macdHist = new double[n]; { double e12 = 0, e26 = 0, sig = 0; double k12 = 2.0 / 13, k26 = 2.0 / 27, k9 = 2.0 / 10; for (int j = 0; j < n; j++) { double c = (double)kl[j].ClosePrice; if (j == 0) { e12 = c; e26 = c; } else { e12 = c * k12 + e12 * (1 - k12); e26 = c * k26 + e26 * (1 - k26); } double macd = e12 - e26; if (j == 0) sig = macd; else sig = macd * k9 + sig * (1 - k9); macdHist[j] = macd - sig; } }
            // ADX(14) + DI
            var adx = new double[n]; var pdi = new double[n]; var mdi = new double[n];
            { double atrS = 0, pdmS = 0, mdmS = 0, adxS = 0; int per = 14; for (int j = 1; j < n; j++) { double h = (double)kl[j].HighPrice, l = (double)kl[j].LowPrice, pc = (double)kl[j - 1].ClosePrice, ph = (double)kl[j - 1].HighPrice, pl = (double)kl[j - 1].LowPrice; double tr = Math.Max(h - l, Math.Max(Math.Abs(h - pc), Math.Abs(l - pc))); double up = h - ph, dn = pl - l; double pdm = (up > dn && up > 0) ? up : 0, mdm = (dn > up && dn > 0) ? dn : 0; if (j <= per) { atrS += tr; pdmS += pdm; mdmS += mdm; if (j == per) { } } else { atrS = atrS - atrS / per + tr; pdmS = pdmS - pdmS / per + pdm; mdmS = mdmS - mdmS / per + mdm; } if (j >= per && atrS > 0) { double pd = 100 * pdmS / atrS, md = 100 * mdmS / atrS; pdi[j] = pd; mdi[j] = md; double dx = (pd + md) > 0 ? 100 * Math.Abs(pd - md) / (pd + md) : 0; if (j <= per * 2) { adxS += dx; if (j == per * 2) adx[j] = adxS / per; } else { adx[j] = (adx[j - 1] * (per - 1) + dx) / per; } } } }
            // RSI(14)
            var rsi = new double[n]; { double ag = 0, al = 0; int per = 14; for (int j = 1; j < n; j++) { double ch = (double)(kl[j].ClosePrice - kl[j - 1].ClosePrice); double g = ch > 0 ? ch : 0, ls = ch < 0 ? -ch : 0; if (j <= per) { ag += g; al += ls; if (j == per) { ag /= per; al /= per; rsi[j] = al == 0 ? 100 : 100 - 100 / (1 + ag / al); } } else { ag = (ag * (per - 1) + g) / per; al = (al * (per - 1) + ls) / per; rsi[j] = al == 0 ? 100 : 100 - 100 / (1 + ag / al); } } }
            // KNN
            var engine = new LorentzianAnnEngine(sym, neighborsCount: K, maxBarsBack: 2000, featureCount: LorentzianFeatures.FeatureCount);
            var sg = new int[n];
            for (int j = 65; j < n; j++) { int s = j - 5; if (feats[s] != null) engine.AddSample(feats[s], labels[s]); if (feats[j] == null) continue; var p = engine.Predict(feats[j]); if (!p.IsReady || p.K == 0) continue; sg[j] = p.Prediction > 0 ? 1 : (p.Prediction < 0 ? -1 : 0); }
            int busy = -1;
            for (int j = 250; j < n - 1; j++)
            {
                if (j <= busy) continue;
                double c = (double)kl[j].ClosePrice;
                // 4개 지표 상승동의(+1)/하락동의(-1)
                int upVotes = 0, dnVotes = 0;
                // 1) EMA 정배열/역배열
                if (ema20[j] > ema50[j] && ema50[j] > ema200[j]) upVotes++; else if (ema20[j] < ema50[j] && ema50[j] < ema200[j]) dnVotes++;
                // 2) MACD 히스토그램 방향(부호+상승/하강)
                if (macdHist[j] > 0 && macdHist[j] > macdHist[j - 1]) upVotes++; else if (macdHist[j] < 0 && macdHist[j] < macdHist[j - 1]) dnVotes++;
                // 3) ADX 추세 + DI 방향
                if (adx[j] >= 20 && pdi[j] > mdi[j]) upVotes++; else if (adx[j] >= 20 && mdi[j] > pdi[j]) dnVotes++;
                // 4) RSI regime
                if (rsi[j] > 55) upVotes++; else if (rsi[j] < 45) dnVotes++;
                int dir; int agree;
                if (upVotes > dnVotes) { dir = 1; agree = upVotes; } else if (dnVotes > upVotes) { dir = -1; agree = dnVotes; } else continue; // 방향 무합의 → 진입안함
                bool isShort = dir < 0;
                bool knnAgree = sg[j] == dir;
                if (kl[j + 1].OpenPrice <= 0) continue;
                decimal entry = kl[j + 1].OpenPrice; decimal net = 0m; bool done = false; int ei = Math.Min(n - 1, j + maxHold);
                if (!isShort) { decimal slPx = entry * (1m - slPct); for (int e = j + 1; e < n && e <= j + maxHold; e++) { if (kl[e].LowPrice <= slPx) { net = -slPct - cost; ei = e; done = true; break; } if (sg[e] == -1) { net = (kl[e].ClosePrice - entry) / entry - cost; ei = e; done = true; break; } } if (!done) net = (kl[ei].ClosePrice - entry) / entry - cost; }
                else { decimal slPx = entry * (1m + slPct); for (int e = j + 1; e < n && e <= j + maxHold; e++) { if (kl[e].HighPrice >= slPx) { net = -slPct - cost; ei = e; done = true; break; } if (sg[e] == 1) { net = (entry - kl[e].ClosePrice) / entry - cost; ei = e; done = true; break; } } if (!done) net = (entry - kl[ei].ClosePrice) / entry - cost; }
                busy = ei;
                recs.Add((dir, agree, knnAgree, net * margin * lev));
            }
        }
        Console.WriteLine($"\n총 {recs.Count}건\n");
        Console.WriteLine("── 합의개수별 방향정확도(=승률) ──");
        Console.WriteLine($"  {"합의개수",8} {"진입",6} {"승률%",7} {"건당$",8} {"롱WR%",7} {"숏WR%",7}");
        for (int a = 1; a <= 4; a++)
        {
            var g = recs.Where(r => r.agree == a).ToList(); if (g.Count == 0) continue;
            int w = g.Count(r => r.pnl > 0); var lg = g.Where(r => r.dir > 0).ToList(); var sgv = g.Where(r => r.dir < 0).ToList();
            Console.WriteLine($"  {a,8} {g.Count,6} {100.0 * w / g.Count,7:F1} {(double)(g.Sum(r => r.pnl) / g.Count),8:F1} {(lg.Count > 0 ? 100.0 * lg.Count(r => r.pnl > 0) / lg.Count : 0),7:F1} {(sgv.Count > 0 ? 100.0 * sgv.Count(r => r.pnl > 0) / sgv.Count : 0),7:F1}");
        }
        Console.WriteLine("\n── 합의≥N + KNN동의 시 6슬롯 실전 백테 ──");
        Console.WriteLine($"  {"조건",14} {"진입",6} {"승률%",7} {"총손익$",11} {"월평균%",8}");
        foreach (var (minA, needKnn) in new[] { (2, false), (3, false), (3, true), (4, false), (4, true) })
        {
            var g = recs.Where(r => r.agree >= minA && (!needKnn || r.knnAgree)).ToList();
            if (g.Count == 0) continue;
            int w = g.Count(r => r.pnl > 0); decimal tp = g.Sum(r => r.pnl);
            // 근사 월평균(슬롯 미적용 총량 기준) — 방향정확도 비교가 목적
            Console.WriteLine($"  합의≥{minA}{(needKnn ? "+KNN" : "    ")}{"",4} {g.Count,6} {100.0 * w / g.Count,7:F1} {tp,11:F2} {(double)(tp / capital * 100m) / 40.0,8:F2}");
        }
    }

    // --knn-labeltest : 결정적 A/B — KNN 학습라벨 [과거]sign(close[j]-close[j-L]) vs [미래]sign(close[j+L]-close[j])
    //                   (미래는 룩어헤드 없이: 결과가 확정된 과거봉만 학습). 나머지 조건 100% 동일. 방향이 뒤집히는지 증명.
    private static async Task RunKnnLabelTestAsync()
    {
        const int featureWindow = 500, maxHold = 96, K = 8, L = 8, pages1h = 20;
        const decimal cost = 0.0004m * 2m + 0.0005m, slPct = 0.03m;
        decimal lev = 10m, margin = 500m; int maxSlots = 6; decimal capital = margin * maxSlots;
        var universe = new[] {
            "BTCUSDT","ETHUSDT","BNBUSDT","SOLUSDT","XRPUSDT","DOGEUSDT","ADAUSDT","TRXUSDT","AVAXUSDT","LINKUSDT",
            "DOTUSDT","LTCUSDT","BCHUSDT","ATOMUSDT","UNIUSDT","NEARUSDT","APTUSDT","ARBUSDT","OPUSDT","SUIUSDT" };
        Console.WriteLine($"=== KNN 라벨 A/B: [과거] vs [미래·룩어헤드없음] — 나머지 동일 (20종·3.4년·${margin}·{lev}x) ===\n");
        // 심볼별 klines + 피처만 1회 계산 (엔진은 라벨모드별로 새로 학습)
        var symData = new List<(string sym, List<IBinanceKline> kl, float[][] feats)>();
        int idx = 0;
        foreach (var sym in universe)
        {
            idx++; Console.Write($"[{idx}/{universe.Length}] {sym} ");
            List<IBinanceKline> kl;
            try { kl = await FetchKlines1hAsync(sym, pages1h); } catch { Console.WriteLine("fail"); continue; }
            if (kl.Count < 500) { Console.WriteLine("skip"); continue; }
            int n = kl.Count; Console.WriteLine($"1h={n}");
            var feats = new float[n][];
            for (int j = 60; j < n; j++) { int ws = Math.Max(0, j - (featureWindow - 1)); feats[j] = LorentzianFeatures.Extract(kl.GetRange(ws, j - ws + 1))!; }
            symData.Add((sym, kl, feats));
        }
        Console.WriteLine();
        Console.WriteLine($"  {"라벨",8} {"진입",6} {"승률%",7} {"총손익$",11} {"월평균%",8} {"롱WR%",7} {"숏WR%",7} {"SL청산",6}");
        foreach (bool forward in new[] { false, true })
        {
            var cands = new List<(DateTime ent, DateTime ex, decimal pnl, bool isShort)>(); int slHitAll = 0;
            foreach (var (sym, kl, feats) in symData)
            {
                int n = kl.Count;
                var engine = new LorentzianAnnEngine(sym, neighborsCount: K, maxBarsBack: 2000, featureCount: LorentzianFeatures.FeatureCount);
                var sg = new int[n];
                for (int j = 65; j < n; j++)
                {
                    // 결과가 확정된 과거봉 1개를 학습에 추가 (두 모드 모두 룩어헤드 0)
                    if (forward) { int s = j - L - 1; if (s >= 8 && feats[s] != null) { decimal a = kl[s + L].ClosePrice, b = kl[s].ClosePrice; int lab = a > b ? 1 : (a < b ? -1 : 0); engine.AddSample(feats[s], lab); } }
                    else { int s = j - 1; if (s - L >= 0 && feats[s] != null) { decimal a = kl[s].ClosePrice, b = kl[s - L].ClosePrice; int lab = a > b ? 1 : (a < b ? -1 : 0); engine.AddSample(feats[s], lab); } }
                    if (feats[j] == null) continue;
                    var p = engine.Predict(feats[j]); if (!p.IsReady || p.K == 0) continue;
                    sg[j] = p.Prediction > 0 ? 1 : (p.Prediction < 0 ? -1 : 0);
                }
                int busy = -1;
                for (int j = 250; j < n - 1; j++)
                {
                    if (j <= busy) continue;
                    if (sg[j] == 0) continue;
                    bool isShort = sg[j] < 0;
                    if (kl[j + 1].OpenPrice <= 0) continue;
                    decimal entry = kl[j + 1].OpenPrice; decimal net = 0m; bool done = false; int ei = Math.Min(n - 1, j + maxHold); bool sl = false;
                    if (!isShort) { decimal slPx = entry * (1m - slPct); for (int e = j + 1; e < n && e <= j + maxHold; e++) { if (kl[e].LowPrice <= slPx) { net = -slPct - cost; ei = e; done = true; sl = true; break; } if (sg[e] == -1) { net = (kl[e].ClosePrice - entry) / entry - cost; ei = e; done = true; break; } } if (!done) net = (kl[ei].ClosePrice - entry) / entry - cost; }
                    else { decimal slPx = entry * (1m + slPct); for (int e = j + 1; e < n && e <= j + maxHold; e++) { if (kl[e].HighPrice >= slPx) { net = -slPct - cost; ei = e; done = true; sl = true; break; } if (sg[e] == 1) { net = (entry - kl[e].ClosePrice) / entry - cost; ei = e; done = true; break; } } if (!done) net = (entry - kl[ei].ClosePrice) / entry - cost; }
                    if (sl) slHitAll++;
                    busy = ei;
                    cands.Add((kl[j + 1].OpenTime, kl[ei].OpenTime, net * margin * lev, isShort));
                }
            }
            cands.Sort((a, b) => a.ent.CompareTo(b.ent));
            var open = new List<DateTime>(); int tn = 0, tw = 0, ls = 0, lw = 0, ss = 0, sw = 0; decimal tp = 0m; var mset = new HashSet<string>();
            foreach (var t in cands) { open.RemoveAll(x => x <= t.ent); if (open.Count >= maxSlots) continue; open.Add(t.ex); tn++; if (t.pnl > 0) tw++; tp += t.pnl; mset.Add(t.ent.ToString("yyyy-MM")); if (t.isShort) { ss++; if (t.pnl > 0) sw++; } else { ls++; if (t.pnl > 0) lw++; } }
            double mo = mset.Count > 0 ? (double)(tp / capital * 100m) / mset.Count : 0;
            Console.WriteLine($"  {(forward ? "미래★" : "과거"),8} {tn,6} {(tn > 0 ? 100.0 * tw / tn : 0),7:F1} {tp,11:F2} {mo,8:F2} {(ls > 0 ? 100.0 * lw / ls : 0),7:F1} {(ss > 0 ? 100.0 * sw / ss : 0),7:F1} {slHitAll,6}");
        }
        Console.WriteLine("\n  → 두 줄이 순수 KNN방향(필터 0)이라, 라벨만 바꿔 승률/손익이 뒤집히면 그게 반대매매의 진짜 원인.");
    }

    // --smc-lcc : [신설계] SMC 오더블록(세력 매물대) 지지 + Lorentzian 매수신호 + OB하단/ATR 구조적 손절.
    //   1) 시장국면: 활성 강세 OB(변위 오더블록) 존재 + 가격이 OB 위 & 지지 근처일 때만 진입허용 (아니면 원천차단)
    //   2) 진입: 그 상태에서 KNN(과거라벨=라이브동일) 매수(+1)
    //   3) 손절: OB 하단(구조적) 또는 ATR 가변 중 더 가까운 쪽. TP = R배수. 롱 전용.
    private static async Task RunSmcLccAsync()
    {
        const int featureWindow = 500, maxHold = 96, K = 8, L = 8, pages1h = 20, piv = 3;
        const decimal cost = 0.0004m * 2m + 0.0005m;
        decimal lev = 10m, margin = 500m; int maxSlots = 6; decimal capital = margin * maxSlots;
        var universe = new[] {
            "BTCUSDT","ETHUSDT","BNBUSDT","SOLUSDT","XRPUSDT","DOGEUSDT","ADAUSDT","TRXUSDT","AVAXUSDT","LINKUSDT",
            "DOTUSDT","LTCUSDT","BCHUSDT","ATOMUSDT","UNIUSDT","NEARUSDT","APTUSDT","ARBUSDT","OPUSDT","SUIUSDT" };
        Console.WriteLine($"=== SMC 오더블록 지지 + Lorentzian + OB하단 손절 (롱전용·20종·3.4년·${margin}·{lev}x) ===\n");
        // 심볼별 klines·피처·KNN(과거라벨)·ATR 사전계산
        var symData = new List<(string sym, List<IBinanceKline> kl, int[] sg, double[] atr)>();
        int idx = 0;
        foreach (var sym in universe)
        {
            idx++; Console.Write($"[{idx}/{universe.Length}] {sym} ");
            List<IBinanceKline> kl;
            try { kl = await FetchKlines1hAsync(sym, pages1h); } catch { Console.WriteLine("fail"); continue; }
            if (kl.Count < 500) { Console.WriteLine("skip"); continue; }
            int n = kl.Count; Console.WriteLine($"1h={n}");
            var feats = new float[n][];
            for (int j = 60; j < n; j++) { int ws = Math.Max(0, j - (featureWindow - 1)); feats[j] = LorentzianFeatures.Extract(kl.GetRange(ws, j - ws + 1))!; }
            var atr = new double[n];
            for (int j = 14; j < n; j++) { double tr = 0; for (int q = j - 13; q <= j; q++) { double h = (double)kl[q].HighPrice, l = (double)kl[q].LowPrice, pc = (double)kl[q - 1].ClosePrice; tr += Math.Max(h - l, Math.Max(Math.Abs(h - pc), Math.Abs(l - pc))); } atr[j] = tr / 14.0; }
            var engine = new LorentzianAnnEngine(sym, neighborsCount: K, maxBarsBack: 2000, featureCount: LorentzianFeatures.FeatureCount);
            var sg = new int[n];
            for (int j = 65; j < n; j++) { int s = j - 1; if (s - L >= 0 && feats[s] != null) { decimal a = kl[s].ClosePrice, b = kl[s - L].ClosePrice; engine.AddSample(feats[s], a > b ? 1 : (a < b ? -1 : 0)); } if (feats[j] == null) continue; var p = engine.Predict(feats[j]); if (!p.IsReady || p.K == 0) continue; sg[j] = p.Prediction > 0 ? 1 : (p.Prediction < 0 ? -1 : 0); }
            symData.Add((sym, kl, sg, atr));
        }
        Console.WriteLine();
        Console.WriteLine($"  {"근접prox",8} {"손절",10} {"TP(R)",6} {"진입",5} {"승률%",7} {"총손익$",11} {"월평균%",8} {"이익$",7} {"손실$",8} {"R/R",5}");
        (double prox, string slMode, double rr, decimal tp) best = default; decimal bestPnl = decimal.MinValue;
        double[] proxes = { 0.3, 0.6, 1.0 };            // OB 상단 대비 근접 허용(%): 지지 근처 정의
        string[] slModes = { "OB", "ATR", "TIGHTER" };  // 손절: OB하단 / 1.5ATR / 둘중 가까운쪽
        double[] rrs = { 1.5, 2.0, 3.0 };               // TP = R배수
        foreach (double prox in proxes)
        foreach (string slMode in slModes)
        foreach (double rr in rrs)
        {
            var cands = new List<(DateTime ent, DateTime ex, decimal pnl, decimal risk)>();
            foreach (var (sym, kl, sg, atr) in symData)
            {
                int n = kl.Count;
                // [선별적 강세 오더블록] — 진짜 구조 돌파(BOS)에서만 형성, OB당 1회 진입, 무효화 관리.
                //  1) 스윙고점: pivot(piv) 확정 고점 추적
                //  2) BOS: 종가가 직전 확정 스윙고점 상향돌파 + 변위 강함(≥0.5ATR)
                //  3) OB = 그 상승레그 직전의 마지막 음봉 [low,high]. 미터치·미무효 상태로 보관.
                double obLow = 0, obHigh = 0; bool obActive = false; bool obUsed = false;
                double lastSwingHigh = double.NaN;
                int busy = -1;
                for (int j = 250; j < n - 1; j++)
                {
                    // 스윙고점 확정 (piv봉 뒤에 확정)
                    int sh = j - piv;
                    if (sh - piv >= 0)
                    {
                        bool isHigh = true; double hh = (double)kl[sh].HighPrice;
                        for (int q = sh - piv; q <= sh + piv; q++) { if (q == sh) continue; if ((double)kl[q].HighPrice >= hh) { isHigh = false; break; } }
                        if (isHigh) lastSwingHigh = hh;
                    }
                    // BOS 상향돌파 → 새 OB 형성 (직전 OB 대체)
                    double cj = (double)kl[j].ClosePrice;
                    if (!double.IsNaN(lastSwingHigh) && cj > lastSwingHigh && atr[j] > 0 && (cj - lastSwingHigh) >= 0.5 * atr[j])
                    {
                        int ob = -1;
                        for (int q = j - 1; q >= Math.Max(1, j - 15); q--) { if ((double)kl[q].ClosePrice < (double)kl[q].OpenPrice) { ob = q; break; } }
                        if (ob >= 0) { obLow = (double)kl[ob].LowPrice; obHigh = (double)kl[ob].HighPrice; obActive = true; obUsed = false; lastSwingHigh = double.NaN; }
                    }
                    if (j <= busy) continue;
                    if (!obActive || obUsed) continue;
                    double c = (double)kl[j].ClosePrice, lo = (double)kl[j].LowPrice;
                    // OB 무효화: 종가가 OB 하단 아래로 마감 → 지지 붕괴
                    if (c < obLow) { obActive = false; continue; }
                    // 국면필터: 가격이 OB존까지 되돌림(지지 재테스트). 저가가 OB상단 근방/존 내부로 진입.
                    bool nearSupport = lo <= obHigh * (1.0 + prox / 100.0) && c > obLow;
                    if (!nearSupport) continue;
                    // 진입: KNN 매수
                    if (sg[j] != 1) continue;
                    obUsed = true;
                    if (kl[j + 1].OpenPrice <= 0 || atr[j] <= 0) continue;
                    decimal entry = kl[j + 1].OpenPrice;
                    // 손절가 결정
                    decimal slOb = (decimal)obLow;
                    decimal slAtr = entry - (decimal)(1.5 * atr[j]);
                    decimal slPx = slMode == "OB" ? slOb : slMode == "ATR" ? slAtr : Math.Max(slOb, slAtr); // TIGHTER=가까운(높은)쪽
                    if (slPx >= entry) continue; // 손절이 진입 위면 무효
                    decimal risk = entry - slPx;
                    decimal tpPx = entry + (decimal)rr * risk;
                    decimal net = 0m; bool done = false; int ei = Math.Min(n - 1, j + maxHold);
                    for (int e = j + 1; e < n && e <= j + maxHold; e++)
                    {
                        if (kl[e].LowPrice <= slPx) { net = (slPx - entry) / entry - cost; ei = e; done = true; break; }
                        if (kl[e].HighPrice >= tpPx) { net = (tpPx - entry) / entry - cost; ei = e; done = true; break; }
                        if (sg[e] == -1) { net = (kl[e].ClosePrice - entry) / entry - cost; ei = e; done = true; break; }
                    }
                    if (!done) net = (kl[ei].ClosePrice - entry) / entry - cost;
                    obActive = false; busy = ei;
                    cands.Add((kl[j + 1].OpenTime, kl[ei].OpenTime, net * margin * lev, risk / entry));
                }
            }
            cands.Sort((a, b) => a.ent.CompareTo(b.ent));
            var open = new List<DateTime>(); int tn = 0, tw = 0; decimal tp = 0m, winSum = 0m, lossSum = 0m; var mset = new HashSet<string>();
            foreach (var t in cands) { open.RemoveAll(x => x <= t.ent); if (open.Count >= maxSlots) continue; open.Add(t.ex); tn++; if (t.pnl > 0) { tw++; winSum += t.pnl; } else lossSum += t.pnl; tp += t.pnl; mset.Add(t.ent.ToString("yyyy-MM")); }
            if (tn == 0) continue;
            double mo = (double)(tp / capital * 100m) / Math.Max(1, mset.Count);
            decimal avgW = tw > 0 ? winSum / tw : 0m, avgL = (tn - tw) > 0 ? lossSum / (tn - tw) : 0m;
            Console.WriteLine($"  {prox,7:F1}% {slMode,10} {rr,6:F1} {tn,5} {100.0 * tw / tn,7:F1} {tp,11:F2} {mo,8:F2} {avgW,7:F1} {avgL,8:F1} {(avgL != 0 ? (double)(avgW / -avgL) : 0),5:F2}");
            if (tp > bestPnl) { bestPnl = tp; best = (prox, slMode, rr, tp); }
        }
        Console.WriteLine($"\n  ★최고: 근접 {best.prox:F1}% · 손절 {best.slMode} · TP {best.rr:F1}R · 총손익 ${best.tp:F2}");
    }

    // --mtf-combo : 지표 조합(2~3개 묶음) 전수탐색 — 손실만 몰린 패턴 발굴. train/test 분할로 과최적화 검증.
    private static async Task RunMtfComboAsync()
    {
        const int featureWindow = 500, K = 8, Lh = 4;
        const decimal feeRT = 0.0008m; double atrMult = 5.0; decimal margin = 1000m; int slots = 6; decimal capital = margin * slots;
        var universe = new[] { "BTCUSDT","ETHUSDT","BNBUSDT","SOLUSDT","XRPUSDT","DOGEUSDT","ADAUSDT","AVAXUSDT","ARBUSDT","SUIUSDT" };
        Console.WriteLine("=== 지표 조합(2~3묶음) 전수탐색 — 손실 몰린 패턴 발굴 (train/test 검증) ===\n");
        List<(DateTime close, bool up)> Regime4h(List<IBinanceKline> b4)
        { int n = b4.Count; var e200 = new double[n]; for (int j = 200; j < n; j++) e200[j] = CalcEMA(b4, j, 200); var e50 = new double[n]; for (int j = 50; j < n; j++) e50[j] = CalcEMA(b4, j, 50); var adx = new double[n]; { double aS = 0, pS = 0, mS = 0; int per = 14; for (int j = 1; j < n; j++) { double hh = (double)b4[j].HighPrice, ll = (double)b4[j].LowPrice, pc = (double)b4[j - 1].ClosePrice, ph = (double)b4[j - 1].HighPrice, pl = (double)b4[j - 1].LowPrice; double tr = Math.Max(hh - ll, Math.Max(Math.Abs(hh - pc), Math.Abs(ll - pc))); double up = hh - ph, dn = pl - ll; double pdm = (up > dn && up > 0) ? up : 0, mdm = (dn > up && dn > 0) ? dn : 0; if (j <= per) { aS += tr; pS += pdm; mS += mdm; } else { aS = aS - aS / per + tr; pS = pS - pS / per + pdm; mS = mS - mS / per + mdm; } if (j >= per && aS > 0) { double pd = 100 * pS / aS, md = 100 * mS / aS; double dx = (pd + md) > 0 ? 100 * Math.Abs(pd - md) / (pd + md) : 0; adx[j] = j <= per * 2 ? dx : (adx[j - 1] * (per - 1) + dx) / per; } } } var r = new List<(DateTime, bool)>(); for (int j = 0; j < n; j++) { double c = (double)b4[j].ClosePrice; r.Add((b4[j].OpenTime.AddHours(4), j >= 200 && e50[j] > 0 && e200[j] > 0 && e50[j] > e200[j] && c > e50[j] && adx[j] >= 25)); } return r; }
        var btc4 = await FetchKlines4hAsync("BTCUSDT", 12); var btcAlign = Regime4h(btc4);
        // trade: pnl, ent, ex, mask(13조건 비트)
        var trades = new List<(decimal pnl, DateTime ent, DateTime ex, int mask)>();
        var condNames = new[] { "MACD음전", "BB상단>0.75", "ADX15<22", "거래량>1.5", "거래량<0.7", "연속상승≥5", "눌림<0.3", "진입봉음봉", "KNN<4", "EMA20이격>1.5", "ATR%>0.8", "윗꼬리>0.4", "EMA50이격>1.2" };
        int ci = 0;
        foreach (var sym in universe)
        {
            ci++; Console.Write($"[{ci}/{universe.Length}] {sym} ");
            List<IBinanceKline> b4, k15;
            try { b4 = await FetchKlines4hAsync(sym, 12); k15 = await FetchKlines15mAsync(sym, 110); } catch { Console.WriteLine("fail"); continue; }
            if (b4.Count < 300 || k15.Count < 1000) { Console.WriteLine("skip"); continue; }
            var reg = Regime4h(b4);
            int n = k15.Count; Console.WriteLine($"{n}"); var close = new double[n]; for (int j = 0; j < n; j++) close[j] = (double)k15[j].ClosePrice;
            var feats = new float[n][]; for (int j = 60; j < n; j++) { int ws = Math.Max(0, j - (featureWindow - 1)); feats[j] = LorentzianFeatures.Extract(k15.GetRange(ws, j - ws + 1))!; }
            var e20 = new double[n]; for (int j = 20; j < n; j++) e20[j] = CalcEMA(k15, j, 20);
            var e50 = new double[n]; for (int j = 50; j < n; j++) e50[j] = CalcEMA(k15, j, 50);
            var e200 = new double[n]; for (int j = 200; j < n; j++) e200[j] = CalcEMA(k15, j, 200);
            var atr = new double[n]; for (int j = 14; j < n; j++) { double tr = 0; for (int q = j - 13; q <= j; q++) { double hh = (double)k15[q].HighPrice, ll = (double)k15[q].LowPrice, pc = close[q - 1]; tr += Math.Max(hh - ll, Math.Max(Math.Abs(hh - pc), Math.Abs(ll - pc))); } atr[j] = tr / 14.0; }
            var adx = new double[n]; { double aS = 0, pS = 0, mS = 0; int per = 14; for (int j = 1; j < n; j++) { double hh = (double)k15[j].HighPrice, ll = (double)k15[j].LowPrice, pc = close[j - 1], ph = (double)k15[j - 1].HighPrice, pl = (double)k15[j - 1].LowPrice; double tr = Math.Max(hh - ll, Math.Max(Math.Abs(hh - pc), Math.Abs(ll - pc))); double up = hh - ph, dn = pl - ll; double pdm = (up > dn && up > 0) ? up : 0, mdm = (dn > up && dn > 0) ? dn : 0; if (j <= per) { aS += tr; pS += pdm; mS += mdm; } else { aS = aS - aS / per + tr; pS = pS - pS / per + pdm; mS = mS - mS / per + mdm; } if (j >= per && aS > 0) { double pd = 100 * pS / aS, md = 100 * mS / aS; double dx = (pd + md) > 0 ? 100 * Math.Abs(pd - md) / (pd + md) : 0; adx[j] = j <= per * 2 ? dx : (adx[j - 1] * (per - 1) + dx) / per; } } }
            var bbUp = new double[n]; var bbLo = new double[n]; for (int j = 20; j < n; j++) { double s = 0; for (int q = j - 19; q <= j; q++) s += close[q]; double mid = s / 20; double v = 0; for (int q = j - 19; q <= j; q++) { double d = close[q] - mid; v += d * d; } double sd = Math.Sqrt(v / 20); bbUp[j] = mid + 2 * sd; bbLo[j] = mid - 2 * sd; }
            var macdH = new double[n]; { double e12 = 0, e26 = 0, sig = 0; double k12 = 2.0 / 13, k26 = 2.0 / 27, k9 = 2.0 / 10; for (int j = 0; j < n; j++) { double c = close[j]; if (j == 0) { e12 = c; e26 = c; } else { e12 = c * k12 + e12 * (1 - k12); e26 = c * k26 + e26 * (1 - k26); } double m = e12 - e26; if (j == 0) sig = m; else sig = m * k9 + sig * (1 - k9); macdH[j] = m - sig; } }
            var predV = new double[n];
            var engine = new LorentzianAnnEngine(sym, neighborsCount: K, maxBarsBack: 2000, featureCount: LorentzianFeatures.FeatureCount);
            var sg = new int[n];
            for (int j = 65; j < n; j++) { int s = j - 1; if (s - Lh >= 0 && feats[s] != null) { double a = close[s], b = close[s - Lh]; engine.AddSample(feats[s], a > b ? 1 : (a < b ? -1 : 0)); } if (feats[j] == null) continue; var p = engine.Predict(feats[j]); if (!p.IsReady || p.K == 0) continue; sg[j] = p.Prediction > 0 ? 1 : (p.Prediction < 0 ? -1 : 0); predV[j] = p.Prediction; }
            int rp = 0, bp = 0, busy = -1;
            for (int j = 250; j < n - 1; j++)
            {
                if (j <= busy) continue;
                var t15 = k15[j].OpenTime;
                while (rp + 1 < reg.Count && reg[rp + 1].Item1 <= t15) rp++;
                while (bp + 1 < btcAlign.Count && btcAlign[bp + 1].Item1 <= t15) bp++;
                if (!(reg[rp].Item1 <= t15 && reg[rp].Item2) || !(btcAlign[bp].Item1 <= t15 && btcAlign[bp].Item2)) continue;
                if (!(sg[j] > 0 && e50[j] > 0 && e200[j] > 0 && e50[j] > e200[j] && close[j] > e50[j])) continue;
                if (atr[j] <= 0 || k15[j + 1].OpenPrice <= 0 || bbUp[j] <= bbLo[j]) continue;
                if ((close[j] - e50[j]) / atr[j] >= 2.0 || atrMult * atr[j] / (double)k15[j + 1].OpenPrice > 0.05) continue;
                double entry = (double)k15[j + 1].OpenPrice; double peakP = entry; decimal net = 0m; int ei = n - 1;
                for (int e = j + 1; e < n; e++) { double cc = close[e]; if (cc > peakP) peakP = cc; if (cc <= peakP - atrMult * atr[e]) { net = ((decimal)cc - (decimal)entry) / (decimal)entry - feeRT; ei = e; break; } if (e == n - 1) net = ((decimal)cc - (decimal)entry) / (decimal)entry - feeRT; }
                double o = (double)k15[j].OpenPrice, h = (double)k15[j].HighPrice, c2 = close[j]; double rng = h - (double)k15[j].LowPrice;
                double vsum = 0; for (int q = j - 19; q <= j; q++) vsum += (double)k15[q].Volume; double vavg = vsum / 20; double vr = vavg > 0 ? (double)k15[j].Volume / vavg : 1;
                double recHi = 0; for (int q = j - 19; q <= j; q++) if ((double)k15[q].HighPrice > recHi) recHi = (double)k15[q].HighPrice;
                int cons = 0; for (int q = j; q > j - 10 && q > 0; q--) { if (close[q] > close[q - 1]) cons++; else break; }
                double ext20 = (c2 - e20[j]) / atr[j], ext50 = (c2 - e50[j]) / atr[j], bbP = (c2 - bbLo[j]) / (bbUp[j] - bbLo[j]), pull = (recHi - c2) / c2 * 100, bodyP = rng > 0 ? (c2 - o) / rng : 0, upw = (h - Math.Max(o, c2)) / atr[j], atrp = atr[j] / c2 * 100;
                int mask = 0;
                if (macdH[j] < 0) mask |= 1 << 0; if (bbP > 0.75) mask |= 1 << 1; if (adx[j] < 22) mask |= 1 << 2; if (vr > 1.5) mask |= 1 << 3; if (vr < 0.7) mask |= 1 << 4; if (cons >= 5) mask |= 1 << 5; if (pull < 0.3) mask |= 1 << 6; if (bodyP < 0) mask |= 1 << 7; if (predV[j] < 4) mask |= 1 << 8; if (ext20 > 1.5) mask |= 1 << 9; if (atrp > 0.8) mask |= 1 << 10; if (upw > 0.4) mask |= 1 << 11; if (ext50 > 1.2) mask |= 1 << 12;
                trades.Add((net, k15[j + 1].OpenTime, k15[ei].OpenTime, mask));
                busy = ei;
            }
        }
        int NC = condNames.Length;
        var tArr = trades.OrderBy(t => t.ent).ToList();
        var splitDate = tArr[tArr.Count / 2].ent;   // train/test 경계(중앙)
        double baseWR = 100.0 * tArr.Count(t => t.pnl > 0) / tArr.Count;
        Console.WriteLine($"\n총 {tArr.Count}건 · 기준승률 {baseWR:F0}% · train/test 경계 {splitDate:yyyy-MM}");
        // 2·3개 조합 전수: 매칭 트레이드 n·승률·총pnl. train/test 각각.
        var combos = new List<(int bits, int n, double wr, double pnl, double wrTr, double wrTe, int nTr, int nTe)>();
        void Eval(int bits)
        {
            var m = tArr.Where(t => (t.mask & bits) == bits).ToList();
            if (m.Count < 60) return;
            var tr = m.Where(t => t.ent < splitDate).ToList(); var te = m.Where(t => t.ent >= splitDate).ToList();
            if (tr.Count < 20 || te.Count < 20) return;
            combos.Add((bits, m.Count, 100.0 * m.Count(x => x.pnl > 0) / m.Count, (double)(m.Sum(x => x.pnl) * margin), 100.0 * tr.Count(x => x.pnl > 0) / tr.Count, 100.0 * te.Count(x => x.pnl > 0) / te.Count, tr.Count, te.Count));
        }
        for (int a = 0; a < NC; a++) for (int b = a + 1; b < NC; b++) Eval((1 << a) | (1 << b));
        for (int a = 0; a < NC; a++) for (int b = a + 1; b < NC; b++) for (int c = b + 1; c < NC; c++) Eval((1 << a) | (1 << b) | (1 << c));
        string Name(int bits) { var s = new List<string>(); for (int i = 0; i < NC; i++) if ((bits & (1 << i)) != 0) s.Add(condNames[i]); return string.Join("+", s); }
        Console.WriteLine($"\n── 손실 몰린 조합 (승률 낮은순, n≥60, train·test 둘다 확인) ──");
        Console.WriteLine($"  {"조합",44} {"건수",4} {"승률%",6} {"총pnl$",8} {"train승률",8} {"test승률",8}");
        foreach (var c in combos.OrderBy(x => x.wr).Take(15))
            Console.WriteLine($"  {Name(c.bits),-44} {c.n,4} {c.wr,6:F0} {c.pnl,8:F0} {c.wrTr,8:F0} {c.wrTe,8:F0}");
        // train·test 둘 다 승률<기준−8%p & 총pnl<0 = 진짜 손실패턴
        var robust = combos.Where(c => c.wrTr < baseWR - 8 && c.wrTe < baseWR - 8 && c.pnl < 0).OrderBy(c => c.pnl).ToList();
        Console.WriteLine($"\n── ★robust 손실패턴 (train·test 둘다 승률<기준−8%p & 총적자) : {robust.Count}개 ──");
        foreach (var c in robust.Take(8)) Console.WriteLine($"   {Name(c.bits),-46} n{c.n} 승률{c.wr:F0}% ${c.pnl:F0} (tr{c.wrTr:F0}/te{c.wrTe:F0})");
        if (robust.Count == 0) Console.WriteLine("   없음 — 조합으로도 train/test 둘다 손실 몰린 패턴 없음(진입예측 불가 확인).");
        Console.WriteLine("\n  → robust 패턴 있으면 그 조합 진입 제외 = 손실만 거름. 없으면 조합으로도 예측 불가.");
    }

    // --mtf-defense : 승자 vs 패자 전수비교 + 방어필터 병렬탐색. 손실만 걸러지는 지표(Δ수익>0) 발굴.
    private static async Task RunMtfDefenseAsync()
    {
        const int featureWindow = 500, K = 8, Lh = 4;
        const decimal feeRT = 0.0008m; double atrMult = 5.0; decimal margin = 1000m; int slots = 6; decimal capital = margin * slots;
        var universe = new[] { "BTCUSDT","ETHUSDT","BNBUSDT","SOLUSDT","XRPUSDT","DOGEUSDT","ADAUSDT","AVAXUSDT","ARBUSDT","SUIUSDT" };
        Console.WriteLine("=== 승자 vs 패자 전수비교 + 방어필터 병렬탐색 (손실만 걸러지는 지표 발굴) ===\n");
        List<(DateTime close, bool up)> Regime4h(List<IBinanceKline> b4)
        { int n = b4.Count; var e200 = new double[n]; for (int j = 200; j < n; j++) e200[j] = CalcEMA(b4, j, 200); var e50 = new double[n]; for (int j = 50; j < n; j++) e50[j] = CalcEMA(b4, j, 50); var adx = new double[n]; { double aS = 0, pS = 0, mS = 0; int per = 14; for (int j = 1; j < n; j++) { double hh = (double)b4[j].HighPrice, ll = (double)b4[j].LowPrice, pc = (double)b4[j - 1].ClosePrice, ph = (double)b4[j - 1].HighPrice, pl = (double)b4[j - 1].LowPrice; double tr = Math.Max(hh - ll, Math.Max(Math.Abs(hh - pc), Math.Abs(ll - pc))); double up = hh - ph, dn = pl - ll; double pdm = (up > dn && up > 0) ? up : 0, mdm = (dn > up && dn > 0) ? dn : 0; if (j <= per) { aS += tr; pS += pdm; mS += mdm; } else { aS = aS - aS / per + tr; pS = pS - pS / per + pdm; mS = mS - mS / per + mdm; } if (j >= per && aS > 0) { double pd = 100 * pS / aS, md = 100 * mS / aS; double dx = (pd + md) > 0 ? 100 * Math.Abs(pd - md) / (pd + md) : 0; adx[j] = j <= per * 2 ? dx : (adx[j - 1] * (per - 1) + dx) / per; } } } var r = new List<(DateTime, bool)>(); for (int j = 0; j < n; j++) { double c = (double)b4[j].ClosePrice; r.Add((b4[j].OpenTime.AddHours(4), j >= 200 && e50[j] > 0 && e200[j] > 0 && e50[j] > e200[j] && c > e50[j] && adx[j] >= 25)); } return r; }
        var btc4 = await FetchKlines4hAsync("BTCUSDT", 12); var btcAlign = Regime4h(btc4);
        // trade: pnl + 진입지표 [knnNet, atrPct, ext20, ext50, bbPos, volR, macdH, adx15, pull, bodyPos, upWick, consecUp]
        var trades = new List<(decimal pnl, double knn, double atrp, double ext20, double ext50, double bb, double vol, double macd, double adx, double pull, double body, double upw, double cons)>();
        var raw = new List<(DateTime ent, DateTime ex, decimal pnl, int idx)>();   // idx = trades index (필터 재계산용)
        int ci = 0;
        foreach (var sym in universe)
        {
            ci++; Console.Write($"[{ci}/{universe.Length}] {sym} ");
            List<IBinanceKline> b4, k15;
            try { b4 = await FetchKlines4hAsync(sym, 12); k15 = await FetchKlines15mAsync(sym, 110); } catch { Console.WriteLine("fail"); continue; }
            if (b4.Count < 300 || k15.Count < 1000) { Console.WriteLine("skip"); continue; }
            var reg = Regime4h(b4);
            int n = k15.Count; Console.WriteLine($"{n}"); var close = new double[n]; for (int j = 0; j < n; j++) close[j] = (double)k15[j].ClosePrice;
            var feats = new float[n][]; for (int j = 60; j < n; j++) { int ws = Math.Max(0, j - (featureWindow - 1)); feats[j] = LorentzianFeatures.Extract(k15.GetRange(ws, j - ws + 1))!; }
            var e20 = new double[n]; for (int j = 20; j < n; j++) e20[j] = CalcEMA(k15, j, 20);
            var e50 = new double[n]; for (int j = 50; j < n; j++) e50[j] = CalcEMA(k15, j, 50);
            var e200 = new double[n]; for (int j = 200; j < n; j++) e200[j] = CalcEMA(k15, j, 200);
            var atr = new double[n]; for (int j = 14; j < n; j++) { double tr = 0; for (int q = j - 13; q <= j; q++) { double hh = (double)k15[q].HighPrice, ll = (double)k15[q].LowPrice, pc = close[q - 1]; tr += Math.Max(hh - ll, Math.Max(Math.Abs(hh - pc), Math.Abs(ll - pc))); } atr[j] = tr / 14.0; }
            var adx = new double[n]; { double aS = 0, pS = 0, mS = 0; int per = 14; for (int j = 1; j < n; j++) { double hh = (double)k15[j].HighPrice, ll = (double)k15[j].LowPrice, pc = close[j - 1], ph = (double)k15[j - 1].HighPrice, pl = (double)k15[j - 1].LowPrice; double tr = Math.Max(hh - ll, Math.Max(Math.Abs(hh - pc), Math.Abs(ll - pc))); double up = hh - ph, dn = pl - ll; double pdm = (up > dn && up > 0) ? up : 0, mdm = (dn > up && dn > 0) ? dn : 0; if (j <= per) { aS += tr; pS += pdm; mS += mdm; } else { aS = aS - aS / per + tr; pS = pS - pS / per + pdm; mS = mS - mS / per + mdm; } if (j >= per && aS > 0) { double pd = 100 * pS / aS, md = 100 * mS / aS; double dx = (pd + md) > 0 ? 100 * Math.Abs(pd - md) / (pd + md) : 0; adx[j] = j <= per * 2 ? dx : (adx[j - 1] * (per - 1) + dx) / per; } } }
            var bbUp = new double[n]; var bbLo = new double[n]; for (int j = 20; j < n; j++) { double s = 0; for (int q = j - 19; q <= j; q++) s += close[q]; double mid = s / 20; double v = 0; for (int q = j - 19; q <= j; q++) { double d = close[q] - mid; v += d * d; } double sd = Math.Sqrt(v / 20); bbUp[j] = mid + 2 * sd; bbLo[j] = mid - 2 * sd; }
            var macdH = new double[n]; { double e12 = 0, e26 = 0, sig = 0; double k12 = 2.0 / 13, k26 = 2.0 / 27, k9 = 2.0 / 10; for (int j = 0; j < n; j++) { double c = close[j]; if (j == 0) { e12 = c; e26 = c; } else { e12 = c * k12 + e12 * (1 - k12); e26 = c * k26 + e26 * (1 - k26); } double m = e12 - e26; if (j == 0) sig = m; else sig = m * k9 + sig * (1 - k9); macdH[j] = m - sig; } }
            var predV = new double[n];
            var engine = new LorentzianAnnEngine(sym, neighborsCount: K, maxBarsBack: 2000, featureCount: LorentzianFeatures.FeatureCount);
            var sg = new int[n];
            for (int j = 65; j < n; j++) { int s = j - 1; if (s - Lh >= 0 && feats[s] != null) { double a = close[s], b = close[s - Lh]; engine.AddSample(feats[s], a > b ? 1 : (a < b ? -1 : 0)); } if (feats[j] == null) continue; var p = engine.Predict(feats[j]); if (!p.IsReady || p.K == 0) continue; sg[j] = p.Prediction > 0 ? 1 : (p.Prediction < 0 ? -1 : 0); predV[j] = p.Prediction; }
            int rp = 0, bp = 0, busy = -1;
            for (int j = 250; j < n - 1; j++)
            {
                if (j <= busy) continue;
                var t15 = k15[j].OpenTime;
                while (rp + 1 < reg.Count && reg[rp + 1].Item1 <= t15) rp++;
                while (bp + 1 < btcAlign.Count && btcAlign[bp + 1].Item1 <= t15) bp++;
                if (!(reg[rp].Item1 <= t15 && reg[rp].Item2) || !(btcAlign[bp].Item1 <= t15 && btcAlign[bp].Item2)) continue;
                if (!(sg[j] > 0 && e50[j] > 0 && e200[j] > 0 && e50[j] > e200[j] && close[j] > e50[j])) continue;
                if (atr[j] <= 0 || k15[j + 1].OpenPrice <= 0 || bbUp[j] <= bbLo[j]) continue;
                if ((close[j] - e50[j]) / atr[j] >= 2.0 || atrMult * atr[j] / (double)k15[j + 1].OpenPrice > 0.05) continue;   // 현행 방어(EMA과확장·손절폭) 유지
                double entry = (double)k15[j + 1].OpenPrice; double peakP = entry; decimal net = 0m; int ei = n - 1;
                for (int e = j + 1; e < n; e++) { double cc = close[e]; if (cc > peakP) peakP = cc; if (cc <= peakP - atrMult * atr[e]) { net = ((decimal)cc - (decimal)entry) / (decimal)entry - feeRT; ei = e; break; } if (e == n - 1) net = ((decimal)cc - (decimal)entry) / (decimal)entry - feeRT; }
                double o = (double)k15[j].OpenPrice, h = (double)k15[j].HighPrice, c2 = close[j]; double rng = h - (double)k15[j].LowPrice;
                double vsum = 0; for (int q = j - 19; q <= j; q++) vsum += (double)k15[q].Volume; double vavg = vsum / 20; double vr = vavg > 0 ? (double)k15[j].Volume / vavg : 1;
                double recHi = 0; for (int q = j - 19; q <= j; q++) if ((double)k15[q].HighPrice > recHi) recHi = (double)k15[q].HighPrice;
                int cons = 0; for (int q = j; q > j - 10 && q > 0; q--) { if (close[q] > close[q - 1]) cons++; else break; }
                int idx = trades.Count;
                trades.Add((net, predV[j], atr[j] / close[j] * 100, (close[j] - e20[j]) / atr[j], (close[j] - e50[j]) / atr[j], (c2 - bbLo[j]) / (bbUp[j] - bbLo[j]), vr, macdH[j], adx[j], (recHi - c2) / c2 * 100, rng > 0 ? (c2 - o) / rng : 0, (h - Math.Max(o, c2)) / atr[j], cons));
                raw.Add((k15[j + 1].OpenTime, k15[ei].OpenTime, net, idx));
                busy = ei;
            }
        }
        var W = trades.Where(t => t.pnl > 0).ToList(); var L = trades.Where(t => t.pnl <= 0).ToList();
        Console.WriteLine($"\n총 {trades.Count} · 승 {W.Count} 패 {L.Count}\n── Part A: 승자 vs 패자 진입지표 평균 ──");
        void Cmp(string nm, Func<(decimal, double, double, double, double, double, double, double, double, double, double, double, double), double> f) { double w = W.Count > 0 ? W.Average(f) : 0, l = L.Count > 0 ? L.Average(f) : 0; Console.WriteLine($"   {nm,-14} 승 {w,7:F2}  패 {l,7:F2}  차 {w - l,6:F2}"); }
        Cmp("KNN net", t => t.Item2); Cmp("ATR%", t => t.Item3); Cmp("EMA20이격", t => t.Item4); Cmp("EMA50이격", t => t.Item5); Cmp("BB위치", t => t.Item6); Cmp("거래량배수", t => t.Item7); Cmp("MACD히스토", t => t.Item8); Cmp("ADX15", t => t.Item9); Cmp("눌림깊이%", t => t.Item10); Cmp("몸통위치", t => t.Item11); Cmp("윗꼬리", t => t.Item12); Cmp("연속상승봉", t => t.Item13);
        // Part B: 필터 병렬 (keep = 진입 유지 조건)
        double baseTot; { var open0 = new List<DateTime>(); var m0 = new SortedDictionary<string, decimal>(); foreach (var t in raw.OrderBy(x => x.ent)) { open0.RemoveAll(x => x <= t.ent); if (open0.Count >= slots) continue; open0.Add(t.ex); m0[t.ent.ToString("yyyy-MM")] = (m0.TryGetValue(t.ent.ToString("yyyy-MM"), out var v) ? v : 0m) + t.pnl * margin; } baseTot = (double)(m0.Values.Sum() / capital * 100m); }
        double EvalFilter(Func<(decimal, double, double, double, double, double, double, double, double, double, double, double, double), bool> keep, out int lr, out int wr)
        {
            int lrr = 0, wrr = 0; var open = new List<DateTime>(); var m = new SortedDictionary<string, decimal>();
            foreach (var t in raw.OrderBy(x => x.ent)) { var tr = trades[t.idx]; if (!keep(tr)) { if (tr.pnl > 0) wrr++; else lrr++; continue; } open.RemoveAll(x => x <= t.ent); if (open.Count >= slots) continue; open.Add(t.ex); m[t.ent.ToString("yyyy-MM")] = (m.TryGetValue(t.ent.ToString("yyyy-MM"), out var v) ? v : 0m) + tr.pnl * margin; }
            lr = lrr; wr = wrr; return (double)(m.Values.Sum() / capital * 100m);
        }
        var filters = new List<(string d, Func<(decimal, double, double, double, double, double, double, double, double, double, double, double, double), bool> k)>
        {
            ($"KNN net≥4", t=>t.Item2>=4),($"KNN net≥6", t=>t.Item2>=6),
            ($"MACD히스토>0", t=>t.Item8>0),
            ($"ADX15≥20", t=>t.Item9>=20),($"ADX15≥25", t=>t.Item9>=25),
            ($"BB위치<0.8", t=>t.Item6<0.8),($"BB위치<0.9", t=>t.Item6<0.9),
            ($"거래량<2", t=>t.Item7<2),($"거래량>0.7", t=>t.Item7>0.7),
            ($"몸통위치>0.3", t=>t.Item11>0.3),($"몸통위치>0(양봉)", t=>t.Item11>0),
            ($"윗꼬리<0.5", t=>t.Item12<0.5),($"윗꼬리<0.8", t=>t.Item12<0.8),
            ($"연속상승<5", t=>t.Item13<5),($"연속상승<3", t=>t.Item13<3),
            ($"눌림>0.3%", t=>t.Item10>0.3),($"눌림>1%", t=>t.Item10>1),
            ($"EMA20이격<1.5", t=>t.Item4<1.5),($"EMA20이격<1", t=>t.Item4<1),
            ($"ATR%<3", t=>t.Item3<3),($"ATR%<2", t=>t.Item3<2),
        };
        var res = new (string d, double tot, int lr, int wr)[filters.Count];
        System.Threading.Tasks.Parallel.For(0, filters.Count, i => { double tt = EvalFilter(filters[i].k, out int lr, out int wr); res[i] = (filters[i].d, tt, lr, wr); });
        Console.WriteLine($"\n── Part B: 방어필터 (기준 총수익 {baseTot:F0}%) — Δ수익>0 & 패거른>승거른 = 손실만 거름 ──");
        Console.WriteLine($"  {"필터",16} {"총수익%",8} {"Δ수익",7} {"패거른",6} {"승거른",6}");
        foreach (var r in res.OrderByDescending(x => x.tot).Take(14))
            Console.WriteLine($"  {r.d,-16} {r.tot,8:F0} {r.tot - baseTot,+7:F0} {r.lr,6} {r.wr,6}");
        Console.WriteLine("\n  → Δ수익>0 이면서 패거른>승거른인 필터가 '손실만 거르는' 지표. 그게 답.");
    }

    // --mtf-rsi : OP·LINK 제거 + RSI 진입밴드 스윕 (하한~상한). 약세구간 진입 제거로 수익집중 검증.
    private static async Task RunMtfRsiAsync()
    {
        const int featureWindow = 500, K = 8, Lh = 4;
        const decimal feeRT = 0.0008m; double atrMult = 5.0; decimal margin = 1000m; int slots = 6; decimal capital = margin * slots;
        var universe = new[] { "BTCUSDT","ETHUSDT","BNBUSDT","SOLUSDT","XRPUSDT","DOGEUSDT","ADAUSDT","AVAXUSDT","ARBUSDT","SUIUSDT" };   // OP·LINK 제거
        Console.WriteLine("=== OP·LINK 제거 + RSI 밴드 스윕 (10코인) ===\n");
        List<(DateTime close, bool up)> Regime4h(List<IBinanceKline> b4)
        { int n = b4.Count; var e200 = new double[n]; for (int j = 200; j < n; j++) e200[j] = CalcEMA(b4, j, 200); var e50 = new double[n]; for (int j = 50; j < n; j++) e50[j] = CalcEMA(b4, j, 50); var adx = new double[n]; { double aS = 0, pS = 0, mS = 0; int per = 14; for (int j = 1; j < n; j++) { double hh = (double)b4[j].HighPrice, ll = (double)b4[j].LowPrice, pc = (double)b4[j - 1].ClosePrice, ph = (double)b4[j - 1].HighPrice, pl = (double)b4[j - 1].LowPrice; double tr = Math.Max(hh - ll, Math.Max(Math.Abs(hh - pc), Math.Abs(ll - pc))); double up = hh - ph, dn = pl - ll; double pdm = (up > dn && up > 0) ? up : 0, mdm = (dn > up && dn > 0) ? dn : 0; if (j <= per) { aS += tr; pS += pdm; mS += mdm; } else { aS = aS - aS / per + tr; pS = pS - pS / per + pdm; mS = mS - mS / per + mdm; } if (j >= per && aS > 0) { double pd = 100 * pS / aS, md = 100 * mS / aS; double dx = (pd + md) > 0 ? 100 * Math.Abs(pd - md) / (pd + md) : 0; adx[j] = j <= per * 2 ? dx : (adx[j - 1] * (per - 1) + dx) / per; } } } var r = new List<(DateTime, bool)>(); for (int j = 0; j < n; j++) { double c = (double)b4[j].ClosePrice; r.Add((b4[j].OpenTime.AddHours(4), j >= 200 && e50[j] > 0 && e200[j] > 0 && e50[j] > e200[j] && c > e50[j] && adx[j] >= 25)); } return r; }
        var btc4 = await FetchKlines4hAsync("BTCUSDT", 12); var btcAlign = Regime4h(btc4);
        var data = new List<(List<IBinanceKline> k15, double[] close, int[] sg, double[] e50, double[] e200, double[] atr, double[] rsi, List<(DateTime, bool)> reg)>();
        int ci = 0;
        foreach (var sym in universe)
        {
            ci++; Console.Write($"[{ci}/{universe.Length}] {sym} ");
            List<IBinanceKline> b4, k15;
            try { b4 = await FetchKlines4hAsync(sym, 12); k15 = await FetchKlines15mAsync(sym, 110); } catch { Console.WriteLine("fail"); continue; }
            if (b4.Count < 300 || k15.Count < 1000) { Console.WriteLine("skip"); continue; }
            var reg = Regime4h(b4);
            int n = k15.Count; Console.WriteLine($"{n}"); var close = new double[n]; for (int j = 0; j < n; j++) close[j] = (double)k15[j].ClosePrice;
            var feats = new float[n][]; for (int j = 60; j < n; j++) { int ws = Math.Max(0, j - (featureWindow - 1)); feats[j] = LorentzianFeatures.Extract(k15.GetRange(ws, j - ws + 1))!; }
            var e50 = new double[n]; for (int j = 50; j < n; j++) e50[j] = CalcEMA(k15, j, 50);
            var e200 = new double[n]; for (int j = 200; j < n; j++) e200[j] = CalcEMA(k15, j, 200);
            var atr = new double[n]; for (int j = 14; j < n; j++) { double tr = 0; for (int q = j - 13; q <= j; q++) { double hh = (double)k15[q].HighPrice, ll = (double)k15[q].LowPrice, pc = close[q - 1]; tr += Math.Max(hh - ll, Math.Max(Math.Abs(hh - pc), Math.Abs(ll - pc))); } atr[j] = tr / 14.0; }
            var rsi = new double[n]; { double ag = 0, al = 0; int per = 14; for (int j = 1; j < n; j++) { double ch = close[j] - close[j - 1]; double g = ch > 0 ? ch : 0, ls = ch < 0 ? -ch : 0; if (j <= per) { ag += g; al += ls; if (j == per) { ag /= per; al /= per; rsi[j] = al == 0 ? 100 : 100 - 100 / (1 + ag / al); } } else { ag = (ag * (per - 1) + g) / per; al = (al * (per - 1) + ls) / per; rsi[j] = al == 0 ? 100 : 100 - 100 / (1 + ag / al); } } }
            var engine = new LorentzianAnnEngine(sym, neighborsCount: K, maxBarsBack: 2000, featureCount: LorentzianFeatures.FeatureCount);
            var sg = new int[n];
            for (int j = 65; j < n; j++) { int s = j - 1; if (s - Lh >= 0 && feats[s] != null) { double a = close[s], b = close[s - Lh]; engine.AddSample(feats[s], a > b ? 1 : (a < b ? -1 : 0)); } if (feats[j] == null) continue; var p = engine.Predict(feats[j]); if (!p.IsReady || p.K == 0) continue; sg[j] = p.Prediction > 0 ? 1 : (p.Prediction < 0 ? -1 : 0); }
            data.Add((k15, close, sg, e50, e200, atr, rsi, reg));
        }
        (int tn, double prof, double tot, double mdd, double worst, double wr, double mavg) Run(double lo, double hi)
        {
            var trades = new List<(DateTime ent, DateTime ex, decimal pnl)>();
            foreach (var (k15, close, sg, e50, e200, atr, rsi, reg) in data)
            {
                int n = k15.Count; int rp = 0, bp = 0, busy = -1;
                for (int j = 250; j < n - 1; j++)
                {
                    if (j <= busy) continue;
                    var t15 = k15[j].OpenTime;
                    while (rp + 1 < reg.Count && reg[rp + 1].Item1 <= t15) rp++;
                    while (bp + 1 < btcAlign.Count && btcAlign[bp + 1].Item1 <= t15) bp++;
                    if (!(reg[rp].Item1 <= t15 && reg[rp].Item2) || !(btcAlign[bp].Item1 <= t15 && btcAlign[bp].Item2)) continue;
                    if (!(sg[j] > 0 && e50[j] > 0 && e200[j] > 0 && e50[j] > e200[j] && close[j] > e50[j])) continue;
                    if (atr[j] <= 0 || k15[j + 1].OpenPrice <= 0) continue;
                    if ((close[j] - e50[j]) / atr[j] >= 2.0) continue;
                    if (!(rsi[j] >= lo && rsi[j] < hi)) continue;   // ★RSI 밴드
                    if (atrMult * atr[j] / (double)k15[j + 1].OpenPrice > 0.05) continue;
                    double entry = (double)k15[j + 1].OpenPrice; double peakP = entry; decimal net = 0m; int ei = n - 1;
                    for (int e = j + 1; e < n; e++) { double cc = close[e]; if (cc > peakP) peakP = cc; if (cc <= peakP - atrMult * atr[e]) { net = ((decimal)cc - (decimal)entry) / (decimal)entry - feeRT; ei = e; break; } if (e == n - 1) net = ((decimal)cc - (decimal)entry) / (decimal)entry - feeRT; }
                    busy = ei; trades.Add((k15[j + 1].OpenTime, k15[ei].OpenTime, net));
                }
            }
            trades.Sort((a, b) => a.ent.CompareTo(b.ent));
            var open = new List<DateTime>(); var monthly = new SortedDictionary<string, decimal>(); int tn = 0, win = 0;
            foreach (var t in trades) { open.RemoveAll(x => x <= t.ent); if (open.Count >= slots) continue; open.Add(t.ex); monthly[t.ent.ToString("yyyy-MM")] = (monthly.TryGetValue(t.ent.ToString("yyyy-MM"), out var v) ? v : 0m) + t.pnl * margin; tn++; if (t.pnl > 0) win++; }
            int prof = 0; decimal cum = 0m, peak = 0m, mdd = 0m, worst = 0m, tot = 0m; foreach (var kv in monthly) { if (kv.Value > 0) prof++; if (kv.Value < worst) worst = kv.Value; cum += kv.Value; tot += kv.Value; if (cum > peak) peak = cum; if (peak - cum > mdd) mdd = peak - cum; }
            int mo = Math.Max(1, monthly.Count);
            return (tn, 100.0 * prof / mo, (double)(tot / capital * 100m), (double)(mdd / capital * 100m), (double)(worst / capital * 100m), tn > 0 ? 100.0 * win / tn : 0, tn / (double)mo);
        }
        Console.WriteLine($"\n  {"RSI밴드",12} {"진입",5} {"월평균",6} {"승률%",6} {"흑자월%",7} {"총수익%",8} {"MDD%",6} {"최악월%",7}");
        void R(double lo, double hi) { var r = Run(lo, hi); Console.WriteLine($"  {lo:F0}~{hi:F0}{"",6} {r.tn,5} {r.mavg,6:F1} {r.wr,6:F0} {r.prof,7:F0} {r.tot,8:F0} {r.mdd,6:F0} {r.worst,7:F1}"); }
        R(0, 60); R(0, 57); R(45, 60); R(45, 57); R(48, 60); R(48, 57); R(48, 55); R(50, 57); R(50, 60);
        Console.WriteLine("\n  → 총수익·흑자월↑ & MDD 유지면 그 밴드 채택. 거래 너무 줄면(월<15) 과최적화 위험.");
    }

    // --mtf-lock : 이익반납 방지 스윕 — 본절이동(+X%→SL진입가) / 수익후 트레일축소. 반납손실 제거 검증.
    private static async Task RunMtfLockAsync()
    {
        const int featureWindow = 500, K = 8, Lh = 4;
        const decimal feeRT = 0.0008m; decimal margin = 1000m; int slots = 6; decimal capital = margin * slots;
        var universe = new[] { "BTCUSDT","ETHUSDT","BNBUSDT","SOLUSDT","XRPUSDT","DOGEUSDT","ADAUSDT","AVAXUSDT","LINKUSDT","ARBUSDT","OPUSDT","SUIUSDT" };
        Console.WriteLine("=== 이익반납 방지 스윕 (본절이동 / 수익후 트레일축소) ===\n");
        List<(DateTime close, bool up)> Regime4h(List<IBinanceKline> b4)
        { int n = b4.Count; var e200 = new double[n]; for (int j = 200; j < n; j++) e200[j] = CalcEMA(b4, j, 200); var e50 = new double[n]; for (int j = 50; j < n; j++) e50[j] = CalcEMA(b4, j, 50); var adx = new double[n]; { double aS = 0, pS = 0, mS = 0; int per = 14; for (int j = 1; j < n; j++) { double hh = (double)b4[j].HighPrice, ll = (double)b4[j].LowPrice, pc = (double)b4[j - 1].ClosePrice, ph = (double)b4[j - 1].HighPrice, pl = (double)b4[j - 1].LowPrice; double tr = Math.Max(hh - ll, Math.Max(Math.Abs(hh - pc), Math.Abs(ll - pc))); double up = hh - ph, dn = pl - ll; double pdm = (up > dn && up > 0) ? up : 0, mdm = (dn > up && dn > 0) ? dn : 0; if (j <= per) { aS += tr; pS += pdm; mS += mdm; } else { aS = aS - aS / per + tr; pS = pS - pS / per + pdm; mS = mS - mS / per + mdm; } if (j >= per && aS > 0) { double pd = 100 * pS / aS, md = 100 * mS / aS; double dx = (pd + md) > 0 ? 100 * Math.Abs(pd - md) / (pd + md) : 0; adx[j] = j <= per * 2 ? dx : (adx[j - 1] * (per - 1) + dx) / per; } } } var r = new List<(DateTime, bool)>(); for (int j = 0; j < n; j++) { double c = (double)b4[j].ClosePrice; r.Add((b4[j].OpenTime.AddHours(4), j >= 200 && e50[j] > 0 && e200[j] > 0 && e50[j] > e200[j] && c > e50[j] && adx[j] >= 25)); } return r; }
        var btc4 = await FetchKlines4hAsync("BTCUSDT", 12); var btcAlign = Regime4h(btc4);
        var data = new List<(List<IBinanceKline> k15, double[] close, int[] sg, double[] e50, double[] e200, double[] atr, double[] rsi, List<(DateTime, bool)> reg)>();
        int ci = 0;
        foreach (var sym in universe)
        {
            ci++; Console.Write($"[{ci}/{universe.Length}] {sym} ");
            List<IBinanceKline> b4, k15;
            try { b4 = await FetchKlines4hAsync(sym, 12); k15 = await FetchKlines15mAsync(sym, 110); } catch { Console.WriteLine("fail"); continue; }
            if (b4.Count < 300 || k15.Count < 1000) { Console.WriteLine("skip"); continue; }
            var reg = Regime4h(b4);
            int n = k15.Count; Console.WriteLine($"{n}"); var close = new double[n]; for (int j = 0; j < n; j++) close[j] = (double)k15[j].ClosePrice;
            var feats = new float[n][]; for (int j = 60; j < n; j++) { int ws = Math.Max(0, j - (featureWindow - 1)); feats[j] = LorentzianFeatures.Extract(k15.GetRange(ws, j - ws + 1))!; }
            var e50 = new double[n]; for (int j = 50; j < n; j++) e50[j] = CalcEMA(k15, j, 50);
            var e200 = new double[n]; for (int j = 200; j < n; j++) e200[j] = CalcEMA(k15, j, 200);
            var atr = new double[n]; for (int j = 14; j < n; j++) { double tr = 0; for (int q = j - 13; q <= j; q++) { double hh = (double)k15[q].HighPrice, ll = (double)k15[q].LowPrice, pc = close[q - 1]; tr += Math.Max(hh - ll, Math.Max(Math.Abs(hh - pc), Math.Abs(ll - pc))); } atr[j] = tr / 14.0; }
            var rsi = new double[n]; { double ag = 0, al = 0; int per = 14; for (int j = 1; j < n; j++) { double ch = close[j] - close[j - 1]; double g = ch > 0 ? ch : 0, ls = ch < 0 ? -ch : 0; if (j <= per) { ag += g; al += ls; if (j == per) { ag /= per; al /= per; rsi[j] = al == 0 ? 100 : 100 - 100 / (1 + ag / al); } } else { ag = (ag * (per - 1) + g) / per; al = (al * (per - 1) + ls) / per; rsi[j] = al == 0 ? 100 : 100 - 100 / (1 + ag / al); } } }
            var engine = new LorentzianAnnEngine(sym, neighborsCount: K, maxBarsBack: 2000, featureCount: LorentzianFeatures.FeatureCount);
            var sg = new int[n];
            for (int j = 65; j < n; j++) { int s = j - 1; if (s - Lh >= 0 && feats[s] != null) { double a = close[s], b = close[s - Lh]; engine.AddSample(feats[s], a > b ? 1 : (a < b ? -1 : 0)); } if (feats[j] == null) continue; var p = engine.Predict(feats[j]); if (!p.IsReady || p.K == 0) continue; sg[j] = p.Prediction > 0 ? 1 : (p.Prediction < 0 ? -1 : 0); }
            data.Add((k15, close, sg, e50, e200, atr, rsi, reg));
        }
        // 청산 시뮬: lockR=본절이동 트리거(%), tightAfter=수익후 트레일배수(0이면 미적용), baseMult=기본트레일
        (int tn, double prof, double tot, double mdd, double worst, double wr) Run(double lockPct, double tightMult, double tightAfterPct, double baseMult)
        {
            var trades = new List<(DateTime ent, DateTime ex, decimal pnl)>();
            foreach (var (k15, close, sg, e50, e200, atr, rsi, reg) in data)
            {
                int n = k15.Count; int rp = 0, bp = 0, busy = -1;
                for (int j = 250; j < n - 1; j++)
                {
                    if (j <= busy) continue;
                    var t15 = k15[j].OpenTime;
                    while (rp + 1 < reg.Count && reg[rp + 1].Item1 <= t15) rp++;
                    while (bp + 1 < btcAlign.Count && btcAlign[bp + 1].Item1 <= t15) bp++;
                    if (!(reg[rp].Item1 <= t15 && reg[rp].Item2) || !(btcAlign[bp].Item1 <= t15 && btcAlign[bp].Item2)) continue;
                    if (!(sg[j] > 0 && e50[j] > 0 && e200[j] > 0 && e50[j] > e200[j] && close[j] > e50[j])) continue;
                    if (atr[j] <= 0 || k15[j + 1].OpenPrice <= 0) continue;
                    if ((close[j] - e50[j]) / atr[j] >= 2.0 || rsi[j] >= 60.0) continue;
                    if (baseMult * atr[j] / (double)k15[j + 1].OpenPrice > 0.05) continue;
                    double entry = (double)k15[j + 1].OpenPrice; double peakP = entry; decimal net = 0m; int ei = n - 1; bool be = false;
                    for (int e = j + 1; e < n; e++)
                    {
                        double cc = close[e]; if (cc > peakP) peakP = cc;
                        double gain = (peakP - entry) / entry * 100;
                        if (lockPct > 0 && !be && gain >= lockPct) be = true;   // 본절 활성
                        double mult = (tightMult > 0 && gain >= tightAfterPct) ? tightMult : baseMult;
                        double trailStop = peakP - mult * atr[e];
                        if (be && trailStop < entry) trailStop = entry;          // 본절: 진입가 아래로 안 내려감
                        if (cc <= trailStop) { net = ((decimal)cc - (decimal)entry) / (decimal)entry - feeRT; ei = e; break; }
                        if (e == n - 1) net = ((decimal)cc - (decimal)entry) / (decimal)entry - feeRT;
                    }
                    busy = ei; trades.Add((k15[j + 1].OpenTime, k15[ei].OpenTime, net));
                }
            }
            trades.Sort((a, b) => a.ent.CompareTo(b.ent));
            var open = new List<DateTime>(); var monthly = new SortedDictionary<string, decimal>(); int tn = 0, win = 0;
            foreach (var t in trades) { open.RemoveAll(x => x <= t.ent); if (open.Count >= slots) continue; open.Add(t.ex); monthly[t.ent.ToString("yyyy-MM")] = (monthly.TryGetValue(t.ent.ToString("yyyy-MM"), out var v) ? v : 0m) + t.pnl * margin; tn++; if (t.pnl > 0) win++; }
            int prof = 0; decimal cum = 0m, peak = 0m, mdd = 0m, worst = 0m, tot = 0m; foreach (var kv in monthly) { if (kv.Value > 0) prof++; if (kv.Value < worst) worst = kv.Value; cum += kv.Value; tot += kv.Value; if (cum > peak) peak = cum; if (peak - cum > mdd) mdd = peak - cum; }
            int mo = Math.Max(1, monthly.Count);
            return (tn, 100.0 * prof / mo, (double)(tot / capital * 100m), (double)(mdd / capital * 100m), (double)(worst / capital * 100m), tn > 0 ? 100.0 * win / tn : 0);
        }
        Console.WriteLine($"\n  {"구성",28} {"진입",5} {"승률%",6} {"흑자월%",7} {"총수익%",8} {"MDD%",6} {"최악월%",7}");
        void Row(string nm, double lp, double tm, double ta, double bm) { var r = Run(lp, tm, ta, bm); Console.WriteLine($"  {nm,-28} {r.tn,5} {r.wr,6:F0} {r.prof,7:F0} {r.tot,8:F0} {r.mdd,6:F0} {r.worst,7:F1}"); }
        Row("현재(5ATR·본절없음)", 0, 0, 0, 5.0);
        Row("본절+1.5%", 1.5, 0, 0, 5.0);
        Row("본절+2%", 2.0, 0, 0, 5.0);
        Row("본절+2.5%", 2.5, 0, 0, 5.0);
        Row("본절+3%", 3.0, 0, 0, 5.0);
        Row("수익2%후 트레일3ATR", 0, 3.0, 2.0, 5.0);
        Row("수익2%후 트레일2.5ATR", 0, 2.5, 2.0, 5.0);
        Row("본절2%+수익3%후 2.5ATR", 2.0, 2.5, 3.0, 5.0);
        Console.WriteLine("\n  → 승률·흑자월↑ & 총수익 유지면 채택. 본절이 승자 자르면 총수익↓로 나타남.");
    }

    // --mtf-lossstat : 손절 전수 통계 — 모든 손실건을 유형(MFE·MAE·보유·RSI·코인·시간대)별로 분류. 고칠 패턴 발굴.
    private static async Task RunMtfLossStatAsync()
    {
        const int featureWindow = 500, K = 8, Lh = 4;
        const decimal feeRT = 0.0008m; double atrMult = 5.0; decimal margin = 1000m;
        var universe = new[] { "BTCUSDT","ETHUSDT","BNBUSDT","SOLUSDT","XRPUSDT","DOGEUSDT","ADAUSDT","AVAXUSDT","LINKUSDT","ARBUSDT","OPUSDT","SUIUSDT" };
        Console.WriteLine("=== MTF 손절 전수 통계 (왜 손절되는가 패턴 발굴) ===\n");
        List<(DateTime close, bool up)> Regime4h(List<IBinanceKline> b4)
        { int n = b4.Count; var e200 = new double[n]; for (int j = 200; j < n; j++) e200[j] = CalcEMA(b4, j, 200); var e50 = new double[n]; for (int j = 50; j < n; j++) e50[j] = CalcEMA(b4, j, 50); var adx = new double[n]; { double aS = 0, pS = 0, mS = 0; int per = 14; for (int j = 1; j < n; j++) { double hh = (double)b4[j].HighPrice, ll = (double)b4[j].LowPrice, pc = (double)b4[j - 1].ClosePrice, ph = (double)b4[j - 1].HighPrice, pl = (double)b4[j - 1].LowPrice; double tr = Math.Max(hh - ll, Math.Max(Math.Abs(hh - pc), Math.Abs(ll - pc))); double up = hh - ph, dn = pl - ll; double pdm = (up > dn && up > 0) ? up : 0, mdm = (dn > up && dn > 0) ? dn : 0; if (j <= per) { aS += tr; pS += pdm; mS += mdm; } else { aS = aS - aS / per + tr; pS = pS - pS / per + pdm; mS = mS - mS / per + mdm; } if (j >= per && aS > 0) { double pd = 100 * pS / aS, md = 100 * mS / aS; double dx = (pd + md) > 0 ? 100 * Math.Abs(pd - md) / (pd + md) : 0; adx[j] = j <= per * 2 ? dx : (adx[j - 1] * (per - 1) + dx) / per; } } } var r = new List<(DateTime, bool)>(); for (int j = 0; j < n; j++) { double c = (double)b4[j].ClosePrice; r.Add((b4[j].OpenTime.AddHours(4), j >= 200 && e50[j] > 0 && e200[j] > 0 && e50[j] > e200[j] && c > e50[j] && adx[j] >= 25)); } return r; }
        var btc4 = await FetchKlines4hAsync("BTCUSDT", 12); var btcAlign = Regime4h(btc4);
        // trade: sym, pnlPct, mfe(최대이익%), mae(최대손실%), held, rsi, hour
        var all = new List<(string sym, double pnl, double mfe, double mae, int held, double rsi, int hour)>();
        int ci = 0;
        foreach (var sym in universe)
        {
            ci++; Console.Write($"[{ci}/{universe.Length}] {sym} ");
            List<IBinanceKline> b4, k15;
            try { b4 = await FetchKlines4hAsync(sym, 12); k15 = await FetchKlines15mAsync(sym, 110); } catch { Console.WriteLine("fail"); continue; }
            if (b4.Count < 300 || k15.Count < 1000) { Console.WriteLine("skip"); continue; }
            var reg = Regime4h(b4);
            int n = k15.Count; Console.WriteLine($"{n}"); var close = new double[n]; for (int j = 0; j < n; j++) close[j] = (double)k15[j].ClosePrice;
            var feats = new float[n][]; for (int j = 60; j < n; j++) { int ws = Math.Max(0, j - (featureWindow - 1)); feats[j] = LorentzianFeatures.Extract(k15.GetRange(ws, j - ws + 1))!; }
            var e50 = new double[n]; for (int j = 50; j < n; j++) e50[j] = CalcEMA(k15, j, 50);
            var e200 = new double[n]; for (int j = 200; j < n; j++) e200[j] = CalcEMA(k15, j, 200);
            var atr = new double[n]; for (int j = 14; j < n; j++) { double tr = 0; for (int q = j - 13; q <= j; q++) { double hh = (double)k15[q].HighPrice, ll = (double)k15[q].LowPrice, pc = close[q - 1]; tr += Math.Max(hh - ll, Math.Max(Math.Abs(hh - pc), Math.Abs(ll - pc))); } atr[j] = tr / 14.0; }
            var rsi = new double[n]; { double ag = 0, al = 0; int per = 14; for (int j = 1; j < n; j++) { double ch = close[j] - close[j - 1]; double g = ch > 0 ? ch : 0, ls = ch < 0 ? -ch : 0; if (j <= per) { ag += g; al += ls; if (j == per) { ag /= per; al /= per; rsi[j] = al == 0 ? 100 : 100 - 100 / (1 + ag / al); } } else { ag = (ag * (per - 1) + g) / per; al = (al * (per - 1) + ls) / per; rsi[j] = al == 0 ? 100 : 100 - 100 / (1 + ag / al); } } }
            var engine = new LorentzianAnnEngine(sym, neighborsCount: K, maxBarsBack: 2000, featureCount: LorentzianFeatures.FeatureCount);
            var sg = new int[n];
            for (int j = 65; j < n; j++) { int s = j - 1; if (s - Lh >= 0 && feats[s] != null) { double a = close[s], b = close[s - Lh]; engine.AddSample(feats[s], a > b ? 1 : (a < b ? -1 : 0)); } if (feats[j] == null) continue; var p = engine.Predict(feats[j]); if (!p.IsReady || p.K == 0) continue; sg[j] = p.Prediction > 0 ? 1 : (p.Prediction < 0 ? -1 : 0); }
            int rp = 0, bp = 0, busy = -1;
            for (int j = 250; j < n - 1; j++)
            {
                if (j <= busy) continue;
                var t15 = k15[j].OpenTime;
                while (rp + 1 < reg.Count && reg[rp + 1].Item1 <= t15) rp++;
                while (bp + 1 < btcAlign.Count && btcAlign[bp + 1].Item1 <= t15) bp++;
                if (!(reg[rp].Item1 <= t15 && reg[rp].Item2) || !(btcAlign[bp].Item1 <= t15 && btcAlign[bp].Item2)) continue;
                if (!(sg[j] > 0 && e50[j] > 0 && e200[j] > 0 && e50[j] > e200[j] && close[j] > e50[j])) continue;
                if (atr[j] <= 0 || k15[j + 1].OpenPrice <= 0) continue;
                if ((close[j] - e50[j]) / atr[j] >= 2.0 || rsi[j] >= 60.0) continue;
                if (atrMult * atr[j] / (double)k15[j + 1].OpenPrice > 0.05) continue;   // v5.27.1 손절폭 상한 반영
                double entry = (double)k15[j + 1].OpenPrice; double peakP = entry, minL = entry, maxH = entry; double net = 0; int ei = n - 1;
                for (int e = j + 1; e < n; e++) { double cc = close[e]; double hi = (double)k15[e].HighPrice, lo = (double)k15[e].LowPrice; if (hi > maxH) maxH = hi; if (lo < minL) minL = lo; if (cc > peakP) peakP = cc; if (cc <= peakP - atrMult * atr[e]) { net = (cc - entry) / entry - (double)feeRT; ei = e; break; } if (e == n - 1) net = (cc - entry) / entry - (double)feeRT; }
                busy = ei;
                all.Add((sym, net, (maxH - entry) / entry * 100, (minL - entry) / entry * 100, ei - j, rsi[j], k15[j + 1].OpenTime.Hour));
            }
        }
        var L = all.Where(x => x.pnl < 0).ToList(); var W = all.Where(x => x.pnl >= 0).ToList();
        Console.WriteLine($"\n총 {all.Count}건 · 승 {W.Count}({100.0 * W.Count / all.Count:F0}%) · 패 {L.Count}({100.0 * L.Count / all.Count:F0}%)");
        Console.WriteLine($"패자 평균: 손실 {L.Average(x => x.pnl) * 100:F2}% · MFE(최대이익) {L.Average(x => x.mfe):F2}% · 보유 {L.Average(x => x.held):F0}봉");
        // 1) MFE 유형별 (손절 전에 이익을 냈었나?)
        Console.WriteLine("\n── ① 손절 유형: 손절 전 최대이익(MFE)이 얼마였나 ──");
        void MfeBucket(string nm, Func<double, bool> f) { var g = L.Where(x => f(x.mfe)).ToList(); if (g.Count == 0) return; Console.WriteLine($"   {nm,-28} {g.Count,4}건 ({100.0 * g.Count / L.Count,4:F0}%) · 평균손실 {g.Average(x => x.pnl) * 100,6:F2}% · 평균보유 {g.Average(x => x.held),3:F0}봉"); }
        MfeBucket("못오름 (MFE<0.5%)", m => m < 0.5);
        MfeBucket("조금올랐다 반전 (0.5~2%)", m => m >= 0.5 && m < 2);
        MfeBucket("2~4% 냈다 반납", m => m >= 2 && m < 4);
        MfeBucket("★4%+ 냈다 반납(큰 반납)", m => m >= 4);
        // 2) 보유봉
        Console.WriteLine("\n── ② 보유 기간별 ──");
        void HeldBucket(string nm, Func<int, bool> f) { var g = L.Where(x => f(x.held)).ToList(); if (g.Count == 0) return; Console.WriteLine($"   {nm,-16} {g.Count,4}건 ({100.0 * g.Count / L.Count,4:F0}%) · 평균손실 {g.Average(x => x.pnl) * 100,6:F2}% · MFE {g.Average(x => x.mfe),5:F2}%"); }
        HeldBucket("즉시 (≤4봉/1h)", h => h <= 4);
        HeldBucket("단기 (5~16봉/4h)", h => h > 4 && h <= 16);
        HeldBucket("중기 (17~48봉/12h)", h => h > 16 && h <= 48);
        HeldBucket("장기 (48봉+/12h+)", h => h > 48);
        // 3) 코인별 승률
        Console.WriteLine("\n── ③ 코인별 승률 (낮은 순) ──");
        foreach (var g in all.GroupBy(x => x.sym).Select(g => (sym: g.Key, n: g.Count(), wr: 100.0 * g.Count(x => x.pnl >= 0) / g.Count(), pnl: g.Sum(x => x.pnl) * (double)margin)).OrderBy(x => x.wr).Take(6))
            Console.WriteLine($"   {g.sym,-10} {g.n,4}건 · 승률 {g.wr,4:F0}% · 총손익 ${g.pnl,6:F0}");
        // 4) 진입 시간대별 승률 (UTC)
        Console.WriteLine("\n── ④ 진입 시간대(UTC)별 승률 — 하위 6개 ──");
        foreach (var g in all.GroupBy(x => x.hour).Select(g => (h: g.Key, n: g.Count(), wr: 100.0 * g.Count(x => x.pnl >= 0) / g.Count())).OrderBy(x => x.wr).Take(6))
            Console.WriteLine($"   {g.h,2}시 {g.n,4}건 · 승률 {g.wr,4:F0}%");
        // 5) 진입 RSI 버킷별 승률
        Console.WriteLine("\n── ⑤ 진입 RSI별 승률 ──");
        foreach (var (lo, hi) in new[] { (0.0, 40.0), (40.0, 45.0), (45.0, 50.0), (50.0, 55.0), (55.0, 60.0) })
        { var g = all.Where(x => x.rsi >= lo && x.rsi < hi).ToList(); if (g.Count == 0) continue; Console.WriteLine($"   RSI {lo:F0}~{hi:F0}  {g.Count,4}건 · 승률 {100.0 * g.Count(x => x.pnl >= 0) / g.Count,4:F0}% · 총손익 ${g.Sum(x => x.pnl) * (double)margin,6:F0}"); }
        Console.WriteLine("\n  → '4%+ 냈다 반납'이 많으면 = 익절보호 필요 / '못오름' 많으면 = 진입질 / 특정코인·시간·RSI 편중이면 = 그 조건 필터.");
    }

    // --mtf-stopcap : 손절폭(변동성) 상한 스윕 — 5×ATR이 진입가 X% 넘는 고변동 진입 스킵. 대형손실 제거 검증.
    private static async Task RunMtfStopcapAsync()
    {
        const int featureWindow = 500, K = 8, Lh = 4;
        const decimal feeRT = 0.0008m; double atrMult = 5.0; decimal margin = 1000m; int slots = 6; decimal capital = margin * slots;
        var universe = new[] { "BTCUSDT","ETHUSDT","BNBUSDT","SOLUSDT","XRPUSDT","DOGEUSDT","ADAUSDT","AVAXUSDT","LINKUSDT","ARBUSDT","OPUSDT","SUIUSDT" };
        Console.WriteLine("=== 손절폭 상한 스윕 (5ATR/진입가 > cap 스킵) — 대형손실 제거 검증 ===\n");
        List<(DateTime close, bool up)> Regime4h(List<IBinanceKline> b4)
        { int n = b4.Count; var e200 = new double[n]; for (int j = 200; j < n; j++) e200[j] = CalcEMA(b4, j, 200); var e50 = new double[n]; for (int j = 50; j < n; j++) e50[j] = CalcEMA(b4, j, 50); var adx = new double[n]; { double aS = 0, pS = 0, mS = 0; int per = 14; for (int j = 1; j < n; j++) { double hh = (double)b4[j].HighPrice, ll = (double)b4[j].LowPrice, pc = (double)b4[j - 1].ClosePrice, ph = (double)b4[j - 1].HighPrice, pl = (double)b4[j - 1].LowPrice; double tr = Math.Max(hh - ll, Math.Max(Math.Abs(hh - pc), Math.Abs(ll - pc))); double up = hh - ph, dn = pl - ll; double pdm = (up > dn && up > 0) ? up : 0, mdm = (dn > up && dn > 0) ? dn : 0; if (j <= per) { aS += tr; pS += pdm; mS += mdm; } else { aS = aS - aS / per + tr; pS = pS - pS / per + pdm; mS = mS - mS / per + mdm; } if (j >= per && aS > 0) { double pd = 100 * pS / aS, md = 100 * mS / aS; double dx = (pd + md) > 0 ? 100 * Math.Abs(pd - md) / (pd + md) : 0; adx[j] = j <= per * 2 ? dx : (adx[j - 1] * (per - 1) + dx) / per; } } } var r = new List<(DateTime, bool)>(); for (int j = 0; j < n; j++) { double c = (double)b4[j].ClosePrice; r.Add((b4[j].OpenTime.AddHours(4), j >= 200 && e50[j] > 0 && e200[j] > 0 && e50[j] > e200[j] && c > e50[j] && adx[j] >= 25)); } return r; }
        var btc4 = await FetchKlines4hAsync("BTCUSDT", 12); var btcAlign = Regime4h(btc4);
        var data = new List<(List<IBinanceKline> k15, double[] close, int[] sg, double[] e50, double[] e200, double[] atr, double[] rsi, List<(DateTime, bool)> reg)>();
        int ci = 0;
        foreach (var sym in universe)
        {
            ci++; Console.Write($"[{ci}/{universe.Length}] {sym} ");
            List<IBinanceKline> b4, k15;
            try { b4 = await FetchKlines4hAsync(sym, 12); k15 = await FetchKlines15mAsync(sym, 110); } catch { Console.WriteLine("fail"); continue; }
            if (b4.Count < 300 || k15.Count < 1000) { Console.WriteLine("skip"); continue; }
            var reg = Regime4h(b4);
            int n = k15.Count; Console.WriteLine($"{n}"); var close = new double[n]; for (int j = 0; j < n; j++) close[j] = (double)k15[j].ClosePrice;
            var feats = new float[n][]; for (int j = 60; j < n; j++) { int ws = Math.Max(0, j - (featureWindow - 1)); feats[j] = LorentzianFeatures.Extract(k15.GetRange(ws, j - ws + 1))!; }
            var e50 = new double[n]; for (int j = 50; j < n; j++) e50[j] = CalcEMA(k15, j, 50);
            var e200 = new double[n]; for (int j = 200; j < n; j++) e200[j] = CalcEMA(k15, j, 200);
            var atr = new double[n]; for (int j = 14; j < n; j++) { double tr = 0; for (int q = j - 13; q <= j; q++) { double hh = (double)k15[q].HighPrice, ll = (double)k15[q].LowPrice, pc = close[q - 1]; tr += Math.Max(hh - ll, Math.Max(Math.Abs(hh - pc), Math.Abs(ll - pc))); } atr[j] = tr / 14.0; }
            var rsi = new double[n]; { double ag = 0, al = 0; int per = 14; for (int j = 1; j < n; j++) { double ch = close[j] - close[j - 1]; double g = ch > 0 ? ch : 0, ls = ch < 0 ? -ch : 0; if (j <= per) { ag += g; al += ls; if (j == per) { ag /= per; al /= per; rsi[j] = al == 0 ? 100 : 100 - 100 / (1 + ag / al); } } else { ag = (ag * (per - 1) + g) / per; al = (al * (per - 1) + ls) / per; rsi[j] = al == 0 ? 100 : 100 - 100 / (1 + ag / al); } } }
            var engine = new LorentzianAnnEngine(sym, neighborsCount: K, maxBarsBack: 2000, featureCount: LorentzianFeatures.FeatureCount);
            var sg = new int[n];
            for (int j = 65; j < n; j++) { int s = j - 1; if (s - Lh >= 0 && feats[s] != null) { double a = close[s], b = close[s - Lh]; engine.AddSample(feats[s], a > b ? 1 : (a < b ? -1 : 0)); } if (feats[j] == null) continue; var p = engine.Predict(feats[j]); if (!p.IsReady || p.K == 0) continue; sg[j] = p.Prediction > 0 ? 1 : (p.Prediction < 0 ? -1 : 0); }
            data.Add((k15, close, sg, e50, e200, atr, rsi, reg));
        }
        Console.WriteLine($"\n  {"손절상한",8} {"진입",5} {"월평균",6} {"흑자월%",7} {"총수익%",8} {"MDD%",6} {"최악월%",7} {"최악건%",7}");
        foreach (double cap in new[] { 99.0, 0.06, 0.05, 0.04, 0.03 })
        {
            var trades = new List<(DateTime ent, DateTime ex, decimal pnl)>(); double worstTrade = 0;
            foreach (var (k15, close, sg, e50, e200, atr, rsi, reg) in data)
            {
                int n = k15.Count; int rp = 0, bp = 0, busy = -1;
                for (int j = 250; j < n - 1; j++)
                {
                    if (j <= busy) continue;
                    var t15 = k15[j].OpenTime;
                    while (rp + 1 < reg.Count && reg[rp + 1].Item1 <= t15) rp++;
                    while (bp + 1 < btcAlign.Count && btcAlign[bp + 1].Item1 <= t15) bp++;
                    if (!(reg[rp].Item1 <= t15 && reg[rp].Item2) || !(btcAlign[bp].Item1 <= t15 && btcAlign[bp].Item2)) continue;
                    if (!(sg[j] > 0 && e50[j] > 0 && e200[j] > 0 && e50[j] > e200[j] && close[j] > e50[j])) continue;
                    if (atr[j] <= 0 || k15[j + 1].OpenPrice <= 0) continue;
                    if ((close[j] - e50[j]) / atr[j] >= 2.0 || rsi[j] >= 60.0) continue;
                    double entry = (double)k15[j + 1].OpenPrice;
                    if (atrMult * atr[j] / entry > cap) continue;   // ★손절폭 상한: 5ATR이 진입가 cap% 넘으면 스킵
                    double peakP = entry; decimal net = 0m; int ei = n - 1;
                    for (int e = j + 1; e < n; e++) { double cc = close[e]; if (cc > peakP) peakP = cc; if (cc <= peakP - atrMult * atr[e]) { net = ((decimal)cc - (decimal)entry) / (decimal)entry - feeRT; ei = e; break; } if (e == n - 1) net = ((decimal)cc - (decimal)entry) / (decimal)entry - feeRT; }
                    if ((double)net < worstTrade) worstTrade = (double)net;
                    busy = ei; trades.Add((k15[j + 1].OpenTime, k15[ei].OpenTime, net));
                }
            }
            trades.Sort((a, b) => a.ent.CompareTo(b.ent));
            var open = new List<DateTime>(); var monthly = new SortedDictionary<string, decimal>(); int tn = 0;
            foreach (var t in trades) { open.RemoveAll(x => x <= t.ent); if (open.Count >= slots) continue; open.Add(t.ex); monthly[t.ent.ToString("yyyy-MM")] = (monthly.TryGetValue(t.ent.ToString("yyyy-MM"), out var v) ? v : 0m) + t.pnl * margin; tn++; }
            int prof = 0; decimal cum = 0m, peak = 0m, mdd = 0m, worst = 0m, tot = 0m; foreach (var kv in monthly) { if (kv.Value > 0) prof++; if (kv.Value < worst) worst = kv.Value; cum += kv.Value; tot += kv.Value; if (cum > peak) peak = cum; if (peak - cum > mdd) mdd = peak - cum; }
            int mo = Math.Max(1, monthly.Count);
            Console.WriteLine($"  {(cap > 1 ? "없음" : (cap * 100).ToString("F0") + "%"),8} {tn,5} {tn / (double)mo,6:F1} {100.0 * prof / mo,7:F0} {(double)(tot / capital * 100m),8:F0} {(double)(mdd / capital * 100m),6:F0} {(double)(worst / capital * 100m),7:F1} {worstTrade * 100,7:F1}");
        }
        Console.WriteLine("\n  → 상한 낮출수록 최악건↓·MDD↓, 총수익/흑자월 유지되는 지점이 최적. 대형손실 제거.");
    }

    // --mtf-worst : MTF 손실 트레이드 점검 — 큰 손실건의 진입가·손절선(진입−5ATR)·이탈가·최대역행·손실원인 진단.
    private static async Task RunMtfWorstAsync()
    {
        const int featureWindow = 500, K = 8, Lh = 4;
        const decimal feeRT = 0.0008m; double atrMult = 5.0; decimal margin = 1000m;
        var universe = new[] { "BTCUSDT","ETHUSDT","BNBUSDT","SOLUSDT","XRPUSDT","DOGEUSDT","ADAUSDT","AVAXUSDT","LINKUSDT","ARBUSDT","OPUSDT","SUIUSDT" };
        Console.WriteLine("=== MTF 손실 트레이드 점검 (진입·손절선·이탈·원인) ===\n");
        List<(DateTime close, bool up)> Regime4h(List<IBinanceKline> b4)
        { int n = b4.Count; var e200 = new double[n]; for (int j = 200; j < n; j++) e200[j] = CalcEMA(b4, j, 200); var e50 = new double[n]; for (int j = 50; j < n; j++) e50[j] = CalcEMA(b4, j, 50); var adx = new double[n]; { double aS = 0, pS = 0, mS = 0; int per = 14; for (int j = 1; j < n; j++) { double hh = (double)b4[j].HighPrice, ll = (double)b4[j].LowPrice, pc = (double)b4[j - 1].ClosePrice, ph = (double)b4[j - 1].HighPrice, pl = (double)b4[j - 1].LowPrice; double tr = Math.Max(hh - ll, Math.Max(Math.Abs(hh - pc), Math.Abs(ll - pc))); double up = hh - ph, dn = pl - ll; double pdm = (up > dn && up > 0) ? up : 0, mdm = (dn > up && dn > 0) ? dn : 0; if (j <= per) { aS += tr; pS += pdm; mS += mdm; } else { aS = aS - aS / per + tr; pS = pS - pS / per + pdm; mS = mS - mS / per + mdm; } if (j >= per && aS > 0) { double pd = 100 * pS / aS, md = 100 * mS / aS; double dx = (pd + md) > 0 ? 100 * Math.Abs(pd - md) / (pd + md) : 0; adx[j] = j <= per * 2 ? dx : (adx[j - 1] * (per - 1) + dx) / per; } } } var r = new List<(DateTime, bool)>(); for (int j = 0; j < n; j++) { double c = (double)b4[j].ClosePrice; r.Add((b4[j].OpenTime.AddHours(4), j >= 200 && e50[j] > 0 && e200[j] > 0 && e50[j] > e200[j] && c > e50[j] && adx[j] >= 25)); } return r; }
        var btc4 = await FetchKlines4hAsync("BTCUSDT", 12); var btcAlign = Regime4h(btc4);
        // trade: sym,ent,entryPx,exitPx,stopAtExit,minLow,rsi,extAtr,held,pnlPct
        var trades = new List<(string sym, DateTime ent, double entry, double exit, double stopExit, double minLow, double rsi, double ext, int held)>();
        int ci = 0;
        foreach (var sym in universe)
        {
            ci++; Console.Write($"[{ci}/{universe.Length}] {sym} ");
            List<IBinanceKline> b4, k15;
            try { b4 = await FetchKlines4hAsync(sym, 12); k15 = await FetchKlines15mAsync(sym, 110); } catch { Console.WriteLine("fail"); continue; }
            if (b4.Count < 300 || k15.Count < 1000) { Console.WriteLine("skip"); continue; }
            var reg = Regime4h(b4);
            int n = k15.Count; Console.WriteLine($"{n}"); var close = new double[n]; for (int j = 0; j < n; j++) close[j] = (double)k15[j].ClosePrice;
            var feats = new float[n][]; for (int j = 60; j < n; j++) { int ws = Math.Max(0, j - (featureWindow - 1)); feats[j] = LorentzianFeatures.Extract(k15.GetRange(ws, j - ws + 1))!; }
            var e50 = new double[n]; for (int j = 50; j < n; j++) e50[j] = CalcEMA(k15, j, 50);
            var e200 = new double[n]; for (int j = 200; j < n; j++) e200[j] = CalcEMA(k15, j, 200);
            var atr = new double[n]; for (int j = 14; j < n; j++) { double tr = 0; for (int q = j - 13; q <= j; q++) { double hh = (double)k15[q].HighPrice, ll = (double)k15[q].LowPrice, pc = close[q - 1]; tr += Math.Max(hh - ll, Math.Max(Math.Abs(hh - pc), Math.Abs(ll - pc))); } atr[j] = tr / 14.0; }
            var rsi = new double[n]; { double ag = 0, al = 0; int per = 14; for (int j = 1; j < n; j++) { double ch = close[j] - close[j - 1]; double g = ch > 0 ? ch : 0, ls = ch < 0 ? -ch : 0; if (j <= per) { ag += g; al += ls; if (j == per) { ag /= per; al /= per; rsi[j] = al == 0 ? 100 : 100 - 100 / (1 + ag / al); } } else { ag = (ag * (per - 1) + g) / per; al = (al * (per - 1) + ls) / per; rsi[j] = al == 0 ? 100 : 100 - 100 / (1 + ag / al); } } }
            var engine = new LorentzianAnnEngine(sym, neighborsCount: K, maxBarsBack: 2000, featureCount: LorentzianFeatures.FeatureCount);
            var sg = new int[n];
            for (int j = 65; j < n; j++) { int s = j - 1; if (s - Lh >= 0 && feats[s] != null) { double a = close[s], b = close[s - Lh]; engine.AddSample(feats[s], a > b ? 1 : (a < b ? -1 : 0)); } if (feats[j] == null) continue; var p = engine.Predict(feats[j]); if (!p.IsReady || p.K == 0) continue; sg[j] = p.Prediction > 0 ? 1 : (p.Prediction < 0 ? -1 : 0); }
            int rp = 0, bp = 0, busy = -1;
            for (int j = 250; j < n - 1; j++)
            {
                if (j <= busy) continue;
                var t15 = k15[j].OpenTime;
                while (rp + 1 < reg.Count && reg[rp + 1].close <= t15) rp++;
                while (bp + 1 < btcAlign.Count && btcAlign[bp + 1].close <= t15) bp++;
                if (!(reg[rp].close <= t15 && reg[rp].up) || !(btcAlign[bp].close <= t15 && btcAlign[bp].up)) continue;
                if (!(sg[j] > 0 && e50[j] > 0 && e200[j] > 0 && e50[j] > e200[j] && close[j] > e50[j])) continue;
                if (atr[j] <= 0 || k15[j + 1].OpenPrice <= 0) continue;
                if ((close[j] - e50[j]) / atr[j] >= 2.0 || rsi[j] >= 60.0) continue;
                double entry = (double)k15[j + 1].OpenPrice; double peakP = entry, minLow = entry; double net = 0, stopExit = entry - atrMult * atr[j]; int ei = n - 1;
                for (int e = j + 1; e < n; e++) { double cc = close[e]; double lo = (double)k15[e].LowPrice; if (lo < minLow) minLow = lo; if (cc > peakP) peakP = cc; double st = peakP - atrMult * atr[e]; if (cc <= st) { net = (cc - entry) / entry - (double)feeRT; ei = e; stopExit = st; break; } if (e == n - 1) { net = (cc - entry) / entry - (double)feeRT; stopExit = st; } }
                busy = ei; trades.Add((sym, k15[j + 1].OpenTime, entry, (double)close[ei], stopExit, minLow, rsi[j], (close[j] - e50[j]) / atr[j], ei - j));
            }
        }
        // pnl% 계산 후 손실 큰 순
        var withPnl = trades.Select(t => (t, pnlPct: (t.exit - t.entry) / t.entry - (double)feeRT)).ToList();
        Console.WriteLine($"\n총 {trades.Count} 트레이드 · 손실건 {withPnl.Count(x => x.pnlPct < 0)}");
        Console.WriteLine($"\n── 최대 손실 25건 (마진$1,000·1x 기준 손익$, 레버시 ×배) ──");
        Console.WriteLine($"  {"심볼",9} {"진입시각",16} {"손실%",6} {"손실$1x",7} {"진입가",11} {"손절선",11} {"이탈가",11} {"최저가",11} {"손절이탈%",8} {"보유봉",5} {"진입RSI",6}");
        foreach (var x in withPnl.Where(x => x.pnlPct < 0).OrderBy(x => x.pnlPct).Take(25))
        {
            var t = x.t; double lossUsd = x.pnlPct * (double)margin;
            double stopBreak = t.stopExit > 0 ? (t.exit - t.stopExit) / t.stopExit * 100 : 0;   // 이탈가가 손절선 대비(음수=손절선 아래로 갭)
            Console.WriteLine($"  {t.sym,9} {t.ent:MM-dd HH:mm} {x.pnlPct * 100,6:F1} {lossUsd,7:F0} {t.entry,11:F4} {t.stopExit,11:F4} {t.exit,11:F4} {t.minLow,11:F4} {stopBreak,8:F2} {t.held,5} {t.rsi,6:F0}");
        }
        // 손실 원인 집계
        var losers = withPnl.Where(x => x.pnlPct < 0).ToList();
        int gapBreak = losers.Count(x => x.t.stopExit > 0 && (x.t.exit - x.t.stopExit) / x.t.stopExit < -0.003);   // 손절선보다 0.3%+ 아래로 이탈(갭)
        int quick = losers.Count(x => x.t.held <= 3);
        Console.WriteLine($"\n  손실 {losers.Count}건 중: 손절선 아래로 갭이탈(0.3%+) {gapBreak}건 · 즉시역행(3봉내) {quick}건 · 평균손실 {losers.Average(x => x.pnlPct) * 100:F2}% (${losers.Average(x => x.pnlPct) * (double)margin:F0}/1x)");
        Console.WriteLine("  → 손실이 대부분 손절선 근처(갭 적음)면 = 손절 정상작동, 진입이 반전자리. 갭이탈 많으면 = 손절선이 늦음(틱 아닌 종가라).");
    }

    // --mtf-4h15m : ★멀티TF — 4h/BTC로 방향(상승) 판단 + 15m로 진입. 빈도↑ & 월0 문제 해결 검증.
    //   4h 상승레짐(EMA50>200·close>EMA50·ADX≥25) + BTC 4h정배열 일 때만, 15m KNN매수+EMA정배열+방어에서 진입. 15m 종가트레일.
    private static async Task RunMtf4h15mAsync()
    {
        const int featureWindow = 500, K = 8, Lh = 4;
        const decimal feeRT = 0.0008m; double atrMult = 5.0;
        decimal margin = 1000m; int slots = 6; decimal capital = margin * slots;
        var universe = new[] { "BTCUSDT","ETHUSDT","BNBUSDT","SOLUSDT","XRPUSDT","DOGEUSDT","ADAUSDT","AVAXUSDT","LINKUSDT","ARBUSDT","OPUSDT","SUIUSDT" };
        Console.WriteLine("=== 멀티TF: 4h방향 + 15m진입 (마진$1,000×6·1x) — 빈도·월0 개선 검증 ===\n");
        // 4h 상승레짐 판정 함수: 리스트+인덱스 → up
        List<(DateTime close, bool up)> Regime4h(List<IBinanceKline> b4)
        {
            int n = b4.Count; var e200 = new double[n]; for (int j = 200; j < n; j++) e200[j] = CalcEMA(b4, j, 200);
            var e50 = new double[n]; for (int j = 50; j < n; j++) e50[j] = CalcEMA(b4, j, 50);
            var adx = new double[n]; { double aS = 0, pS = 0, mS = 0; int per = 14; for (int j = 1; j < n; j++) { double hh = (double)b4[j].HighPrice, ll = (double)b4[j].LowPrice, pc = (double)b4[j - 1].ClosePrice, ph = (double)b4[j - 1].HighPrice, pl = (double)b4[j - 1].LowPrice; double tr = Math.Max(hh - ll, Math.Max(Math.Abs(hh - pc), Math.Abs(ll - pc))); double up = hh - ph, dn = pl - ll; double pdm = (up > dn && up > 0) ? up : 0, mdm = (dn > up && dn > 0) ? dn : 0; if (j <= per) { aS += tr; pS += pdm; mS += mdm; } else { aS = aS - aS / per + tr; pS = pS - pS / per + pdm; mS = mS - mS / per + mdm; } if (j >= per && aS > 0) { double pd = 100 * pS / aS, md = 100 * mS / aS; double dx = (pd + md) > 0 ? 100 * Math.Abs(pd - md) / (pd + md) : 0; adx[j] = j <= per * 2 ? dx : (adx[j - 1] * (per - 1) + dx) / per; } } }
            var r = new List<(DateTime, bool)>();
            for (int j = 0; j < n; j++) { double c = (double)b4[j].ClosePrice; bool up = j >= 200 && e50[j] > 0 && e200[j] > 0 && e50[j] > e200[j] && c > e50[j] && adx[j] >= 25; r.Add((b4[j].OpenTime.AddHours(4), up)); }
            return r;   // close시각(=다음 진입 유효 시작)
        }
        var btc4 = await FetchKlines4hAsync("BTCUSDT", 12);
        var btcReg = Regime4h(btc4).Select(x => { double c = 0; return x; }).ToList();
        // BTC 완전정배열도 같이 (Regime4h의 up이 이미 정배열+ADX; BTC는 ADX 없이 정배열만 쓰자)
        List<(DateTime close, bool up)> BtcAlign(List<IBinanceKline> b4)
        { int n = b4.Count; var e200 = new double[n]; for (int j = 200; j < n; j++) e200[j] = CalcEMA(b4, j, 200); var e50 = new double[n]; for (int j = 50; j < n; j++) e50[j] = CalcEMA(b4, j, 50); var r = new List<(DateTime, bool)>(); for (int j = 0; j < n; j++) { double c = (double)b4[j].ClosePrice; r.Add((b4[j].OpenTime.AddHours(4), j >= 200 && e50[j] > 0 && e200[j] > 0 && c > e50[j] && e50[j] > e200[j])); } return r; }
        var btcAlign = BtcAlign(btc4);
        var allTrades = new List<(DateTime ent, DateTime ex, decimal pnl)>();
        int ci = 0;
        foreach (var sym in universe)
        {
            ci++; Console.Write($"[{ci}/{universe.Length}] {sym} ");
            List<IBinanceKline> b4, k15;
            try { b4 = await FetchKlines4hAsync(sym, 12); k15 = await FetchKlines15mAsync(sym, 110); } catch { Console.WriteLine("fail"); continue; }
            if (b4.Count < 300 || k15.Count < 1000) { Console.WriteLine($"skip"); continue; }
            var reg = Regime4h(b4);
            int n = k15.Count; Console.WriteLine($"15m={n} 4h={b4.Count}");
            var close = new double[n]; for (int j = 0; j < n; j++) close[j] = (double)k15[j].ClosePrice;
            var feats = new float[n][]; for (int j = 60; j < n; j++) { int ws = Math.Max(0, j - (featureWindow - 1)); feats[j] = LorentzianFeatures.Extract(k15.GetRange(ws, j - ws + 1))!; }
            var e50 = new double[n]; for (int j = 50; j < n; j++) e50[j] = CalcEMA(k15, j, 50);
            var e200 = new double[n]; for (int j = 200; j < n; j++) e200[j] = CalcEMA(k15, j, 200);
            var atr = new double[n]; for (int j = 14; j < n; j++) { double tr = 0; for (int q = j - 13; q <= j; q++) { double hh = (double)k15[q].HighPrice, ll = (double)k15[q].LowPrice, pc = close[q - 1]; tr += Math.Max(hh - ll, Math.Max(Math.Abs(hh - pc), Math.Abs(ll - pc))); } atr[j] = tr / 14.0; }
            var rsi = new double[n]; { double ag = 0, al = 0; int per = 14; for (int j = 1; j < n; j++) { double ch = close[j] - close[j - 1]; double g = ch > 0 ? ch : 0, ls = ch < 0 ? -ch : 0; if (j <= per) { ag += g; al += ls; if (j == per) { ag /= per; al /= per; rsi[j] = al == 0 ? 100 : 100 - 100 / (1 + ag / al); } } else { ag = (ag * (per - 1) + g) / per; al = (al * (per - 1) + ls) / per; rsi[j] = al == 0 ? 100 : 100 - 100 / (1 + ag / al); } } }
            var engine = new LorentzianAnnEngine(sym, neighborsCount: K, maxBarsBack: 2000, featureCount: LorentzianFeatures.FeatureCount);
            var sg = new int[n];
            for (int j = 65; j < n; j++) { int s = j - 1; if (s - Lh >= 0 && feats[s] != null) { double a = close[s], b = close[s - Lh]; engine.AddSample(feats[s], a > b ? 1 : (a < b ? -1 : 0)); } if (feats[j] == null) continue; var p = engine.Predict(feats[j]); if (!p.IsReady || p.K == 0) continue; sg[j] = p.Prediction > 0 ? 1 : (p.Prediction < 0 ? -1 : 0); }
            // 4h 레짐 정렬 포인터 (해당 심볼 reg + BTC align)
            int rp = 0, bp = 0; int busy = -1;
            for (int j = 250; j < n - 1; j++)
            {
                if (j <= busy) continue;
                var t15 = k15[j].OpenTime;
                while (rp + 1 < reg.Count && reg[rp + 1].close <= t15) rp++;   // 마지막 마감 4h
                while (bp + 1 < btcAlign.Count && btcAlign[bp + 1].close <= t15) bp++;
                bool dirUp = reg[rp].close <= t15 && reg[rp].up;
                bool btcUp = btcAlign[bp].close <= t15 && btcAlign[bp].up;
                if (!dirUp || !btcUp) continue;                                   // 4h 방향 상승 + BTC 정배열만
                if (!(sg[j] > 0 && e50[j] > 0 && e200[j] > 0 && e50[j] > e200[j] && close[j] > e50[j])) continue;   // 15m 진입조건
                if (atr[j] <= 0 || k15[j + 1].OpenPrice <= 0) continue;
                if ((close[j] - e50[j]) / atr[j] >= 2.0 || rsi[j] >= 60.0) continue;   // 방어
                decimal entry = k15[j + 1].OpenPrice; double peakP = (double)entry; decimal net = 0m; int ei = n - 1;
                for (int e = j + 1; e < n; e++) { double cc = close[e]; if (cc > peakP) peakP = cc; if (cc <= peakP - atrMult * atr[e]) { net = ((decimal)cc - entry) / entry - feeRT; ei = e; break; } if (e == n - 1) net = ((decimal)cc - entry) / entry - feeRT; }
                busy = ei; allTrades.Add((k15[j + 1].OpenTime, k15[ei].OpenTime, net));
            }
        }
        allTrades.Sort((a, b) => a.ent.CompareTo(b.ent));
        var open = new List<DateTime>(); var monthly = new SortedDictionary<string, (int n, decimal pnl)>(); int tn = 0;
        foreach (var t in allTrades) { open.RemoveAll(x => x <= t.ent); if (open.Count >= slots) continue; open.Add(t.ex); var mk = t.ent.ToString("yyyy-MM"); var mc = monthly.TryGetValue(mk, out var mv) ? mv : (0, 0m); monthly[mk] = (mc.Item1 + 1, mc.Item2 + t.pnl * margin); tn++; }
        int prof = 0; decimal cum = 0m, peak = 0m, mdd = 0m, worst = 0m, tot = 0m;
        Console.WriteLine($"\n  {"월",8} {"진입",5} {"수익금$",10} {"월수익률%",9} {"누적$",11}");
        var inv = System.Globalization.CultureInfo.InvariantCulture; var sb = new System.Text.StringBuilder(); sb.Append('['); bool jf = true;
        foreach (var kv in monthly) { cum += kv.Value.pnl; if (kv.Value.pnl > 0) prof++; if (kv.Value.pnl < worst) worst = kv.Value.pnl; tot += kv.Value.pnl; if (cum > peak) peak = cum; if (peak - cum > mdd) mdd = peak - cum; double ret = (double)(kv.Value.pnl / capital * 100m); Console.WriteLine($"  {kv.Key,8} {kv.Value.n,5} {kv.Value.pnl,10:F0} {ret,9:F1} {cum,11:F0}"); if (!jf) sb.Append(','); jf = false; sb.Append($"{{\"m\":\"{kv.Key}\",\"n\":{kv.Value.n},\"pnl\":{kv.Value.pnl.ToString("F0", inv)},\"ret\":{ret.ToString("F1", inv)},\"cum\":{cum.ToString("F0", inv)}}}"); }
        sb.Append(']'); System.IO.File.WriteAllText("mtf-monthly.json", sb.ToString());
        int mo = Math.Max(1, monthly.Count);
        Console.WriteLine($"\n  총 {mo}개월 · 진입 {tn}(월평균 {tn / (double)mo:F1}) · 흑자월 {prof}/{mo}({100.0 * prof / mo:F0}%) · 총 ${tot:F0}({(double)(tot / capital * 100m):F0}%) · MDD {(double)(mdd / capital * 100m):F0}% · 최악월 {(double)(worst / capital * 100m):F1}%");
        Console.WriteLine("  → 4h만(월평균 6건)보다 진입↑ & 흑자월%·수익 유지면 = MTF 채택.");
    }

    // --mtf-final : ★라이브 v5.27.3 정확재현 월별리포트. 4h방향+15m진입 + OP·LINK제외 + 손절폭상한5% + MACD음전&윗꼬리조합 제외.
    private static async Task RunMtfFinalAsync()
    {
        const int featureWindow = 500, K = 8, Lh = 4;
        const decimal feeRT = 0.0008m; double atrMult = 5.0;
        decimal margin = 1000m; int slots = 6; decimal capital = margin * slots;
        // v5.27.2: OP·LINK 순손실 제외 → 10코인
        var universe = new[] { "BTCUSDT","ETHUSDT","BNBUSDT","SOLUSDT","XRPUSDT","DOGEUSDT","ADAUSDT","AVAXUSDT","ARBUSDT","SUIUSDT" };
        Console.WriteLine("=== 라이브 v5.27.3 재현: 4h방향+15m진입 · OP/LINK제외 · 손절폭≤5% · MACD음전+윗꼬리제외 (마진$1,000×6·1x) ===\n");
        var cmdArgs = Environment.GetCommandLineArgs();
        bool loosen = cmdArgs.Any(a => a.Equals("--loosen", StringComparison.OrdinalIgnoreCase));   // BTC 게이트 완화: 완전정배열 → 종가>EMA50만
        bool noBtc = cmdArgs.Any(a => a.Equals("--nobtc", StringComparison.OrdinalIgnoreCase));     // BTC 게이트 완전제거: 코인 자체 4h+15m만
        bool adx20 = cmdArgs.Any(a => a.Equals("--adx20", StringComparison.OrdinalIgnoreCase));     // 코인 4h ADX 25→20
        double coinAdxThr = adx20 ? 20.0 : 25.0;
        if (loosen) Console.WriteLine("  [완화모드] BTC 4h: 종가>EMA50만 (EMA50>EMA200 조건 제거)\n");
        if (noBtc) Console.WriteLine("  [BTC제거모드] BTC 게이트 없음 — 코인 자체 4h추세+15m만\n");
        if (adx20) Console.WriteLine("  [ADX20모드] 코인 4h ADX 25→20\n");
        List<(DateTime close, bool up)> Regime4h(List<IBinanceKline> b4)
        {
            int n = b4.Count; var e200 = new double[n]; for (int j = 200; j < n; j++) e200[j] = CalcEMA(b4, j, 200);
            var e50 = new double[n]; for (int j = 50; j < n; j++) e50[j] = CalcEMA(b4, j, 50);
            var adx = new double[n]; { double aS = 0, pS = 0, mS = 0; int per = 14; for (int j = 1; j < n; j++) { double hh = (double)b4[j].HighPrice, ll = (double)b4[j].LowPrice, pc = (double)b4[j - 1].ClosePrice, ph = (double)b4[j - 1].HighPrice, pl = (double)b4[j - 1].LowPrice; double tr = Math.Max(hh - ll, Math.Max(Math.Abs(hh - pc), Math.Abs(ll - pc))); double up = hh - ph, dn = pl - ll; double pdm = (up > dn && up > 0) ? up : 0, mdm = (dn > up && dn > 0) ? dn : 0; if (j <= per) { aS += tr; pS += pdm; mS += mdm; } else { aS = aS - aS / per + tr; pS = pS - pS / per + pdm; mS = mS - mS / per + mdm; } if (j >= per && aS > 0) { double pd = 100 * pS / aS, md = 100 * mS / aS; double dx = (pd + md) > 0 ? 100 * Math.Abs(pd - md) / (pd + md) : 0; adx[j] = j <= per * 2 ? dx : (adx[j - 1] * (per - 1) + dx) / per; } } }
            var r = new List<(DateTime, bool)>();
            for (int j = 0; j < n; j++) { double c = (double)b4[j].ClosePrice; bool up = j >= 200 && e50[j] > 0 && e200[j] > 0 && e50[j] > e200[j] && c > e50[j] && adx[j] >= coinAdxThr; r.Add((b4[j].OpenTime.AddHours(4), up)); }
            return r;
        }
        var btc4 = await FetchKlines4hAsync("BTCUSDT", 12);
        List<(DateTime close, bool up)> BtcAlign(List<IBinanceKline> b4)
        { int n = b4.Count; var e200 = new double[n]; for (int j = 200; j < n; j++) e200[j] = CalcEMA(b4, j, 200); var e50 = new double[n]; for (int j = 50; j < n; j++) e50[j] = CalcEMA(b4, j, 50); var r = new List<(DateTime, bool)>(); for (int j = 0; j < n; j++) { double c = (double)b4[j].ClosePrice; bool ok = loosen ? (j >= 50 && e50[j] > 0 && c > e50[j]) : (j >= 200 && e50[j] > 0 && e200[j] > 0 && c > e50[j] && e50[j] > e200[j]); r.Add((b4[j].OpenTime.AddHours(4), ok)); } return r; }
        var btcAlign = BtcAlign(btc4);
        var allTrades = new List<(DateTime ent, DateTime ex, decimal pnl)>();
        int ci = 0; int cutCombo = 0, cutStop = 0;
        foreach (var sym in universe)
        {
            ci++; Console.Write($"[{ci}/{universe.Length}] {sym} ");
            List<IBinanceKline> b4, k15;
            try { b4 = await FetchKlines4hAsync(sym, 12); k15 = await FetchKlines15mAsync(sym, 110); } catch { Console.WriteLine("fail"); continue; }
            if (b4.Count < 300 || k15.Count < 1000) { Console.WriteLine($"skip"); continue; }
            var reg = Regime4h(b4);
            int n = k15.Count; Console.WriteLine($"15m={n} 4h={b4.Count}");
            var close = new double[n]; for (int j = 0; j < n; j++) close[j] = (double)k15[j].ClosePrice;
            var feats = new float[n][]; for (int j = 60; j < n; j++) { int ws = Math.Max(0, j - (featureWindow - 1)); feats[j] = LorentzianFeatures.Extract(k15.GetRange(ws, j - ws + 1))!; }
            var e50 = new double[n]; for (int j = 50; j < n; j++) e50[j] = CalcEMA(k15, j, 50);
            var e200 = new double[n]; for (int j = 200; j < n; j++) e200[j] = CalcEMA(k15, j, 200);
            var atr = new double[n]; for (int j = 14; j < n; j++) { double tr = 0; for (int q = j - 13; q <= j; q++) { double hh = (double)k15[q].HighPrice, ll = (double)k15[q].LowPrice, pc = close[q - 1]; tr += Math.Max(hh - ll, Math.Max(Math.Abs(hh - pc), Math.Abs(ll - pc))); } atr[j] = tr / 14.0; }
            var rsi = new double[n]; { double ag = 0, al = 0; int per = 14; for (int j = 1; j < n; j++) { double ch = close[j] - close[j - 1]; double g = ch > 0 ? ch : 0, ls = ch < 0 ? -ch : 0; if (j <= per) { ag += g; al += ls; if (j == per) { ag /= per; al /= per; rsi[j] = al == 0 ? 100 : 100 - 100 / (1 + ag / al); } } else { ag = (ag * (per - 1) + g) / per; al = (al * (per - 1) + ls) / per; rsi[j] = al == 0 ? 100 : 100 - 100 / (1 + ag / al); } } }
            // MACD 히스토그램 (12/26/9)
            var hist = new double[n]; { double e12 = 0, e26 = 0, sig = 0; const double k12 = 2.0 / 13, k26 = 2.0 / 27, k9 = 2.0 / 10; for (int j = 0; j < n; j++) { double cc = close[j]; if (j == 0) { e12 = cc; e26 = cc; } else { e12 = cc * k12 + e12 * (1 - k12); e26 = cc * k26 + e26 * (1 - k26); } double macd = e12 - e26; sig = (j == 0) ? macd : macd * k9 + sig * (1 - k9); hist[j] = macd - sig; } }
            var engine = new LorentzianAnnEngine(sym, neighborsCount: K, maxBarsBack: 2000, featureCount: LorentzianFeatures.FeatureCount);
            var sg = new int[n];
            for (int j = 65; j < n; j++) { int s = j - 1; if (s - Lh >= 0 && feats[s] != null) { double a = close[s], b = close[s - Lh]; engine.AddSample(feats[s], a > b ? 1 : (a < b ? -1 : 0)); } if (feats[j] == null) continue; var p = engine.Predict(feats[j]); if (!p.IsReady || p.K == 0) continue; sg[j] = p.Prediction > 0 ? 1 : (p.Prediction < 0 ? -1 : 0); }
            int rp = 0, bp = 0; int busy = -1;
            for (int j = 250; j < n - 1; j++)
            {
                if (j <= busy) continue;
                var t15 = k15[j].OpenTime;
                while (rp + 1 < reg.Count && reg[rp + 1].close <= t15) rp++;
                while (bp + 1 < btcAlign.Count && btcAlign[bp + 1].close <= t15) bp++;
                if (!(reg[rp].close <= t15 && reg[rp].up)) continue;
                if (!noBtc && !(btcAlign[bp].close <= t15 && btcAlign[bp].up)) continue;
                if (!(sg[j] > 0 && e50[j] > 0 && e200[j] > 0 && e50[j] > e200[j] && close[j] > e50[j])) continue;
                if (atr[j] <= 0 || k15[j + 1].OpenPrice <= 0) continue;
                if ((close[j] - e50[j]) / atr[j] >= 2.0 || rsi[j] >= 60.0) continue;   // 방어: EMA50과확장·RSI60
                if ((5.0 * atr[j]) / close[j] > 0.05) { cutStop++; continue; }          // v5.27.1: 손절폭상한 5%
                double uw = ((double)k15[j].HighPrice - Math.Max((double)k15[j].OpenPrice, close[j])) / atr[j];
                if (hist[j] < 0 && uw > 0.4) { cutCombo++; continue; }                   // v5.27.3: MACD음전+윗꼬리 조합제외
                decimal entry = k15[j + 1].OpenPrice; double peakP = (double)entry; decimal net = 0m; int ei = n - 1;
                for (int e = j + 1; e < n; e++) { double cc = close[e]; if (cc > peakP) peakP = cc; if (cc <= peakP - atrMult * atr[e]) { net = ((decimal)cc - entry) / entry - feeRT; ei = e; break; } if (e == n - 1) net = ((decimal)cc - entry) / entry - feeRT; }
                busy = ei; allTrades.Add((k15[j + 1].OpenTime, k15[ei].OpenTime, net));
            }
        }
        allTrades.Sort((a, b) => a.ent.CompareTo(b.ent));
        var open = new List<DateTime>(); var monthly = new SortedDictionary<string, (int n, decimal pnl, int w)>();
        var daily = new SortedDictionary<string, (int n, decimal pnl)>(); int tn = 0, wn = 0;
        DateTime? firstEnt = null, lastEnt = null;
        foreach (var t in allTrades) { open.RemoveAll(x => x <= t.ent); if (open.Count >= slots) continue; open.Add(t.ex); if (firstEnt == null) firstEnt = t.ent; lastEnt = t.ent; var mk = t.ent.ToString("yyyy-MM"); var mc = monthly.TryGetValue(mk, out var mv) ? mv : (0, 0m, 0); bool win = t.pnl > 0; monthly[mk] = (mc.Item1 + 1, mc.Item2 + t.pnl * margin, mc.Item3 + (win ? 1 : 0)); var dk = t.ent.ToString("yyyy-MM-dd"); var dc = daily.TryGetValue(dk, out var dv) ? dv : (0, 0m); daily[dk] = (dc.Item1 + 1, dc.Item2 + t.pnl * margin); tn++; if (win) wn++; }
        int prof = 0, zeroMo = 0; decimal cum = 0m, peak = 0m, mdd = 0m, worst = 0m, tot = 0m;
        var inv = System.Globalization.CultureInfo.InvariantCulture; var sb = new System.Text.StringBuilder(); sb.Append('['); bool jf = true;
        // ── 월별: 첫 진입월~마지막 진입월 전 구간, 빠짐없이(0원도 0으로) ──
        Console.WriteLine($"\n  {"월",8} {"진입",5} {"수익금$",10} {"월수익률%",9} {"누적$",11}");
        int totalMonths = 0;
        if (firstEnt != null)
        {
            var cur = new DateTime(firstEnt.Value.Year, firstEnt.Value.Month, 1);
            var end = new DateTime(lastEnt!.Value.Year, lastEnt.Value.Month, 1);
            for (; cur <= end; cur = cur.AddMonths(1))
            {
                totalMonths++;
                var mk = cur.ToString("yyyy-MM");
                var mv = monthly.TryGetValue(mk, out var m) ? m : (n: 0, pnl: 0m, w: 0);
                cum += mv.pnl; if (mv.pnl > 0) prof++; if (mv.n == 0) zeroMo++; if (mv.pnl < worst) worst = mv.pnl; tot += mv.pnl; if (cum > peak) peak = cum; if (peak - cum > mdd) mdd = peak - cum;
                double ret = (double)(mv.pnl / capital * 100m);
                Console.WriteLine($"  {mk,8} {mv.n,5} {mv.pnl,10:F0} {ret,9:F1} {cum,11:F0}");
                if (!jf) sb.Append(','); jf = false; sb.Append($"{{\"m\":\"{mk}\",\"n\":{mv.n},\"pnl\":{mv.pnl.ToString("F0", inv)},\"ret\":{ret.ToString("F1", inv)},\"cum\":{cum.ToString("F0", inv)}}}");
            }
        }
        sb.Append(']');
        int mo = Math.Max(1, totalMonths);
        Console.WriteLine($"\n  총 {mo}개월(진입있던 달 {monthly.Count} · 0원 달 {zeroMo}) · 진입 {tn}(월평균 {tn / (double)mo:F1}) · 승률 {100.0 * wn / Math.Max(1, tn):F0}% · 흑자월 {prof}/{mo}({100.0 * prof / mo:F0}%)");
        Console.WriteLine($"  총 ${tot:F0}({(double)(tot / capital * 100m):F0}%) · MDD {(double)(mdd / capital * 100m):F0}% · 최악월 {(double)(worst / capital * 100m):F1}% · 제외: 손절폭상한 {cutStop}건 · MACD조합 {cutCombo}건");
        // ── 최근 3개월 일별: 매일(0원 날도 0으로) ──
        var dsb = new System.Text.StringBuilder(); dsb.Append('['); bool df = true;
        if (lastEnt != null)
        {
            var lastM = new DateTime(lastEnt.Value.Year, lastEnt.Value.Month, 1);
            var startM = lastM.AddMonths(-2);   // 최근 3개월
            Console.WriteLine($"\n── 최근 3개월 일별 ({startM:yyyy-MM}~{lastM:yyyy-MM}, 0원 날 포함) ──");
            Console.WriteLine($"  {"날짜",12} {"진입",5} {"수익금$",10}");
            var lastDayInRange = lastEnt.Value.Date;
            for (var d = startM; d <= lastDayInRange; d = d.AddDays(1))
            {
                var dk = d.ToString("yyyy-MM-dd");
                var dv = daily.TryGetValue(dk, out var dd) ? dd : (n: 0, pnl: 0m);
                Console.WriteLine($"  {dk,12} {dv.n,5} {dv.pnl,10:F0}");
                if (!df) dsb.Append(','); df = false; dsb.Append($"{{\"d\":\"{dk}\",\"n\":{dv.n},\"pnl\":{dv.pnl.ToString("F0", inv)}}}");
            }
        }
        dsb.Append(']');
        System.IO.File.WriteAllText("mtf-final.json", "{\"monthly\":" + sb.ToString() + ",\"daily\":" + dsb.ToString() + "}");
        Console.WriteLine("\n  → mtf-final.json 저장. 현재 라이브(v5.27.3)와 동일 로직. 월/일 0원 구간 = BTC 4h 비정배열로 전코인 미진입(설계).");
    }

    // --major17 : ★메이저 4개 07-17부터 4h/1h 정배열 타임라인 — "17일22시부터 상승인데 왜 진입0" 검증. EMA지연이 원인인지.
    private static async Task RunMajor17Async()
    {
        var majors = new[] { "BTCUSDT", "ETHUSDT", "SOLUSDT", "XRPUSDT" };
        var start = new DateTime(2026, 7, 17, 0, 0, 0);
        Console.WriteLine("=== 메이저 4개: 07-17부터 4h/1h 추세정렬 타임라인 (가격상승 vs 봇의 '정배열' 정의) ===\n");
        foreach (var sym in majors)
        {
            List<IBinanceKline> b4, h1;
            try { b4 = await FetchKlines4hAsync(sym, 6); h1 = await FetchKlines1hAsync(sym, 8); } catch { Console.WriteLine($"{sym} fail"); continue; }
            // 4h EMA/ADX
            int bn = b4.Count; var be200 = new double[bn]; for (int j = 200; j < bn; j++) be200[j] = CalcEMA(b4, j, 200);
            var be50 = new double[bn]; for (int j = 50; j < bn; j++) be50[j] = CalcEMA(b4, j, 50);
            var badx = new double[bn]; { double aS = 0, pS = 0, mS = 0; int per = 14; for (int j = 1; j < bn; j++) { double hh = (double)b4[j].HighPrice, ll = (double)b4[j].LowPrice, pc = (double)b4[j - 1].ClosePrice, ph = (double)b4[j - 1].HighPrice, pl = (double)b4[j - 1].LowPrice; double tr = Math.Max(hh - ll, Math.Max(Math.Abs(hh - pc), Math.Abs(ll - pc))); double up = hh - ph, dn = pl - ll; double pdm = (up > dn && up > 0) ? up : 0, mdm = (dn > up && dn > 0) ? dn : 0; if (j <= per) { aS += tr; pS += pdm; mS += mdm; } else { aS = aS - aS / per + tr; pS = pS - pS / per + pdm; mS = mS - mS / per + mdm; } if (j >= per && aS > 0) { double pd = 100 * pS / aS, md = 100 * mS / aS; double dx = (pd + md) > 0 ? 100 * Math.Abs(pd - md) / (pd + md) : 0; badx[j] = j <= per * 2 ? dx : (badx[j - 1] * (per - 1) + dx) / per; } } }
            int hn = h1.Count; var he50 = new double[hn]; for (int j = 50; j < hn; j++) he50[j] = CalcEMA(h1, j, 50); var he200 = new double[hn]; for (int j = 200; j < hn; j++) he200[j] = CalcEMA(h1, j, 200);
            Console.WriteLine($"── {sym} ── (4h봉: 시각KST · 종가 · 4h정배열 · ADX  |  1h정배열)");
            for (int j = 200; j < bn; j++)
            {
                var kst = b4[j].OpenTime.AddHours(9); if (kst < start) continue;
                double c = (double)b4[j].ClosePrice;
                bool r4 = be50[j] > 0 && be200[j] > 0 && be50[j] > be200[j] && c > be50[j] && badx[j] >= 20.0;
                // 이 4h봉 시점의 1h 정배열 (가장 가까운 마감 1h)
                var t4end = b4[j].OpenTime.AddHours(4);
                int hi = -1; for (int q = hn - 1; q >= 0; q--) { if (h1[q].OpenTime.AddHours(1) <= t4end) { hi = q; break; } }
                string h1state = "?"; double hgap = 0;
                if (hi >= 200) { bool r1 = he50[hi] > 0 && he200[hi] > 0 && he50[hi] > he200[hi] && (double)h1[hi].ClosePrice > he50[hi]; hgap = he50[hi] - he200[hi]; h1state = r1 ? "✅" : (he50[hi] <= he200[hi] ? $"❌(50<200,gap{hgap:F2})" : "❌(종가<50)"); }
                Console.WriteLine($"   {kst:MM-dd HH:mm}  {c,11:F4}  4h:{(r4 ? "✅상승" : "❌")}  ADX{badx[j],3:F0}  |  1h:{h1state}");
            }
            Console.WriteLine();
        }
        Console.WriteLine("  → 가격은 07-17부터 오르는데 '4h✅' 또는 '1h✅'가 늦게 뜨면 = EMA200 지연으로 봇 '정배열'이 실제 상승보다 며칠 늦음(과필터).");
    }

    // --top50-recent : ★시총 상위 50코인에서 07-16 이후 진입 가능(★진입!)한 게 있었나. 개발로직 그대로, 신선데이터.
    private static async Task RunTop50RecentAsync()
    {
        const int featureWindow = 500, K = 8, Lh = 4;
        var universe = new[] {
            "BTCUSDT","ETHUSDT","BNBUSDT","SOLUSDT","XRPUSDT","DOGEUSDT","ADAUSDT","TRXUSDT","AVAXUSDT","LINKUSDT",
            "DOTUSDT","LTCUSDT","BCHUSDT","NEARUSDT","UNIUSDT","APTUSDT","ICPUSDT","ETCUSDT","XLMUSDT","ATOMUSDT",
            "FILUSDT","HBARUSDT","ARBUSDT","VETUSDT","OPUSDT","INJUSDT","SUIUSDT","AAVEUSDT","GRTUSDT","ALGOUSDT",
            "SEIUSDT","RUNEUSDT","IMXUSDT","RENDERUSDT","MKRUSDT","TIAUSDT","SANDUSDT","MANAUSDT","AXSUSDT","XMRUSDT",
            "ZECUSDT","GALAUSDT","EGLDUSDT","FLOWUSDT","CHZUSDT","EOSUSDT","XTZUSDT","THETAUSDT","LDOUSDT","POLUSDT" };
        var start = new DateTime(2026, 7, 16);
        Console.WriteLine($"=== 시총50 코인 07-16 이후 진입 가능했나 (개발로직·신선데이터, {universe.Length}코인) ===\n");
        var entered = new SortedDictionary<string, int>(); var failAgg = new SortedDictionary<string, int>(); int coinsOk = 0, coinsFail = 0;
        var entryLines = new List<string>();
        int ci = 0;
        foreach (var sym in universe)
        {
            ci++;
            List<IBinanceKline> b4, k15, h1;
            try { b4 = await FetchKlines4hAsync(sym, 6); k15 = await FetchKlines15mAsync(sym, 33); h1 = await FetchKlines1hAsync(sym, 8); } catch { Console.WriteLine($"[{ci}/{universe.Length}] {sym} fail"); coinsFail++; continue; }
            if (b4.Count < 260 || k15.Count < 1000) { Console.WriteLine($"[{ci}/{universe.Length}] {sym} skip(데이터부족)"); coinsFail++; continue; }
            int bn = b4.Count; var be200 = new double[bn]; for (int j = 200; j < bn; j++) be200[j] = CalcEMA(b4, j, 200);
            var be50 = new double[bn]; for (int j = 50; j < bn; j++) be50[j] = CalcEMA(b4, j, 50);
            var badx = new double[bn]; { double aS = 0, pS = 0, mS = 0; int per = 14; for (int j = 1; j < bn; j++) { double hh = (double)b4[j].HighPrice, ll = (double)b4[j].LowPrice, pc = (double)b4[j - 1].ClosePrice, ph = (double)b4[j - 1].HighPrice, pl = (double)b4[j - 1].LowPrice; double tr = Math.Max(hh - ll, Math.Max(Math.Abs(hh - pc), Math.Abs(ll - pc))); double up = hh - ph, dn = pl - ll; double pdm = (up > dn && up > 0) ? up : 0, mdm = (dn > up && dn > 0) ? dn : 0; if (j <= per) { aS += tr; pS += pdm; mS += mdm; } else { aS = aS - aS / per + tr; pS = pS - pS / per + pdm; mS = mS - mS / per + mdm; } if (j >= per && aS > 0) { double pd = 100 * pS / aS, md = 100 * mS / aS; double dx = (pd + md) > 0 ? 100 * Math.Abs(pd - md) / (pd + md) : 0; badx[j] = j <= per * 2 ? dx : (badx[j - 1] * (per - 1) + dx) / per; } } }
            var reg = new List<(DateTime close, bool up)>();
            for (int j = 0; j < bn; j++) { double c = (double)b4[j].ClosePrice; reg.Add((b4[j].OpenTime.AddHours(4), j >= 200 && be50[j] > 0 && be200[j] > 0 && be50[j] > be200[j] && c > be50[j] && badx[j] >= 20.0)); }
            int hn = h1.Count; var h50 = new double[hn]; for (int j = 50; j < hn; j++) h50[j] = CalcEMA(h1, j, 50); var h200 = new double[hn]; for (int j = 200; j < hn; j++) h200[j] = CalcEMA(h1, j, 200);
            var hreg = new List<(DateTime close, bool up)>(); for (int j = 0; j < hn; j++) { double c = (double)h1[j].ClosePrice; hreg.Add((h1[j].OpenTime.AddHours(1), j >= 200 && h50[j] > 0 && h200[j] > 0 && h50[j] > h200[j] && c > h50[j])); }
            int n = k15.Count; var close = new double[n]; for (int j = 0; j < n; j++) close[j] = (double)k15[j].ClosePrice;
            var feats = new float[n][]; for (int j = 60; j < n; j++) { int ws = Math.Max(0, j - (featureWindow - 1)); feats[j] = LorentzianFeatures.Extract(k15.GetRange(ws, j - ws + 1))!; }
            var e50 = new double[n]; for (int j = 50; j < n; j++) e50[j] = CalcEMA(k15, j, 50);
            var e200 = new double[n]; for (int j = 200; j < n; j++) e200[j] = CalcEMA(k15, j, 200);
            var atr = new double[n]; for (int j = 14; j < n; j++) { double tr = 0; for (int q = j - 13; q <= j; q++) { double hh = (double)k15[q].HighPrice, ll = (double)k15[q].LowPrice, pc = close[q - 1]; tr += Math.Max(hh - ll, Math.Max(Math.Abs(hh - pc), Math.Abs(ll - pc))); } atr[j] = tr / 14.0; }
            var rsi = new double[n]; { double ag = 0, al = 0; int per = 14; for (int j = 1; j < n; j++) { double ch = close[j] - close[j - 1]; double g = ch > 0 ? ch : 0, ls = ch < 0 ? -ch : 0; if (j <= per) { ag += g; al += ls; if (j == per) { ag /= per; al /= per; rsi[j] = al == 0 ? 100 : 100 - 100 / (1 + ag / al); } } else { ag = (ag * (per - 1) + g) / per; al = (al * (per - 1) + ls) / per; rsi[j] = al == 0 ? 100 : 100 - 100 / (1 + ag / al); } } }
            var hist = new double[n]; { double x12 = close[0], x26 = close[0], sig = 0; bool si = false; for (int j = 1; j < n; j++) { double c = close[j]; x12 += (c - x12) * (2.0 / 13); x26 += (c - x26) * (2.0 / 27); double macd = x12 - x26; if (!si) { sig = macd; si = true; } else sig += (macd - sig) * (2.0 / 10); hist[j] = macd - sig; } }
            var engine = new LorentzianAnnEngine(sym, neighborsCount: K, maxBarsBack: 2000, featureCount: LorentzianFeatures.FeatureCount);
            var sg = new int[n];
            for (int j = 65; j < n; j++) { int s = j - 1; if (s - Lh >= 0 && feats[s] != null) { double a = close[s], b = close[s - Lh]; engine.AddSample(feats[s], a > b ? 1 : (a < b ? -1 : 0)); } if (feats[j] == null) continue; var p = engine.Predict(feats[j]); if (!p.IsReady || p.K == 0) continue; sg[j] = p.Prediction > 0 ? 1 : (p.Prediction < 0 ? -1 : 0); }
            int rp = 0, hp = 0; int nEnt = 0;
            for (int j = 250; j < n - 1; j++)
            {
                var kst = k15[j].OpenTime.AddHours(9); if (kst < start) continue;
                var t15 = k15[j].OpenTime;
                while (rp + 1 < reg.Count && reg[rp + 1].close <= t15) rp++;
                while (hp + 1 < hreg.Count && hreg[hp + 1].close <= t15) hp++;
                if (!(reg[rp].close <= t15 && reg[rp].up)) { failAgg["4h아님"] = failAgg.GetValueOrDefault("4h아님") + 1; continue; }
                if (!(hreg[hp].close <= t15 && hreg[hp].up)) { failAgg["1h아님"] = failAgg.GetValueOrDefault("1h아님") + 1; continue; }
                if (!(sg[j] > 0 && e50[j] > 0 && e200[j] > 0 && e50[j] > e200[j] && close[j] > e50[j])) { failAgg[sg[j] <= 0 ? "KNN아님" : "15mEMA아님"] = failAgg.GetValueOrDefault(sg[j] <= 0 ? "KNN아님" : "15mEMA아님") + 1; continue; }
                if (atr[j] <= 0) continue;
                if ((close[j] - e50[j]) / atr[j] >= 2.0 || rsi[j] >= 60.0) { failAgg["방어(과확장/RSI)"] = failAgg.GetValueOrDefault("방어(과확장/RSI)") + 1; continue; }
                if ((5.0 * atr[j]) / close[j] > 0.05) { failAgg["손절폭"] = failAgg.GetValueOrDefault("손절폭") + 1; continue; }
                double uw = ((double)k15[j].HighPrice - Math.Max((double)k15[j].OpenPrice, close[j])) / atr[j];
                if (hist[j] < 0 && uw > 0.4) { failAgg["MACD조합"] = failAgg.GetValueOrDefault("MACD조합") + 1; continue; }
                nEnt++; if (nEnt <= 3) entryLines.Add($"  ★ {kst:MM-dd HH:mm} {sym}");
            }
            if (nEnt > 0) { entered[sym] = nEnt; coinsOk++; }
            Console.WriteLine($"[{ci}/{universe.Length}] {sym,10} 15m={n} 진입가능봉={nEnt}");
        }
        Console.WriteLine($"\n══════ 결과: 07-16 이후 진입 가능했던 코인 ══════");
        if (entered.Count == 0) Console.WriteLine("  ❌ 시총50 어떤 코인도 07-16 이후 개발로직상 진입 신호 없음 = 진입0이 정상(전면 약세/횡보)");
        else { foreach (var kv in entered.OrderByDescending(x => x.Value)) Console.WriteLine($"  ✅ {kv.Key,10} : {kv.Value}봉 진입가능"); Console.WriteLine($"\n  → {coinsOk}개 코인에서 진입신호 존재. 라이브가 이걸 놓쳤으면 유니버스/게이트 점검 필요."); }
        Console.WriteLine($"\n  진입가능 샘플: "); foreach (var l in entryLines.Take(20)) Console.WriteLine(l);
        Console.WriteLine($"\n  전체 차단사유 집계(07-16이후):"); foreach (var kv in failAgg.OrderByDescending(x => x.Value)) Console.WriteLine($"    {kv.Value,7}  {kv.Key}");
        Console.WriteLine($"\n  (코인 {coinsOk}개 진입가능 / {coinsFail}개 페치실패)");
    }

    // --check-recent : ★최신 신선데이터로 최근 4일(KST) 진입 깔때기 + 4h 추세 타임라인. "어제 상승인데 왜 진입0" 규명. KNN포함. 새 페이지수=강제 fresh fetch.
    private static async Task RunCheckRecentAsync()
    {
        const int featureWindow = 500, K = 8, Lh = 4;
        var universe = new[] { "BTCUSDT","ETHUSDT","BNBUSDT","SOLUSDT","XRPUSDT","DOGEUSDT","ADAUSDT","AVAXUSDT","ARBUSDT","SUIUSDT" };
        Console.WriteLine("=== 최근 4일 진입 진단 (신선데이터·KNN포함) — 어제 상승인데 왜 진입0? ===\n");
        var candLines = new List<string>();
        foreach (var sym in universe)
        {
            List<IBinanceKline> b4, k15, h1;
            // 새 페이지수(6/8/33) = 새 캐시키 = 강제 fresh fetch (최신 07-22까지)
            try { b4 = await FetchKlines4hAsync(sym, 6); k15 = await FetchKlines15mAsync(sym, 33); h1 = await FetchKlines1hAsync(sym, 8); } catch { Console.WriteLine($"{sym} fail"); continue; }
            if (b4.Count < 260 || k15.Count < 1000) { Console.WriteLine($"{sym} skip"); continue; }
            int bn = b4.Count; var be200 = new double[bn]; for (int j = 200; j < bn; j++) be200[j] = CalcEMA(b4, j, 200);
            var be50 = new double[bn]; for (int j = 50; j < bn; j++) be50[j] = CalcEMA(b4, j, 50);
            var badx = new double[bn]; { double aS = 0, pS = 0, mS = 0; int per = 14; for (int j = 1; j < bn; j++) { double hh = (double)b4[j].HighPrice, ll = (double)b4[j].LowPrice, pc = (double)b4[j - 1].ClosePrice, ph = (double)b4[j - 1].HighPrice, pl = (double)b4[j - 1].LowPrice; double tr = Math.Max(hh - ll, Math.Max(Math.Abs(hh - pc), Math.Abs(ll - pc))); double up = hh - ph, dn = pl - ll; double pdm = (up > dn && up > 0) ? up : 0, mdm = (dn > up && dn > 0) ? dn : 0; if (j <= per) { aS += tr; pS += pdm; mS += mdm; } else { aS = aS - aS / per + tr; pS = pS - pS / per + pdm; mS = mS - mS / per + mdm; } if (j >= per && aS > 0) { double pd = 100 * pS / aS, md = 100 * mS / aS; double dx = (pd + md) > 0 ? 100 * Math.Abs(pd - md) / (pd + md) : 0; badx[j] = j <= per * 2 ? dx : (badx[j - 1] * (per - 1) + dx) / per; } } }
            var reg = new List<(DateTime close, bool up)>();
            for (int j = 0; j < bn; j++) { double c = (double)b4[j].ClosePrice; reg.Add((b4[j].OpenTime.AddHours(4), j >= 200 && be50[j] > 0 && be200[j] > 0 && be50[j] > be200[j] && c > be50[j] && badx[j] >= 20.0)); }
            int hn = h1.Count; var h50 = new double[hn]; for (int j = 50; j < hn; j++) h50[j] = CalcEMA(h1, j, 50); var h200 = new double[hn]; for (int j = 200; j < hn; j++) h200[j] = CalcEMA(h1, j, 200);
            var hreg = new List<(DateTime close, bool up)>(); for (int j = 0; j < hn; j++) { double c = (double)h1[j].ClosePrice; hreg.Add((h1[j].OpenTime.AddHours(1), j >= 200 && h50[j] > 0 && h200[j] > 0 && h50[j] > h200[j] && c > h50[j])); }
            int n = k15.Count; var close = new double[n]; for (int j = 0; j < n; j++) close[j] = (double)k15[j].ClosePrice;
            var feats = new float[n][]; for (int j = 60; j < n; j++) { int ws = Math.Max(0, j - (featureWindow - 1)); feats[j] = LorentzianFeatures.Extract(k15.GetRange(ws, j - ws + 1))!; }
            var e50 = new double[n]; for (int j = 50; j < n; j++) e50[j] = CalcEMA(k15, j, 50);
            var e200 = new double[n]; for (int j = 200; j < n; j++) e200[j] = CalcEMA(k15, j, 200);
            var atr = new double[n]; for (int j = 14; j < n; j++) { double tr = 0; for (int q = j - 13; q <= j; q++) { double hh = (double)k15[q].HighPrice, ll = (double)k15[q].LowPrice, pc = close[q - 1]; tr += Math.Max(hh - ll, Math.Max(Math.Abs(hh - pc), Math.Abs(ll - pc))); } atr[j] = tr / 14.0; }
            var rsi = new double[n]; { double ag = 0, al = 0; int per = 14; for (int j = 1; j < n; j++) { double ch = close[j] - close[j - 1]; double g = ch > 0 ? ch : 0, ls = ch < 0 ? -ch : 0; if (j <= per) { ag += g; al += ls; if (j == per) { ag /= per; al /= per; rsi[j] = al == 0 ? 100 : 100 - 100 / (1 + ag / al); } } else { ag = (ag * (per - 1) + g) / per; al = (al * (per - 1) + ls) / per; rsi[j] = al == 0 ? 100 : 100 - 100 / (1 + ag / al); } } }
            var hist = new double[n]; { double x12 = close[0], x26 = close[0], sig = 0; bool si = false; for (int j = 1; j < n; j++) { double c = close[j]; x12 += (c - x12) * (2.0 / 13); x26 += (c - x26) * (2.0 / 27); double macd = x12 - x26; if (!si) { sig = macd; si = true; } else sig += (macd - sig) * (2.0 / 10); hist[j] = macd - sig; } }
            var engine = new LorentzianAnnEngine(sym, neighborsCount: K, maxBarsBack: 2000, featureCount: LorentzianFeatures.FeatureCount);
            var sg = new int[n];
            for (int j = 65; j < n; j++) { int s = j - 1; if (s - Lh >= 0 && feats[s] != null) { double a = close[s], b = close[s - Lh]; engine.AddSample(feats[s], a > b ? 1 : (a < b ? -1 : 0)); } if (feats[j] == null) continue; var p = engine.Predict(feats[j]); if (!p.IsReady || p.K == 0) continue; sg[j] = p.Prediction > 0 ? 1 : (p.Prediction < 0 ? -1 : 0); }
            // 최근 4일(KST) 깔때기 + 마지막봉 시각 로그
            var last15 = k15[n - 1].OpenTime.AddHours(9);
            Console.WriteLine($"  {sym,9} 최신15m {last15:MM-dd HH:mm}(KST)  4h최신 {reg[bn - 2].up}({badx[bn - 2]:F0})");
            int rp = 0, hp = 0;
            for (int j = 250; j < n - 1; j++)
            {
                var kst = k15[j].OpenTime.AddHours(9);
                if (kst < new DateTime(2026, 7, 19)) continue;
                var t15 = k15[j].OpenTime;
                while (rp + 1 < reg.Count && reg[rp + 1].close <= t15) rp++;
                while (hp + 1 < hreg.Count && hreg[hp + 1].close <= t15) hp++;
                bool p4 = reg[rp].close <= t15 && reg[rp].up;
                bool p1 = hreg[hp].close <= t15 && hreg[hp].up;
                bool pk = sg[j] > 0 && e50[j] > 0 && e200[j] > 0 && e50[j] > e200[j] && close[j] > e50[j];
                if (!p4) continue;   // 4h 통과한 것만 관심 (상승추세였다면 여기 걸림)
                // 어느 관문에서 막혔나
                string fail;
                if (!p1) fail = "1h정배열X";
                else if (atr[j] <= 0) fail = "atr0";
                else if (!pk) fail = sg[j] <= 0 ? "KNN매수X" : "15mEMA정배열X";
                else if ((close[j] - e50[j]) / atr[j] >= 2.0) fail = "EMA과확장(고점)";
                else if (rsi[j] >= 60.0) fail = $"RSI과매수({rsi[j]:F0})";
                else if ((5.0 * atr[j]) / close[j] > 0.05) fail = "손절폭과대";
                else { double uw = ((double)k15[j].HighPrice - Math.Max((double)k15[j].OpenPrice, close[j])) / atr[j]; fail = (hist[j] < 0 && uw > 0.4) ? "MACD음전+윗꼬리" : "★진입!"; }
                candLines.Add($"  {kst:MM-dd HH:mm} {sym,9} 4h✅ {fail}");
            }
        }
        Console.WriteLine($"\n── 최근(07-19~) 4h 상승추세였던 15m봉들 — 어느 관문에서 막혔나 ──");
        if (candLines.Count == 0) Console.WriteLine("  (해당 없음: 07-19 이후 4h 상승추세 통과한 15m봉 자체가 없음 = 전 코인 하락/횡보)");
        else foreach (var l in candLines.OrderBy(x => x)) Console.WriteLine(l);
        Console.WriteLine($"\n  → '★진입!'이 있는데 라이브가 안 들어갔으면 = 라이브 버그. 전부 다른 사유면 = 그 방어에 걸린 정상.");
        Console.WriteLine("  → 4h통과 봉이 아예 없으면 = 어제도 4h 상승추세가 아니었던 것(15m·짧은 반등을 상승으로 봤을 수 있음).");
    }

    // --regime-now : ★지금 이 순간 10코인의 4h/1h 상승추세 상태 — "16일부터 진입0"이 정상(하락/횡보)인지 버그인지 판별. KNN없음, 빠름.
    private static async Task RunRegimeNowAsync()
    {
        var universe = new[] { "BTCUSDT","ETHUSDT","BNBUSDT","SOLUSDT","XRPUSDT","DOGEUSDT","ADAUSDT","AVAXUSDT","ARBUSDT","SUIUSDT" };
        Console.WriteLine("=== 현재 시점 추세 상태 — 진입 게이트가 열려있나? (16일부터 진입0 원인) ===\n");
        Console.WriteLine($"  {"코인",9} {"현재가",12} {"4h정배열",9} {"4h ADX",7} {"1h정배열",9} {"게이트",8}");
        int gateOpen = 0;
        foreach (var sym in universe)
        {
            List<IBinanceKline> b4, h1;
            try { b4 = await FetchKlines4hAsync(sym, 3); h1 = await FetchKlines1hAsync(sym, 3); } catch { Console.WriteLine($"  {sym,9} fetch 실패"); continue; }
            if (b4.Count < 210 || h1.Count < 210) { Console.WriteLine($"  {sym,9} 데이터부족"); continue; }
            int i4 = b4.Count - 2;   // 마지막 마감 4h봉
            double e50 = CalcEMA(b4, i4, 50), e200 = CalcEMA(b4, i4, 200), c4 = (double)b4[i4].ClosePrice;
            double adx4 = 0; { double aS = 0, pS = 0, mS = 0; int per = 14; var badx = new double[b4.Count]; for (int j = 1; j <= i4; j++) { double hh = (double)b4[j].HighPrice, ll = (double)b4[j].LowPrice, pc = (double)b4[j - 1].ClosePrice, ph = (double)b4[j - 1].HighPrice, pl = (double)b4[j - 1].LowPrice; double tr = Math.Max(hh - ll, Math.Max(Math.Abs(hh - pc), Math.Abs(ll - pc))); double up = hh - ph, dn = pl - ll; double pdm = (up > dn && up > 0) ? up : 0, mdm = (dn > up && dn > 0) ? dn : 0; if (j <= per) { aS += tr; pS += pdm; mS += mdm; } else { aS = aS - aS / per + tr; pS = pS - pS / per + pdm; mS = mS - mS / per + mdm; } if (j >= per && aS > 0) { double pd = 100 * pS / aS, md = 100 * mS / aS; double dx = (pd + md) > 0 ? 100 * Math.Abs(pd - md) / (pd + md) : 0; badx[j] = j <= per * 2 ? dx : (badx[j - 1] * (per - 1) + dx) / per; } } adx4 = badx[i4]; }
            bool r4 = e50 > 0 && e200 > 0 && e50 > e200 && c4 > e50 && adx4 >= 20.0;
            int i1 = h1.Count - 2; double he50 = CalcEMA(h1, i1, 50), he200 = CalcEMA(h1, i1, 200), hc = (double)h1[i1].ClosePrice;
            bool r1 = he50 > 0 && he200 > 0 && he50 > he200 && hc > he50;
            bool gate = r4 && r1;
            if (gate) gateOpen++;
            Console.WriteLine($"  {sym,9} {c4,12:F4} {(r4 ? "✅상승" : "❌아님"),9} {adx4,7:F0} {(r1 ? "✅상승" : "❌아님"),9} {(gate ? "🟢열림" : "🔴닫힘"),8}");
        }
        Console.WriteLine($"\n  게이트 열린 코인: {gateOpen}/{universe.Length}");
        Console.WriteLine(gateOpen == 0
            ? "  → 0개 = 지금 10코인 전부 4h/1h 상승추세 아님 = 진입0이 정상(하락/횡보 회피). 버그 아님."
            : "  → 열린 코인 있는데 라이브가 진입0이면 = 15m KNN/방어에서 막히거나 라이브 이슈 점검 필요.");
    }

    // --optimize2020 : ★2020~현재 전체 데이터로 흑자월 최대 로직 탐색. 훈련(2020~23)/검증(2024~26) 분리 = 과최적화 방지.
    //   코인별 KNN·지표·HA 1회 프리컴퓨트 → 다변형(트레일 5종 × 1h컨플루언스 × ADX) 재생. 모든 트레이드/월별 저장.
    private static async Task RunOptimize2020Async()
    {
        const int featureWindow = 500, K = 8, Lh = 4;
        const decimal feeRT = 0.0008m; decimal margin = 1000m; int slots = 6; decimal capital = margin * slots;
        var universe = new[] { "BTCUSDT","ETHUSDT","BNBUSDT","SOLUSDT","XRPUSDT","DOGEUSDT","ADAUSDT","AVAXUSDT","LTCUSDT","BCHUSDT","ETCUSDT","LINKUSDT" };
        Console.WriteLine("=== 2020~현재 옵티마이저 — 흑자월 최대 로직 (훈련2020-23/검증2024-26 분리, KNN+HA) ===\n");
        // 코인별 프리컴퓨트 저장
        var coins = new List<(string sym, List<IBinanceKline> k15, double[] close, double[] e50, double[] e200, double[] atr, double[] rsi, double[] hist, int[] sg, bool[] haGreen, List<(DateTime c, bool up20, bool up25)> reg4, List<(DateTime c, bool up)> reg1)>();
        int ci = 0;
        foreach (var sym in universe)
        {
            ci++; Console.Write($"[{ci}/{universe.Length}] {sym} ");
            List<IBinanceKline> b4, k15, h1;
            try { b4 = await FetchKlines4hAsync(sym, 20); k15 = await FetchKlines15mAsync(sym, 170); h1 = await FetchKlines1hAsync(sym, 60); } catch { Console.WriteLine("fail"); continue; }
            if (b4.Count < 300 || k15.Count < 1000) { Console.WriteLine("skip"); continue; }
            int bn = b4.Count; var be200 = new double[bn]; for (int j = 200; j < bn; j++) be200[j] = CalcEMA(b4, j, 200);
            var be50 = new double[bn]; for (int j = 50; j < bn; j++) be50[j] = CalcEMA(b4, j, 50);
            var badx = new double[bn]; { double aS = 0, pS = 0, mS = 0; int per = 14; for (int j = 1; j < bn; j++) { double hh = (double)b4[j].HighPrice, ll = (double)b4[j].LowPrice, pc = (double)b4[j - 1].ClosePrice, ph = (double)b4[j - 1].HighPrice, pl = (double)b4[j - 1].LowPrice; double tr = Math.Max(hh - ll, Math.Max(Math.Abs(hh - pc), Math.Abs(ll - pc))); double up = hh - ph, dn = pl - ll; double pdm = (up > dn && up > 0) ? up : 0, mdm = (dn > up && dn > 0) ? dn : 0; if (j <= per) { aS += tr; pS += pdm; mS += mdm; } else { aS = aS - aS / per + tr; pS = pS - pS / per + pdm; mS = mS - mS / per + mdm; } if (j >= per && aS > 0) { double pd = 100 * pS / aS, md = 100 * mS / aS; double dx = (pd + md) > 0 ? 100 * Math.Abs(pd - md) / (pd + md) : 0; badx[j] = j <= per * 2 ? dx : (badx[j - 1] * (per - 1) + dx) / per; } } }
            var reg4 = new List<(DateTime, bool, bool)>();
            for (int j = 0; j < bn; j++) { double c = (double)b4[j].ClosePrice; bool align = j >= 200 && be50[j] > 0 && be200[j] > 0 && be50[j] > be200[j] && c > be50[j]; reg4.Add((b4[j].OpenTime.AddHours(4), align && badx[j] >= 20.0, align && badx[j] >= 25.0)); }
            int hn = h1.Count; var h50 = new double[hn]; for (int j = 50; j < hn; j++) h50[j] = CalcEMA(h1, j, 50); var h200 = new double[hn]; for (int j = 200; j < hn; j++) h200[j] = CalcEMA(h1, j, 200);
            var reg1 = new List<(DateTime, bool)>(); for (int j = 0; j < hn; j++) { double c = (double)h1[j].ClosePrice; reg1.Add((h1[j].OpenTime.AddHours(1), j >= 200 && h50[j] > 0 && h200[j] > 0 && h50[j] > h200[j] && c > h50[j])); }
            int n = k15.Count; var close = new double[n]; for (int j = 0; j < n; j++) close[j] = (double)k15[j].ClosePrice;
            var feats = new float[n][]; for (int j = 60; j < n; j++) { int ws = Math.Max(0, j - (featureWindow - 1)); feats[j] = LorentzianFeatures.Extract(k15.GetRange(ws, j - ws + 1))!; }
            var e50 = new double[n]; for (int j = 50; j < n; j++) e50[j] = CalcEMA(k15, j, 50);
            var e200 = new double[n]; for (int j = 200; j < n; j++) e200[j] = CalcEMA(k15, j, 200);
            var atr = new double[n]; for (int j = 14; j < n; j++) { double tr = 0; for (int q = j - 13; q <= j; q++) { double hh = (double)k15[q].HighPrice, ll = (double)k15[q].LowPrice, pc = close[q - 1]; tr += Math.Max(hh - ll, Math.Max(Math.Abs(hh - pc), Math.Abs(ll - pc))); } atr[j] = tr / 14.0; }
            var rsi = new double[n]; { double ag = 0, al = 0; int per = 14; for (int j = 1; j < n; j++) { double ch = close[j] - close[j - 1]; double g = ch > 0 ? ch : 0, ls = ch < 0 ? -ch : 0; if (j <= per) { ag += g; al += ls; if (j == per) { ag /= per; al /= per; rsi[j] = al == 0 ? 100 : 100 - 100 / (1 + ag / al); } } else { ag = (ag * (per - 1) + g) / per; al = (al * (per - 1) + ls) / per; rsi[j] = al == 0 ? 100 : 100 - 100 / (1 + ag / al); } } }
            var hist = new double[n]; { double x12 = close[0], x26 = close[0], sig = 0; bool si = false; for (int j = 1; j < n; j++) { double c = close[j]; x12 += (c - x12) * (2.0 / 13); x26 += (c - x26) * (2.0 / 27); double macd = x12 - x26; if (!si) { sig = macd; si = true; } else sig += (macd - sig) * (2.0 / 10); hist[j] = macd - sig; } }
            // Heikin Ashi (색: HA종가>=HA시가 = 초록)
            var haGreen = new bool[n]; { double haO = 0, haC = 0; for (int j = 0; j < n; j++) { double o = (double)k15[j].OpenPrice, h = (double)k15[j].HighPrice, l = (double)k15[j].LowPrice, c = close[j]; double hc = (o + h + l + c) / 4.0; haO = j == 0 ? (o + c) / 2.0 : (haO + haC) / 2.0; haC = hc; haGreen[j] = haC >= haO; } }
            var engine = new LorentzianAnnEngine(sym, neighborsCount: K, maxBarsBack: 2000, featureCount: LorentzianFeatures.FeatureCount);
            var sg = new int[n];
            for (int j = 65; j < n; j++) { int s = j - 1; if (s - Lh >= 0 && feats[s] != null) { double a = close[s], b = close[s - Lh]; engine.AddSample(feats[s], a > b ? 1 : (a < b ? -1 : 0)); } if (feats[j] == null) continue; var p = engine.Predict(feats[j]); if (!p.IsReady || p.K == 0) continue; sg[j] = p.Prediction > 0 ? 1 : (p.Prediction < 0 ? -1 : 0); }
            var first = k15.Count > 0 ? k15[0].OpenTime : DateTime.MinValue;
            Console.WriteLine($"15m={n} (시작 {first:yyyy-MM})");
            coins.Add((sym, k15, close, e50, e200, atr, rsi, hist, sg, haGreen, reg4, reg1));
        }
        Console.WriteLine($"\n프리컴퓨트 완료 {coins.Count}코인. 다변형 스윕 시작...\n");
        // 트레일 재생 함수
        double RunExit(double[] close, double[] atr, bool[] haGreen, int jEntry, double entryPx, int exitMode, out int ei)
        {
            int n = close.Length; double peak = entryPx; ei = n - 1; double exPx = close[n - 1]; double atrE = atr[jEntry];
            for (int e = jEntry + 1; e < n; e++)
            {
                double cc = close[e]; if (cc > peak) peak = cc;
                bool hit = false;
                if (exitMode == 0) { double p = atrE > 0 ? (peak - entryPx) / atrE : 0; hit = cc <= peak - (p < 3 ? 4.0 : 10.0) * atr[e]; }       // 확대4→10
                else if (exitMode == 1) hit = cc <= peak - 5.0 * atr[e];                                                                          // 고정5
                else if (exitMode == 2) hit = cc <= peak - 10.0 * atr[e];                                                                         // 고정10
                else if (exitMode == 3) { double p = atrE > 0 ? (peak - entryPx) / atrE : 0; hit = cc <= peak - (p < 2 ? 3.0 : 12.0) * atr[e]; }   // 확대3→12
                else if (exitMode == 4) hit = !haGreen[e] && !haGreen[e - 1];                                                                     // HA 2봉 연속 빨강
                if (hit) { ei = e; exPx = cc; return (exPx - entryPx) / entryPx - (double)feeRT; }
                if (e == n - 1) { ei = e; exPx = cc; }
            }
            return (exPx - entryPx) / entryPx - (double)feeRT;
        }
        var exitNames = new[] { "확대4→10", "고정5ATR", "고정10ATR", "확대3→12", "HA색전환" };
        var results = new List<(string name, int trainN, double trainGreen, int testN, double testGreen, double totRet, double pf, double mdd)>();
        for (int exitMode = 0; exitMode < 5; exitMode++)
        foreach (bool use1h in new[] { false, true })
        foreach (int adxSel in new[] { 20, 25 })
        {
            var trades = new List<(DateTime ent, DateTime ex, decimal pnl)>();
            foreach (var cd in coins)
            {
                int n = cd.close.Length; int rp = 0, hp = 0, busy = -1;
                for (int j = 250; j < n - 1; j++)
                {
                    if (j <= busy) continue;
                    var t15 = cd.k15[j].OpenTime;
                    while (rp + 1 < cd.reg4.Count && cd.reg4[rp + 1].c <= t15) rp++;
                    while (hp + 1 < cd.reg1.Count && cd.reg1[hp + 1].c <= t15) hp++;
                    bool r4 = cd.reg4[rp].c <= t15 && (adxSel == 20 ? cd.reg4[rp].up20 : cd.reg4[rp].up25);
                    if (!r4) continue;
                    if (use1h && !(cd.reg1[hp].c <= t15 && cd.reg1[hp].up)) continue;
                    if (!(cd.sg[j] > 0 && cd.e50[j] > 0 && cd.e200[j] > 0 && cd.e50[j] > cd.e200[j] && cd.close[j] > cd.e50[j])) continue;
                    if (cd.atr[j] <= 0 || cd.k15[j + 1].OpenPrice <= 0) continue;
                    if ((cd.close[j] - cd.e50[j]) / cd.atr[j] >= 2.0 || cd.rsi[j] >= 60.0) continue;
                    if ((5.0 * cd.atr[j]) / cd.close[j] > 0.05) continue;
                    double uw = ((double)cd.k15[j].HighPrice - Math.Max((double)cd.k15[j].OpenPrice, cd.close[j])) / cd.atr[j];
                    if (cd.hist[j] < 0 && uw > 0.4) continue;
                    double entryPx = (double)cd.k15[j + 1].OpenPrice;
                    double net = RunExit(cd.close, cd.atr, cd.haGreen, j, entryPx, exitMode, out int ei);
                    busy = ei; trades.Add((cd.k15[j + 1].OpenTime, cd.k15[ei].OpenTime, (decimal)net));
                }
            }
            trades.Sort((a, b) => a.ent.CompareTo(b.ent));
            var open = new List<DateTime>(); var mon = new SortedDictionary<string, decimal>(); decimal gw = 0, gl = 0, cum = 0, peak = 0, mdd = 0, tot = 0;
            foreach (var t in trades)
            {
                open.RemoveAll(x => x <= t.ent); if (open.Count >= slots) continue; open.Add(t.ex);
                decimal p = t.pnl * margin; tot += p; cum += p; if (cum > peak) peak = cum; if (peak - cum > mdd) mdd = peak - cum;
                if (p > 0) gw += p; else gl += -p;
                var mk = t.ent.ToString("yyyy-MM"); mon[mk] = (mon.TryGetValue(mk, out var mv) ? mv : 0) + p;
            }
            int trN = mon.Keys.Count(k => string.Compare(k, "2024-01") < 0), teN = mon.Keys.Count(k => string.Compare(k, "2024-01") >= 0);
            int trG = mon.Count(kv => string.Compare(kv.Key, "2024-01") < 0 && kv.Value > 0);
            int teG = mon.Count(kv => string.Compare(kv.Key, "2024-01") >= 0 && kv.Value > 0);
            double pf = gl > 0 ? (double)(gw / gl) : 999;
            string name = $"{exitNames[exitMode]}·{(use1h ? "1h" : "no1h")}·ADX{adxSel}";
            results.Add((name, trN, trN > 0 ? 100.0 * trG / trN : 0, teN, teN > 0 ? 100.0 * teG / teN : 0, (double)(tot / capital * 100m), pf, (double)(mdd / capital * 100m)));
        }
        // 검증셋 흑자월% 순 정렬
        results.Sort((a, b) => b.testGreen.CompareTo(a.testGreen));
        Console.WriteLine($"  {"설정",24} {"훈련흑자월%",11} {"검증흑자월%",11} {"총수익%",8} {"PF",5} {"MDD%",6}");
        var inv = System.Globalization.CultureInfo.InvariantCulture; var sb = new System.Text.StringBuilder(); sb.Append('[');
        bool jf = true;
        foreach (var r in results)
        {
            Console.WriteLine($"  {r.name,24} {r.trainGreen,10:F0}% {r.testGreen,10:F0}% {r.totRet,8:F0} {r.pf,5:F2} {r.mdd,6:F0}");
            if (!jf) sb.Append(','); jf = false;
            sb.Append($"{{\"cfg\":\"{r.name}\",\"trainGreen\":{r.trainGreen.ToString("F0", inv)},\"testGreen\":{r.testGreen.ToString("F0", inv)},\"ret\":{r.totRet.ToString("F0", inv)},\"pf\":{r.pf.ToString("F2", inv)},\"mdd\":{r.mdd.ToString("F0", inv)}}}");
        }
        sb.Append(']'); System.IO.File.WriteAllText("optimize2020-results.json", sb.ToString());
        Console.WriteLine("\n  → 검증(2024-26) 흑자월%가 훈련과 비슷하게 높은 설정 = 과최적화 아닌 진짜. 훈련만 높고 검증 낮으면 = 과최적화(버림).");
        Console.WriteLine("  → optimize2020-results.json 저장. 100% 흑자월 나오면 오히려 의심(표본/기간 확인).");
    }

    // --funnel2026 : ★개발 로직(v5.28.3, KNN포함) 그대로 — 2026 월별 진입 깔때기. 각 관문(4h→1h→KNN+EMA→방어→진입)에서 몇 개가 떨어지나. 진입0월 원인 규명.
    private static async Task RunFunnel2026Async()
    {
        const int featureWindow = 500, K = 8, Lh = 4;
        var universe = new[] { "BTCUSDT","ETHUSDT","BNBUSDT","SOLUSDT","XRPUSDT","DOGEUSDT","ADAUSDT","AVAXUSDT","ARBUSDT","SUIUSDT" };
        Console.WriteLine("=== 개발로직(v5.28.3·KNN포함) 2026 월별 진입 깔때기 — 어느 관문에서 0이 되나 (진입0월 원인) ===\n");
        // month -> [evalBars, pass4h, pass1h, passKnnEma, passDef]
        var f = new SortedDictionary<string, long[]>();
        void Bump(string mo, int idx) { if (!f.ContainsKey(mo)) f[mo] = new long[5]; f[mo][idx]++; }
        int ci = 0;
        foreach (var sym in universe)
        {
            ci++; Console.Write($"[{ci}/{universe.Length}] {sym} ");
            List<IBinanceKline> b4, k15, h1;
            try { b4 = await FetchKlines4hAsync(sym, 12); k15 = await FetchKlines15mAsync(sym, 110); h1 = await FetchKlines1hAsync(sym, 40); } catch { Console.WriteLine("fail"); continue; }
            if (b4.Count < 300 || k15.Count < 1000) { Console.WriteLine("skip"); continue; }
            int bn = b4.Count; var be200 = new double[bn]; for (int j = 200; j < bn; j++) be200[j] = CalcEMA(b4, j, 200);
            var be50 = new double[bn]; for (int j = 50; j < bn; j++) be50[j] = CalcEMA(b4, j, 50);
            var badx = new double[bn]; { double aS = 0, pS = 0, mS = 0; int per = 14; for (int j = 1; j < bn; j++) { double hh = (double)b4[j].HighPrice, ll = (double)b4[j].LowPrice, pc = (double)b4[j - 1].ClosePrice, ph = (double)b4[j - 1].HighPrice, pl = (double)b4[j - 1].LowPrice; double tr = Math.Max(hh - ll, Math.Max(Math.Abs(hh - pc), Math.Abs(ll - pc))); double up = hh - ph, dn = pl - ll; double pdm = (up > dn && up > 0) ? up : 0, mdm = (dn > up && dn > 0) ? dn : 0; if (j <= per) { aS += tr; pS += pdm; mS += mdm; } else { aS = aS - aS / per + tr; pS = pS - pS / per + pdm; mS = mS - mS / per + mdm; } if (j >= per && aS > 0) { double pd = 100 * pS / aS, md = 100 * mS / aS; double dx = (pd + md) > 0 ? 100 * Math.Abs(pd - md) / (pd + md) : 0; badx[j] = j <= per * 2 ? dx : (badx[j - 1] * (per - 1) + dx) / per; } } }
            var reg = new List<(DateTime close, bool up)>();
            for (int j = 0; j < bn; j++) { double c = (double)b4[j].ClosePrice; reg.Add((b4[j].OpenTime.AddHours(4), j >= 200 && be50[j] > 0 && be200[j] > 0 && be50[j] > be200[j] && c > be50[j] && badx[j] >= 20.0)); }
            int hn = h1.Count; var h50 = new double[hn]; for (int j = 50; j < hn; j++) h50[j] = CalcEMA(h1, j, 50); var h200 = new double[hn]; for (int j = 200; j < hn; j++) h200[j] = CalcEMA(h1, j, 200);
            var hreg = new List<(DateTime close, bool up)>(); for (int j = 0; j < hn; j++) { double c = (double)h1[j].ClosePrice; hreg.Add((h1[j].OpenTime.AddHours(1), j >= 200 && h50[j] > 0 && h200[j] > 0 && h50[j] > h200[j] && c > h50[j])); }
            int n = k15.Count; Console.WriteLine($"15m={n}");
            var close = new double[n]; for (int j = 0; j < n; j++) close[j] = (double)k15[j].ClosePrice;
            var feats = new float[n][]; for (int j = 60; j < n; j++) { int ws = Math.Max(0, j - (featureWindow - 1)); feats[j] = LorentzianFeatures.Extract(k15.GetRange(ws, j - ws + 1))!; }
            var e50 = new double[n]; for (int j = 50; j < n; j++) e50[j] = CalcEMA(k15, j, 50);
            var e200 = new double[n]; for (int j = 200; j < n; j++) e200[j] = CalcEMA(k15, j, 200);
            var atr = new double[n]; for (int j = 14; j < n; j++) { double tr = 0; for (int q = j - 13; q <= j; q++) { double hh = (double)k15[q].HighPrice, ll = (double)k15[q].LowPrice, pc = close[q - 1]; tr += Math.Max(hh - ll, Math.Max(Math.Abs(hh - pc), Math.Abs(ll - pc))); } atr[j] = tr / 14.0; }
            var rsi = new double[n]; { double ag = 0, al = 0; int per = 14; for (int j = 1; j < n; j++) { double ch = close[j] - close[j - 1]; double g = ch > 0 ? ch : 0, ls = ch < 0 ? -ch : 0; if (j <= per) { ag += g; al += ls; if (j == per) { ag /= per; al /= per; rsi[j] = al == 0 ? 100 : 100 - 100 / (1 + ag / al); } } else { ag = (ag * (per - 1) + g) / per; al = (al * (per - 1) + ls) / per; rsi[j] = al == 0 ? 100 : 100 - 100 / (1 + ag / al); } } }
            var hist = new double[n]; { double x12 = close[0], x26 = close[0], sig = 0; bool si = false; for (int j = 1; j < n; j++) { double c = close[j]; x12 += (c - x12) * (2.0 / 13); x26 += (c - x26) * (2.0 / 27); double macd = x12 - x26; if (!si) { sig = macd; si = true; } else sig += (macd - sig) * (2.0 / 10); hist[j] = macd - sig; } }
            var engine = new LorentzianAnnEngine(sym, neighborsCount: K, maxBarsBack: 2000, featureCount: LorentzianFeatures.FeatureCount);
            var sg = new int[n];
            for (int j = 65; j < n; j++) { int s = j - 1; if (s - Lh >= 0 && feats[s] != null) { double a = close[s], b = close[s - Lh]; engine.AddSample(feats[s], a > b ? 1 : (a < b ? -1 : 0)); } if (feats[j] == null) continue; var p = engine.Predict(feats[j]); if (!p.IsReady || p.K == 0) continue; sg[j] = p.Prediction > 0 ? 1 : (p.Prediction < 0 ? -1 : 0); }
            int rp = 0, hp = 0;
            for (int j = 250; j < n - 1; j++)
            {
                var kst = k15[j].OpenTime.AddHours(9); if (kst.Year != 2026) continue;
                string mo = kst.ToString("yyyy-MM");
                var t15 = k15[j].OpenTime;
                while (rp + 1 < reg.Count && reg[rp + 1].close <= t15) rp++;
                while (hp + 1 < hreg.Count && hreg[hp + 1].close <= t15) hp++;
                Bump(mo, 0); // evalBars
                if (!(reg[rp].close <= t15 && reg[rp].up)) continue; Bump(mo, 1); // pass 4h
                if (!(hreg[hp].close <= t15 && hreg[hp].up)) continue; Bump(mo, 2); // pass 1h
                if (!(sg[j] > 0 && e50[j] > 0 && e200[j] > 0 && e50[j] > e200[j] && close[j] > e50[j])) continue; Bump(mo, 3); // KNN+EMA
                if (atr[j] <= 0 || k15[j + 1].OpenPrice <= 0) continue;
                if ((close[j] - e50[j]) / atr[j] >= 2.0 || rsi[j] >= 60.0) continue;
                if ((5.0 * atr[j]) / close[j] > 0.05) continue;
                double uw = ((double)k15[j].HighPrice - Math.Max((double)k15[j].OpenPrice, close[j])) / atr[j];
                if (hist[j] < 0 && uw > 0.4) continue;
                Bump(mo, 4); // pass 방어 (진입후보)
            }
        }
        Console.WriteLine($"\n  {"월",8} {"평가봉",8} {"4h통과",8} {"1h통과",8} {"KNN+EMA",9} {"방어통과(후보)",12}");
        for (int mo = 1; mo <= 7; mo++)
        {
            string key = $"2026-{mo:00}";
            var a = f.TryGetValue(key, out var v) ? v : new long[5];
            Console.WriteLine($"  {key,8} {a[0],8} {a[1],8} {a[2],8} {a[3],9} {a[4],12}");
        }
        Console.WriteLine("\n  → 2·6월이 '4h통과'부터 0이면 = 30코인이라도 확정상승추세 자체가 없었던 것(진입0 정당).");
        Console.WriteLine("     4h/1h는 통과하는데 KNN+EMA나 방어에서 0되면 = 그 관문이 과필터(완화 검토 대상).");
    }

    // --levfinal : ★발굴조합(BB중심상+ADX25) 확정 — 고정12/확대3→12 × 레버(1/3/5/10x) 계좌 ruin 시뮬 + 승률. 연100% 검증.
    private static async Task RunLevFinalAsync()
    {
