        var msb = new System.Text.StringBuilder(); msb.Append('['); bool mf = true;
        foreach (var kv in monthly) { cum += kv.Value.pnl; if (kv.Value.pnl > 0) prof++; Console.WriteLine($"  {kv.Key,8} {kv.Value.n,5} {kv.Value.pnl,10:F0} {cum,11:F0}"); if (!mf) msb.Append(','); mf = false; msb.Append($"{{\"m\":\"{kv.Key}\",\"n\":{kv.Value.n},\"pnl\":{kv.Value.pnl.ToString("F0", inv)},\"cum\":{cum.ToString("F0", inv)}}}"); }
        msb.Append(']');
        Console.WriteLine($"  총 {monthly.Count}개월 · 흑자월 {prof} ({100.0 * prof / Math.Max(1, monthly.Count):F0}%) · 총 ${cum:F0}");
        // 콘솔 일별(최근 3개월)
        Console.WriteLine($"\n── 최근 3개월 일별 ({string.Join(",", last3.OrderBy(x => x))}) ──");
        Console.WriteLine($"  {"날짜",12} {"진입",5} {"수익금$",10}");
        var dsb = new System.Text.StringBuilder(); dsb.Append('['); bool df = true;
        foreach (var kv in daily) { if (!last3.Contains(kv.Key.Substring(0, 7))) continue; Console.WriteLine($"  {kv.Key,12} {kv.Value.n,5} {kv.Value.pnl,10:F0}"); if (!df) dsb.Append(','); df = false; dsb.Append($"{{\"d\":\"{kv.Key}\",\"n\":{kv.Value.n},\"pnl\":{kv.Value.pnl.ToString("F0", inv)}}}"); }
        dsb.Append(']');
        System.IO.File.WriteAllText("report-final.json", "{\"monthly\":" + msb + ",\"daily\":" + dsb + "}");
        Console.WriteLine($"\n  → report-final.json 저장 (월별+최근3개월 일별)");
    }

    // --tune-4h : 4h 기준 파라미터 재최적화 — ADX임계 × ATR트레일배수 병렬스윕 (방어3종 포함). 흑자월%·수익·MDD 최적점.
    private static async Task RunTune4hAsync()
    {
        const int featureWindow = 500, K = 8, Lh = 4;
        const decimal feeRT = 0.0008m; decimal margin = 500m; int slots = 6; decimal capital = margin * slots;
        var universe = new[] {
            "BTCUSDT","ETHUSDT","BNBUSDT","SOLUSDT","XRPUSDT","DOGEUSDT","ADAUSDT","TRXUSDT","AVAXUSDT","LINKUSDT",
            "DOTUSDT","LTCUSDT","BCHUSDT","ATOMUSDT","UNIUSDT","NEARUSDT","APTUSDT","ARBUSDT","OPUSDT","SUIUSDT" };
        Console.WriteLine("=== 4h 파라미터 재최적화: ADX임계 × ATR트레일 병렬스윕 (방어3종·1x·6슬롯) ===\n");
        var btcBull = new Dictionary<DateTime, bool>();
        { var btc = await FetchKlines4hAsync("BTCUSDT", 12); int bn = btc.Count; var be2 = new double[bn]; for (int j = 200; j < bn; j++) be2[j] = CalcEMA(btc, j, 200); for (int j = 200; j < bn; j++) btcBull[btc[j].OpenTime] = be2[j] > 0 && (double)btc[j].ClosePrice > be2[j]; }
        var data = new List<(List<IBinanceKline> kl, double[] close, int[] sg, double[] e50, double[] e200, double[] atr, double[] adx)>();
        int ci = 0;
        foreach (var sym in universe)
        {
            ci++; Console.Write($"[{ci}/{universe.Length}] {sym} ");
            List<IBinanceKline> kl;
            try { kl = await FetchKlines4hAsync(sym, 12); } catch { Console.WriteLine("fail"); continue; }
            if (kl.Count < 800) { Console.WriteLine("skip"); continue; }
            int n = kl.Count; Console.WriteLine($"{n}"); var close = new double[n]; for (int j = 0; j < n; j++) close[j] = (double)kl[j].ClosePrice;
            var feats = new float[n][];
            for (int j = 60; j < n; j++) { int ws = Math.Max(0, j - (featureWindow - 1)); feats[j] = LorentzianFeatures.Extract(kl.GetRange(ws, j - ws + 1))!; }
            var e50 = new double[n]; for (int j = 50; j < n; j++) e50[j] = CalcEMA(kl, j, 50);
            var e200 = new double[n]; for (int j = 200; j < n; j++) e200[j] = CalcEMA(kl, j, 200);
            var atr = new double[n]; for (int j = 14; j < n; j++) { double tr = 0; for (int q = j - 13; q <= j; q++) { double hh = (double)kl[q].HighPrice, ll = (double)kl[q].LowPrice, pc = close[q - 1]; tr += Math.Max(hh - ll, Math.Max(Math.Abs(hh - pc), Math.Abs(ll - pc))); } atr[j] = tr / 14.0; }
            var adx = new double[n]; { double atrS = 0, pdmS = 0, mdmS = 0; int per = 14; for (int j = 1; j < n; j++) { double hh = (double)kl[j].HighPrice, ll = (double)kl[j].LowPrice, pc = close[j - 1], ph = (double)kl[j - 1].HighPrice, pl = (double)kl[j - 1].LowPrice; double tr = Math.Max(hh - ll, Math.Max(Math.Abs(hh - pc), Math.Abs(ll - pc))); double up = hh - ph, dn = pl - ll; double pdm = (up > dn && up > 0) ? up : 0, mdm = (dn > up && dn > 0) ? dn : 0; if (j <= per) { atrS += tr; pdmS += pdm; mdmS += mdm; } else { atrS = atrS - atrS / per + tr; pdmS = pdmS - pdmS / per + pdm; mdmS = mdmS - mdmS / per + mdm; } if (j >= per && atrS > 0) { double pd = 100 * pdmS / atrS, md = 100 * mdmS / atrS; double dx = (pd + md) > 0 ? 100 * Math.Abs(pd - md) / (pd + md) : 0; adx[j] = j <= per * 2 ? dx : (adx[j - 1] * (per - 1) + dx) / per; } } }
            var engine = new LorentzianAnnEngine(sym, neighborsCount: K, maxBarsBack: 2000, featureCount: LorentzianFeatures.FeatureCount);
            var sg = new int[n];
            for (int j = 65; j < n; j++) { int s = j - 1; if (s - Lh >= 0 && feats[s] != null) { double a = close[s], b = close[s - Lh]; engine.AddSample(feats[s], a > b ? 1 : (a < b ? -1 : 0)); } if (feats[j] == null) continue; var p = engine.Predict(feats[j]); if (!p.IsReady || p.K == 0) continue; sg[j] = p.Prediction > 0 ? 1 : (p.Prediction < 0 ? -1 : 0); }
            data.Add((kl, close, sg, e50, e200, atr, adx));
        }
        Console.WriteLine();
        double[] adxThrs = { 15, 20, 25, 30 };
        double[] atrMults = { 3, 4, 5, 6 };
        int nA = adxThrs.Length, nM = atrMults.Length, total = nA * nM;
        var results = new (double adxT, double atrM, int tn, double prof, double tot, double mo, double mdd, double worst)[total];
        System.Threading.Tasks.Parallel.For(0, total, idx =>
        {
            double adxT = adxThrs[idx % nA]; double atrM = atrMults[idx / nA];
            var trades = new List<(DateTime ent, DateTime ex, decimal pnl)>();
            foreach (var (kl, close, sg, e50, e200, atr, adx) in data)
            {
                int n = kl.Count; int busy = -1;
                for (int j = 250; j < n - 1; j++)
                {
                    if (j <= busy) continue;
                    if (!(sg[j] > 0 && e50[j] > 0 && e200[j] > 0 && e50[j] > e200[j] && close[j] > e50[j] && adx[j] >= adxT)) continue;
                    if (!(btcBull.TryGetValue(kl[j].OpenTime, out var bb) && bb)) continue;
                    if (atr[j] <= 0 || kl[j + 1].OpenPrice <= 0) continue;
                    // [4h 손실방어 재분석] EMA50 과확장만 유지 — 거래량·윗꼬리는 4h에서 승자 제거(해로움)라 제거. RSI14<60 추가.
                    if ((close[j] - e50[j]) / atr[j] >= 2.0) continue;
                    // RSI14<60 (과매수 회피)
                    { double ag = 0, al = 0; int per = 14; int s0 = Math.Max(1, j - 200); for (int q = s0; q <= j; q++) { double ch = close[q] - close[q - 1]; double g = ch > 0 ? ch : 0, ls = ch < 0 ? -ch : 0; if (q == s0) { ag = g; al = ls; } else { ag = (ag * (per - 1) + g) / per; al = (al * (per - 1) + ls) / per; } } double rsi = al == 0 ? 100 : 100 - 100 / (1 + ag / al); if (rsi >= 60) continue; }
                    decimal entry = kl[j + 1].OpenPrice; double peakP = (double)entry; decimal net = 0m; int ei = n - 1;
                    for (int e = j + 1; e < n; e++) { double cc = close[e]; if (cc > peakP) peakP = cc; if (cc <= peakP - atrM * atr[e]) { net = ((decimal)cc - entry) / entry - feeRT; ei = e; break; } if (e == n - 1) net = ((decimal)cc - entry) / entry - feeRT; }
                    busy = ei; trades.Add((kl[j + 1].OpenTime, kl[ei].OpenTime, net));
                }
            }
            trades.Sort((a, b) => a.ent.CompareTo(b.ent));
            var open = new List<DateTime>(); var monthly = new SortedDictionary<string, decimal>(); int tn = 0;
            foreach (var t in trades) { open.RemoveAll(x => x <= t.ent); if (open.Count >= slots) continue; open.Add(t.ex); monthly[t.ent.ToString("yyyy-MM")] = (monthly.TryGetValue(t.ent.ToString("yyyy-MM"), out var v) ? v : 0m) + t.pnl * margin; tn++; }
            int prof = 0; decimal cum = 0m, peak = 0m, mdd = 0m, worst = 0m, tot = 0m; int mo = monthly.Count;
            foreach (var kv in monthly) { if (kv.Value > 0) prof++; if (kv.Value < worst) worst = kv.Value; cum += kv.Value; tot += kv.Value; if (cum > peak) peak = cum; if (peak - cum > mdd) mdd = peak - cum; }
            results[idx] = (adxT, atrM, tn, mo > 0 ? 100.0 * prof / mo : 0, (double)(tot / capital * 100m), mo > 0 ? (double)(tot / capital * 100m) / mo : 0, (double)(mdd / capital * 100m), (double)(worst / capital * 100m));
        });
        Console.WriteLine($"  {"ADX",4} {"ATR트레일",8} {"진입",5} {"흑자월%",7} {"총수익%",8} {"월평균%",8} {"MDD%",6} {"최악월%",7}");
        foreach (var r in results.OrderByDescending(x => x.prof).ThenByDescending(x => x.tot))
            Console.WriteLine($"  {r.adxT,4:F0} {r.atrM,8:F0} {r.tn,5} {r.prof,7:F0} {r.tot,8:F0} {r.mo,8:F1} {r.mdd,6:F0} {r.worst,7:F1}");
        Console.WriteLine("\n  → 흑자월% 최고 & MDD 낮은 조합이 4h 최적. 현재 라이브=ADX20·ATR5.");
    }

    // --tf-compare : 동일 로직(KNN+EMA정배열+ADX20+BTC상승장+방어3종, 종가 5ATR트레일)을 1h vs 4h 비교.
    //   4h가 추세 깨끗해 흑자월↑·MDD↓ 되는지 검증. 1x 6슬롯.
    private static async Task RunTfCompareAsync()
    {
        const int featureWindow = 500, K = 8, Lh = 4;
        const decimal feeRT = 0.0008m; const double atrMult = 5.0, adxThr = 20;
        decimal margin = 500m; int slots = 6; decimal capital = margin * slots;
        var universe = new[] {
            "BTCUSDT","ETHUSDT","BNBUSDT","SOLUSDT","XRPUSDT","DOGEUSDT","ADAUSDT","TRXUSDT","AVAXUSDT","LINKUSDT",
            "DOTUSDT","LTCUSDT","BCHUSDT","ATOMUSDT","UNIUSDT","NEARUSDT","APTUSDT","ARBUSDT","OPUSDT","SUIUSDT" };
        async Task<(int tn, double prof, double tot, double mdd, double worst, int months)> RunTf(Func<string, Task<List<IBinanceKline>>> fetch, string tf)
        {
            var btcBull = new Dictionary<DateTime, bool>();
            { var btc = await fetch("BTCUSDT"); int bn = btc.Count; var be2 = new double[bn]; for (int j = 200; j < bn; j++) be2[j] = CalcEMA(btc, j, 200); for (int j = 200; j < bn; j++) btcBull[btc[j].OpenTime] = be2[j] > 0 && (double)btc[j].ClosePrice > be2[j]; }
            var allTrades = new List<(DateTime ent, DateTime ex, decimal pnl)>();
            int ci = 0;
            foreach (var sym in universe)
            {
                ci++; Console.Write($"  [{tf} {ci}/{universe.Length}] {sym} ");
                List<IBinanceKline> kl;
                try { kl = await fetch(sym); } catch { Console.WriteLine("fail"); continue; }
                if (kl.Count < 800) { Console.WriteLine($"skip({kl.Count})"); continue; }
                int n = kl.Count; Console.WriteLine($"{n}"); var close = new double[n]; for (int j = 0; j < n; j++) close[j] = (double)kl[j].ClosePrice;
                var feats = new float[n][];
                for (int j = 60; j < n; j++) { int ws = Math.Max(0, j - (featureWindow - 1)); feats[j] = LorentzianFeatures.Extract(kl.GetRange(ws, j - ws + 1))!; }
                var e50 = new double[n]; for (int j = 50; j < n; j++) e50[j] = CalcEMA(kl, j, 50);
                var e200 = new double[n]; for (int j = 200; j < n; j++) e200[j] = CalcEMA(kl, j, 200);
                var atr = new double[n]; for (int j = 14; j < n; j++) { double tr = 0; for (int q = j - 13; q <= j; q++) { double hh = (double)kl[q].HighPrice, ll = (double)kl[q].LowPrice, pc = close[q - 1]; tr += Math.Max(hh - ll, Math.Max(Math.Abs(hh - pc), Math.Abs(ll - pc))); } atr[j] = tr / 14.0; }
                var adx = new double[n]; { double atrS = 0, pdmS = 0, mdmS = 0; int per = 14; for (int j = 1; j < n; j++) { double hh = (double)kl[j].HighPrice, ll = (double)kl[j].LowPrice, pc = close[j - 1], ph = (double)kl[j - 1].HighPrice, pl = (double)kl[j - 1].LowPrice; double tr = Math.Max(hh - ll, Math.Max(Math.Abs(hh - pc), Math.Abs(ll - pc))); double up = hh - ph, dn = pl - ll; double pdm = (up > dn && up > 0) ? up : 0, mdm = (dn > up && dn > 0) ? dn : 0; if (j <= per) { atrS += tr; pdmS += pdm; mdmS += mdm; } else { atrS = atrS - atrS / per + tr; pdmS = pdmS - pdmS / per + pdm; mdmS = mdmS - mdmS / per + mdm; } if (j >= per && atrS > 0) { double pd = 100 * pdmS / atrS, md = 100 * mdmS / atrS; double dx = (pd + md) > 0 ? 100 * Math.Abs(pd - md) / (pd + md) : 0; adx[j] = j <= per * 2 ? dx : (adx[j - 1] * (per - 1) + dx) / per; } } }
                var engine = new LorentzianAnnEngine(sym, neighborsCount: K, maxBarsBack: 2000, featureCount: LorentzianFeatures.FeatureCount);
                var sg = new int[n];
                for (int j = 65; j < n; j++) { int s = j - 1; if (s - Lh >= 0 && feats[s] != null) { double a = close[s], b = close[s - Lh]; engine.AddSample(feats[s], a > b ? 1 : (a < b ? -1 : 0)); } if (feats[j] == null) continue; var p = engine.Predict(feats[j]); if (!p.IsReady || p.K == 0) continue; sg[j] = p.Prediction > 0 ? 1 : (p.Prediction < 0 ? -1 : 0); }
                int busy = -1;
                for (int j = 250; j < n - 1; j++)
                {
                    if (j <= busy) continue;
                    if (!(sg[j] > 0 && e50[j] > 0 && e200[j] > 0 && e50[j] > e200[j] && close[j] > e50[j] && adx[j] >= adxThr)) continue;
                    if (!(btcBull.TryGetValue(kl[j].OpenTime, out var bb) && bb)) continue;
                    if (atr[j] <= 0 || kl[j + 1].OpenPrice <= 0) continue;
                    if ((close[j] - e50[j]) / atr[j] >= 2.0) continue;
                    double vsumM = 0; for (int q = j - 19; q <= j; q++) vsumM += (double)kl[q].Volume; double vavgM = vsumM / 20;
                    if (vavgM > 0 && (double)kl[j].Volume / vavgM >= 1.5) continue;
                    if (((double)kl[j].HighPrice - Math.Max((double)kl[j].OpenPrice, close[j])) / atr[j] >= 0.5) continue;
                    decimal entry = kl[j + 1].OpenPrice; double peakP = (double)entry; decimal net = 0m; int ei = n - 1;
                    for (int e = j + 1; e < n; e++) { double cc = close[e]; if (cc > peakP) peakP = cc; if (cc <= peakP - atrMult * atr[e]) { net = ((decimal)cc - entry) / entry - feeRT; ei = e; break; } if (e == n - 1) net = ((decimal)cc - entry) / entry - feeRT; }
                    busy = ei; allTrades.Add((kl[j + 1].OpenTime, kl[ei].OpenTime, net));
                }
            }
            allTrades.Sort((a, b) => a.ent.CompareTo(b.ent));
            var open = new List<DateTime>(); var monthly = new SortedDictionary<string, decimal>(); int tn = 0;
            foreach (var t in allTrades) { open.RemoveAll(x => x <= t.ent); if (open.Count >= slots) continue; open.Add(t.ex); monthly[t.ent.ToString("yyyy-MM")] = (monthly.TryGetValue(t.ent.ToString("yyyy-MM"), out var v) ? v : 0m) + t.pnl * margin; tn++; }
            if (monthly.Count == 0) return (0, 0, 0, 0, 0, 0);
            int prof = 0; decimal cum = 0m, peak = 0m, mdd = 0m, worst = 0m, tot = 0m;
            foreach (var kv in monthly) { if (kv.Value > 0) prof++; if (kv.Value < worst) worst = kv.Value; cum += kv.Value; tot += kv.Value; if (cum > peak) peak = cum; if (peak - cum > mdd) mdd = peak - cum; }
            return (tn, 100.0 * prof / monthly.Count, (double)(tot / capital * 100m), (double)(mdd / capital * 100m), (double)(worst / capital * 100m), monthly.Count);
        }
        Console.WriteLine("=== 타임프레임 비교: 1h vs 4h (동일 로직+방어, 1x 6슬롯 $3,000) ===\n");
        var r1 = await RunTf(s => FetchKlines1hAsync(s, 20), "1h");
        var r4 = await RunTf(s => FetchKlines4hAsync(s, 12), "4h");
        Console.WriteLine($"\n  {"TF",5} {"진입",5} {"흑자월%",7} {"총수익%",8} {"월평균%",8} {"MDD%",6} {"최악월%",7} {"개월",4}");
        Console.WriteLine($"  {"1h",5} {r1.tn,5} {r1.prof,7:F0} {r1.tot,8:F0} {(r1.months > 0 ? r1.tot / r1.months : 0),8:F1} {r1.mdd,6:F0} {r1.worst,7:F1} {r1.months,4}");
        Console.WriteLine($"  {"4h",5} {r4.tn,5} {r4.prof,7:F0} {r4.tot,8:F0} {(r4.months > 0 ? r4.tot / r4.months : 0),8:F1} {r4.mdd,6:F0} {r4.worst,7:F1} {r4.months,4}");
        Console.WriteLine("\n  → 4h가 흑자월%↑ & MDD↓ & 총수익 유지면 = 4h 채택. 노이즈 감소 효과 확인.");
    }

    // --loss-defense : 지는 트레이드 진입시점 지표상태 전수분석 → 승자/패자 판별지표 발굴 → 방어필터 병렬 전수테스트.
    //   손실 원인을 지표로 정량화하고, 그 지표로 손실만 골라 막는 필터를 Parallel.For로 탐색.
    private static async Task RunLossDefenseAsync()
    {
        const int featureWindow = 500, K = 8, Lh = 4;
        const decimal feeRT = 0.0008m; const double atrMult = 4.0, adxThr = 30;   // [v5.26.4] 4h·ADX30·트레일4 기준
        decimal margin = 500m; int slots = 6; decimal capital = margin * slots;
        var majors = new HashSet<string> { "BTCUSDT", "ETHUSDT", "SOLUSDT", "XRPUSDT" };
        var universe = new[] {
            "BTCUSDT","ETHUSDT","BNBUSDT","SOLUSDT","XRPUSDT","DOGEUSDT","ADAUSDT","TRXUSDT","AVAXUSDT","LINKUSDT",
            "DOTUSDT","LTCUSDT","BCHUSDT","ATOMUSDT","UNIUSDT","NEARUSDT","APTUSDT","ARBUSDT","OPUSDT","SUIUSDT" };
        Console.WriteLine("=== 손실 방어 분석 [4h·ADX30·트레일4]: 승자/패자 판별지표 + 방어필터 병렬탐색 ===\n");
        var btcBull = new Dictionary<DateTime, bool>();
        { var btc = await FetchKlines4hAsync("BTCUSDT", 12); int bn = btc.Count; var be2 = new double[bn]; for (int j = 200; j < bn; j++) be2[j] = CalcEMA(btc, j, 200); for (int j = 200; j < bn; j++) btcBull[btc[j].OpenTime] = be2[j] > 0 && (double)btc[j].ClosePrice > be2[j]; }
        // trade: ent,ex,pnlPct,lev + 진입지표 [rsi14,ext20(ATR),bbPos,volRatio,upWick,macdUp?,ema20slope%,ext50]
        var trades = new List<(DateTime ent, DateTime ex, decimal pnl, int lev, double rsi, double ext20, double bbPos, double vol, double upw, double macd, double slope, double ext50)>();
        int ci = 0;
        foreach (var sym in universe)
        {
            ci++; Console.Write($"[{ci}/{universe.Length}] {sym} ");
            int lev = majors.Contains(sym) ? 10 : 5;
            List<IBinanceKline> kl;
            try { kl = await FetchKlines4hAsync(sym, 12); } catch { Console.WriteLine("fail"); continue; }
            if (kl.Count < 800) { Console.WriteLine("skip"); continue; }
            int n = kl.Count; Console.WriteLine($"{n}"); var close = new double[n]; for (int j = 0; j < n; j++) close[j] = (double)kl[j].ClosePrice;
            var feats = new float[n][];
            for (int j = 60; j < n; j++) { int ws = Math.Max(0, j - (featureWindow - 1)); feats[j] = LorentzianFeatures.Extract(kl.GetRange(ws, j - ws + 1))!; }
            var e20 = new double[n]; for (int j = 20; j < n; j++) e20[j] = CalcEMA(kl, j, 20);
            var e50 = new double[n]; for (int j = 50; j < n; j++) e50[j] = CalcEMA(kl, j, 50);
            var e200 = new double[n]; for (int j = 200; j < n; j++) e200[j] = CalcEMA(kl, j, 200);
            var atr = new double[n]; for (int j = 14; j < n; j++) { double tr = 0; for (int q = j - 13; q <= j; q++) { double hh = (double)kl[q].HighPrice, ll = (double)kl[q].LowPrice, pc = close[q - 1]; tr += Math.Max(hh - ll, Math.Max(Math.Abs(hh - pc), Math.Abs(ll - pc))); } atr[j] = tr / 14.0; }
            var adx = new double[n]; { double atrS = 0, pdmS = 0, mdmS = 0; int per = 14; for (int j = 1; j < n; j++) { double hh = (double)kl[j].HighPrice, ll = (double)kl[j].LowPrice, pc = close[j - 1], ph = (double)kl[j - 1].HighPrice, pl = (double)kl[j - 1].LowPrice; double tr = Math.Max(hh - ll, Math.Max(Math.Abs(hh - pc), Math.Abs(ll - pc))); double up = hh - ph, dn = pl - ll; double pdm = (up > dn && up > 0) ? up : 0, mdm = (dn > up && dn > 0) ? dn : 0; if (j <= per) { atrS += tr; pdmS += pdm; mdmS += mdm; } else { atrS = atrS - atrS / per + tr; pdmS = pdmS - pdmS / per + pdm; mdmS = mdmS - mdmS / per + mdm; } if (j >= per && atrS > 0) { double pd = 100 * pdmS / atrS, md = 100 * mdmS / atrS; double dx = (pd + md) > 0 ? 100 * Math.Abs(pd - md) / (pd + md) : 0; adx[j] = j <= per * 2 ? dx : (adx[j - 1] * (per - 1) + dx) / per; } } }
            var rsi = new double[n]; { double ag = 0, al = 0; int per = 14; for (int j = 1; j < n; j++) { double ch = close[j] - close[j - 1]; double g = ch > 0 ? ch : 0, ls = ch < 0 ? -ch : 0; if (j <= per) { ag += g; al += ls; if (j == per) { ag /= per; al /= per; rsi[j] = al == 0 ? 100 : 100 - 100 / (1 + ag / al); } } else { ag = (ag * (per - 1) + g) / per; al = (al * (per - 1) + ls) / per; rsi[j] = al == 0 ? 100 : 100 - 100 / (1 + ag / al); } } }
            var bbUp = new double[n]; var bbLo = new double[n]; for (int j = 20; j < n; j++) { double sum = 0; for (int q = j - 19; q <= j; q++) sum += close[q]; double mid = sum / 20; double vv = 0; for (int q = j - 19; q <= j; q++) { double d = close[q] - mid; vv += d * d; } double sd = Math.Sqrt(vv / 20); bbUp[j] = mid + 2 * sd; bbLo[j] = mid - 2 * sd; }
            var macdH = new double[n]; { double e12 = 0, e26 = 0, sig = 0; double k12 = 2.0 / 13, k26 = 2.0 / 27, k9 = 2.0 / 10; for (int j = 0; j < n; j++) { double c = close[j]; if (j == 0) { e12 = c; e26 = c; } else { e12 = c * k12 + e12 * (1 - k12); e26 = c * k26 + e26 * (1 - k26); } double macd = e12 - e26; if (j == 0) sig = macd; else sig = macd * k9 + sig * (1 - k9); macdH[j] = macd - sig; } }
            var engine = new LorentzianAnnEngine(sym, neighborsCount: K, maxBarsBack: 2000, featureCount: LorentzianFeatures.FeatureCount);
            var sg = new int[n];
            for (int j = 65; j < n; j++) { int s = j - 1; if (s - Lh >= 0 && feats[s] != null) { double a = close[s], b = close[s - Lh]; engine.AddSample(feats[s], a > b ? 1 : (a < b ? -1 : 0)); } if (feats[j] == null) continue; var p = engine.Predict(feats[j]); if (!p.IsReady || p.K == 0) continue; sg[j] = p.Prediction > 0 ? 1 : (p.Prediction < 0 ? -1 : 0); }
            int busy = -1;
            for (int j = 250; j < n - 1; j++)
            {
                if (j <= busy) continue;
                if (!(sg[j] > 0 && e50[j] > 0 && e200[j] > 0 && e50[j] > e200[j] && close[j] > e50[j] && adx[j] >= adxThr)) continue;
                if (!(btcBull.TryGetValue(kl[j].OpenTime, out var bb) && bb)) continue;
                if (atr[j] <= 0 || kl[j + 1].OpenPrice <= 0 || bbUp[j] <= bbLo[j]) continue;
                decimal entry = kl[j + 1].OpenPrice; double peakP = (double)entry; decimal net = 0m; int ei = n - 1;
                for (int e = j + 1; e < n; e++) { double cc = close[e]; if (cc > peakP) peakP = cc; if (cc <= peakP - atrMult * atr[e]) { net = ((decimal)cc - entry) / entry - feeRT; ei = e; break; } if (e == n - 1) net = ((decimal)cc - entry) / entry - feeRT; }
                busy = ei;
                double o = (double)kl[j].OpenPrice, h = (double)kl[j].HighPrice, c = close[j]; double upw = (h - Math.Max(o, c)) / Math.Max(1e-9, atr[j]);
                double vsum = 0; for (int q = j - 19; q <= j; q++) vsum += (double)kl[q].Volume; double vavg = vsum / 20; double vr = vavg > 0 ? (double)kl[j].Volume / vavg : 1;
                double sl = j >= 6 && e20[j - 6] > 0 ? (e20[j] - e20[j - 6]) / e20[j - 6] * 100 : 0;
                double bp = (c - bbLo[j]) / (bbUp[j] - bbLo[j]);
                trades.Add((kl[j + 1].OpenTime, kl[ei].OpenTime, net, lev, rsi[j], (c - e20[j]) / atr[j], bp, vr, upw, macdH[j], sl, (c - e50[j]) / atr[j]));
            }
        }
        Console.WriteLine($"\n총 {trades.Count} 트레이드 (승 {trades.Count(t => t.pnl > 0)} / 패 {trades.Count(t => t.pnl <= 0)})\n");
        // Part A: 승자 vs 패자 지표 평균 비교
        var W = trades.Where(t => t.pnl > 0).ToList(); var L = trades.Where(t => t.pnl <= 0).ToList();
        Console.WriteLine("── Part A: 승자 vs 패자 진입시점 지표 평균 ──");
        void Cmp(string nm, Func<(DateTime, DateTime, decimal, int, double, double, double, double, double, double, double, double), double> f) => Console.WriteLine($"   {nm,-16} 승 {W.Average(f),7:F2}  패 {L.Average(f),7:F2}");
        Cmp("RSI14", t => t.Item5); Cmp("EMA20이격ATR", t => t.Item6); Cmp("BB위치", t => t.Item7);
        Cmp("거래량배수", t => t.Item8); Cmp("윗꼬리ATR", t => t.Item9); Cmp("MACD히스토", t => t.Item10);
        Cmp("EMA20기울기%", t => t.Item11); Cmp("EMA50이격ATR", t => t.Item12);
        // Part B: 방어필터 병렬 전수테스트 (진입 제거조건 → 6슬롯 월별)
        (double totRet, double profPct, int tn, int lossRemoved, int winRemoved) EvalFilter(Func<(DateTime, DateTime, decimal, int, double, double, double, double, double, double, double, double), bool> keep)
        {
            int lr = 0, wr = 0; var kept = new List<(DateTime, DateTime, decimal, int)>();
            foreach (var t in trades) { if (keep(t)) kept.Add((t.ent, t.ex, t.pnl, t.lev)); else { if (t.pnl > 0) wr++; else lr++; } }
            kept.Sort((a, b) => a.Item1.CompareTo(b.Item1));
            var open = new List<DateTime>(); var monthly = new SortedDictionary<string, decimal>(); int tn = 0;
            foreach (var t in kept) { open.RemoveAll(x => x <= t.Item1); if (open.Count >= slots) continue; open.Add(t.Item2); monthly[t.Item1.ToString("yyyy-MM")] = (monthly.TryGetValue(t.Item1.ToString("yyyy-MM"), out var v) ? v : 0m) + t.Item3 * margin * t.Item4; tn++; }
            if (monthly.Count == 0) return (0, 0, 0, lr, wr);
            int prof = 0; decimal tot = 0m; foreach (var kv in monthly) { if (kv.Value > 0) prof++; tot += kv.Value; }
            return ((double)(tot / capital * 100m), 100.0 * prof / monthly.Count, tn, lr, wr);
        }
        var filters = new List<(string desc, Func<(DateTime, DateTime, decimal, int, double, double, double, double, double, double, double, double), bool> keep)>();
        filters.Add(("(기준=무필터)", t => true));
        foreach (var x in new[] { 60.0, 65, 70, 75 }) filters.Add(($"RSI14 < {x:F0}", t => t.Item5 < x));
        foreach (var x in new[] { 1.5, 2.0, 2.5, 3.0 }) filters.Add(($"EMA20이격 < {x:F1}ATR", t => t.Item6 < x));
        foreach (var x in new[] { 0.7, 0.8, 0.9, 1.0 }) filters.Add(($"BB위치 < {x:F1}", t => t.Item7 < x));
        foreach (var x in new[] { 1.5, 2.0, 3.0 }) filters.Add(($"거래량배수 < {x:F1}", t => t.Item8 < x));
        foreach (var x in new[] { 0.3, 0.5, 0.8 }) filters.Add(($"윗꼬리 < {x:F1}ATR", t => t.Item9 < x));
        filters.Add(("MACD히스토 > 0", t => t.Item10 > 0));
        foreach (var x in new[] { 0.0, 0.3, 0.6 }) filters.Add(($"EMA20기울기 > {x:F1}%", t => t.Item11 > x));
        foreach (var x in new[] { 1.0, 2.0 }) filters.Add(($"EMA50이격 < {x:F1}ATR", t => t.Item12 < x));
        // 조합 방어 (상위 단일들 결합 → 흑자월% 극대화)
        filters.Add(("이격2+거래량1.5", t => t.Item12 < 2.0 && t.Item8 < 1.5));
        filters.Add(("이격2+윗꼬리0.5", t => t.Item12 < 2.0 && t.Item9 < 0.5));
        filters.Add(("이격2+BB0.7", t => t.Item12 < 2.0 && t.Item7 < 0.7));
        filters.Add(("이격2+거래량1.5+윗꼬리0.5", t => t.Item12 < 2.0 && t.Item8 < 1.5 && t.Item9 < 0.5));
        filters.Add(("이격1.5+거래량1.5+BB0.7", t => t.Item12 < 1.5 && t.Item8 < 1.5 && t.Item7 < 0.7));
        filters.Add(("이격2+거래량1.5+BB0.7+윗꼬리0.5", t => t.Item12 < 2.0 && t.Item8 < 1.5 && t.Item7 < 0.7 && t.Item9 < 0.5));
        var res = new (string desc, double tot, double prof, int tn, int lr, int wr)[filters.Count];
        System.Threading.Tasks.Parallel.For(0, filters.Count, i => { var r = EvalFilter(filters[i].keep); res[i] = (filters[i].desc, r.totRet, r.profPct, r.tn, r.lossRemoved, r.winRemoved); });
        double baseTot = res[0].tot, baseProf = res[0].prof;
        Console.WriteLine($"\n── Part B: 방어필터 (기준 총수익 {baseTot:F0}% · 흑자월 {baseProf:F0}%) ──");
        Console.WriteLine($"  {"필터",22} {"총수익%",8} {"흑자월%",7} {"진입",5} {"패거른",6} {"승거른",6} {"Δ수익",7}");
        foreach (var r in res.OrderByDescending(x => x.tot).Take(16))
            Console.WriteLine($"  {r.desc,-22} {r.tot,8:F0} {r.prof,7:F0} {r.tn,5} {r.lr,6} {r.wr,6} {r.tot - baseTot,+7:F0}");
        Console.WriteLine("\n  → 총수익↑ & 흑자월%↑ & 패거른>승거른 = 좋은 방어. 손실만 골라 막는 지표.");
    }

    // --lorentzian-monthly-lev : 차등 레버리지 월별 성과 — 메이저(BTC/ETH/SOL/XRP)=10x, 나머지 알트=5x.
    //   추세추종 단일 로직(KNN+EMA정배열+ADX20+BTC상승장, 종가 5ATR 트레일). $500×6=$3,000. monthly-lev.json 저장.
    private static async Task RunLorentzianMonthlyLevAsync()
    {
        const int featureWindow = 500, K = 8, Lh = 8, pages1h = 20;
        const decimal feeRT = 0.0008m; const double atrMult = 5.0, adxThr = 20;
        decimal margin = 500m; int slots = 6; decimal capital = margin * slots;
        var majors = new HashSet<string> { "BTCUSDT", "ETHUSDT", "SOLUSDT", "XRPUSDT" };
        var universe = new[] {
            "BTCUSDT","ETHUSDT","BNBUSDT","SOLUSDT","XRPUSDT","DOGEUSDT","ADAUSDT","TRXUSDT","AVAXUSDT","LINKUSDT",
            "DOTUSDT","LTCUSDT","BCHUSDT","ATOMUSDT","UNIUSDT","NEARUSDT","APTUSDT","ARBUSDT","OPUSDT","SUIUSDT" };
        Console.WriteLine("=== 차등 레버리지 월별 : 메이저(BTC/ETH/SOL/XRP)=10x · 알트=5x (6슬롯 $3,000) ===\n");
        var btcBull = new Dictionary<DateTime, bool>();
        { var btc = await FetchKlines1hAsync("BTCUSDT", pages1h); int bn = btc.Count; var be2 = new double[bn]; for (int j = 200; j < bn; j++) be2[j] = CalcEMA(btc, j, 200); for (int j = 200; j < bn; j++) btcBull[btc[j].OpenTime] = be2[j] > 0 && (double)btc[j].ClosePrice > be2[j]; }
        var allTrades = new List<(DateTime ent, DateTime ex, decimal pnlPct, int lev)>();
        int ci = 0;
        foreach (var sym in universe)
        {
            ci++; Console.Write($"[{ci}/{universe.Length}] {sym} ");
            int lev = majors.Contains(sym) ? 10 : 5;
            List<IBinanceKline> kl;
            try { kl = await FetchKlines1hAsync(sym, pages1h); } catch { Console.WriteLine("fail"); continue; }
            if (kl.Count < 2000) { Console.WriteLine("skip"); continue; }
            int n = kl.Count; Console.WriteLine($"{n} ({lev}x)"); var close = new double[n]; for (int j = 0; j < n; j++) close[j] = (double)kl[j].ClosePrice;
            var feats = new float[n][];
            for (int j = 60; j < n; j++) { int ws = Math.Max(0, j - (featureWindow - 1)); feats[j] = LorentzianFeatures.Extract(kl.GetRange(ws, j - ws + 1))!; }
            var e50 = new double[n]; for (int j = 50; j < n; j++) e50[j] = CalcEMA(kl, j, 50);
            var e200 = new double[n]; for (int j = 200; j < n; j++) e200[j] = CalcEMA(kl, j, 200);
            var atr = new double[n]; for (int j = 14; j < n; j++) { double tr = 0; for (int q = j - 13; q <= j; q++) { double hh = (double)kl[q].HighPrice, ll = (double)kl[q].LowPrice, pc = close[q - 1]; tr += Math.Max(hh - ll, Math.Max(Math.Abs(hh - pc), Math.Abs(ll - pc))); } atr[j] = tr / 14.0; }
            var adx = new double[n]; { double atrS = 0, pdmS = 0, mdmS = 0; int per = 14; for (int j = 1; j < n; j++) { double hh = (double)kl[j].HighPrice, ll = (double)kl[j].LowPrice, pc = close[j - 1], ph = (double)kl[j - 1].HighPrice, pl = (double)kl[j - 1].LowPrice; double tr = Math.Max(hh - ll, Math.Max(Math.Abs(hh - pc), Math.Abs(ll - pc))); double up = hh - ph, dn = pl - ll; double pdm = (up > dn && up > 0) ? up : 0, mdm = (dn > up && dn > 0) ? dn : 0; if (j <= per) { atrS += tr; pdmS += pdm; mdmS += mdm; } else { atrS = atrS - atrS / per + tr; pdmS = pdmS - pdmS / per + pdm; mdmS = mdmS - mdmS / per + mdm; } if (j >= per && atrS > 0) { double pd = 100 * pdmS / atrS, md = 100 * mdmS / atrS; double dx = (pd + md) > 0 ? 100 * Math.Abs(pd - md) / (pd + md) : 0; adx[j] = j <= per * 2 ? dx : (adx[j - 1] * (per - 1) + dx) / per; } } }
            var engine = new LorentzianAnnEngine(sym, neighborsCount: K, maxBarsBack: 2000, featureCount: LorentzianFeatures.FeatureCount);
            var sg = new int[n];
            for (int j = 65; j < n; j++) { int s = j - 1; if (s - Lh >= 0 && feats[s] != null) { double a = close[s], b = close[s - Lh]; engine.AddSample(feats[s], a > b ? 1 : (a < b ? -1 : 0)); } if (feats[j] == null) continue; var p = engine.Predict(feats[j]); if (!p.IsReady || p.K == 0) continue; sg[j] = p.Prediction > 0 ? 1 : (p.Prediction < 0 ? -1 : 0); }
            int busy = -1;
            for (int j = 250; j < n - 1; j++)
            {
                if (j <= busy) continue;
                if (!(sg[j] > 0 && e50[j] > 0 && e200[j] > 0 && e50[j] > e200[j] && close[j] > e50[j] && adx[j] >= adxThr)) continue;
                if (!(btcBull.TryGetValue(kl[j].OpenTime, out var bb) && bb)) continue;
                if (atr[j] <= 0 || kl[j + 1].OpenPrice <= 0) continue;
                // [손실 방어 3종] 데이터 검증(흑자월 36→52%): 과확장·거래량급증·윗꼬리 = 손실 진입 → 차단
                if ((close[j] - e50[j]) / atr[j] >= 2.0) continue;                                   // EMA50 2ATR 이상 과확장
                double vsum2 = 0; for (int q = j - 19; q <= j; q++) vsum2 += (double)kl[q].Volume; double vavg2 = vsum2 / 20;
                if (vavg2 > 0 && (double)kl[j].Volume / vavg2 >= 1.5) continue;                       // 거래량 1.5배 급증(climax)
                double upw2 = ((double)kl[j].HighPrice - Math.Max((double)kl[j].OpenPrice, close[j])) / atr[j];
                if (upw2 >= 0.5) continue;                                                            // 윗꼬리 0.5ATR 이상(매도거부)
                decimal entry = kl[j + 1].OpenPrice; double peakP = (double)entry; decimal net = 0m; int ei = n - 1;
                for (int e = j + 1; e < n; e++) { double cc = close[e]; if (cc > peakP) peakP = cc; if (cc <= peakP - atrMult * atr[e]) { net = ((decimal)cc - entry) / entry - feeRT; ei = e; break; } if (e == n - 1) net = ((decimal)cc - entry) / entry - feeRT; }
                busy = ei; allTrades.Add((kl[j + 1].OpenTime, kl[ei].OpenTime, net, lev));
            }
        }
        allTrades.Sort((a, b) => a.ent.CompareTo(b.ent));
        var open = new List<DateTime>(); var monthly = new SortedDictionary<string, (int n, decimal pnl)>(); decimal total = 0m; int totalN = 0, majN = 0, altN = 0;
        foreach (var t in allTrades)
        {
            open.RemoveAll(x => x <= t.ent); if (open.Count >= slots) continue; open.Add(t.ex);
            decimal pnl = t.pnlPct * margin * t.lev; string mk = t.ent.ToString("yyyy-MM");
            var cur = monthly.TryGetValue(mk, out var v) ? v : (0, 0m); monthly[mk] = (cur.Item1 + 1, cur.Item2 + pnl);
            total += pnl; totalN++; if (t.lev == 10) majN++; else altN++;
        }
        Console.WriteLine($"\n  {"월",8} {"진입",5} {"수익금$",10} {"월수익률%",9} {"누적$",11}");
        decimal cum = 0m; int prof = 0; decimal peak = 0m, mdd = 0m, worst = 0m;
        var inv = System.Globalization.CultureInfo.InvariantCulture; var sb = new System.Text.StringBuilder(); sb.Append('['); bool first = true;
        foreach (var kv in monthly)
        {
            cum += kv.Value.pnl; if (kv.Value.pnl > 0) prof++; if (kv.Value.pnl < worst) worst = kv.Value.pnl; if (cum > peak) peak = cum; if (peak - cum > mdd) mdd = peak - cum;
            Console.WriteLine($"  {kv.Key,8} {kv.Value.n,5} {kv.Value.pnl,10:F0} {(double)(kv.Value.pnl / capital * 100m),9:F1} {cum,11:F0}");
            if (!first) sb.Append(','); first = false; sb.Append($"{{\"m\":\"{kv.Key}\",\"n\":{kv.Value.n},\"pnl\":{kv.Value.pnl.ToString("F0", inv)},\"ret\":{((double)(kv.Value.pnl / capital * 100m)).ToString("F1", inv)},\"cum\":{cum.ToString("F0", inv)}}}");
        }
        sb.Append(']'); System.IO.File.WriteAllText("monthly-lev.json", sb.ToString());
        int months = monthly.Count;
        Console.WriteLine($"  ─────────────────────────────────────────────");
        Console.WriteLine($"  총 {months}개월 · 진입 {totalN}(메이저10x {majN}/알트5x {altN}) · 총수익 ${total:F0} ({(double)(total / capital * 100m):F0}%)");
        Console.WriteLine($"  월평균 ${(months > 0 ? total / months : 0):F0} ({(months > 0 ? (double)(total / capital * 100m) / months : 0):F1}%) · 흑자월 {prof}/{months} ({100.0 * prof / months:F0}%) · MDD {(double)(mdd / capital * 100m):F0}% · 최악월 {(double)(worst / capital * 100m):F1}%");
        Console.WriteLine($"  → monthly-lev.json 저장");
    }

    // --regime-combo : 레짐 분리 — 추세장(ADX高)=추세추종 / 횡보장(ADX低)=역추세(눌림매수→평균회귀).
    //   둘을 합쳐 적자월(횡보월)을 역추세로 메운다. 종가기준 손절(꼬리무시) 적용. 월별 일관성 측정.
    private static async Task RunRegimeComboAsync()
    {
        const int featureWindow = 500, K = 8, Lh = 8, pages1h = 20;
        const decimal feeRT = 0.0008m; decimal margin = 500m; int slots = 6; decimal capital = margin * slots;
        var universe = new[] {
            "BTCUSDT","ETHUSDT","BNBUSDT","SOLUSDT","XRPUSDT","DOGEUSDT","ADAUSDT","TRXUSDT","AVAXUSDT","LINKUSDT",
            "DOTUSDT","LTCUSDT","BCHUSDT","ATOMUSDT","UNIUSDT","NEARUSDT","APTUSDT","ARBUSDT","OPUSDT","SUIUSDT" };
        Console.WriteLine("=== 레짐분리: 추세장=추세추종 / 횡보장=역추세(눌림) 합산 월별 일관성 (6슬롯 $3,000) ===\n");
        var btcBull = new Dictionary<DateTime, bool>();
        { var btc = await FetchKlines1hAsync("BTCUSDT", pages1h); int bn = btc.Count; var be2 = new double[bn]; for (int j = 200; j < bn; j++) be2[j] = CalcEMA(btc, j, 200); for (int j = 200; j < bn; j++) btcBull[btc[j].OpenTime] = be2[j] > 0 && (double)btc[j].ClosePrice > be2[j]; }
        var data = new List<(string sym, List<IBinanceKline> kl, double[] close, int[] sg, double[] e20, double[] e50, double[] e200, double[] atr, double[] adx, double[] rsi2)>();
        int ci = 0;
        foreach (var sym in universe)
        {
            ci++; Console.Write($"[{ci}/{universe.Length}] {sym} ");
            List<IBinanceKline> kl;
            try { kl = await FetchKlines1hAsync(sym, pages1h); } catch { Console.WriteLine("fail"); continue; }
            if (kl.Count < 2000) { Console.WriteLine("skip"); continue; }
            int n = kl.Count; Console.WriteLine($"{n}"); var close = new double[n]; for (int j = 0; j < n; j++) close[j] = (double)kl[j].ClosePrice;
            var feats = new float[n][];
            for (int j = 60; j < n; j++) { int ws = Math.Max(0, j - (featureWindow - 1)); feats[j] = LorentzianFeatures.Extract(kl.GetRange(ws, j - ws + 1))!; }
            var e20 = new double[n]; for (int j = 20; j < n; j++) e20[j] = CalcEMA(kl, j, 20);
            var e50 = new double[n]; for (int j = 50; j < n; j++) e50[j] = CalcEMA(kl, j, 50);
            var e200 = new double[n]; for (int j = 200; j < n; j++) e200[j] = CalcEMA(kl, j, 200);
            var atr = new double[n]; for (int j = 14; j < n; j++) { double tr = 0; for (int q = j - 13; q <= j; q++) { double hh = (double)kl[q].HighPrice, ll = (double)kl[q].LowPrice, pc = close[q - 1]; tr += Math.Max(hh - ll, Math.Max(Math.Abs(hh - pc), Math.Abs(ll - pc))); } atr[j] = tr / 14.0; }
            var adx = new double[n]; { double atrS = 0, pdmS = 0, mdmS = 0; int per = 14; for (int j = 1; j < n; j++) { double hh = (double)kl[j].HighPrice, ll = (double)kl[j].LowPrice, pc = close[j - 1], ph = (double)kl[j - 1].HighPrice, pl = (double)kl[j - 1].LowPrice; double tr = Math.Max(hh - ll, Math.Max(Math.Abs(hh - pc), Math.Abs(ll - pc))); double up = hh - ph, dn = pl - ll; double pdm = (up > dn && up > 0) ? up : 0, mdm = (dn > up && dn > 0) ? dn : 0; if (j <= per) { atrS += tr; pdmS += pdm; mdmS += mdm; } else { atrS = atrS - atrS / per + tr; pdmS = pdmS - pdmS / per + pdm; mdmS = mdmS - mdmS / per + mdm; } if (j >= per && atrS > 0) { double pd = 100 * pdmS / atrS, md = 100 * mdmS / atrS; double dx = (pd + md) > 0 ? 100 * Math.Abs(pd - md) / (pd + md) : 0; adx[j] = j <= per * 2 ? dx : (adx[j - 1] * (per - 1) + dx) / per; } } }
            var rsi2 = new double[n]; { double ag = 0, al = 0; int per = 2; for (int j = 1; j < n; j++) { double ch = close[j] - close[j - 1]; double g = ch > 0 ? ch : 0, ls = ch < 0 ? -ch : 0; if (j <= per) { ag += g; al += ls; if (j == per) { ag /= per; al /= per; rsi2[j] = al == 0 ? 100 : 100 - 100 / (1 + ag / al); } } else { ag = (ag * (per - 1) + g) / per; al = (al * (per - 1) + ls) / per; rsi2[j] = al == 0 ? 100 : 100 - 100 / (1 + ag / al); } } }
            var engine = new LorentzianAnnEngine(sym, neighborsCount: K, maxBarsBack: 2000, featureCount: LorentzianFeatures.FeatureCount);
            var sg = new int[n];
            for (int j = 65; j < n; j++) { int s = j - 1; if (s - Lh >= 0 && feats[s] != null) { double a = close[s], b = close[s - Lh]; engine.AddSample(feats[s], a > b ? 1 : (a < b ? -1 : 0)); } if (feats[j] == null) continue; var p = engine.Predict(feats[j]); if (!p.IsReady || p.K == 0) continue; sg[j] = p.Prediction > 0 ? 1 : (p.Prediction < 0 ? -1 : 0); }
            data.Add((sym, kl, close, sg, e20, e50, e200, atr, adx, rsi2));
        }
        Console.WriteLine();
        (double profPct, double totRet, double mdd, double worst, int months, int trades) Eval(List<(DateTime ent, DateTime ex, decimal pnl)> trades)
        {
            trades.Sort((a, b) => a.ent.CompareTo(b.ent));
            var open = new List<DateTime>(); var monthly = new SortedDictionary<string, decimal>(); int tn = 0;
            foreach (var t in trades) { open.RemoveAll(x => x <= t.ent); if (open.Count >= slots) continue; open.Add(t.ex); decimal pnl = t.pnl * margin; string mk = t.ent.ToString("yyyy-MM"); monthly[mk] = (monthly.TryGetValue(mk, out var v) ? v : 0m) + pnl; tn++; }
            if (monthly.Count == 0) return (0, 0, 0, 0, 0, 0);
            int prof = 0; decimal cum = 0m, peak = 0m, mdd = 0m, worst = 0m, tot = 0m;
            foreach (var kv in monthly) { if (kv.Value > 0) prof++; if (kv.Value < worst) worst = kv.Value; cum += kv.Value; tot += kv.Value; if (cum > peak) peak = cum; if (peak - cum > mdd) mdd = peak - cum; }
            return (100.0 * prof / monthly.Count, (double)(tot / capital * 100m), (double)(mdd / capital * 100m), (double)(worst / capital * 100m), monthly.Count, tn);
        }
        // 추세추종 trade (ADX≥trendAdx): KNN+EMA정배열 → 종가 5ATR 트레일
        // 역추세 trade (ADX<rangeAdx): 상승추세(close>EMA200)+RSI2<10 눌림 → 종가기준, EMA20 회귀 익절 or 2.5ATR 손절
        List<(DateTime, DateTime, decimal)> Gen(bool trend, bool mean, double trendAdx, double rangeAdx, double mrRsi)
        {
            var tr = new List<(DateTime, DateTime, decimal)>();
            foreach (var (sym, kl, close, sg, e20, e50, e200, atr, adx, rsi2) in data)
            {
                int n = kl.Count; int busy = -1;
                for (int j = 250; j < n - 1; j++)
                {
                    if (j <= busy) continue;
                    bool btcOk = btcBull.TryGetValue(kl[j].OpenTime, out var bb) && bb;
                    if (!btcOk || atr[j] <= 0 || kl[j + 1].OpenPrice <= 0) continue;
                    decimal entry = kl[j + 1].OpenPrice; double ep = (double)entry;
                    // 추세추종
                    if (trend && adx[j] >= trendAdx && sg[j] > 0 && e50[j] > 0 && e200[j] > 0 && e50[j] > e200[j] && close[j] > e50[j])
                    {
                        double peakP = ep; decimal net = 0m; int ei = n - 1;
                        for (int e = j + 1; e < n; e++) { double cc = close[e]; if (cc > peakP) peakP = cc; if (cc <= peakP - 5.0 * atr[e]) { net = ((decimal)cc - entry) / entry - feeRT; ei = e; break; } if (e == n - 1) net = ((decimal)cc - entry) / entry - feeRT; }
                        busy = ei; tr.Add((kl[j + 1].OpenTime, kl[ei].OpenTime, net)); continue;
                    }
                    // 역추세(눌림): 횡보(ADX<range) + 상승추세(close>EMA200) + RSI2 과매도
                    if (mean && adx[j] < rangeAdx && e200[j] > 0 && close[j] > e200[j] && rsi2[j] < mrRsi)
                    {
                        double stop0 = ep - 2.5 * atr[j]; decimal net = 0m; int ei = n - 1;
                        for (int e = j + 1; e < n; e++)
                        {
                            double cc = close[e];
                            if (cc >= e20[e]) { net = ((decimal)cc - entry) / entry - feeRT; ei = e; break; }   // 평균(EMA20) 회귀 익절
                            if (cc <= stop0) { net = ((decimal)cc - entry) / entry - feeRT; ei = e; break; }     // 종가기준 손절
                            if (e >= j + 48) { net = ((decimal)cc - entry) / entry - feeRT; ei = e; break; }       // 2일 시간정지
                            if (e == n - 1) net = ((decimal)cc - entry) / entry - feeRT;
                        }
                        busy = ei; tr.Add((kl[j + 1].OpenTime, kl[ei].OpenTime, net));
                    }
                }
            }
            return tr;
        }
        void Row(string name, List<(DateTime, DateTime, decimal)> t) { var r = Eval(t); Console.WriteLine($"  {name,-24} {r.trades,5} {r.profPct,7:F0} {r.totRet,8:F0} {r.mdd,6:F0} {r.worst,7:F1} {r.months,4}"); }
        Console.WriteLine($"  {"시스템",24} {"진입",5} {"흑자월%",7} {"총수익%",8} {"MDD%",6} {"최악월%",7} {"개월",4}");
        Row("추세추종만(ADX25)", Gen(true, false, 25, 25, 10));
        Row("역추세만(ADX<20·RSI2<10)", Gen(false, true, 25, 20, 10));
        Row("역추세만(ADX<25·RSI2<15)", Gen(false, true, 25, 25, 15));
        Row("합산 추세25+역추세20", Gen(true, true, 25, 20, 10));
        Row("합산 추세25+역추세25", Gen(true, true, 25, 25, 10));
        Row("합산 추세30+역추세25R15", Gen(true, true, 30, 25, 15));
        Console.WriteLine("\n  → 합산의 흑자월%가 각각보다 높으면 = 레짐분리가 적자월을 메움(성공). 총수익도 +유지 필수.");
    }

    // --lorentzian-consistency : 월별 일관성(흑자월 비율) 최적화 탐색. ADX강도 × 청산방식 스윕 →
    //   흑자월% 최대 + 낙폭 최소 구성 발굴. 총수익만이 아니라 '매달 안 물리는' 로직 찾기.
    private static async Task RunLorentzianConsistencyAsync()
    {
        const int featureWindow = 500, K = 8, Lh = 8, pages1h = 20;
        const decimal feeRT = 0.0008m; decimal margin = 500m; int slots = 6; decimal capital = margin * slots;
        var universe = new[] {
            "BTCUSDT","ETHUSDT","BNBUSDT","SOLUSDT","XRPUSDT","DOGEUSDT","ADAUSDT","TRXUSDT","AVAXUSDT","LINKUSDT",
            "DOTUSDT","LTCUSDT","BCHUSDT","ATOMUSDT","UNIUSDT","NEARUSDT","APTUSDT","ARBUSDT","OPUSDT","SUIUSDT" };
        Console.WriteLine("=== 월별 일관성 최적화 : ADX강도 × 청산방식 스윕 (6슬롯 $3,000, 1x) ===\n");
        var btcBull = new Dictionary<DateTime, bool>();
        { var btc = await FetchKlines1hAsync("BTCUSDT", pages1h); int bn = btc.Count; var be2 = new double[bn]; for (int j = 200; j < bn; j++) be2[j] = CalcEMA(btc, j, 200); for (int j = 200; j < bn; j++) btcBull[btc[j].OpenTime] = be2[j] > 0 && (double)btc[j].ClosePrice > be2[j]; }
        // 코인별 사전계산
        var data = new List<(string sym, List<IBinanceKline> kl, double[] close, int[] sg, double[] e50, double[] e200, double[] atr, double[] adx)>();
        int ci = 0;
        foreach (var sym in universe)
        {
            ci++; Console.Write($"[{ci}/{universe.Length}] {sym} ");
            List<IBinanceKline> kl;
            try { kl = await FetchKlines1hAsync(sym, pages1h); } catch { Console.WriteLine("fail"); continue; }
            if (kl.Count < 2000) { Console.WriteLine("skip"); continue; }
            int n = kl.Count; Console.WriteLine($"{n}"); var close = new double[n]; for (int j = 0; j < n; j++) close[j] = (double)kl[j].ClosePrice;
            var feats = new float[n][];
            for (int j = 60; j < n; j++) { int ws = Math.Max(0, j - (featureWindow - 1)); feats[j] = LorentzianFeatures.Extract(kl.GetRange(ws, j - ws + 1))!; }
            var e50 = new double[n]; for (int j = 50; j < n; j++) e50[j] = CalcEMA(kl, j, 50);
            var e200 = new double[n]; for (int j = 200; j < n; j++) e200[j] = CalcEMA(kl, j, 200);
            var atr = new double[n]; for (int j = 14; j < n; j++) { double tr = 0; for (int q = j - 13; q <= j; q++) { double hh = (double)kl[q].HighPrice, ll = (double)kl[q].LowPrice, pc = close[q - 1]; tr += Math.Max(hh - ll, Math.Max(Math.Abs(hh - pc), Math.Abs(ll - pc))); } atr[j] = tr / 14.0; }
            var adx = new double[n]; { double atrS = 0, pdmS = 0, mdmS = 0; int per = 14; for (int j = 1; j < n; j++) { double hh = (double)kl[j].HighPrice, ll = (double)kl[j].LowPrice, pc = close[j - 1], ph = (double)kl[j - 1].HighPrice, pl = (double)kl[j - 1].LowPrice; double tr = Math.Max(hh - ll, Math.Max(Math.Abs(hh - pc), Math.Abs(ll - pc))); double up = hh - ph, dn = pl - ll; double pdm = (up > dn && up > 0) ? up : 0, mdm = (dn > up && dn > 0) ? dn : 0; if (j <= per) { atrS += tr; pdmS += pdm; mdmS += mdm; } else { atrS = atrS - atrS / per + tr; pdmS = pdmS - pdmS / per + pdm; mdmS = mdmS - mdmS / per + mdm; } if (j >= per && atrS > 0) { double pd = 100 * pdmS / atrS, md = 100 * mdmS / atrS; double dx = (pd + md) > 0 ? 100 * Math.Abs(pd - md) / (pd + md) : 0; adx[j] = j <= per * 2 ? dx : (adx[j - 1] * (per - 1) + dx) / per; } } }
            var engine = new LorentzianAnnEngine(sym, neighborsCount: K, maxBarsBack: 2000, featureCount: LorentzianFeatures.FeatureCount);
            var sg = new int[n];
            for (int j = 65; j < n; j++) { int s = j - 1; if (s - Lh >= 0 && feats[s] != null) { double a = close[s], b = close[s - Lh]; engine.AddSample(feats[s], a > b ? 1 : (a < b ? -1 : 0)); } if (feats[j] == null) continue; var p = engine.Predict(feats[j]); if (!p.IsReady || p.K == 0) continue; sg[j] = p.Prediction > 0 ? 1 : (p.Prediction < 0 ? -1 : 0); }
            data.Add((sym, kl, close, sg, e50, e200, atr, adx));
        }
        Console.WriteLine();
        // 포트폴리오 월별 평가
        (double profPct, double totRet, double mdd, double worst, int months, int trades) Eval(List<(DateTime ent, DateTime ex, decimal pnl)> trades)
        {
            trades.Sort((a, b) => a.ent.CompareTo(b.ent));
            var open = new List<DateTime>(); var monthly = new SortedDictionary<string, decimal>(); int tn = 0;
            foreach (var t in trades) { open.RemoveAll(x => x <= t.ent); if (open.Count >= slots) continue; open.Add(t.ex); decimal pnl = t.pnl * margin; string mk = t.ent.ToString("yyyy-MM"); monthly[mk] = (monthly.TryGetValue(mk, out var v) ? v : 0m) + pnl; tn++; }
            if (monthly.Count == 0) return (0, 0, 0, 0, 0, 0);
            int prof = 0; decimal cum = 0m, peak = 0m, mdd = 0m, worst = 0m, tot = 0m;
            foreach (var kv in monthly) { if (kv.Value > 0) prof++; if (kv.Value < worst) worst = kv.Value; cum += kv.Value; tot += kv.Value; if (cum > peak) peak = cum; if (peak - cum > mdd) mdd = peak - cum; }
            return (100.0 * prof / monthly.Count, (double)(tot / capital * 100m), (double)(mdd / capital * 100m), (double)(worst / capital * 100m), monthly.Count, tn);
        }
        List<(DateTime, DateTime, decimal)> Gen(double adxThr, int exitMode, double p1, double p2)
        {
            var trades = new List<(DateTime, DateTime, decimal)>();
            foreach (var (sym, kl, close, sg, e50, e200, atr, adx) in data)
            {
                int n = kl.Count; int busy = -1;
                for (int j = 250; j < n - 1; j++)
                {
                    if (j <= busy) continue;
                    if (!(sg[j] > 0 && e50[j] > 0 && e200[j] > 0 && e50[j] > e200[j] && close[j] > e50[j] && adx[j] >= adxThr)) continue;
                    if (!(btcBull.TryGetValue(kl[j].OpenTime, out var bb) && bb)) continue;
                    if (atr[j] <= 0 || kl[j + 1].OpenPrice <= 0) continue;
                    decimal entry = kl[j + 1].OpenPrice; double ep = (double)entry, peakP = ep; decimal net = 0m; int ei = n - 1;
                    double riskAtr = atr[j];
                    for (int e = j + 1; e < n; e++)
                    {
                        double cc = close[e]; if (cc > peakP) peakP = cc;
                        bool done = false;
                        if (exitMode == 0) { double stop = peakP - p1 * atr[e]; if (cc <= stop) { net = ((decimal)cc - entry) / entry - feeRT; ei = e; done = true; } }
                        else { double stop = ep - p1 * riskAtr; double tp = ep + p2 * p1 * riskAtr; if (cc <= stop) { net = ((decimal)cc - entry) / entry - feeRT; ei = e; done = true; } else if (cc >= tp) { net = ((decimal)cc - entry) / entry - feeRT; ei = e; done = true; } }
                        if (done) break;
                        if (e == n - 1) net = ((decimal)cc - entry) / entry - feeRT;
                    }
                    busy = ei; trades.Add((kl[j + 1].OpenTime, kl[ei].OpenTime, net));
                }
            }
            return trades;
        }
        Console.WriteLine($"  {"구성",34} {"진입",5} {"흑자월%",7} {"총수익%",8} {"MDD%",6} {"최악월%",7}");
        var results = new List<(string desc, double prof, double tot, double mdd, double worst, int tr)>();
        foreach (double ath in new[] { 20.0, 25, 30, 35 })
        {
            // 트레일 청산 (mult 3/4/5)
            foreach (double m in new[] { 3.0, 4.0, 5.0 }) { var (pf, tr, md, wr, mo, tn) = Eval(Gen(ath, 0, m, 0)); results.Add(($"ADX{ath:F0}·트레일{m:F0}ATR", pf, tr, md, wr, tn)); }
            // 브라켓 청산 (stop 3ATR, TP rr×)
            foreach (double rr in new[] { 1.5, 2.0, 3.0 }) { var (pf, tr, md, wr, mo, tn) = Eval(Gen(ath, 1, 3.0, rr)); results.Add(($"ADX{ath:F0}·손절3ATR·TP{rr:F1}R", pf, tr, md, wr, tn)); }
        }
        foreach (var r in results.Where(x => x.tot > 0).OrderByDescending(x => x.prof).ThenByDescending(x => x.tot).Take(18))
            Console.WriteLine($"  {r.desc,-34} {r.tr,5} {r.prof,7:F0} {r.tot,8:F0} {r.mdd,6:F0} {r.worst,7:F1}");
        Console.WriteLine("\n  → 흑자월% 높고 MDD 낮은 게 '매달 안 물리는' 구성. 총수익도 +여야 채택.");
    }

    // --lorentzian-monthly : 라이브 v5.26.1 로직(종가기준 5ATR트레일·본절OFF) 6슬롯 포트폴리오 월별 성과표.
    //   $500×6=$3,000 자본. 월별 진입수·수익금$·수익률%·누적. 레버 1x/2x/3x. monthly-perf.json 저장.
    private static async Task RunLorentzianMonthlyAsync()
    {
        const int featureWindow = 500, K = 8, Lh = 8, pages1h = 20;
        const decimal feeRT = 0.0008m; const double atrMult = 5.0, adxThr = 20;
        decimal margin = 500m; int slots = 6; decimal capital = margin * slots;
        var universe = new[] {
            "BTCUSDT","ETHUSDT","BNBUSDT","SOLUSDT","XRPUSDT","DOGEUSDT","ADAUSDT","TRXUSDT","AVAXUSDT","LINKUSDT",
            "DOTUSDT","LTCUSDT","BCHUSDT","ATOMUSDT","UNIUSDT","NEARUSDT","APTUSDT","ARBUSDT","OPUSDT","SUIUSDT" };
        Console.WriteLine("=== 라이브 v5.26.1 로직 6슬롯 포트폴리오 월별 성과 ($500×6=$3,000) ===\n");
        var btcBull = new Dictionary<DateTime, bool>();
        { var btc = await FetchKlines1hAsync("BTCUSDT", pages1h); int bn = btc.Count; var be2 = new double[bn]; for (int j = 200; j < bn; j++) be2[j] = CalcEMA(btc, j, 200); for (int j = 200; j < bn; j++) btcBull[btc[j].OpenTime] = be2[j] > 0 && (double)btc[j].ClosePrice > be2[j]; }
        var allTrades = new List<(DateTime ent, DateTime ex, decimal pnlPct)>();
        int ci = 0;
        foreach (var sym in universe)
        {
            ci++; Console.Write($"[{ci}/{universe.Length}] {sym} ");
            List<IBinanceKline> kl;
            try { kl = await FetchKlines1hAsync(sym, pages1h); } catch { Console.WriteLine("fail"); continue; }
            if (kl.Count < 2000) { Console.WriteLine("skip"); continue; }
            int n = kl.Count; Console.WriteLine($"{n}"); var close = new double[n]; for (int j = 0; j < n; j++) close[j] = (double)kl[j].ClosePrice;
            var feats = new float[n][];
            for (int j = 60; j < n; j++) { int ws = Math.Max(0, j - (featureWindow - 1)); feats[j] = LorentzianFeatures.Extract(kl.GetRange(ws, j - ws + 1))!; }
            var e50 = new double[n]; for (int j = 50; j < n; j++) e50[j] = CalcEMA(kl, j, 50);
            var e200 = new double[n]; for (int j = 200; j < n; j++) e200[j] = CalcEMA(kl, j, 200);
            var atr = new double[n]; for (int j = 14; j < n; j++) { double tr = 0; for (int q = j - 13; q <= j; q++) { double hh = (double)kl[q].HighPrice, ll = (double)kl[q].LowPrice, pc = close[q - 1]; tr += Math.Max(hh - ll, Math.Max(Math.Abs(hh - pc), Math.Abs(ll - pc))); } atr[j] = tr / 14.0; }
            var adx = new double[n]; { double atrS = 0, pdmS = 0, mdmS = 0; int per = 14; for (int j = 1; j < n; j++) { double hh = (double)kl[j].HighPrice, ll = (double)kl[j].LowPrice, pc = close[j - 1], ph = (double)kl[j - 1].HighPrice, pl = (double)kl[j - 1].LowPrice; double tr = Math.Max(hh - ll, Math.Max(Math.Abs(hh - pc), Math.Abs(ll - pc))); double up = hh - ph, dn = pl - ll; double pdm = (up > dn && up > 0) ? up : 0, mdm = (dn > up && dn > 0) ? dn : 0; if (j <= per) { atrS += tr; pdmS += pdm; mdmS += mdm; } else { atrS = atrS - atrS / per + tr; pdmS = pdmS - pdmS / per + pdm; mdmS = mdmS - mdmS / per + mdm; } if (j >= per && atrS > 0) { double pd = 100 * pdmS / atrS, md = 100 * mdmS / atrS; double dx = (pd + md) > 0 ? 100 * Math.Abs(pd - md) / (pd + md) : 0; adx[j] = j <= per * 2 ? dx : (adx[j - 1] * (per - 1) + dx) / per; } } }
            var engine = new LorentzianAnnEngine(sym, neighborsCount: K, maxBarsBack: 2000, featureCount: LorentzianFeatures.FeatureCount);
            var sg = new int[n];
            for (int j = 65; j < n; j++) { int s = j - 1; if (s - Lh >= 0 && feats[s] != null) { double a = close[s], b = close[s - Lh]; engine.AddSample(feats[s], a > b ? 1 : (a < b ? -1 : 0)); } if (feats[j] == null) continue; var p = engine.Predict(feats[j]); if (!p.IsReady || p.K == 0) continue; sg[j] = p.Prediction > 0 ? 1 : (p.Prediction < 0 ? -1 : 0); }
            int busy = -1;
            for (int j = 250; j < n - 1; j++)
            {
                if (j <= busy) continue;
                if (!(sg[j] > 0 && e50[j] > 0 && e200[j] > 0 && e50[j] > e200[j] && close[j] > e50[j] && adx[j] >= adxThr)) continue;
                if (!(btcBull.TryGetValue(kl[j].OpenTime, out var bb) && bb)) continue;
                if (atr[j] <= 0 || kl[j + 1].OpenPrice <= 0) continue;
                // [v5.26.2 손실방어 3종] 과확장·거래량급증·윗꼬리 차단 (흑자월 36→48%)
                if ((close[j] - e50[j]) / atr[j] >= 2.0) continue;
                double vsumM = 0; for (int q = j - 19; q <= j; q++) vsumM += (double)kl[q].Volume; double vavgM = vsumM / 20;
                if (vavgM > 0 && (double)kl[j].Volume / vavgM >= 1.5) continue;
                if (((double)kl[j].HighPrice - Math.Max((double)kl[j].OpenPrice, close[j])) / atr[j] >= 0.5) continue;
                decimal entry = kl[j + 1].OpenPrice; double peakP = (double)entry; decimal net = 0m; int ei = n - 1;
                for (int e = j + 1; e < n; e++)   // 종가기준 5ATR 트레일 (라이브 v5.26.1과 동일)
                {
                    double cc = (double)kl[e].ClosePrice; if (cc > peakP) peakP = cc;
                    double stop = peakP - atrMult * atr[e];
                    if (cc <= stop) { net = ((decimal)cc - entry) / entry - feeRT; ei = e; break; }
                    if (e == n - 1) net = ((decimal)cc - entry) / entry - feeRT;
                }
                busy = ei; allTrades.Add((kl[j + 1].OpenTime, kl[ei].OpenTime, net));
            }
        }
        allTrades.Sort((a, b) => a.ent.CompareTo(b.ent));
        // 6슬롯 적용 + 월별 집계 (레버 1x 기준). 다른 레버는 배수.
        foreach (decimal lev in new[] { 1m, 2m, 3m })
        {
            var open = new List<DateTime>();
            var monthly = new SortedDictionary<string, (int n, decimal pnl)>();
            decimal total = 0m; int totalN = 0;
            foreach (var t in allTrades)
            {
                open.RemoveAll(x => x <= t.ent); if (open.Count >= slots) continue; open.Add(t.ex);
                decimal pnl = t.pnlPct * margin * lev; string mk = t.ent.ToString("yyyy-MM");
                var cur = monthly.TryGetValue(mk, out var v) ? v : (0, 0m); monthly[mk] = (cur.Item1 + 1, cur.Item2 + pnl);
                total += pnl; totalN++;
            }
            Console.WriteLine($"\n═══════════ 레버리지 {lev:F0}x · $500×6=$3,000 ═══════════");
            Console.WriteLine($"  {"월",8} {"진입",5} {"수익금$",10} {"월수익률%",9} {"누적$",11}");
            decimal cum = 0m;
            foreach (var kv in monthly) { cum += kv.Value.pnl; Console.WriteLine($"  {kv.Key,8} {kv.Value.n,5} {kv.Value.pnl,10:F0} {(double)(kv.Value.pnl / capital * 100m),9:F1} {cum,11:F0}"); }
            int months = monthly.Count;
            Console.WriteLine($"  ─────────────────────────────────────────────");
            Console.WriteLine($"  총 {months}개월 · 진입 {totalN} · 총수익 ${total:F0} ({(double)(total / capital * 100m):F0}%) · 월평균 ${(months > 0 ? total / months : 0):F0} ({(months > 0 ? (double)(total / capital * 100m) / months : 0):F1}%)");
            if (lev == 1m)
            {
                var sb = new System.Text.StringBuilder(); var inv = System.Globalization.CultureInfo.InvariantCulture; sb.Append('[');
                bool first = true; decimal c2 = 0m;
                foreach (var kv in monthly) { c2 += kv.Value.pnl; if (!first) sb.Append(','); first = false; sb.Append($"{{\"m\":\"{kv.Key}\",\"n\":{kv.Value.n},\"pnl\":{kv.Value.pnl.ToString("F0", inv)},\"ret\":{((double)(kv.Value.pnl / capital * 100m)).ToString("F1", inv)},\"cum\":{c2.ToString("F0", inv)}}}"); }
                sb.Append(']'); System.IO.File.WriteAllText("monthly-perf.json", sb.ToString());
                Console.WriteLine($"  → monthly-perf.json 저장 (1x)");
            }
        }
    }

    // --lorentzian-live : 라이브 v5.26.0 로직 그대로 백테 — 진입(KNN+EMA정배열+ADX20+BTC상승장) + 청산(peak−5ATR 트레일).
    //   본절(breakeven) ON/OFF 비교 → 본절이 승자를 본절컷해 수익 깎는지 확인. 배포 전 최종 검증.
    private static async Task RunLorentzianLiveAsync()
    {
        const int featureWindow = 500, K = 8, Lh = 8, pages1h = 20;
        const decimal feeRT = 0.0008m; const double atrMult = 5.0, adxThr = 20;
        var universe = new[] {
            "BTCUSDT","ETHUSDT","BNBUSDT","SOLUSDT","XRPUSDT","DOGEUSDT","ADAUSDT","TRXUSDT","AVAXUSDT","LINKUSDT",
            "DOTUSDT","LTCUSDT","BCHUSDT","ATOMUSDT","UNIUSDT","NEARUSDT","APTUSDT","ARBUSDT","OPUSDT","SUIUSDT" };
        Console.WriteLine("=== 라이브 v5.26.0 로직 백테 : 진입 KNN+EMA정배열+ADX20+BTC상승장 / 청산 peak−5ATR 트레일 ===\n");
        // BTC 상승장 룩업 (1h 종가>EMA200) by OpenTime
        var btcBull = new Dictionary<DateTime, bool>();
        {
            var btc = await FetchKlines1hAsync("BTCUSDT", pages1h);
            int bn = btc.Count; var be2 = new double[bn];
            for (int j = 200; j < bn; j++) be2[j] = CalcEMA(btc, j, 200);
            for (int j = 200; j < bn; j++) btcBull[btc[j].OpenTime] = be2[j] > 0 && (double)btc[j].ClosePrice > be2[j];
        }
        foreach (var (breakeven, closeOnly) in new[] { (false, true), (false, false), (true, true) })
        {
            Console.WriteLine($"\n──────── 본절 {(breakeven ? "ON" : "OFF")} · 손절 {(closeOnly ? "종가기준(꼬리무시)" : "틱기준(장중저가)")} ────────");
            Console.WriteLine($"  {"심볼",10} {"거래",5} {"승률%",6} {"PF",5} {"MDD%",6} {"1x%",8} {"판정",5}");
            int prof = 0, valid = 0; double sum1 = 0;
            foreach (var sym in universe)
            {
                List<IBinanceKline> kl;
                try { kl = await FetchKlines1hAsync(sym, pages1h); } catch { continue; }
                if (kl.Count < 2000) continue;
                int n = kl.Count; var close = new double[n]; for (int j = 0; j < n; j++) close[j] = (double)kl[j].ClosePrice;
                var feats = new float[n][];
                for (int j = 60; j < n; j++) { int ws = Math.Max(0, j - (featureWindow - 1)); feats[j] = LorentzianFeatures.Extract(kl.GetRange(ws, j - ws + 1))!; }
                var e50 = new double[n]; for (int j = 50; j < n; j++) e50[j] = CalcEMA(kl, j, 50);
                var e200 = new double[n]; for (int j = 200; j < n; j++) e200[j] = CalcEMA(kl, j, 200);
                var atr = new double[n]; for (int j = 14; j < n; j++) { double tr = 0; for (int q = j - 13; q <= j; q++) { double hh = (double)kl[q].HighPrice, ll = (double)kl[q].LowPrice, pc = close[q - 1]; tr += Math.Max(hh - ll, Math.Max(Math.Abs(hh - pc), Math.Abs(ll - pc))); } atr[j] = tr / 14.0; }
                var adx = new double[n]; { double atrS = 0, pdmS = 0, mdmS = 0; int per = 14; for (int j = 1; j < n; j++) { double hh = (double)kl[j].HighPrice, ll = (double)kl[j].LowPrice, pc = close[j - 1], ph = (double)kl[j - 1].HighPrice, pl = (double)kl[j - 1].LowPrice; double tr = Math.Max(hh - ll, Math.Max(Math.Abs(hh - pc), Math.Abs(ll - pc))); double up = hh - ph, dn = pl - ll; double pdm = (up > dn && up > 0) ? up : 0, mdm = (dn > up && dn > 0) ? dn : 0; if (j <= per) { atrS += tr; pdmS += pdm; mdmS += mdm; } else { atrS = atrS - atrS / per + tr; pdmS = pdmS - pdmS / per + pdm; mdmS = mdmS - mdmS / per + mdm; } if (j >= per && atrS > 0) { double pd = 100 * pdmS / atrS, md = 100 * mdmS / atrS; double dx = (pd + md) > 0 ? 100 * Math.Abs(pd - md) / (pd + md) : 0; adx[j] = j <= per * 2 ? dx : (adx[j - 1] * (per - 1) + dx) / per; } } }
                var engine = new LorentzianAnnEngine(sym, neighborsCount: K, maxBarsBack: 2000, featureCount: LorentzianFeatures.FeatureCount);
                var sg = new int[n];
                for (int j = 65; j < n; j++) { int s = j - 1; if (s - Lh >= 0 && feats[s] != null) { double a = close[s], b = close[s - Lh]; engine.AddSample(feats[s], a > b ? 1 : (a < b ? -1 : 0)); } if (feats[j] == null) continue; var p = engine.Predict(feats[j]); if (!p.IsReady || p.K == 0) continue; sg[j] = p.Prediction > 0 ? 1 : (p.Prediction < 0 ? -1 : 0); }
                decimal equity = 1m, peak = 1m, mdd = 0m; int trades = 0, wins = 0; decimal gW = 0m, gL = 0m; int busy = -1;
                for (int j = 250; j < n - 1; j++)
                {
                    if (j <= busy) continue;
                    if (!(sg[j] > 0 && e50[j] > 0 && e200[j] > 0 && e50[j] > e200[j] && close[j] > e50[j] && adx[j] >= adxThr)) continue;
                    if (!(btcBull.TryGetValue(kl[j].OpenTime, out var bb) && bb)) continue;  // BTC 상승장만
                    if (atr[j] <= 0 || kl[j + 1].OpenPrice <= 0) continue;
                    decimal entry = kl[j + 1].OpenPrice; double peakP = (double)entry; bool beOn = false; decimal net = 0m; int ei = n - 1;
                    for (int e = j + 1; e < n; e++)
                    {
                        double hi = (double)kl[e].HighPrice, lo = (double)kl[e].LowPrice, cc = (double)kl[e].ClosePrice;
                        double peakRef = closeOnly ? cc : hi;
                        if (peakRef > peakP) peakP = peakRef;
                        double beTrig = closeOnly ? cc : hi;
                        if (breakeven && !beOn && beTrig >= (double)entry * 1.02) beOn = true;
                        double trail = peakP - atrMult * atr[e];
                        double stop = beOn ? Math.Max(trail, (double)entry) : trail;
                        if (closeOnly)
                        {
                            if (cc <= stop) { net = ((decimal)cc - entry) / entry - feeRT; ei = e; break; }   // 종가 마감 확인
                        }
                        else
                        {
                            if (lo <= stop) { net = ((decimal)stop - entry) / entry - feeRT; ei = e; break; } // 장중 저가 터치
                        }
                        if (e == n - 1) net = ((decimal)cc - entry) / entry - feeRT;
                    }
                    equity *= (1m + net); if (equity <= 0) break; trades++; if (net > 0) { wins++; gW += net; } else gL += -net;
                    if (equity > peak) peak = equity; decimal dd = (peak - equity) / peak; if (dd > mdd) mdd = dd; busy = ei;
                }
                double pf = gL > 0 ? (double)(gW / gL) : (gW > 0 ? 99 : 0); double ret = (double)((equity - 1m) * 100m);
                valid++; sum1 += ret; if (ret > 0) prof++;
                string vd = pf > 1.2 && ret > 0 ? "★흑자" : ret > 0 ? "흑자" : "적자";
                Console.WriteLine($"  {sym,10} {trades,5} {(trades > 0 ? 100.0 * wins / trades : 0),6:F1} {pf,5:F2} {mdd * 100m,6:F1} {ret,8:F1} {vd,5}");
            }
            Console.WriteLine($"  → 흑자 {prof}/{valid} ({(valid > 0 ? 100.0 * prof / valid : 0):F0}%) · 평균 1x {(valid > 0 ? sum1 / valid : 0):F1}%");
        }
        Console.WriteLine("\n  ★ 본절 OFF(순수 트레일)가 검증 백테와 동일. 본절 ON이 수익 깎으면 라이브에서 본절 제거 필요.");
    }

    // --lorentzian-validate : 그리드 최적구조(롱전용 KNN+EMA정배열→ATR5트레일·ADX20)를 20코인 전체에 고정 적용.
    //   과최적화 여부 검증 — 대부분 코인에서 PF>1·흑자면 진짜 엣지. 종목별 미최적화(동일 파라미터).
    private static async Task RunLorentzianValidateAsync()
    {
        const int featureWindow = 500, K = 8, Lh = 8, pages1h = 20;
        const decimal feeRT = 0.0008m; const double atrMult = 5.0, adxThr = 20;
        var universe = new[] {
            "BTCUSDT","ETHUSDT","BNBUSDT","SOLUSDT","XRPUSDT","DOGEUSDT","ADAUSDT","TRXUSDT","AVAXUSDT","LINKUSDT",
            "DOTUSDT","LTCUSDT","BCHUSDT","ATOMUSDT","UNIUSDT","NEARUSDT","APTUSDT","ARBUSDT","OPUSDT","SUIUSDT" };
        Console.WriteLine("=== 최적구조 20코인 교차검증 : 롱전용 KNN(과거8)+EMA정배열 → ATR5트레일 · ADX20 (동일 파라미터) ===\n");
        Console.WriteLine($"  {"심볼",10} {"존버%",8} {"거래",5} {"승률%",6} {"PF",5} {"MDD%",6} {"1x수익%",9} {"2x수익%",9} {"판정",5}");
        int profitable = 0, beatBH = 0, valid = 0; double sum1x = 0, sum2x = 0, sumBH = 0;
        foreach (var sym in universe)
        {
            List<IBinanceKline> kl;
            try { kl = await FetchKlines1hAsync(sym, pages1h); } catch { Console.WriteLine($"  {sym,10} fail"); continue; }
            if (kl.Count < 2000) { Console.WriteLine($"  {sym,10} skip(bars={kl.Count})"); continue; }
            int n = kl.Count; var close = new double[n]; for (int j = 0; j < n; j++) close[j] = (double)kl[j].ClosePrice;
            var feats = new float[n][];
            for (int j = 60; j < n; j++) { int ws = Math.Max(0, j - (featureWindow - 1)); feats[j] = LorentzianFeatures.Extract(kl.GetRange(ws, j - ws + 1))!; }
            var e50 = new double[n]; for (int j = 50; j < n; j++) e50[j] = CalcEMA(kl, j, 50);
            var e200 = new double[n]; for (int j = 200; j < n; j++) e200[j] = CalcEMA(kl, j, 200);
            var atr = new double[n]; for (int j = 14; j < n; j++) { double tr = 0; for (int q = j - 13; q <= j; q++) { double hh = (double)kl[q].HighPrice, ll = (double)kl[q].LowPrice, pc = close[q - 1]; tr += Math.Max(hh - ll, Math.Max(Math.Abs(hh - pc), Math.Abs(ll - pc))); } atr[j] = tr / 14.0; }
            var adx = new double[n]; { double atrS = 0, pdmS = 0, mdmS = 0; int per = 14; for (int j = 1; j < n; j++) { double hh = (double)kl[j].HighPrice, ll = (double)kl[j].LowPrice, pc = close[j - 1], ph = (double)kl[j - 1].HighPrice, pl = (double)kl[j - 1].LowPrice; double tr = Math.Max(hh - ll, Math.Max(Math.Abs(hh - pc), Math.Abs(ll - pc))); double up = hh - ph, dn = pl - ll; double pdm = (up > dn && up > 0) ? up : 0, mdm = (dn > up && dn > 0) ? dn : 0; if (j <= per) { atrS += tr; pdmS += pdm; mdmS += mdm; } else { atrS = atrS - atrS / per + tr; pdmS = pdmS - pdmS / per + pdm; mdmS = mdmS - mdmS / per + mdm; } if (j >= per && atrS > 0) { double pd = 100 * pdmS / atrS, md = 100 * mdmS / atrS; double dx = (pd + md) > 0 ? 100 * Math.Abs(pd - md) / (pd + md) : 0; adx[j] = j <= per * 2 ? dx : (adx[j - 1] * (per - 1) + dx) / per; } } }
            var engine = new LorentzianAnnEngine(sym, neighborsCount: K, maxBarsBack: 2000, featureCount: LorentzianFeatures.FeatureCount);
            var sg = new int[n];
            for (int j = 65; j < n; j++) { int s = j - 1; if (s - Lh >= 0 && feats[s] != null) { double a = close[s], b = close[s - Lh]; engine.AddSample(feats[s], a > b ? 1 : (a < b ? -1 : 0)); } if (feats[j] == null) continue; var p = engine.Predict(feats[j]); if (!p.IsReady || p.K == 0) continue; sg[j] = p.Prediction > 0 ? 1 : (p.Prediction < 0 ? -1 : 0); }
            decimal bh = (kl[n - 1].ClosePrice - kl[250].ClosePrice) / kl[250].ClosePrice * 100m;
            (double ret, double pf, double mdd, int trades, double wr) Run(decimal lev)
            {
                int pos = 0; double entryPx = 0, peakP = 0; decimal equity = 1m, peak = 1m, mdd = 0m; int trades = 0, wins = 0; decimal gW = 0m, gL = 0m; bool blown = false;
                for (int j = 250; j < n; j++)
                {
                    double c = close[j]; if (pos == 1 && c > peakP) peakP = c;
                    if (pos == 0) { if (adx[j] >= adxThr && sg[j] > 0 && e50[j] > 0 && e200[j] > 0 && e50[j] > e200[j] && c > e50[j]) { pos = 1; entryPx = c; peakP = c; } }
                    else { if (atr[j] > 0 && c <= peakP - atrMult * atr[j]) { decimal r = ((decimal)((c - entryPx) / entryPx) - feeRT) * lev; equity *= (1m + r); if (equity <= 0) { blown = true; break; } trades++; if (r > 0) { wins++; gW += r; } else gL += -r; if (equity > peak) peak = equity; decimal dd = (peak - equity) / peak; if (dd > mdd) mdd = dd; pos = 0; } }
                }
                double pf = gL > 0 ? (double)(gW / gL) : (gW > 0 ? 99 : 0);
                return (blown ? -100 : (double)((equity - 1m) * 100m), pf, (double)(mdd * 100m), trades, trades > 0 ? 100.0 * wins / trades : 0);
            }
            var r1 = Run(1m); var r2 = Run(2m);
            valid++; sum1x += r1.ret; sum2x += r2.ret; sumBH += (double)bh;
            if (r1.ret > 0) profitable++; if (r1.ret > (double)bh) beatBH++;
            string verdict = r1.pf > 1.2 && r1.ret > 0 ? "★흑자" : r1.ret > 0 ? "흑자" : "적자";
            Console.WriteLine($"  {sym,10} {bh,8:F0} {r1.trades,5} {r1.wr,6:F1} {r1.pf,5:F2} {r1.mdd,6:F1} {r1.ret,9:F1} {r2.ret,9:F1} {verdict,5}");
        }
        Console.WriteLine($"\n  검증 {valid}종: 흑자 {profitable}/{valid} ({(valid > 0 ? 100.0 * profitable / valid : 0):F0}%) · 존버초과 {beatBH}/{valid}");
        Console.WriteLine($"  평균수익: 1x {(valid > 0 ? sum1x / valid : 0):F1}% · 2x {(valid > 0 ? sum2x / valid : 0):F1}% · 존버평균 {(valid > 0 ? sumBH / valid : 0):F1}%");
        Console.WriteLine($"  → 흑자비율 높고 존버초과 많으면 = 과최적화 아닌 진짜 엣지. 낮으면 BTC 과최적화.");
    }

    // --lorentzian-grid : 롱전용 추세타기 구조를 병렬 전수탐색. 진입6×청산6×ADX3×라벨3=324조합 Parallel.For.
    //   목표: PF>1 & 존버초과 & MDD낮음. 수익나는 구조 발굴.
    private static async Task RunLorentzianGridAsync()
    {
        const int featureWindow = 500, K = 8, pages1h = 20;
        const decimal feeRT = 0.0008m;
        Console.WriteLine("=== 롱전용 추세타기 병렬 그리드서치 : BTCUSDT 1h · 324조합 ===\n");
        var kl = await FetchKlines1hAsync("BTCUSDT", pages1h);
        int n = kl.Count;
        var close = new double[n]; for (int j = 0; j < n; j++) close[j] = (double)kl[j].ClosePrice;
        decimal bh = (kl[n - 1].ClosePrice - kl[250].ClosePrice) / kl[250].ClosePrice * 100m;
        Console.WriteLine($"BTCUSDT bars={n}, 존버={bh:F1}%\n");
        var feats = new float[n][];
        for (int j = 60; j < n; j++) { int ws = Math.Max(0, j - (featureWindow - 1)); feats[j] = LorentzianFeatures.Extract(kl.GetRange(ws, j - ws + 1))!; }
        // 지표 사전계산
        var yhat = new double[n]; { int h = 8; double r = 8; for (int j = 25; j < n; j++) { double num = 0, den = 0; int kmax = Math.Min(j, 100); for (int kk = 0; kk <= kmax; kk++) { double w = Math.Pow(1 + (kk * kk) / (2.0 * r * h * h), -r); num += close[j - kk] * w; den += w; } yhat[j] = num / den; } }
        var e50 = new double[n]; for (int j = 50; j < n; j++) e50[j] = CalcEMA(kl, j, 50);
        var e200 = new double[n]; for (int j = 200; j < n; j++) e200[j] = CalcEMA(kl, j, 200);
        var atr = new double[n]; for (int j = 14; j < n; j++) { double tr = 0; for (int q = j - 13; q <= j; q++) { double hh = close[q] > 0 ? (double)kl[q].HighPrice : 0, ll = (double)kl[q].LowPrice, pc = close[q - 1]; tr += Math.Max(hh - ll, Math.Max(Math.Abs(hh - pc), Math.Abs(ll - pc))); } atr[j] = tr / 14.0; }
        var adx = new double[n]; { double atrS = 0, pdmS = 0, mdmS = 0; int per = 14; for (int j = 1; j < n; j++) { double hh = (double)kl[j].HighPrice, ll = (double)kl[j].LowPrice, pc = close[j - 1], ph = (double)kl[j - 1].HighPrice, pl = (double)kl[j - 1].LowPrice; double tr = Math.Max(hh - ll, Math.Max(Math.Abs(hh - pc), Math.Abs(ll - pc))); double up = hh - ph, dn = pl - ll; double pdm = (up > dn && up > 0) ? up : 0, mdm = (dn > up && dn > 0) ? dn : 0; if (j <= per) { atrS += tr; pdmS += pdm; mdmS += mdm; } else { atrS = atrS - atrS / per + tr; pdmS = pdmS - pdmS / per + pdm; mdmS = mdmS - mdmS / per + mdm; } if (j >= per && atrS > 0) { double pd = 100 * pdmS / atrS, md = 100 * mdmS / atrS; double dx = (pd + md) > 0 ? 100 * Math.Abs(pd - md) / (pd + md) : 0; adx[j] = j <= per * 2 ? dx : (adx[j - 1] * (per - 1) + dx) / per; } } }
        // 라벨 3종 sg 사전계산
        var sgLabels = new int[3][]; var lblNames = new[] { "과거4", "과거8", "미래4" };
        for (int li = 0; li < 3; li++)
        {
            int Lh = li == 1 ? 8 : 4; bool forward = li == 2;
            var engine = new LorentzianAnnEngine("BTCUSDT", neighborsCount: K, maxBarsBack: 2000, featureCount: LorentzianFeatures.FeatureCount);
            var sg = new int[n];
            for (int j = 65; j < n; j++) { if (forward) { int s = j - Lh - 1; if (s >= 8 && feats[s] != null) { double a = close[s + Lh], b = close[s]; engine.AddSample(feats[s], a > b ? 1 : (a < b ? -1 : 0)); } } else { int s = j - 1; if (s - Lh >= 0 && feats[s] != null) { double a = close[s], b = close[s - Lh]; engine.AddSample(feats[s], a > b ? 1 : (a < b ? -1 : 0)); } } if (feats[j] == null) continue; var p = engine.Predict(feats[j]); if (!p.IsReady || p.K == 0) continue; sg[j] = p.Prediction > 0 ? 1 : (p.Prediction < 0 ? -1 : 0); }
            sgLabels[li] = sg;
        }
        var entryNames = new[] { "KNN", "KNN+커널", "KNN+커널+EMA배열", "커널+EMA50", "커널+EMA200", "KNN+EMA배열" };
        var exitNames = new[] { "ATR2.0", "ATR2.5", "ATR3.0", "ATR4.0", "ATR5.0", "EMA200이탈" };
        double[] atrMults = { 2.0, 2.5, 3.0, 4.0, 5.0 };
        double[] adxThrs = { 0, 20, 25 };
        decimal[] levs = { 1m, 2m, 3m };
        bool Enter(int t, int j, int[] sg) => t switch {
            0 => sg[j] > 0,
            1 => sg[j] > 0 && yhat[j] > yhat[j - 1],
            2 => sg[j] > 0 && yhat[j] > yhat[j - 1] && e50[j] > 0 && e200[j] > 0 && e50[j] > e200[j],
            3 => yhat[j] > yhat[j - 1] && e50[j] > 0 && close[j] > e50[j],
            4 => yhat[j] > yhat[j - 1] && e200[j] > 0 && close[j] > e200[j],
            _ => sg[j] > 0 && e50[j] > 0 && e200[j] > 0 && e50[j] > e200[j] && close[j] > e50[j],
        };
        // 6진입 × 6청산 × 3ADX × 3라벨 × 3레버 = 972
        int nE = 6, nX = 6, nA = 3, nL = 3, nLev = 3;
        int totalCombos = nE * nX * nA * nL * nLev;
        var results = new (double ret, double pf, double mdd, int trades, double wr, decimal lev, string desc)[totalCombos];
        System.Threading.Tasks.Parallel.For(0, totalCombos, idx =>
        {
            int eT = idx % nE, xT = (idx / nE) % nX, aT = (idx / (nE * nX)) % nA, lT = (idx / (nE * nX * nA)) % nL, vT = (idx / (nE * nX * nA * nL)) % nLev;
            var sg = sgLabels[lT]; double athr = adxThrs[aT]; decimal lev = levs[vT];
            int pos = 0; double entryPx = 0, peakP = 0; decimal equity = 1m, peak = 1m, mdd = 0m; int trades = 0, wins = 0; decimal gW = 0m, gL = 0m; bool blown = false;
            for (int j = 250; j < n; j++)
            {
                double c = close[j];
                if (pos == 1 && c > peakP) peakP = c;
                if (pos == 0)
                {
                    if (adx[j] >= athr && Enter(eT, j, sg)) { pos = 1; entryPx = c; peakP = c; }
                }
                else
                {
                    bool ex = xT < 5 ? (atr[j] > 0 && c <= peakP - atrMults[xT] * atr[j]) : (e200[j] > 0 && c < e200[j]);
                    if (ex) { decimal r = ((decimal)((c - entryPx) / entryPx) - feeRT) * lev; equity *= (1m + r); if (equity <= 0) { blown = true; break; } trades++; if (r > 0) { wins++; gW += r; } else gL += -r; if (equity > peak) peak = equity; decimal dd = (peak - equity) / peak; if (dd > mdd) mdd = dd; pos = 0; }
                }
            }
            double pf = gL > 0 ? (double)(gW / gL) : (gW > 0 ? 99 : 0);
            results[idx] = (blown ? -100 : (double)((equity - 1m) * 100m), pf, (double)(mdd * 100m), trades, trades > 0 ? 100.0 * wins / trades : 0, lev, $"{lblNames[lT]}|{entryNames[eT]}→{exitNames[xT]}|ADX{athr:F0}|{lev:F0}x");
        });
        Console.WriteLine("── 수익률 상위 15 (PF>1, 거래≥30) ──");
        Console.WriteLine($"  {"구성",46} {"거래",5} {"승률%",6} {"PF",5} {"MDD%",6} {"수익%",9}");
        foreach (var r in results.Where(r => r.pf > 1.0 && r.trades >= 30).OrderByDescending(r => r.ret).Take(15))
            Console.WriteLine($"  {r.desc,-46} {r.trades,5} {r.wr,6:F1} {r.pf,5:F2} {r.mdd,6:F1} {r.ret,9:F1}");
        Console.WriteLine("\n── 위험대비(수익/MDD=Calmar) 상위 12 (PF>1, 거래≥30) ──");
        Console.WriteLine($"  {"구성",46} {"거래",5} {"PF",5} {"MDD%",6} {"수익%",9} {"Calmar",6}");
        foreach (var r in results.Where(r => r.pf > 1.0 && r.trades >= 30 && r.ret > 0).OrderByDescending(r => r.mdd > 0 ? r.ret / r.mdd : 0).Take(12))
            Console.WriteLine($"  {r.desc,-46} {r.trades,5} {r.pf,5:F2} {r.mdd,6:F1} {r.ret,9:F1} {(r.mdd > 0 ? r.ret / r.mdd : 0),6:F2}");
        Console.WriteLine($"\n  존버={bh:F1}%. 존버초과 & MDD낮은(Calmar높은) 구조가 목표.");
    }

    // --lorentzian-btc-flip : 제미나이 주장 재현. BTCUSDT 1h, jdehorty 정통 플립(항상 롱/숏, 반대신호에 전환), 하드SL 없음.
    //   fee 0.08% 왕복. 라벨 forward(정통)/backward(라이브) × 레버 1x/10x 비교. 존버(B&H) 대비.
    private static async Task RunLorentzianBtcFlipAsync()
    {
        const int featureWindow = 500, K = 8, pages1h = 20;
        const decimal feeRT = 0.0008m; // 왕복 0.08%
        Console.WriteLine("=== Lorentzian 정통 플립 재현 : BTCUSDT 1h · 하드SL없음 · fee 0.08%왕복 ===\n");
        var kl = await FetchKlines1hAsync("BTCUSDT", pages1h);
        int n = kl.Count;
        Console.WriteLine($"BTCUSDT 1h bars = {n} (~{n / 24 / 30}개월)\n");
        var feats = new float[n][];
        for (int j = 60; j < n; j++) { int ws = Math.Max(0, j - (featureWindow - 1)); feats[j] = LorentzianFeatures.Extract(kl.GetRange(ws, j - ws + 1))!; }
        // 존버 수익률
        decimal bh = (kl[n - 1].ClosePrice - kl[250].ClosePrice) / kl[250].ClosePrice * 100m;
        Console.WriteLine($"존버(Buy&Hold) 동기간 = {bh:F1}%\n");
        Console.WriteLine($"  {"라벨",8} {"레버",5} {"거래",5} {"승률%",6} {"손익비PF",8} {"MDD%",7} {"누적수익%",10}");

        foreach (int Lh in new[] { 4, 8 })      // 라벨 호라이즌: 4=정통기본, 8=라이브
        foreach (bool forward in new[] { true, false })
        {
            // 신호 생성 (룩어헤드 0)
            var engine = new LorentzianAnnEngine("BTCUSDT", neighborsCount: K, maxBarsBack: 2000, featureCount: LorentzianFeatures.FeatureCount);
            var sg = new int[n];
            for (int j = 65; j < n; j++)
            {
                if (forward) { int s = j - Lh - 1; if (s >= 8 && feats[s] != null) { decimal a = kl[s + Lh].ClosePrice, b = kl[s].ClosePrice; engine.AddSample(feats[s], a > b ? 1 : (a < b ? -1 : 0)); } }
                else { int s = j - 1; if (s - Lh >= 0 && feats[s] != null) { decimal a = kl[s].ClosePrice, b = kl[s - Lh].ClosePrice; engine.AddSample(feats[s], a > b ? 1 : (a < b ? -1 : 0)); } }
                if (feats[j] == null) continue; var p = engine.Predict(feats[j]); if (!p.IsReady || p.K == 0) continue; sg[j] = p.Prediction > 0 ? 1 : (p.Prediction < 0 ? -1 : 0);
            }
            foreach (decimal lev in new[] { 1m, 10m })
            {
                int pos = 0; decimal entryPx = 0m; decimal equity = 1m, peak = 1m, mdd = 0m; int trades = 0, wins = 0; decimal gW = 0m, gL = 0m; bool blown = false;
                for (int j = 250; j < n; j++)
                {
                    int sig = sg[j]; decimal c = kl[j].ClosePrice;
                    if (sig != 0 && sig != pos)
                    {
                        if (pos != 0 && entryPx > 0)
                        {
                            decimal r = pos * (c - entryPx) / entryPx - feeRT;
                            decimal pnl = r * lev; equity *= (1m + pnl);
                            if (equity <= 0m) { blown = true; equity = 0m; }
                            trades++; if (pnl > 0) { wins++; gW += pnl; } else gL += -pnl;
                            if (equity > peak) peak = equity; decimal dd = peak > 0 ? (peak - equity) / peak : 0m; if (dd > mdd) mdd = dd;
                        }
                        if (blown) break;
                        pos = sig; entryPx = c;
                    }
                }
                double pf = gL > 0 ? (double)(gW / gL) : 0;
                string lab = forward ? $"미래{Lh}" : $"과거{Lh}";
                string net = blown ? "청산(-100%)" : $"{(equity - 1m) * 100m:F1}%";
                Console.WriteLine($"  {lab,8} {lev,4:F0}x {trades,5} {(trades > 0 ? 100.0 * wins / trades : 0),6:F1} {pf,8:F2} {mdd * 100m,6:F1} {net,10}");
            }
        }
        Console.WriteLine("\n  ※ 정통=미래라벨 호라이즌4, 1x. 10x는 같은 전략이라도 MDD가 10배→청산 위험 확인용.");

        // ===== jdehorty 필터 스택 추가 (나다라야-왓슨 커널 + ADX 레짐) → 거래수 급감 재현 =====
        Console.WriteLine("\n=== + jdehorty 필터(NW커널 확인 + ADX레짐) : 진짜 jdehorty 재현 ===");
        // 나다라야-왓슨 rational quadratic 커널 (h=8, r=8)
        var yhat = new double[n];
        { int h = 8; double r = 8; for (int j = 25; j < n; j++) { double num = 0, den = 0; int kmax = Math.Min(j, 100); for (int kk = 0; kk <= kmax; kk++) { double w = Math.Pow(1 + (kk * kk) / (2.0 * r * h * h), -r); num += (double)kl[j - kk].ClosePrice * w; den += w; } yhat[j] = num / den; } }
        // ADX(14)
        var adx = new double[n];
        { double atrS = 0, pdmS = 0, mdmS = 0; int per = 14; for (int j = 1; j < n; j++) { double hh = (double)kl[j].HighPrice, ll = (double)kl[j].LowPrice, pc = (double)kl[j - 1].ClosePrice, ph = (double)kl[j - 1].HighPrice, pl = (double)kl[j - 1].LowPrice; double tr = Math.Max(hh - ll, Math.Max(Math.Abs(hh - pc), Math.Abs(ll - pc))); double up = hh - ph, dn = pl - ll; double pdm = (up > dn && up > 0) ? up : 0, mdm = (dn > up && dn > 0) ? dn : 0; if (j <= per) { atrS += tr; pdmS += pdm; mdmS += mdm; } else { atrS = atrS - atrS / per + tr; pdmS = pdmS - pdmS / per + pdm; mdmS = mdmS - mdmS / per + mdm; } if (j >= per && atrS > 0) { double pd = 100 * pdmS / atrS, md = 100 * mdmS / atrS; double dx = (pd + md) > 0 ? 100 * Math.Abs(pd - md) / (pd + md) : 0; adx[j] = j <= per * 2 ? dx : (adx[j - 1] * (per - 1) + dx) / per; } } }
        Console.WriteLine($"  {"라벨",8} {"필터",14} {"레버",5} {"거래",5} {"승률%",6} {"손익비PF",8} {"MDD%",7} {"누적수익%",10}");
        foreach (int Lh in new[] { 4, 8 })
        foreach (bool forward in new[] { true, false })
        {
            var engine = new LorentzianAnnEngine("BTCUSDT", neighborsCount: K, maxBarsBack: 2000, featureCount: LorentzianFeatures.FeatureCount);
            var sg = new int[n];
            for (int j = 65; j < n; j++)
            {
                if (forward) { int s = j - Lh - 1; if (s >= 8 && feats[s] != null) { decimal a = kl[s + Lh].ClosePrice, b = kl[s].ClosePrice; engine.AddSample(feats[s], a > b ? 1 : (a < b ? -1 : 0)); } }
                else { int s = j - 1; if (s - Lh >= 0 && feats[s] != null) { decimal a = kl[s].ClosePrice, b = kl[s - Lh].ClosePrice; engine.AddSample(feats[s], a > b ? 1 : (a < b ? -1 : 0)); } }
                if (feats[j] == null) continue; var p = engine.Predict(feats[j]); if (!p.IsReady || p.K == 0) continue; sg[j] = p.Prediction > 0 ? 1 : (p.Prediction < 0 ? -1 : 0);
            }
            foreach (var (fname, useKernel, useAdx) in new[] { ("커널만", true, false), ("커널+ADX25", true, true) })
            foreach (decimal lev in new[] { 1m, 10m })
            {
                int pos = 0; decimal entryPx = 0m; decimal equity = 1m, peak = 1m, mdd = 0m; int trades = 0, wins = 0; decimal gW = 0m, gL = 0m; bool blown = false;
                for (int j = 250; j < n; j++)
                {
                    int rawSig = sg[j]; decimal c = kl[j].ClosePrice;
                    // jdehorty 필터: 커널 방향 확인 + ADX 레짐(추세장만)
                    bool kb = yhat[j] > yhat[j - 1];  // 커널 상승
                    bool adxOk = !useAdx || adx[j] >= 25;
                    int sig = 0;
                    if (rawSig > 0 && (!useKernel || kb) && adxOk) sig = 1;
                    else if (rawSig < 0 && (!useKernel || !kb) && adxOk) sig = -1;
                    if (sig != 0 && sig != pos)
                    {
                        if (pos != 0 && entryPx > 0)
                        {
                            decimal ret = pos * (c - entryPx) / entryPx - feeRT; decimal pnl = ret * lev; equity *= (1m + pnl);
                            if (equity <= 0m) { blown = true; equity = 0m; }
                            trades++; if (pnl > 0) { wins++; gW += pnl; } else gL += -pnl;
                            if (equity > peak) peak = equity; decimal dd = peak > 0 ? (peak - equity) / peak : 0m; if (dd > mdd) mdd = dd;
                        }
                        if (blown) break;
                        pos = sig; entryPx = c;
                    }
                }
                double pf = gL > 0 ? (double)(gW / gL) : 0;
                string lab = forward ? $"미래{Lh}" : $"과거{Lh}";
                string net = blown ? "청산(-100%)" : $"{(equity - 1m) * 100m:F1}%";
                Console.WriteLine($"  {lab,8} {fname,14} {lev,4:F0}x {trades,5} {(trades > 0 ? 100.0 * wins / trades : 0),6:F1} {pf,8:F2} {mdd * 100m,6:F1} {net,10}");
            }
        }

        // ===== 제미나이 핵심 주장 재현: 2% 리스크 룰 + ATR -2% 손절 + 지정가, 시드 $10,000 =====
        Console.WriteLine("\n=== 제미나이 정밀재현: 2% 리스크사이징 + ATR손절 + 커널+ADX 필터 (시드 $10,000) ===");
        var atr14 = new double[n];
        for (int j = 14; j < n; j++) { double tr = 0; for (int q = j - 13; q <= j; q++) { double h = (double)kl[q].HighPrice, l = (double)kl[q].LowPrice, pc = (double)kl[q - 1].ClosePrice; tr += Math.Max(h - l, Math.Max(Math.Abs(h - pc), Math.Abs(l - pc))); } atr14[j] = tr / 14.0; }
        Console.WriteLine($"  {"라벨",8} {"거래",5} {"승률%",6} {"손익비PF",8} {"MDD%",7} {"최종잔고$",11} {"수익률%",9}");
        foreach (int Lh in new[] { 4, 8 })
        {
            var engine = new LorentzianAnnEngine("BTCUSDT", neighborsCount: K, maxBarsBack: 2000, featureCount: LorentzianFeatures.FeatureCount);
            var sg = new int[n];
            for (int j = 65; j < n; j++) { int s = j - 1; if (s - Lh >= 0 && feats[s] != null) { decimal a = kl[s].ClosePrice, b = kl[s - Lh].ClosePrice; engine.AddSample(feats[s], a > b ? 1 : (a < b ? -1 : 0)); } if (feats[j] == null) continue; var p = engine.Predict(feats[j]); if (!p.IsReady || p.K == 0) continue; sg[j] = p.Prediction > 0 ? 1 : (p.Prediction < 0 ? -1 : 0); }
            decimal equity = 10000m, peak = 10000m, mdd = 0m; int pos = 0; decimal entryPx = 0m, stopPx = 0m, notional = 0m; int trades = 0, wins = 0; decimal gW = 0m, gL = 0m;
            for (int j = 250; j < n; j++)
            {
                decimal c = kl[j].ClosePrice; bool kb = yhat[j] > yhat[j - 1]; bool adxOk = adx[j] >= 25;
                // 보유 중 ATR 손절 체크 (롱만: 저가<=손절 / 숏: 고가>=손절)
                if (pos != 0)
                {
                    bool stopHit = pos > 0 ? (double)kl[j].LowPrice <= (double)stopPx : (double)kl[j].HighPrice >= (double)stopPx;
                    int rawSig2 = sg[j]; bool flip = rawSig2 != 0 && rawSig2 != pos && ((rawSig2 > 0 && kb) || (rawSig2 < 0 && !kb)) && adxOk;
                    if (stopHit || flip)
                    {
                        decimal exitPx = stopHit ? stopPx : c;
                        decimal ret = pos * (exitPx - entryPx) / entryPx; decimal pnl = ret * notional - feeRT * notional;
                        equity += pnl; trades++; if (pnl > 0) { wins++; gW += pnl; } else gL += -pnl;
                        if (equity > peak) peak = equity; decimal dd = peak > 0 ? (peak - equity) / peak : 0m; if (dd > mdd) mdd = dd;
                        pos = 0;
                        if (equity <= 0) break;
                    }
                }
                // 신규 진입 (2% 리스크 사이징)
                if (pos == 0 && adxOk && atr14[j] > 0)
                {
                    int rawSig = sg[j]; int sig = (rawSig > 0 && kb) ? 1 : (rawSig < 0 && !kb) ? -1 : 0;
                    if (sig != 0)
                    {
                        double stopDist = 1.5 * atr14[j];                    // ATR 기반 손절폭(≈-2%)
                        decimal stopPct = (decimal)(stopDist / (double)c);
                        if (stopPct > 0.001m)
                        {
                            decimal riskAmt = equity * 0.02m;                 // 시드 2% 리스크
                            notional = riskAmt / stopPct;                     // 손절 시 딱 2% 잃도록 역산
                            decimal maxNotional = equity * 10m;               // 10배 상한
                            if (notional > maxNotional) notional = maxNotional;
                            pos = sig; entryPx = c; stopPx = sig > 0 ? c - (decimal)stopDist : c + (decimal)stopDist;
                        }
                    }
                }
            }
            double pf = gL > 0 ? (double)(gW / gL) : 0;
            Console.WriteLine($"  과거{Lh,-6} {trades,5} {(trades > 0 ? 100.0 * wins / trades : 0),6:F1} {pf,8:F2} {mdd * 100m,6:F1} {equity,11:F0} {(equity / 10000m - 1m) * 100m,9:F1}");
        }
        Console.WriteLine("\n  ★ 2% 리스크룰은 손절폭이 2%면 실효레버리지≈1x. 사이징은 이기는전략(PF>1) 위험관리용 — PF<1은 사이징으로도 적자.");

        // ===== 롱 전용 + 추세타기(상승장 먹기) : 봇 규칙(롱전용) 준수 + 숏 제거 =====
        Console.WriteLine("\n=== 롱 전용 + 추세타기 : 숏 제거, 상승트렌드 홀딩 (존버 156.4% 대비) ===");
        var e50 = new double[n]; for (int j = 50; j < n; j++) e50[j] = CalcEMA(kl, j, 50);
        var e200b = new double[n]; for (int j = 200; j < n; j++) e200b[j] = CalcEMA(kl, j, 200);
        Console.WriteLine($"  {"라벨",6} {"진입조건",16} {"청산조건",16} {"레버",5} {"거래",5} {"승률%",6} {"PF",5} {"MDD%",7} {"누적수익%",9}");
        foreach (int Lh in new[] { 4, 8 })
        {
            var engine = new LorentzianAnnEngine("BTCUSDT", neighborsCount: K, maxBarsBack: 2000, featureCount: LorentzianFeatures.FeatureCount);
            var sg = new int[n];
            for (int j = 65; j < n; j++) { int s = j - 1; if (s - Lh >= 0 && feats[s] != null) { decimal a = kl[s].ClosePrice, b = kl[s - Lh].ClosePrice; engine.AddSample(feats[s], a > b ? 1 : (a < b ? -1 : 0)); } if (feats[j] == null) continue; var p = engine.Predict(feats[j]); if (!p.IsReady || p.K == 0) continue; sg[j] = p.Prediction > 0 ? 1 : (p.Prediction < 0 ? -1 : 0); }
            // 진입/청산 변형
            var variants = new (string ename, string xname, Func<int, bool> enter, Func<int, bool> exit)[] {
                ("KNN+커널", "KNN약세", j => sg[j] > 0 && yhat[j] > yhat[j - 1], j => sg[j] < 0),
                ("KNN+커널+ADX", "커널꺾임", j => sg[j] > 0 && yhat[j] > yhat[j - 1] && adx[j] >= 20, j => yhat[j] < yhat[j - 1] && yhat[j-1] < yhat[j-2]),
                ("KNN+커널+EMA200", "EMA50이탈", j => sg[j] > 0 && yhat[j] > yhat[j - 1] && e200b[j] > 0 && (double)kl[j].ClosePrice > e200b[j], j => e50[j] > 0 && (double)kl[j].ClosePrice < e50[j]),
                ("KNN+EMA정배열", "KNN약세", j => sg[j] > 0 && e50[j] > 0 && e200b[j] > 0 && e50[j] > e200b[j] && (double)kl[j].ClosePrice > e50[j], j => sg[j] < 0),
            };
            foreach (var v in variants)
            foreach (decimal lev in new[] { 1m, 3m })
            {
                int pos = 0; decimal entryPx = 0m; decimal equity = 1m, peak = 1m, mdd = 0m; int trades = 0, wins = 0; decimal gW = 0m, gL = 0m; bool blown = false;
                for (int j = 250; j < n; j++)
                {
                    decimal c = kl[j].ClosePrice;
                    if (pos == 0) { if (v.enter(j)) { pos = 1; entryPx = c; } }
                    else if (v.exit(j)) { decimal ret = (c - entryPx) / entryPx - feeRT; decimal pnl = ret * lev; equity *= (1m + pnl); if (equity <= 0) { blown = true; break; } trades++; if (pnl > 0) { wins++; gW += pnl; } else gL += -pnl; if (equity > peak) peak = equity; decimal dd = (peak - equity) / peak; if (dd > mdd) mdd = dd; pos = 0; } }
                double pf = gL > 0 ? (double)(gW / gL) : (gW > 0 ? 99 : 0);
                string net = blown ? "청산" : $"{(equity - 1m) * 100m:F1}%";
                Console.WriteLine($"  과거{Lh,-4} {v.ename,16} {v.xname,16} {lev,4:F0}x {trades,5} {(trades > 0 ? 100.0 * wins / trades : 0),6:F1} {pf,5:F2} {mdd * 100m,6:F1} {net,9}");
            }
        }
        Console.WriteLine("\n  ★ 롱전용 추세타기가 존버(156%)를 이기고 MDD 낮으면 = 진짜 엣지. PF>1 + 존버초과가 목표.");
    }

    // --smc-inflection : [변곡매매] 스윙저점 변곡점에서 반등 진입 + 라이브식 청산(본절→부분익절40%→트레일링) +
    //                    큰손실 케이스 저장→자동 진단(왜 진입이 틀렸나). 손절=변곡저점 바로아래(타이트=R/R우수). 롱전용.
    private static async Task RunSmcInflectionAsync()
    {
        const int featureWindow = 500, maxHold = 96, K = 8, L = 8, pages1h = 20, piv = 3;
        const decimal cost = 0.0004m * 2m + 0.0005m;
        decimal lev = 10m, margin = 500m; int maxSlots = 6; decimal capital = margin * maxSlots;
        double maxRiskPct = 0.035;   // 변곡저점이 너무 멀면(위험>3.5%) 스킵 — R/R 확보
        var universe = new[] {
            "BTCUSDT","ETHUSDT","BNBUSDT","SOLUSDT","XRPUSDT","DOGEUSDT","ADAUSDT","TRXUSDT","AVAXUSDT","LINKUSDT",
            "DOTUSDT","LTCUSDT","BCHUSDT","ATOMUSDT","UNIUSDT","NEARUSDT","APTUSDT","ARBUSDT","OPUSDT","SUIUSDT" };
        Console.WriteLine($"=== 변곡매매(스윙저점 반등) + 라이브식청산(본절·부분익절·트레일링) + 손실진단 (롱전용·20종·3.4년) ===\n");
        var symData = new List<(string sym, List<IBinanceKline> kl, int[] sg, double[] atr, double[] e20, double[] e50, double[] e200)>();
        int idx = 0;
        foreach (var sym in universe)
        {
            idx++; Console.Write($"[{idx}/{universe.Length}] {sym} ");
            List<IBinanceKline> kl;
            try { kl = await FetchKlines1hAsync(sym, pages1h); } catch { Console.WriteLine("fail"); continue; }
            if (kl.Count < 500) { Console.WriteLine("skip"); continue; }
            int n = kl.Count; Console.WriteLine($"1h={n}");
            var feats = new float[n][];
            for (int j = 60; j < n; j++) { int ws = Math.Max(0, j - (featureWindow - 1)); feats[j] = LorentzianFeatures.Extract(kl.GetRange(ws, j - ws + 1))!; }
            var atr = new double[n]; var e20 = new double[n]; var e50 = new double[n]; var e200 = new double[n];
            for (int j = 14; j < n; j++) { double tr = 0; for (int q = j - 13; q <= j; q++) { double h = (double)kl[q].HighPrice, l = (double)kl[q].LowPrice, pc = (double)kl[q - 1].ClosePrice; tr += Math.Max(h - l, Math.Max(Math.Abs(h - pc), Math.Abs(l - pc))); } atr[j] = tr / 14.0; }
            for (int j = 20; j < n; j++) e20[j] = CalcEMA(kl, j, 20);
            for (int j = 50; j < n; j++) e50[j] = CalcEMA(kl, j, 50);
            for (int j = 200; j < n; j++) e200[j] = CalcEMA(kl, j, 200);
            var engine = new LorentzianAnnEngine(sym, neighborsCount: K, maxBarsBack: 2000, featureCount: LorentzianFeatures.FeatureCount);
            var sg = new int[n];
            for (int j = 65; j < n; j++) { int s = j - 1; if (s - L >= 0 && feats[s] != null) { decimal a = kl[s].ClosePrice, b = kl[s - L].ClosePrice; engine.AddSample(feats[s], a > b ? 1 : (a < b ? -1 : 0)); } if (feats[j] == null) continue; var p = engine.Predict(feats[j]); if (!p.IsReady || p.K == 0) continue; sg[j] = p.Prediction > 0 ? 1 : (p.Prediction < 0 ? -1 : 0); }
            symData.Add((sym, kl, sg, atr, e20, e50, e200));
        }
        Console.WriteLine();

        // 변곡 진입 1건의 라이브식 청산 시뮬 → (net수익률, 청산사유, 진단태그, 홀딩봉수, R배수도달)
        // 청산 파라미터(스윕용 클로저 변수) — 손익비 튜닝
        decimal exPartialR = 1.0m, exPartialFrac = 0.4m; double exTrailStartR = 2.0, exTrailMult = 1.0;
        (decimal net, string exitKind, string diag, int hold, double rMax) SimTrade(List<IBinanceKline> kl, double[] atr, int[] sg, int j, int slBar, int n)
        {
            decimal entry = kl[j + 1].OpenPrice;
            decimal slInit = (decimal)((double)kl[slBar].LowPrice * 0.999); // 변곡저점 -0.1%
            decimal risk = entry - slInit;
            decimal sl = slInit, peak = entry; bool be = false, partial = false; decimal realized = 0m; decimal remain = 1m;
            decimal net = 0m; string exitKind = "MAXHOLD"; int ei = Math.Min(n - 1, j + maxHold); double rMax = 0;
            for (int e = j + 1; e < n && e <= j + maxHold; e++)
            {
                decimal h = kl[e].HighPrice, lo = kl[e].LowPrice, c = kl[e].ClosePrice;
                if (h > peak) peak = h;
                double rNow = risk > 0 ? (double)((peak - entry) / risk) : 0; if (rNow > rMax) rMax = rNow;
                // 부분익절: +exPartialR R 도달 시 exPartialFrac 실현 + 나머지 본절이동
                if (!partial && exPartialFrac > 0m && risk > 0 && h >= entry + exPartialR * risk) { realized += exPartialFrac * (exPartialR * risk / entry); remain = 1m - exPartialFrac; partial = true; be = true; sl = entry > sl ? entry : sl; }
                // 본절: +0.6R 도달만 해도 손절 진입가로(작은 이익 보호)
                if (!be && risk > 0 && h >= entry + risk * 0.6m) { be = true; sl = entry > sl ? entry : sl; }
                // 트레일링: +exTrailStartR R 이후 peak-exTrailMult*ATR 추적
                if (risk > 0 && peak >= entry + (decimal)exTrailStartR * risk && atr[e] > 0) { decimal t = peak - (decimal)(exTrailMult * atr[e]); if (t > sl) sl = t; }
                // 손절/트레일 히트
                if (lo <= sl) { decimal exitPx = sl; net = realized + remain * ((exitPx - entry) / entry) - cost * (partial ? 1.2m : 1m); ei = e; exitKind = be ? (partial ? "TRAIL/BE(부분후)" : "BREAKEVEN") : "SL(변곡이탈)"; break; }
                // 시간정지(반전신호)
                if (sg[e] == -1) { net = realized + remain * ((c - entry) / entry) - cost * (partial ? 1.2m : 1m); ei = e; exitKind = "KNN반전"; break; }
                if (e == j + maxHold || e == n - 1) { net = realized + remain * ((c - entry) / entry) - cost * (partial ? 1.2m : 1m); ei = e; exitKind = "MAXHOLD"; break; }
            }
            // 손실 진단 태그
            string diag = "";
            int hold = ei - j;
            if (net < 0)
            {
                if (hold <= 2 && rMax < 0.5) diag = "즉시역행(변곡실패-계속하락)";
                else if (rMax >= 1.0) diag = "본절/부분후 반전-되돌림";
                else if (rMax < 0.6) diag = "추세미형성-슬로우블리드";
                else diag = "중간반전";
            }
            return (net, exitKind, diag, hold, rMax);
        }

        Console.WriteLine($"  {"청산방식",-34} {"진입",5} {"승률%",6} {"총손익$",10} {"월평균%",7} {"이익$",6} {"손실$",7} {"R/R",5}");
        var worstAll = new List<(string sym, DateTime ent, decimal pnlUsd, string exitKind, string diag, double rMax, int hold, int j, int slBar, List<IBinanceKline> kl, double[] e20)>();
        var diagCount = new Dictionary<string, (int n, decimal pnl)>();
        // 조건: 변곡 + (추세컨텍스트) + (KNN)
        // 고정 진입 = 변곡+추세+KNN+EMA20탈환(=최선). 청산(손익비) 파라미터를 스윕.
        const bool useTrend = true, useKnn = true, useEma20Zone = false, useReclaim = true;
        var exitCfgs = new (string name, decimal pR, decimal pFrac, double tStartR, double tMult)[] {
            ("현행(40%@1R·트레일2R·1ATR)", 1.0m, 0.4m, 2.0, 1.0),
            ("승자태움(부분없음·트레일1.5R·2.5ATR)", 1.0m, 0.0m, 1.5, 2.5),
            ("승자태움(20%@2R·트레일2R·2.5ATR)", 2.0m, 0.2m, 2.0, 2.5),
            ("승자태움(부분없음·트레일1R·3ATR)", 1.0m, 0.0m, 1.0, 3.0),
            ("절충(30%@2R·트레일2R·2ATR)", 2.0m, 0.3m, 2.0, 2.0),
        };
        foreach (var (name, pR, pFrac, tStartR, tMult) in exitCfgs)
        {
            exPartialR = pR; exPartialFrac = pFrac; exTrailStartR = tStartR; exTrailMult = tMult;
            var cands = new List<(DateTime ent, DateTime ex, decimal pnl, string exitKind, string diag, double rMax, int hold, int j, int slBar, string sym, List<IBinanceKline> kl, double[] e20)>();
            foreach (var (sym, kl, sg, atr, e20, e50, e200) in symData)
            {
                int n = kl.Count; int busy = -1;
                for (int j = 250; j < n - 1; j++)
                {
                    if (j <= busy) continue;
                    // 스윙저점 변곡: sl2 = j-piv 가 pivot low 로 확정 + 현재봉 반등확인
                    int sl2 = j - piv;
                    if (sl2 - piv < 0) continue;
                    bool isLow = true; double ll = (double)kl[sl2].LowPrice;
                    for (int q = sl2 - piv; q <= sl2 + piv; q++) { if (q == sl2) continue; if ((double)kl[q].LowPrice <= ll) { isLow = false; break; } }
                    if (!isLow) continue;
                    // 반등확인: 현재봉 양봉 + 종가가 변곡저점 위 유지 + 고가 갱신 시도
                    double c = (double)kl[j].ClosePrice, o = (double)kl[j].OpenPrice;
                    if (!(c > o && c > (double)kl[sl2].HighPrice * 0.999)) continue;
                    // 추세 컨텍스트: 종가 > EMA200 (더 큰 상승장 내 눌림 반등 = 칼날회피)
                    if (useTrend && !(e200[j] > 0 && c > e200[j] && e50[j] > 0 && e20[j] > e50[j])) continue;
                    // EMA20 눌림존: 변곡저점이 EMA20 근처/아래(진짜 눌림)
                    if (useEma20Zone && !(e20[j] > 0 && (double)kl[sl2].LowPrice <= e20[j] * 1.005)) continue;
                    // EMA20 탈환: 반등봉 종가가 EMA20 위 마감(데드캣 배제 — 진짜 반전은 단기평균 회복)
                    if (useReclaim && !(e20[j] > 0 && c > e20[j])) continue;
                    // KNN 매수
                    if (useKnn && sg[j] != 1) continue;
                    if (kl[j + 1].OpenPrice <= 0 || atr[j] <= 0) continue;
                    decimal entry = kl[j + 1].OpenPrice; decimal slInit = (decimal)((double)kl[sl2].LowPrice * 0.999);
                    if (slInit >= entry) continue; double riskPct = (double)((entry - slInit) / entry);
                    if (riskPct > maxRiskPct || riskPct < 0.002) continue; // 너무 넓거나 너무 좁은 변곡 제외
                    var r = SimTrade(kl, atr, sg, j, sl2, n);
                    int ei = Math.Min(n - 1, j + r.hold); busy = ei;
                    cands.Add((kl[j + 1].OpenTime, kl[ei].OpenTime, r.net * margin * lev, r.exitKind, r.diag, r.rMax, r.hold, j, sl2, sym, kl, e20));
                }
            }
            cands.Sort((a, b) => a.ent.CompareTo(b.ent));
            var open = new List<DateTime>(); int tn = 0, tw = 0; decimal tp = 0m, winSum = 0m, lossSum = 0m; var mset = new HashSet<string>();
            var taken = new List<(DateTime ent, decimal pnl, string exitKind, string diag, double rMax, int hold, int j, int slBar, string sym, List<IBinanceKline> kl, double[] e20)>();
            foreach (var t in cands) { open.RemoveAll(x => x <= t.ent); if (open.Count >= maxSlots) continue; open.Add(t.ex); tn++; if (t.pnl > 0) { tw++; winSum += t.pnl; } else lossSum += t.pnl; tp += t.pnl; mset.Add(t.ent.ToString("yyyy-MM")); taken.Add((t.ent, t.pnl, t.exitKind, t.diag, t.rMax, t.hold, t.j, t.slBar, t.sym, t.kl, t.e20)); }
            if (tn == 0) { Console.WriteLine($"  {name,20} 진입 0"); continue; }
            double mo = (double)(tp / capital * 100m) / Math.Max(1, mset.Count);
            decimal avgW = tw > 0 ? winSum / tw : 0m, avgL = (tn - tw) > 0 ? lossSum / (tn - tw) : 0m;
            Console.WriteLine($"  {name,-34} {tn,5} {100.0 * tw / tn,6:F1} {tp,10:F0} {mo,7:F2} {avgW,6:F1} {avgL,7:F1} {(avgL != 0 ? (double)(avgW / -avgL) : 0),5:F2}");
            // 손실 진단 집계 + 최악 저장 (현행 청산 기준)
            if (name.StartsWith("현행"))
            {
                foreach (var t in taken)
                {
                    if (t.pnl < 0) { var key = t.diag == "" ? "기타" : t.diag; var cur = diagCount.TryGetValue(key, out var v) ? v : (0, 0m); diagCount[key] = (cur.Item1 + 1, cur.Item2 + t.pnl); }
                }
                worstAll = taken.Where(t => t.pnl < 0).OrderBy(t => t.pnl).Take(12)
                    .Select(t => (t.sym, t.ent, t.pnl, t.exitKind, t.diag, t.rMax, t.hold, t.j, t.slBar, t.kl, t.e20)).ToList();
            }
        }
        // 손실 진단 요약
        Console.WriteLine($"\n── [변곡+추세+KNN+EMA20눌림] 손실 원인 자동진단 ──");
        foreach (var kv in diagCount.OrderBy(x => x.Value.pnl))
            Console.WriteLine($"   {kv.Key,-28} {kv.Value.n,4}건  손익합 ${kv.Value.pnl,9:F0}");
        // 최악 12건 구조 저장
        var sb = new System.Text.StringBuilder(); var inv = System.Globalization.CultureInfo.InvariantCulture; sb.Append('[');
        for (int i = 0; i < worstAll.Count; i++)
        {
            var w = worstAll[i]; if (i > 0) sb.Append(','); int j = w.j; var kl = w.kl;
            sb.Append('{');
            sb.Append($"\"sym\":\"{w.sym}\",\"pnl\":{w.pnlUsd.ToString("F1", inv)},\"exit\":\"{w.exitKind}\",\"diag\":\"{w.diag}\",\"rMax\":{w.rMax.ToString("F2", inv)},\"hold\":{w.hold},");
            sb.Append("\"bars\":[");
            int a = Math.Max(0, j - 20), b = Math.Min(kl.Count - 1, j + w.hold + 2);
            for (int q = a; q <= b; q++) { if (q > a) sb.Append(','); var k = kl[q]; double em = w.e20[q]; sb.Append($"[{k.OpenPrice.ToString(inv)},{k.HighPrice.ToString(inv)},{k.LowPrice.ToString(inv)},{k.ClosePrice.ToString(inv)},{em.ToString("F6", inv)},{(q == j + 1 ? 1 : q == w.slBar ? 2 : 0)}]"); }
            sb.Append("]}");
        }
        sb.Append(']');
        System.IO.File.WriteAllText("smc-inflection-worst.json", sb.ToString());
        Console.WriteLine($"\n→ 최악 {worstAll.Count}건 구조 저장: smc-inflection-worst.json (진단태그 포함)");
    }

    // --knn-worst-mtf : 완전스펙 최대손실 10건 → 각 건 5m·15m·1h + 볼린저밴드 → JSON.
    private static string TfJson(List<IBinanceKline> kl, DateTime entT, DateTime exT, System.Globalization.CultureInfo inv)
    {
        int n = kl.Count; var U = new double[n]; var M = new double[n]; var Lo = new double[n];
        for (int i = 19; i < n; i++) { double s = 0; for (int q = i - 19; q <= i; q++) s += (double)kl[q].ClosePrice; double mean = s / 20; double sd = 0; for (int q = i - 19; q <= i; q++) { double d = (double)kl[q].ClosePrice - mean; sd += d * d; } sd = Math.Sqrt(sd / 20); M[i] = mean; U[i] = mean + 2 * sd; Lo[i] = mean - 2 * sd; }
        int ent = 0; for (int i = 0; i < n; i++) { if (kl[i].OpenTime >= entT) { ent = i; break; } }
        int ex = n - 1; for (int i = ent; i < n; i++) { if (kl[i].OpenTime >= exT) { ex = i; break; } }
        int from = Math.Max(19, ent - 50), to = Math.Min(n - 1, ex + 8);
        var sb = new System.Text.StringBuilder(); sb.Append("{\"entIdx\":").Append(ent - from).Append(",\"exIdx\":").Append(ex - from).Append(",\"bars\":[");
        for (int b = from; b <= to; b++) { if (b > from) sb.Append(","); sb.Append("[").Append(((double)kl[b].OpenPrice).ToString("R", inv)).Append(",").Append(((double)kl[b].HighPrice).ToString("R", inv)).Append(",").Append(((double)kl[b].LowPrice).ToString("R", inv)).Append(",").Append(((double)kl[b].ClosePrice).ToString("R", inv)).Append(",").Append(U[b].ToString("R", inv)).Append(",").Append(M[b].ToString("R", inv)).Append(",").Append(Lo[b].ToString("R", inv)).Append("]"); }
        sb.Append("]}"); return sb.ToString();
    }
    private static async Task RunKnnWorstMtfAsync()
    {
        const int featureWindow = 500, maxHold = 96, K = 8, L = 8, pages1h = 20, pages5m = 40;
        const decimal cost = 0.0004m * 2m + 0.0005m, slPct = 0.03m;
        decimal lev = 10m, margin = 500m; int maxSlots = 6;
        var inv = System.Globalization.CultureInfo.InvariantCulture;
        var universe = new[] {
            "BTCUSDT","ETHUSDT","BNBUSDT","SOLUSDT","XRPUSDT","DOGEUSDT","ADAUSDT","TRXUSDT","AVAXUSDT","LINKUSDT",
            "DOTUSDT","LTCUSDT","BCHUSDT","ATOMUSDT","UNIUSDT","NEARUSDT","APTUSDT","ARBUSDT","OPUSDT","SUIUSDT" };
        Console.WriteLine("=== 완전스펙 최대손실 10건 → 5m/15m/1h + BB ===");
        var cands = new List<(string sym, DateTime ent, DateTime ex, decimal pnl, bool isShort)>();
        int idx = 0;
        foreach (var sym in universe)
        {
            idx++; Console.Write($"[{idx}/{universe.Length}] {sym} ");
            List<IBinanceKline> kl; List<IBinanceKline> k5;
            try { kl = await FetchKlines1hAsync(sym, pages1h); k5 = await FetchKlines5mWindowFullAsync(sym, pages5m); } catch { Console.WriteLine("fail"); continue; }
            if (kl.Count < 500 || k5.Count < 500) { Console.WriteLine("skip"); continue; }
            int n = kl.Count; Console.WriteLine($"1h={n}");
            var feats = new float[n][];
            for (int j = 60; j < n; j++) { int ws = Math.Max(0, j - (featureWindow - 1)); feats[j] = LorentzianFeatures.Extract(kl.GetRange(ws, j - ws + 1))!; }
            var labels = new int[n];
            for (int j = L; j < n; j++) { decimal nc = kl[j].ClosePrice, pc = kl[j - L].ClosePrice; labels[j] = nc > pc ? 1 : (nc < pc ? -1 : 0); }
            var ema20 = new double[n]; for (int j = 20; j < n; j++) ema20[j] = CalcEMA(kl, j, 20);
            var engine = new LorentzianAnnEngine(sym, neighborsCount: K, maxBarsBack: 2000, featureCount: LorentzianFeatures.FeatureCount);
            var sg = new int[n];
            for (int j = 65; j < n; j++) { int s = j - 5; if (feats[s] != null) engine.AddSample(feats[s], labels[s]); if (feats[j] == null) continue; var p = engine.Predict(feats[j]); if (!p.IsReady || p.K == 0) continue; sg[j] = p.Prediction > 0 ? 1 : (p.Prediction < 0 ? -1 : 0); }
            int p5 = 0; double Slope5At(DateTime t) { while (p5 + 1 < k5.Count && k5[p5 + 1].OpenTime < t) p5++; if (p5 < 12) return 0; return (double)(k5[p5].ClosePrice - k5[p5 - 11].ClosePrice); }
            int busy = -1;
            for (int j = 250; j < n - 1; j++)
            {
                if (j <= busy) continue;
                double o = (double)kl[j].OpenPrice, c = (double)kl[j].ClosePrice, h = (double)kl[j].HighPrice, lo = (double)kl[j].LowPrice;
                double body = Math.Abs(c - o), upWick = h - Math.Max(o, c), dnWick = Math.Min(o, c) - lo;
                bool up1h = c > ema20[j] && j >= 6 && ema20[j] > ema20[j - 6];
                bool dn1h = c < ema20[j] && j >= 6 && ema20[j] < ema20[j - 6];
                bool isShort; if (sg[j] == 1 && up1h) isShort = false; else if (sg[j] == -1 && dn1h) isShort = true; else continue;
                if (!isShort) { if (c < o && (upWick + dnWick) > body) continue; } else { if (c > o && (upWick + dnWick) > body) continue; }
                double pc = (double)kl[j - 1].ClosePrice, po = (double)kl[j - 1].OpenPrice;
                if (!isShort) { if (pc < po) continue; } else { if (pc > po) continue; }
                if (!isShort) { double bt = Math.Max(o, c), mx = 0; for (int q = j - 5; q <= j - 1; q++) { double b2 = Math.Max((double)kl[q].OpenPrice, (double)kl[q].ClosePrice); if (b2 > mx) mx = b2; } if (bt < mx) continue; } else { double bb = Math.Min(o, c), mn = 1e18; for (int q = j - 5; q <= j - 1; q++) { double b2 = Math.Min((double)kl[q].OpenPrice, (double)kl[q].ClosePrice); if (b2 < mn) mn = b2; } if (bb > mn) continue; }
                double sl5 = Slope5At(kl[j + 1].OpenTime); if (!isShort) { if (sl5 <= 0) continue; } else { if (sl5 >= 0) continue; }
                if (kl[j + 1].OpenPrice <= 0) continue;
                decimal entry = kl[j + 1].OpenPrice; decimal net = 0m; bool done = false; int ei = Math.Min(n - 1, j + maxHold);
                if (!isShort) { decimal slPx = entry * (1m - slPct); for (int e = j + 1; e < n && e <= j + maxHold; e++) { if (kl[e].LowPrice <= slPx) { net = -slPct - cost; ei = e; done = true; break; } if (sg[e] == -1) { net = (kl[e].ClosePrice - entry) / entry - cost; ei = e; done = true; break; } } if (!done) net = (kl[ei].ClosePrice - entry) / entry - cost; }
                else { decimal slPx = entry * (1m + slPct); for (int e = j + 1; e < n && e <= j + maxHold; e++) { if (kl[e].HighPrice >= slPx) { net = -slPct - cost; ei = e; done = true; break; } if (sg[e] == 1) { net = (entry - kl[e].ClosePrice) / entry - cost; ei = e; done = true; break; } } if (!done) net = (entry - kl[ei].ClosePrice) / entry - cost; }
                busy = ei;
                cands.Add((sym, kl[j + 1].OpenTime, kl[ei].OpenTime, net * margin * lev, isShort));
            }
        }
        cands.Sort((a, b) => a.ent.CompareTo(b.ent));
        var open = new List<DateTime>(); var taken = new List<(string sym, DateTime ent, DateTime ex, decimal pnl, bool isShort)>();
        foreach (var c in cands) { open.RemoveAll(x => x <= c.ent); if (open.Count >= maxSlots) continue; open.Add(c.ex); taken.Add(c); }
        var worst = taken.OrderBy(t => t.pnl).Take(10).ToList();
        Console.WriteLine($"\n최대손실 10건 3TF+BB 페치...");
        var sb = new System.Text.StringBuilder(); sb.Append("[");
        for (int w = 0; w < worst.Count; w++)
        {
            var t = worst[w];
            long endMs1h = ((DateTimeOffset)t.ex.AddHours(12)).ToUnixTimeMilliseconds();
            long endMs15 = ((DateTimeOffset)t.ex.AddHours(6)).ToUnixTimeMilliseconds();
            long endMs5 = ((DateTimeOffset)t.ex.AddHours(3)).ToUnixTimeMilliseconds();
            var h1 = await FetchKlines1hPageAsync(t.sym, endMs1h, 130) ?? new List<IBinanceKline>();
            var m15 = await FetchKlines15mPageAsync(t.sym, endMs15, 160) ?? new List<IBinanceKline>();
            var m5 = await FetchKlines5mWindowAsync(t.sym, endMs5, 190);
            if (h1.Count < 25 || m15.Count < 25 || m5.Count < 25) continue;
            if (w > 0) sb.Append(",");
            sb.Append("{\"sym\":\"").Append(t.sym).Append("\",\"pnl\":").Append(t.pnl.ToString("F2", inv)).Append(",\"roe\":").Append(((double)t.pnl / (double)margin * 100).ToString("F0", inv))
              .Append(",\"dir\":\"").Append(t.isShort ? "SHORT" : "LONG").Append("\",\"entT\":\"").Append(t.ent.AddHours(9).ToString("MM-dd HH:mm")).Append("\"")
              .Append(",\"h1\":").Append(TfJson(h1, t.ent, t.ex, inv)).Append(",\"m15\":").Append(TfJson(m15, t.ent, t.ex, inv)).Append(",\"m5\":").Append(TfJson(m5, t.ent, t.ex, inv)).Append("}");
            Console.Write($" {t.sym}");
        }
        sb.Append("]");
        System.IO.File.WriteAllText("knn-worst-mtf.json", sb.ToString());
        Console.WriteLine($"\n→ knn-worst-mtf.json 작성 완료");
    }

    // [v5.22.72] Daily Swing + ProfitTrailing 3년 월별 통계
    private static async Task RunDailySwingMonthly3yAsync()
    {
        Console.WriteLine("================================================================");
        Console.WriteLine("  Daily Swing + ProfitTrailing 3년 월별 통계 (lev 20x)");
        Console.WriteLine("================================================================");

        const decimal seed = 400m;
        const decimal margin = 200m;
        const int maxSlots = 2;
        const decimal tpPct = 15m;
        const decimal slPct = 5m;
        const decimal slippagePct = 0.05m;
        const int maxHoldBars = 14;
        const decimal swingLeverage = 20m;
        const decimal trailingTriggerRoe = 3m;
        const decimal trailingMinRetrace = 5m;
        const decimal trailingRatio = 0.33m;

        var fullData = new Dictionary<string, List<IBinanceKline>>();
        Console.WriteLine($"\n[fetch 3년 1D — {symbols.Length}개 심볼]");
        int idx = 0;
        foreach (var sym in symbols)
        {
            idx++;
            Console.Write($"[{idx}/{symbols.Length}] {sym} ");
            try
            {
                var kl = await FetchKlines1dAsync(sym, 1);
                if (kl.Count < 60) { Console.WriteLine($"skip ({kl.Count})"); continue; }
                fullData[sym] = kl;
                Console.WriteLine($"ok ({kl.Count} bars)");
            }
            catch (Exception ex) { Console.WriteLine("fail: " + ex.Message); }
        }

        bool ShouldEnter(List<IBinanceKline> kl, int i)
        {
            if (i < 51) return false;
            decimal sma20 = 0m; for (int q = i - 19; q <= i; q++) sma20 += kl[q].ClosePrice; sma20 /= 20m;
            decimal sma50 = 0m; for (int q = i - 49; q <= i; q++) sma50 += kl[q].ClosePrice; sma50 /= 50m;
            if (kl[i].ClosePrice <= sma20) return false;
            if (sma20 <= sma50) return false;
            double rsi = CalcRsi14(kl, i);
            if (rsi < 50.0 || rsi > 70.0) return false;
            decimal volAvg = 0m; for (int q = i - 5; q <= i - 1; q++) volAvg += kl[q].Volume; volAvg /= 5m;
            if (volAvg <= 0m || kl[i].Volume < volAvg * 1.5m) return false;
            if (kl[i].ClosePrice <= kl[i].OpenPrice) return false;
            return true;
        }

        (string kind, decimal pctRaw, int holdBars) Outcome(List<IBinanceKline> kl, int i)
        {
            decimal entry = kl[i].ClosePrice;
            decimal tpPx = entry * (1 + tpPct / 100m);
            decimal slPx = entry * (1 - slPct / 100m);
            decimal highestRoe = 0m;
            for (int k = 1; k <= maxHoldBars && i + k < kl.Count; k++)
            {
                var b = kl[i + k];
                decimal highPriceRoe = (b.HighPrice - entry) / entry * 100m * swingLeverage;
                if (highPriceRoe > highestRoe) highestRoe = highPriceRoe;

                if (b.HighPrice >= tpPx && b.LowPrice <= slPx) return ("SL", -slPct, k);
                if (b.HighPrice >= tpPx) return ("TP", tpPct, k);
                if (b.LowPrice <= slPx) return ("SL", -slPct, k);

                if (highestRoe >= trailingTriggerRoe)
                {
                    decimal closeRoe = (b.ClosePrice - entry) / entry * 100m * swingLeverage;
                    decimal limit = Math.Max(trailingMinRetrace, highestRoe * trailingRatio);
                    if (highestRoe - closeRoe >= limit)
                    {
                        decimal exitPct = (b.ClosePrice - entry) / entry * 100m;
                        return ("TRAIL", exitPct, k);
                    }
                }
            }
            int idxClose = Math.Min(i + maxHoldBars, kl.Count - 1);
            decimal pctTo = (kl[idxClose].ClosePrice - entry) / entry * 100m;
            return (Math.Abs(pctTo) < 1m ? "BE" : "TIMEOUT", pctTo, maxHoldBars);
        }

        // 3년 시뮬
        DateTime since = DateTime.UtcNow.AddYears(-3);
        var candidates = new List<(DateTime time, string sym, int barIdx)>();
        foreach (var kv in fullData)
        {
            var kl = kv.Value; var sym = kv.Key;
            for (int i = 51; i < kl.Count - maxHoldBars; i++)
            {
                if (kl[i].OpenTime < since) continue;
                if (!ShouldEnter(kl, i)) continue;
                candidates.Add((kl[i].OpenTime, sym, i));
            }
        }
        candidates.Sort((a, b) => a.time.CompareTo(b.time));

        var active = new List<DateTime>();
        // 월별 집계: yyyy-MM → (n, tpN, slN, trailN, pnl)
        var monthly = new SortedDictionary<string, (int n, int tp, int sl, int trail, decimal pnl)>();
        decimal totalPnl = 0m;
        int totalN = 0, totalTp = 0, totalSl = 0, totalTrail = 0;

        foreach (var c in candidates)
        {
            active.RemoveAll(t => t <= c.time);
            if (active.Count >= maxSlots) continue;
            decimal notional = margin * swingLeverage;
            var (kind, pctRaw, hold) = Outcome(fullData[c.sym], c.barIdx);
            decimal pctNet = pctRaw - (decimal)(FEE_RATE * 2m * 100m) - (slippagePct * 2m);
            decimal pnlUsd = notional * pctNet / 100m;
            totalPnl += pnlUsd;
            totalN++;
            if (kind == "TP") totalTp++;
            else if (kind == "SL") totalSl++;
            else if (kind == "TRAIL") totalTrail++;

            string monthKey = c.time.ToString("yyyy-MM");
            if (!monthly.ContainsKey(monthKey)) monthly[monthKey] = (0, 0, 0, 0, 0m);
            var m = monthly[monthKey];
            m.n++;
            if (kind == "TP") m.tp++;
            else if (kind == "SL") m.sl++;
            else if (kind == "TRAIL") m.trail++;
            m.pnl += pnlUsd;
            monthly[monthKey] = m;

            int endBar = Math.Min(c.barIdx + hold, fullData[c.sym].Count - 1);
            active.Add(fullData[c.sym][endBar].OpenTime);
        }

        Console.WriteLine();
        Console.WriteLine($"  설정: 시드 ${seed} 마진 ${margin}×{maxSlots}슬롯×{swingLeverage}x | TP+{tpPct}% SL-{slPct}% / Trailing v5.22.68");
        Console.WriteLine();
        Console.WriteLine($"==== 월별 통계 (3년) ====");
        Console.WriteLine($"{"월",-9} {"진입",4} {"TP",3} {"SL",3} {"TRAIL",6} {"PnL($)",10} {"ROI(시드기준)",14}");
        Console.WriteLine(new string('-', 65));
        foreach (var kv in monthly)
        {
            decimal monthRoi = kv.Value.pnl / seed * 100m;
            Console.WriteLine($"{kv.Key,-9} {kv.Value.n,4} {kv.Value.tp,3} {kv.Value.sl,3} {kv.Value.trail,6} {kv.Value.pnl,9:F2} {monthRoi,12:F2}%");
        }
        Console.WriteLine(new string('-', 65));
        decimal totalRoi = totalPnl / seed * 100m;
        Console.WriteLine($"{"합계",-9} {totalN,4} {totalTp,3} {totalSl,3} {totalTrail,6} {totalPnl,9:F2} {totalRoi,12:F2}%");
        Console.WriteLine();
        // 월 통계
        var profitMonths = monthly.Values.Count(m => m.pnl > 0);
        var lossMonths = monthly.Values.Count(m => m.pnl < 0);
        Console.WriteLine($"수익 월 {profitMonths}개월 / 손실 월 {lossMonths}개월 / 중립 월 {monthly.Count - profitMonths - lossMonths}개월");
    }

    // [v5.22.72] Daily Swing + v5.22.68 ProfitTrailing 통합 백테스트
    //   사용자 의문: "SL ROE -40%인데 정말 흑자 가능?"
    //   Daily Swing 단독 백테스트(+330%)는 ProfitTrailing 미적용. 실 라이브 동작 시뮬 필요.
    //   진입: 1D close>20SMA + 20SMA>50SMA + RSI 50~70 + vol×1.5 + 양봉
    //   청산: TP+15% / SL-7% (price) / ProfitTrailing (highest>=+3% → retrace>=max(5,highest×33))
    //   leverage 5x 가정
    private static async Task RunDailySwingWithTrailingAsync()
    {
        Console.WriteLine("================================================================");
        Console.WriteLine("  Daily Swing + ProfitTrailing v5.22.68 통합 백테스트");
        Console.WriteLine("================================================================");

        const decimal seed = 400m;
        const decimal margin = 200m;
        const int maxSlots = 2;
        const decimal tpPct = 15m;        // 가격 +15%
        const decimal slPct = 5m;         // 가격 -5% (20x 레버리지 강제청산 부근, SL 우선)
        const decimal slippagePct = 0.05m;
        const int maxHoldBars = 14;       // 14일
        const decimal swingLeverage = 20m;   // 20x 사용자 환경
        const decimal trailingTriggerRoe = 3m;     // ROE +3% 이상 도달 시 활성
        const decimal trailingMinRetrace = 5m;     // 최소 retrace %p
        const decimal trailingRatio = 0.33m;       // highest × 33%

        var fullData = new Dictionary<string, List<IBinanceKline>>();
        Console.WriteLine($"\n[fetch — {symbols.Length}개 심볼 (1D)]");
        int idx = 0;
        foreach (var sym in symbols)
        {
            idx++;
            Console.Write($"[{idx}/{symbols.Length}] {sym} ");
            try
            {
                var kl = await FetchKlines1dAsync(sym, 1);
                if (kl.Count < 60) { Console.WriteLine($"skip ({kl.Count})"); continue; }
                fullData[sym] = kl;
                Console.WriteLine($"ok ({kl.Count} bars)");
            }
            catch (Exception ex) { Console.WriteLine("fail: " + ex.Message); }
        }

        bool ShouldEnter(List<IBinanceKline> kl, int i)
        {
            if (i < 51) return false;
            decimal sma20 = 0m; for (int q = i - 19; q <= i; q++) sma20 += kl[q].ClosePrice; sma20 /= 20m;
            decimal sma50 = 0m; for (int q = i - 49; q <= i; q++) sma50 += kl[q].ClosePrice; sma50 /= 50m;
            if (kl[i].ClosePrice <= sma20) return false;
            if (sma20 <= sma50) return false;
            double rsi = CalcRsi14(kl, i);
            if (rsi < 50.0 || rsi > 70.0) return false;
            decimal volAvg = 0m; for (int q = i - 5; q <= i - 1; q++) volAvg += kl[q].Volume; volAvg /= 5m;
            if (volAvg <= 0m || kl[i].Volume < volAvg * 1.5m) return false;
            if (kl[i].ClosePrice <= kl[i].OpenPrice) return false;
            return true;
        }

        // 시뮬: 매 봉 ROE 추적 + ProfitTrailing 적용
        // 라이브는 5분 tick 검사하지만 1D 봉만 있으므로 봉 내 high/low 로 근사
        (string kind, decimal pctRaw, int holdBars) Outcome(List<IBinanceKline> kl, int i)
        {
            decimal entry = kl[i].ClosePrice;
            decimal tpPx = entry * (1 + tpPct / 100m);
            decimal slPx = entry * (1 - slPct / 100m);
            decimal highestRoe = 0m;
            for (int k = 1; k <= maxHoldBars && i + k < kl.Count; k++)
            {
                var b = kl[i + k];
                // 봉 내 최고 가격 ROE
                decimal highPriceRoe = (b.HighPrice - entry) / entry * 100m * swingLeverage;
                decimal lowPriceRoe  = (b.LowPrice  - entry) / entry * 100m * swingLeverage;
                if (highPriceRoe > highestRoe) highestRoe = highPriceRoe;

                // TP/SL 도달 우선
                if (b.HighPrice >= tpPx && b.LowPrice <= slPx) return ("SL", -slPct, k);
                if (b.HighPrice >= tpPx) return ("TP", tpPct, k);
                if (b.LowPrice <= slPx) return ("SL", -slPct, k);

                // ProfitTrailing 시뮬: highest ROE 도달 후 봉 종가 ROE 가 trailing limit 넘게 retrace 시 청산
                //   봉 종가 기준 (라이브는 매 5분 tick 이므로 더 빠르게 트리거되지만 봉 종가로 근사)
                if (highestRoe >= trailingTriggerRoe)
                {
                    decimal closeRoe = (b.ClosePrice - entry) / entry * 100m * swingLeverage;
                    decimal limit = Math.Max(trailingMinRetrace, highestRoe * trailingRatio);
                    decimal retrace = highestRoe - closeRoe;
                    if (retrace >= limit)
                    {
                        decimal exitPct = (b.ClosePrice - entry) / entry * 100m;
                        return ("TRAIL", exitPct, k);
                    }
                }
            }
            int idxClose = Math.Min(i + maxHoldBars, kl.Count - 1);
            decimal pctTo = (kl[idxClose].ClosePrice - entry) / entry * 100m;
            return (Math.Abs(pctTo) < 1m ? "BE" : "TIMEOUT", pctTo, maxHoldBars);
        }

        (decimal pnl, int n, int tpN, int slN, int trailN, int beN, int toN, decimal mddPct) Eval(int days)
        {
            DateTime since = DateTime.UtcNow.AddDays(-days);
            decimal feeRate = FEE_RATE;
            var candidates = new List<(DateTime time, string sym, int barIdx)>();
            foreach (var kv in fullData)
            {
                var kl = kv.Value; var sym = kv.Key;
                for (int i = 51; i < kl.Count - maxHoldBars; i++)
                {
                    if (kl[i].OpenTime < since) continue;
                    if (!ShouldEnter(kl, i)) continue;
                    candidates.Add((kl[i].OpenTime, sym, i));
                }
            }
            candidates.Sort((a, b) => a.time.CompareTo(b.time));
            var active = new List<DateTime>();
            decimal totalPnl = 0m;
            int n = 0, tpN = 0, slN = 0, trailN = 0, beN = 0, toN = 0;
            var byDay = new SortedDictionary<DateTime, decimal>();
            foreach (var c in candidates)
            {
                active.RemoveAll(t => t <= c.time);
                if (active.Count >= maxSlots) continue;
                decimal notional = margin * swingLeverage;
                var (kind, pctRaw, hold) = Outcome(fullData[c.sym], c.barIdx);
                decimal pctNet = pctRaw - (decimal)(feeRate * 2m * 100m) - (slippagePct * 2m);
                decimal pnlUsd = notional * pctNet / 100m;
                totalPnl += pnlUsd;
                n++;
                if (kind == "TP") tpN++;
                else if (kind == "SL") slN++;
                else if (kind == "TRAIL") trailN++;
                else if (kind == "BE") beN++;
                else toN++;
                int endBar = Math.Min(c.barIdx + hold, fullData[c.sym].Count - 1);
                active.Add(fullData[c.sym][endBar].OpenTime);
                DateTime day = c.time.Date;
                byDay[day] = byDay.TryGetValue(day, out var v) ? v + pnlUsd : pnlUsd;
            }
            decimal cum = 0m, peak = 0m, mdd = 0m;
            foreach (var kv in byDay) { cum += kv.Value; if (cum > peak) peak = cum; decimal dd = peak - cum; if (dd > mdd) mdd = dd; }
            decimal mddPct = peak > 0 ? mdd / (seed + peak) * 100m : 0m;
            return (totalPnl, n, tpN, slN, trailN, beN, toN, mddPct);
        }

        Console.WriteLine();
        Console.WriteLine($"  TP+{tpPct}% SL-{slPct}% (price) / lev {swingLeverage}x");
        Console.WriteLine($"  ProfitTrailing: highest≥+{trailingTriggerRoe}% ROE 활성, retrace≥max({trailingMinRetrace}%, highest×{trailingRatio:P0}) → 청산");
        Console.WriteLine();
        Console.WriteLine($"{"기간",-7} {"진입",6} {"TP",5} {"SL",5} {"TRAIL",6} {"BE",5} {"TO",5} {"PnL",10} {"ROI",10} {"MDD%",8}");
        Console.WriteLine(new string('-', 90));
        int[] periods = { 30, 60, 90, 180, 365 };
        foreach (int days in periods)
        {
            var r = Eval(days);
            decimal roi = r.pnl / seed * 100m;
            Console.WriteLine($"{days,-7}일 {r.n,6} {r.tpN,5} {r.slN,5} {r.trailN,6} {r.beN,5} {r.toN,5} {r.pnl,9:F2} {roi,9:F2}% {r.mddPct,7:F2}%");
        }
        Console.WriteLine(new string('-', 90));
    }

    // [v5.22.72] Pullback Long 전략 백테스트 — 눌림목 진입
    //   1H EMA20 위 + 15m 직전 봉 BEAR + 현재 봉 BULL + Higher High + EMA20 ±1% + RSI 35~60 + vol×1.2
    //   180일 30심볼 시뮬
    private static async Task RunPullbackLongAsync()
    {
        Console.WriteLine("================================================================");
        Console.WriteLine("  v5.22.72 Pullback Long — 눌림목 진입 백테스트 (180일)");
        Console.WriteLine("================================================================");

        const decimal seed = 400m;
        const decimal margin = 100m;
        const int maxSlots = 3;
        const decimal tpPct = 2.0m;
        const decimal slPct = 1.5m;
        const decimal slippagePct = 0.05m;
        const int fetchPages = 12;
        const int maxHoldBars = 24;        // 6h max

        var fullData15m = new Dictionary<string, List<IBinanceKline>>();
        Console.WriteLine($"\n[fetch 180일 — {symbols.Length}개 심볼 (15m)]");
        int idx = 0;
        foreach (var sym in symbols)
        {
            idx++;
            Console.Write($"[{idx}/{symbols.Length}] {sym} ");
            try
            {
                var kl = await FetchKlines15mAsync(sym, fetchPages);
                if (kl.Count < 200) { Console.WriteLine("skip"); continue; }
                fullData15m[sym] = kl;
                Console.WriteLine($"ok ({kl.Count} bars)");
            }
            catch (Exception ex) { Console.WriteLine("fail: " + ex.Message); }
        }

        // 1H EMA20 = 15m EMA80 근사 (4배). 15m 봉 i 시점에서 80봉 EMA = 1H 20봉 EMA 근사
        bool ShouldEnter(List<IBinanceKline> kl, int i)
        {
            if (i < 85) return false;

            // 1. 1H EMA20 위 (15m 80봉 EMA 근사)
            decimal ema80 = Ema(kl, i, 80);
            if (kl[i].ClosePrice <= ema80) return false;

            // 2. 직전 봉 BEAR
            if (kl[i - 1].ClosePrice >= kl[i - 1].OpenPrice) return false;

            // 3. 현재 봉 BULL + 종가 > 직전 봉 high
            if (kl[i].ClosePrice <= kl[i].OpenPrice) return false;
            if (kl[i].ClosePrice <= kl[i - 1].HighPrice) return false;

            // 4. 15m EMA20 이격도 ≤ ±1%
            decimal ema20 = Ema(kl, i, 20);
            decimal dist = (kl[i].ClosePrice - ema20) / ema20 * 100m;
            if (dist > 1m || dist < -1m) return false;

            // 5. RSI 35~60
            double rsi = CalcRsi14(kl, i);
            if (rsi < 35.0 || rsi > 60.0) return false;

            // 6. 거래량 > 직전 5봉 평균 × 1.2
            decimal volAvg5 = 0m;
            for (int q = i - 5; q <= i - 1; q++) volAvg5 += kl[q].Volume;
            volAvg5 /= 5m;
            if (volAvg5 <= 0m || kl[i].Volume < volAvg5 * 1.2m) return false;

            return true;
        }

        (string kind, decimal pctRaw, int holdBars) Outcome(List<IBinanceKline> kl, int i)
        {
            decimal entry = kl[i].ClosePrice;
            decimal tpPx = entry * (1 + tpPct / 100m);
            decimal slPx = entry * (1 - slPct / 100m);
            for (int k = 1; k <= maxHoldBars && i + k < kl.Count; k++)
            {
                var b = kl[i + k];
                if (b.HighPrice >= tpPx && b.LowPrice <= slPx) return ("SL", -slPct, k);
                if (b.HighPrice >= tpPx) return ("TP", tpPct, k);
                if (b.LowPrice <= slPx) return ("SL", -slPct, k);
            }
            int idxClose = Math.Min(i + maxHoldBars, kl.Count - 1);
            decimal pctTo = (kl[idxClose].ClosePrice - entry) / entry * 100m;
            return (Math.Abs(pctTo) < 0.3m ? "BE" : "TIMEOUT", pctTo, maxHoldBars);
        }

        (decimal pnl, int n, int tpN, int slN, int beN, int toN, decimal mdd, decimal mddPct, decimal avgHold)
            Eval(int days)
        {
            DateTime since = DateTime.UtcNow.AddDays(-days);
            decimal feeRate = FEE_RATE;
            const int cooldownBars = 2;

            var candidates = new List<(DateTime time, string sym, int barIdx)>();
            foreach (var kv in fullData15m)
            {
                var kl = kv.Value; var sym = kv.Key;
                int lastFire = -1000;
                for (int i = 90; i < kl.Count - maxHoldBars; i++)
                {
                    if (kl[i].OpenTime < since) continue;
                    if (i - lastFire < cooldownBars) continue;
                    if (!ShouldEnter(kl, i)) continue;
                    candidates.Add((kl[i].OpenTime, sym, i));
                    lastFire = i;
                }
            }
            candidates.Sort((a, b) => a.time.CompareTo(b.time));

            var active = new List<DateTime>();
            decimal totalPnl = 0m;
            int n = 0, tpN = 0, slN = 0, beN = 0, toN = 0;
            int holdSum = 0;
            var byDay = new SortedDictionary<DateTime, decimal>();
            foreach (var c in candidates)
            {
                active.RemoveAll(t => t <= c.time);
                if (active.Count >= maxSlots) continue;
                decimal notional = margin * LEVERAGE;
                var (kind, pctRaw, hold) = Outcome(fullData15m[c.sym], c.barIdx);
                decimal pctNet = pctRaw - (decimal)(feeRate * 2m * 100m) - (slippagePct * 2m);
                decimal pnlUsd = notional * pctNet / 100m;
                totalPnl += pnlUsd;
                n++; holdSum += hold;
                if (kind == "TP") tpN++;
                else if (kind == "SL") slN++;
                else if (kind == "BE") beN++;
                else toN++;
                int endBar = Math.Min(c.barIdx + hold, fullData15m[c.sym].Count - 1);
                active.Add(fullData15m[c.sym][endBar].OpenTime);
                DateTime day = c.time.Date;
                byDay[day] = byDay.TryGetValue(day, out var v) ? v + pnlUsd : pnlUsd;
            }
            decimal cum = 0m, peak = 0m, mdd = 0m;
            foreach (var kv in byDay) { cum += kv.Value; if (cum > peak) peak = cum; decimal dd = peak - cum; if (dd > mdd) mdd = dd; }
            decimal mddPct = peak > 0 ? mdd / (seed + peak) * 100m : 0m;
            decimal avgHoldBars = n > 0 ? (decimal)holdSum / n : 0m;
            return (totalPnl, n, tpN, slN, beN, toN, mdd, mddPct, avgHoldBars);
        }

        Console.WriteLine();
        Console.WriteLine($"  TP+{tpPct}% / SL-{slPct}% / max {maxHoldBars}봉(6h) / 1H EMA20위 + 눌림+반등 + EMA20±1%");
        Console.WriteLine();
        Console.WriteLine($"{"기간",-7} {"진입",6} {"TP",5} {"SL",5} {"BE",5} {"TO",5} {"보유",8} {"PnL",10} {"ROI",10} {"MDD%",8}");
        Console.WriteLine(new string('-', 95));
        int[] periods = { 30, 60, 90, 180 };
        foreach (int days in periods)
        {
            var r = Eval(days);
            decimal roi = r.pnl / seed * 100m;
            Console.WriteLine($"{days,-7}일 {r.n,6} {r.tpN,5} {r.slN,5} {r.beN,5} {r.toN,5} {r.avgHold,7:F1} {r.pnl,9:F2} {roi,9:F2}% {r.mddPct,7:F2}%");
        }
        Console.WriteLine(new string('-', 95));
    }

    // [v5.22.69] Top30 24h 상승률 백테스트 — AltMomentum 검증
    //   사용자 보고: "BUSDT/TST 폭등 코인 진입 없음. 손절만 나옴"
    //   1. Binance /fapi/v1/ticker/24hr 호출 → priceChangePercent 상위 30개 추출
    //   2. 각 심볼 1m 1500봉 fetch (~25h)
    //   3. AltMomentum 진입 시뮬 (24h +5~30% + EMA20 갓 돌파 + vol×2 + RSI<70)
    //   4. TP +3% / SL -2% / max 30분 hold
    private static async Task RunTop30Last24hAsync()
    {
        Console.WriteLine("================================================================");
        Console.WriteLine("  v5.22.69 검증 — top 30 상승률 알트 (24h) AltMomentum 시뮬");
        Console.WriteLine("================================================================");

        // 1. ticker/24hr fetch top 30
        Console.WriteLine("\n[1] Binance /fapi/v1/ticker/24hr — top 30 추출");
        List<(string sym, decimal change24h, decimal qVol)> top30;
        try
        {
            var json = await http.GetStringAsync("https://fapi.binance.com/fapi/v1/ticker/24hr");
            var arr = JsonDocument.Parse(json).RootElement;
            var all = new List<(string, decimal, decimal)>();
            foreach (var e in arr.EnumerateArray())
            {
                string sym = e.GetProperty("symbol").GetString() ?? "";
                if (!sym.EndsWith("USDT")) continue;
                if (!decimal.TryParse(e.GetProperty("priceChangePercent").GetString(), CultureInfo.InvariantCulture, out var ch)) continue;
                if (!decimal.TryParse(e.GetProperty("quoteVolume").GetString(), CultureInfo.InvariantCulture, out var qv)) continue;
                if (qv < 5_000_000m) continue;     // 거래대금 500만 USDT 이상
                all.Add((sym, ch, qv));
            }
            top30 = all.OrderByDescending(x => x.Item2).Take(30).ToList();
        }
        catch (Exception ex)
        {
            Console.WriteLine($"❌ ticker fetch 실패: {ex.Message}");
            return;
        }

        Console.WriteLine($"  TOP 30 추출 완료. 1~5위:");
        for (int k = 0; k < Math.Min(5, top30.Count); k++)
            Console.WriteLine($"    {k + 1}. {top30[k].sym,-15} +{top30[k].change24h,6:F2}%  qVol=${top30[k].qVol / 1_000_000m,8:F1}M");

        // 2. 각 심볼 1m fetch
        Console.WriteLine($"\n[2] fetch 1m 1500봉 (~25h) × {top30.Count}");
        var fullData = new Dictionary<string, List<IBinanceKline>>();
        int idx = 0;
        foreach (var (sym, _, _) in top30)
        {
            idx++;
            Console.Write($"[{idx}/{top30.Count}] {sym} ");
            try
            {
                var kl = await FetchKlines1mAsync(sym, 1);
                if (kl.Count < 1440) { Console.WriteLine($"skip ({kl.Count})"); continue; }
                fullData[sym] = kl;
                Console.WriteLine($"ok ({kl.Count} bars)");
            }
            catch (Exception ex) { Console.WriteLine("fail: " + ex.Message); }
        }

        // 3. AltMomentum 시뮬 (1m → 15m 환산)
        const decimal margin = 100m;
        const int maxSlots = 3;
        const decimal tpPct = 3.0m;
        const decimal slPct = 2.0m;
        const decimal slippagePct = 0.05m;
        const int maxHoldBars = 30;       // 30분
        const int cooldownBars = 30;

        bool ShouldEnter(List<IBinanceKline> kl, int i)
        {
            // 1m봉. 15봉 = 15분.
            if (i < 1440) return false;       // 24h 백필 필요
            // 24h 변화율 5~30%
            decimal price24h = kl[i - 1440].ClosePrice;
            if (price24h <= 0) return false;
            decimal change24h = (kl[i].ClosePrice - price24h) / price24h * 100m;
            if (change24h < 5m || change24h > 30m) return false;
            // 15m EMA20 — 1m × 300봉 → EMA20 환산
            decimal ema20 = Ema(kl, i, 300);     // 1m EMA300 ≈ 15m EMA20
            decimal ema20Prev = Ema(kl, i - 15, 300);
            if (kl[i].ClosePrice <= ema20) return false;
            if (kl[i - 15].ClosePrice > ema20Prev) return false;     // 갓 돌파
            // 거래량 (직전 5×15봉 = 75봉 평균 × 2)
            decimal volAvg = 0m;
            for (int q = i - 75; q < i; q++) volAvg += kl[q].Volume;
            volAvg /= 75m;
            if (volAvg <= 0m || kl[i].Volume * 15m < volAvg * 75m * 2m) return false;
            // RSI < 70
            double rsi = CalcRsi14(kl, i);
            if (rsi >= 70) return false;
            return true;
        }

        (string kind, decimal pctRaw, int holdBars) Outcome(List<IBinanceKline> kl, int i)
        {
            decimal entry = kl[i].ClosePrice;
            decimal tpPx = entry * (1 + tpPct / 100m);
            decimal slPx = entry * (1 - slPct / 100m);
            for (int k = 1; k <= maxHoldBars && i + k < kl.Count; k++)
            {
                var b = kl[i + k];
                if (b.HighPrice >= tpPx && b.LowPrice <= slPx) return ("SL", -slPct, k);
                if (b.HighPrice >= tpPx) return ("TP", tpPct, k);
                if (b.LowPrice <= slPx) return ("SL", -slPct, k);
            }
            int idxClose = Math.Min(i + maxHoldBars, kl.Count - 1);
            decimal pctTo = (kl[idxClose].ClosePrice - entry) / entry * 100m;
            return (Math.Abs(pctTo) < 0.3m ? "BE" : "TIMEOUT", pctTo, maxHoldBars);
        }

        // 시뮬
        var candidates = new List<(DateTime time, string sym, int barIdx)>();
        foreach (var kv in fullData)
        {
            var kl = kv.Value; var sym = kv.Key;
            int lastFire = -1000;
            for (int i = 1450; i < kl.Count - maxHoldBars; i++)
            {
                if (i - lastFire < cooldownBars) continue;
                if (!ShouldEnter(kl, i)) continue;
                candidates.Add((kl[i].OpenTime, sym, i));
                lastFire = i;
            }
        }
        candidates.Sort((a, b) => a.time.CompareTo(b.time));

        var active = new List<DateTime>();
        decimal totalPnl = 0m;
        int n = 0, tpN = 0, slN = 0, beN = 0, toN = 0;
        var perSym = new Dictionary<string, (int n, int tp, int sl, decimal pnl)>();
        foreach (var c in candidates)
        {
            active.RemoveAll(t => t <= c.time);
            if (active.Count >= maxSlots) continue;
            decimal notional = margin * LEVERAGE;
            var (kind, pctRaw, hold) = Outcome(fullData[c.sym], c.barIdx);
            decimal pctNet = pctRaw - (decimal)(FEE_RATE * 2m * 100m) - (slippagePct * 2m);
            decimal pnlUsd = notional * pctNet / 100m;
            totalPnl += pnlUsd;
            n++;
            if (kind == "TP") tpN++;
            else if (kind == "SL") slN++;
            else if (kind == "BE") beN++;
            else toN++;
            int endBar = Math.Min(c.barIdx + hold, fullData[c.sym].Count - 1);
            active.Add(fullData[c.sym][endBar].OpenTime);
            if (!perSym.ContainsKey(c.sym)) perSym[c.sym] = (0, 0, 0, 0m);
            var p = perSym[c.sym];
            perSym[c.sym] = (p.n + 1, p.tp + (kind == "TP" ? 1 : 0), p.sl + (kind == "SL" ? 1 : 0), p.pnl + pnlUsd);
        }

        Console.WriteLine();
        Console.WriteLine($"  TP+{tpPct}% / SL-{slPct}% / max {maxHoldBars}분 / 마진 ${margin}×{maxSlots}슬롯×{LEVERAGE}x / cooldown {cooldownBars}분");
        Console.WriteLine();
        Console.WriteLine($"==== 24h 종합 결과 ====");
        Console.WriteLine($"  진입: {n}건  TP: {tpN}  SL: {slN}  BE: {beN}  TIMEOUT: {toN}");
        Console.WriteLine($"  PnL: ${totalPnl:F2}  ROI(시드 $400): {totalPnl / 400m * 100m:F2}%");
        Console.WriteLine();
        Console.WriteLine($"==== 심볼별 결과 (PnL desc) ====");
        Console.WriteLine($"{"심볼",-15} {"진입",4} {"TP",3} {"SL",3} {"PnL",10}");
        Console.WriteLine(new string('-', 50));
        foreach (var kv in perSym.OrderByDescending(k => k.Value.pnl))
        {
            Console.WriteLine($"{kv.Key,-15} {kv.Value.n,4} {kv.Value.tp,3} {kv.Value.sl,3} {kv.Value.pnl,9:F2}");
        }
    }

    // [v5.22.65] Daily Swing 변형 4종 — 수익성 더 높은 변형 탐색
    //   #A 베이스: 1D close>20SMA + 20SMA>50SMA + RSI 50~65 + vol×1.5 + 양봉 (현재 라이브)
    //   #B 강화: + 24h 변화율 ≥ +5% (펌프 종목 우선)
    //   #C RSI 완화: RSI 50~70 (놓치는 강한 추세 잡기)
    //   #D 거래대금 가중: 24h quoteVolume 상위 50% 만 진입 (유동성 ↑)
    //   #E B+C+D 조합 (모두 적용)
    private static async Task RunDailySwingVariantsAsync()
    {
        Console.WriteLine("================================================================");
        Console.WriteLine("  v5.22.65 Daily Swing 변형 4종 — 수익성 비교");
        Console.WriteLine("================================================================");

        const decimal seed = 400m;
        const decimal margin = 200m;
        const int maxSlots = 2;
        const decimal tpPct = 15m;
        const decimal slPct = 7m;
        const decimal slippagePct = 0.05m;
        const int maxHoldBars = 7;
        const decimal swingLeverage = 5m;

        var fullData = new Dictionary<string, List<IBinanceKline>>();
        Console.WriteLine($"\n[fetch — {symbols.Length}개 심볼 (1D)]");
        int idx = 0;
        foreach (var sym in symbols)
        {
            idx++;
            Console.Write($"[{idx}/{symbols.Length}] {sym} ");
            try
            {
                var kl = await FetchKlines1dAsync(sym, 1);
                if (kl.Count < 60) { Console.WriteLine($"skip ({kl.Count})"); continue; }
                fullData[sym] = kl;
                Console.WriteLine($"ok ({kl.Count} bars)");
            }
            catch (Exception ex) { Console.WriteLine("fail: " + ex.Message); }
        }

        // 24h quoteVolume 누적 (1D 기준 = 1봉 = 24h)
        // 상위 50% 종목 동적 선정
        var dailyQVolAvg = new Dictionary<string, decimal>();
        foreach (var kv in fullData)
        {
            decimal sumQv = 0m; int cnt = 0;
            foreach (var k in kv.Value)
            {
                decimal q = k.QuoteVolume > 0 ? k.QuoteVolume : k.ClosePrice * k.Volume;
                sumQv += q; cnt++;
            }
            dailyQVolAvg[kv.Key] = cnt > 0 ? sumQv / cnt : 0m;
        }
        decimal medianQVol = dailyQVolAvg.Values.OrderByDescending(v => v).Skip(dailyQVolAvg.Count / 2).FirstOrDefault();

        // 변형 진입 조건들
        bool BaseEnter(List<IBinanceKline> kl, int i)
        {
            if (i < 51) return false;
            decimal sma20 = 0m; for (int q = i - 19; q <= i; q++) sma20 += kl[q].ClosePrice; sma20 /= 20m;
            decimal sma50 = 0m; for (int q = i - 49; q <= i; q++) sma50 += kl[q].ClosePrice; sma50 /= 50m;
            if (kl[i].ClosePrice <= sma20) return false;
            if (sma20 <= sma50) return false;
            double rsi = CalcRsi14(kl, i);
            if (rsi < 50.0 || rsi > 65.0) return false;
            decimal volAvg = 0m; for (int q = i - 5; q <= i - 1; q++) volAvg += kl[q].Volume; volAvg /= 5m;
            if (volAvg <= 0m || kl[i].Volume < volAvg * 1.5m) return false;
            if (kl[i].ClosePrice <= kl[i].OpenPrice) return false;
            return true;
        }
        bool BEnter(List<IBinanceKline> kl, int i)   // + 24h +5%
        {
            if (!BaseEnter(kl, i)) return false;
            if (i < 1) return false;
            decimal change24h = (kl[i].ClosePrice - kl[i - 1].OpenPrice) / kl[i - 1].OpenPrice * 100m;
            return change24h >= 5m;
        }
        bool CEnter(List<IBinanceKline> kl, int i)   // RSI 50~70
        {
            if (i < 51) return false;
            decimal sma20 = 0m; for (int q = i - 19; q <= i; q++) sma20 += kl[q].ClosePrice; sma20 /= 20m;
            decimal sma50 = 0m; for (int q = i - 49; q <= i; q++) sma50 += kl[q].ClosePrice; sma50 /= 50m;
            if (kl[i].ClosePrice <= sma20) return false;
            if (sma20 <= sma50) return false;
            double rsi = CalcRsi14(kl, i);
            if (rsi < 50.0 || rsi > 70.0) return false;
            decimal volAvg = 0m; for (int q = i - 5; q <= i - 1; q++) volAvg += kl[q].Volume; volAvg /= 5m;
            if (volAvg <= 0m || kl[i].Volume < volAvg * 1.5m) return false;
            if (kl[i].ClosePrice <= kl[i].OpenPrice) return false;
            return true;
        }
        bool DEnter(string sym, List<IBinanceKline> kl, int i)   // 거래대금 가중 + base
        {
            if (!BaseEnter(kl, i)) return false;
            return dailyQVolAvg.TryGetValue(sym, out var qv) && qv >= medianQVol;
        }
        bool EEnter(string sym, List<IBinanceKline> kl, int i)   // B+C+D 조합
        {
            return CEnter(kl, i)
                && (i >= 1 && (kl[i].ClosePrice - kl[i - 1].OpenPrice) / kl[i - 1].OpenPrice * 100m >= 5m)
                && dailyQVolAvg.TryGetValue(sym, out var qv) && qv >= medianQVol;
        }

        (string kind, decimal pctRaw, int holdBars) Outcome(List<IBinanceKline> kl, int i)
        {
            decimal entry = kl[i].ClosePrice;
            decimal tpPx = entry * (1 + tpPct / 100m);
            decimal slPx = entry * (1 - slPct / 100m);
            for (int k = 1; k <= maxHoldBars && i + k < kl.Count; k++)
            {
                var b = kl[i + k];
                if (b.HighPrice >= tpPx && b.LowPrice <= slPx) return ("SL", -slPct, k);
                if (b.HighPrice >= tpPx) return ("TP", tpPct, k);
                if (b.LowPrice <= slPx) return ("SL", -slPct, k);
            }
            int idxClose = Math.Min(i + maxHoldBars, kl.Count - 1);
            decimal pctTo = (kl[idxClose].ClosePrice - entry) / entry * 100m;
            return (Math.Abs(pctTo) < 1.0m ? "BE" : "TIMEOUT", pctTo, maxHoldBars);
        }

        (decimal pnl, int n, int tpN, int slN, decimal mddPct) Eval(int days, Func<string, List<IBinanceKline>, int, bool> shouldEnter)
        {
            DateTime since = DateTime.UtcNow.AddDays(-days);
            decimal feeRate = FEE_RATE;
            var candidates = new List<(DateTime time, string sym, int barIdx)>();
            foreach (var kv in fullData)
            {
                var kl = kv.Value; var sym = kv.Key;
                for (int i = 51; i < kl.Count - maxHoldBars; i++)
                {
                    if (kl[i].OpenTime < since) continue;
                    if (!shouldEnter(sym, kl, i)) continue;
                    candidates.Add((kl[i].OpenTime, sym, i));
                }
            }
            candidates.Sort((a, b) => a.time.CompareTo(b.time));
            var active = new List<DateTime>();
            decimal totalPnl = 0m;
            int n = 0, tpN = 0, slN = 0;
            var byDay = new SortedDictionary<DateTime, decimal>();
            foreach (var c in candidates)
            {
                active.RemoveAll(t => t <= c.time);
                if (active.Count >= maxSlots) continue;
                decimal notional = margin * swingLeverage;
                var (kind, pctRaw, hold) = Outcome(fullData[c.sym], c.barIdx);
                decimal pctNet = pctRaw - (decimal)(feeRate * 2m * 100m) - (slippagePct * 2m);
                decimal pnlUsd = notional * pctNet / 100m;
                totalPnl += pnlUsd;
                n++;
                if (kind == "TP") tpN++; else if (kind == "SL") slN++;
                int endBar = Math.Min(c.barIdx + hold, fullData[c.sym].Count - 1);
                active.Add(fullData[c.sym][endBar].OpenTime);
                DateTime day = c.time.Date;
                byDay[day] = byDay.TryGetValue(day, out var v) ? v + pnlUsd : pnlUsd;
            }
            decimal cum = 0m, peak = 0m, mdd = 0m;
            foreach (var kv in byDay) { cum += kv.Value; if (cum > peak) peak = cum; decimal dd = peak - cum; if (dd > mdd) mdd = dd; }
            decimal mddPct = peak > 0 ? mdd / (seed + peak) * 100m : 0m;
            return (totalPnl, n, tpN, slN, mddPct);
        }

        Console.WriteLine();
        Console.WriteLine($"  TP+{tpPct}% / SL-{slPct}% / 마진 ${margin}×{maxSlots}슬롯×{swingLeverage}x");
        Console.WriteLine();
        int[] periods = { 180, 365 };
        foreach (int days in periods)
        {
            Console.WriteLine($"==== {days}일 결과 ====");
            Console.WriteLine($"{"변형",-30} {"진입",6} {"TP",4} {"SL",4} {"PnL",10} {"ROI",10} {"MDD%",8}");
            Console.WriteLine(new string('-', 80));
            var rA = Eval(days, (s, k, i) => BaseEnter(k, i));
            var rB = Eval(days, (s, k, i) => BEnter(k, i));
            var rC = Eval(days, (s, k, i) => CEnter(k, i));
            var rD = Eval(days, (s, k, i) => DEnter(s, k, i));
            var rE = Eval(days, (s, k, i) => EEnter(s, k, i));
            void Show(string label, (decimal pnl, int n, int tpN, int slN, decimal mddPct) r)
            {
                decimal roi = r.pnl / seed * 100m;
                Console.WriteLine($"{label,-30} {r.n,6} {r.tpN,4} {r.slN,4} {r.pnl,9:F2} {roi,9:F2}% {r.mddPct,7:F2}%");
            }
            Show("#A 베이스 (현재 라이브)", rA);
            Show("#B + 24h+5% 펌프", rB);
            Show("#C RSI 50~70 완화", rC);
            Show("#D 거래대금 상위 50%", rD);
            Show("#E B+C+D 조합", rE);
            Console.WriteLine();
        }
    }

    // [v5.22.65] B+D 조합 — EMA20 갓 돌파 + 이격도 ≤ 1% (조기 진입)
    //   사용자 보고: "WLFI 13:45 고점 진입, 12:45/13:00 진입했어야" → 5중 가드 추격 매수 구조 변경
    //   진입: 1) 15m 종가 > EMA20  2) 직전 봉 ≤ 직전 EMA20 (갓 돌파)  3) 이격도 ≤ 1%  4) vol > 5봉 평균 × 2  5) RSI < 75
    //   진짜 모델 (수수료 0.08% + 슬리피지 0.10% + 미체결 PnL + MDD)
    private static async Task RunEma20BreakTightAsync()
    {
        Console.WriteLine("================================================================");
        Console.WriteLine("  v5.22.65 검증 — EMA20 갓 돌파 + 이격도 ≤ 1% + vol×2 + RSI<75");
        Console.WriteLine("  WLFI 같은 추격 매수 회피 → 조기 진입 효과 검증");
        Console.WriteLine("================================================================");

        const decimal seed = 400m;
        const decimal margin = 100m;
        const int maxSlots = 3;
        const decimal tpPct = 1.0m;
        const decimal slPct = 1.5m;
        const decimal slippagePct = 0.05m;
        const int fetchPages = 12;             // 180일 15m
        const int maxHoldBars = 24;            // 6h max

        var fullData = new Dictionary<string, List<IBinanceKline>>();
        Console.WriteLine($"\n[fetch 180일 — {symbols.Length}개 심볼 (15m)]");
        int idx = 0;
        foreach (var sym in symbols)
        {
            idx++;
            Console.Write($"[{idx}/{symbols.Length}] {sym} ");
            try
            {
                var kl = await FetchKlines15mAsync(sym, fetchPages);
                if (kl.Count < 200) { Console.WriteLine("skip"); continue; }
                fullData[sym] = kl;
                Console.WriteLine($"ok ({kl.Count} bars)");
            }
            catch (Exception ex) { Console.WriteLine("fail: " + ex.Message); }
        }

        bool ShouldEnter(List<IBinanceKline> kl, int i)
        {
            if (i < 22) return false;
            decimal ema20Now = Ema(kl, i, 20);
            decimal ema20Prev = Ema(kl, i - 1, 20);
            // 1. 종가 > EMA20
            if (kl[i].ClosePrice <= ema20Now) return false;
            // 2. 직전 봉 ≤ 직전 EMA20 (갓 돌파)
            if (kl[i - 1].ClosePrice > ema20Prev) return false;
            // 3. 이격도 ≤ 1%
            decimal distToEma = (kl[i].ClosePrice - ema20Now) / ema20Now * 100m;
            if (distToEma > 1.0m) return false;
            // 4. 거래량 > 직전 5봉 평균 × 2
            decimal volAvg5 = 0m;
            for (int q = i - 5; q <= i - 1; q++) volAvg5 += kl[q].Volume;
            volAvg5 /= 5m;
            if (volAvg5 <= 0m || kl[i].Volume < volAvg5 * 2m) return false;
            // 5. RSI < 75
            double rsi = CalcRsi14(kl, i);
            if (rsi >= 75) return false;
            return true;
        }

        (string kind, decimal pctRaw, int holdBars) Outcome(List<IBinanceKline> kl, int i)
        {
            decimal entry = kl[i].ClosePrice;
            decimal tpPx = entry * (1 + tpPct / 100m);
            decimal slPx = entry * (1 - slPct / 100m);
            for (int k = 1; k <= maxHoldBars && i + k < kl.Count; k++)
            {
                var b = kl[i + k];
                if (b.HighPrice >= tpPx && b.LowPrice <= slPx) return ("SL", -slPct, k);
                if (b.HighPrice >= tpPx) return ("TP", tpPct, k);
                if (b.LowPrice <= slPx) return ("SL", -slPct, k);
            }
            int idxClose = Math.Min(i + maxHoldBars, kl.Count - 1);
            decimal pctTo = (kl[idxClose].ClosePrice - entry) / entry * 100m;
            return (Math.Abs(pctTo) < 0.3m ? "BE" : "TIMEOUT", pctTo, maxHoldBars);
        }

        (decimal pnl, int n, int tpN, int slN, int beN, int toN, decimal mdd, decimal mddPct, decimal avgHold)
            Eval(int days)
        {
            DateTime since = DateTime.UtcNow.AddDays(-days);
            decimal feeRate = FEE_RATE;
            const int cooldownBars = 2;       // 30분 (15m × 2)

            var candidates = new List<(DateTime time, string sym, int barIdx)>();
            foreach (var kv in fullData)
            {
                var kl = kv.Value; var sym = kv.Key;
                int lastFire = -1000;
                for (int i = 25; i < kl.Count - maxHoldBars; i++)
                {
                    if (kl[i].OpenTime < since) continue;
                    if (i - lastFire < cooldownBars) continue;
                    if (!ShouldEnter(kl, i)) continue;
                    candidates.Add((kl[i].OpenTime, sym, i));
                    lastFire = i;
                }
            }
            candidates.Sort((a, b) => a.time.CompareTo(b.time));

            var active = new List<DateTime>();
            decimal totalPnl = 0m;
            int n = 0, tpN = 0, slN = 0, beN = 0, toN = 0;
            int holdSum = 0;
            var byDay = new SortedDictionary<DateTime, decimal>();
            foreach (var c in candidates)
            {
                active.RemoveAll(t => t <= c.time);
                if (active.Count >= maxSlots) continue;
                decimal notional = margin * LEVERAGE;
                var (kind, pctRaw, hold) = Outcome(fullData[c.sym], c.barIdx);
                decimal pctNet = pctRaw - (decimal)(feeRate * 2m * 100m) - (slippagePct * 2m);
                decimal pnlUsd = notional * pctNet / 100m;
                totalPnl += pnlUsd;
                n++; holdSum += hold;
                if (kind == "TP") tpN++;
                else if (kind == "SL") slN++;
                else if (kind == "BE") beN++;
                else toN++;
                int endBar = Math.Min(c.barIdx + hold, fullData[c.sym].Count - 1);
                active.Add(fullData[c.sym][endBar].OpenTime);
                DateTime day = c.time.Date;
                byDay[day] = byDay.TryGetValue(day, out var v) ? v + pnlUsd : pnlUsd;
            }

            decimal cum = 0m, peak = 0m, mdd = 0m;
            foreach (var kv in byDay) { cum += kv.Value; if (cum > peak) peak = cum; decimal dd = peak - cum; if (dd > mdd) mdd = dd; }
            decimal mddPct = peak > 0 ? mdd / (seed + peak) * 100m : 0m;
            decimal avgHoldBars = n > 0 ? (decimal)holdSum / n : 0m;
            return (totalPnl, n, tpN, slN, beN, toN, mdd, mddPct, avgHoldBars);
        }

        Console.WriteLine();
        Console.WriteLine($"  TP+{tpPct}% / SL-{slPct}% / max {maxHoldBars}봉(6h) / EMA20 갓 돌파 + 이격도≤1% + vol×2");
        Console.WriteLine();
        Console.WriteLine($"{"기간",-7} {"진입",6} {"TP",5} {"SL",5} {"BE",5} {"TO",5} {"보유봉",8} {"PnL",10} {"ROI",10} {"MDD$",10} {"MDD%",8}");
        Console.WriteLine(new string('-', 105));
        int[] periods = { 30, 60, 90, 180 };
        foreach (int days in periods)
        {
            var r = Eval(days);
            decimal roi = r.pnl / seed * 100m;
            Console.WriteLine($"{days,-7}일 {r.n,6} {r.tpN,5} {r.slN,5} {r.beN,5} {r.toN,5} {r.avgHold,7:F1} {r.pnl,9:F2} {roi,9:F2}% {r.mdd,9:F2} {r.mddPct,7:F2}%");
        }
        Console.WriteLine(new string('-', 105));
    }

    // [v5.22.53 라이브 v2] 처방 1+2+3 동시 적용
    //   1. SL 3%→1.5% (1:1 손익비) + Time Stop 단축 (메이저 4→2봉, 알트 8→4봉)
    //   2. 거래량 가드 ×2.0→×3.0 (진입 -40% / 수수료 -40% 기대)
    //   3. TP 1%→1.5% (TP 1건당 +$60)
    private static async Task RunLiveRealisticV2Async()
    {
        Console.WriteLine("================================================================");
        Console.WriteLine("  v5.22.54 후보 — 처방 1+2+3 동시 적용");
        Console.WriteLine("  TP+1.5% / SL-1.5% / vol×3.0 / Time Stop 메이저 2봉 / 알트 4봉");
        Console.WriteLine("================================================================");

        const decimal seed = 400m;
        const decimal majorMargin = 150m;
        const decimal altMargin = 100m;
        const int majorSlot = 1;
        const int altSlot = 2;
        const decimal tpPct = 1.5m;
        const decimal slPct = 1.5m;
        const decimal slippagePct = 0.05m;
        const int majorWinBars = 2;        // 30분
        const int altWinBars = 4;          // 60분
        const int fetchPages = 12;
        const decimal volMult = 3.0m;

        var fullData = new Dictionary<string, List<IBinanceKline>>();
        Console.WriteLine($"\n[fetch 180일 — {symbols.Length}개 심볼 (15m)]");
        int idx = 0;
        foreach (var sym in symbols)
        {
            idx++;
            Console.Write($"[{idx}/{symbols.Length}] {sym} ");
            try
            {
                var kl = await FetchKlines15mAsync(sym, fetchPages);
                if (kl.Count < 200) { Console.WriteLine("skip"); continue; }
                fullData[sym] = kl;
                Console.WriteLine($"ok ({kl.Count} bars)");
            }
            catch (Exception ex) { Console.WriteLine("fail: " + ex.Message); }
        }

        var majors = new HashSet<string> { "BTCUSDT", "ETHUSDT", "SOLUSDT", "XRPUSDT", "BNBUSDT" };

        bool ShouldEnter(List<IBinanceKline> kl, int i)
        {
            if (i < 21) return false;
            decimal ema20 = Ema(kl, i, 20);
            if (kl[i].ClosePrice <= ema20) return false;
            double sum = 0;
            for (int q = i - 19; q <= i; q++) sum += (double)kl[q].ClosePrice;
            double mean = sum / 20.0;
            double sq = 0;
            for (int q = i - 19; q <= i; q++) { double d = (double)kl[q].ClosePrice - mean; sq += d * d; }
            double sd = Math.Sqrt(sq / 20.0);
            decimal mid = (decimal)mean;
            decimal upper = (decimal)(mean + 2 * sd);
            decimal lower = (decimal)(mean - 2 * sd);
            if (mid <= 0) return false;
            decimal distMid = (kl[i].ClosePrice - mid) / mid * 100m;
            if (distMid > 2.5m) return false;
            decimal bbw = (upper - lower) / mid * 100m;
            if (bbw >= 5.0m) return false;
            if (kl[i].ClosePrice <= upper) return false;
            decimal volAvg5 = 0m;
            for (int q = i - 5; q <= i - 1; q++) volAvg5 += kl[q].Volume;
            volAvg5 /= 5m;
            if (volAvg5 <= 0m || kl[i].Volume < volAvg5 * volMult) return false;   // ×3.0
            double rsi = CalcRsi14(kl, i);
            if (rsi >= 75) return false;
            return true;
        }

        (string kind, decimal pctRaw, int holdBars) Outcome(List<IBinanceKline> kl, int i, int winBars, decimal lev)
        {
            decimal entry = kl[i].ClosePrice;
            decimal tpPx = entry * (1 + tpPct / 100m);
            decimal slPx = entry * (1 - slPct / 100m);
            for (int k = 1; k <= winBars && i + k < kl.Count; k++)
            {
                var b = kl[i + k];
                if (b.HighPrice >= tpPx && b.LowPrice <= slPx) return ("SL", -slPct, k);
                if (b.HighPrice >= tpPx) return ("TP", tpPct, k);
                if (b.LowPrice <= slPx) return ("SL", -slPct, k);
                if (k >= 2)
                {
                    double rsiCurr = CalcRsi14(kl, i + k);
                    double rsiPrev = CalcRsi14(kl, i + k - 1);
                    if (rsiPrev >= 80.0 && rsiCurr < rsiPrev)
                    {
                        decimal pct = (b.ClosePrice - entry) / entry * 100m;
                        if (pct * lev > 0.3m * lev) return ("RSI_EXIT", pct, k);
                    }
                }
            }
            int idxClose = Math.Min(i + winBars, kl.Count - 1);
            decimal pctTo = (kl[idxClose].ClosePrice - entry) / entry * 100m;
            return (Math.Abs(pctTo) < 0.3m ? "BE" : "TIMEOUT", pctTo, winBars);
        }

        (decimal pnl, int n, int tpN, int slN, int rsiN, int beN, int toN, decimal mdd, decimal mddPct, decimal avgHold)
            Eval(int days)
        {
            DateTime since = DateTime.UtcNow.AddDays(-days);
            decimal feeRate = FEE_RATE;

            var candidates = new List<(DateTime time, string sym, bool isMajor, int barIdx)>();
            foreach (var kv in fullData)
            {
                var kl = kv.Value; var sym = kv.Key;
                bool isMajor = majors.Contains(sym);
                int winBars = isMajor ? majorWinBars : altWinBars;
                DateTime lastFireTime = DateTime.MinValue;
                for (int i = 25; i < kl.Count - winBars; i++)
                {
                    if (kl[i].OpenTime < since) continue;
                    if ((kl[i].OpenTime - lastFireTime).TotalMinutes < 30) continue;
                    if (!ShouldEnter(kl, i)) continue;
                    candidates.Add((kl[i].OpenTime, sym, isMajor, i));
                    lastFireTime = kl[i].OpenTime;
                }
            }
            candidates.Sort((a, b) => a.time.CompareTo(b.time));

            var majorActive = new List<DateTime>();
            var altActive = new List<DateTime>();
            decimal totalPnl = 0m;
            int n = 0, tpN = 0, slN = 0, rsiN = 0, beN = 0, toN = 0;
            int holdSum = 0;
            var byDay = new SortedDictionary<DateTime, decimal>();

            foreach (var c in candidates)
            {
                majorActive.RemoveAll(t => t <= c.time);
                altActive.RemoveAll(t => t <= c.time);
                bool slotOk = c.isMajor ? majorActive.Count < majorSlot : altActive.Count < altSlot;
                if (!slotOk) continue;

                int winBars = c.isMajor ? majorWinBars : altWinBars;
                decimal margin = c.isMajor ? majorMargin : altMargin;
                decimal notional = margin * LEVERAGE;

                var (kind, pctRaw, hold) = Outcome(fullData[c.sym], c.barIdx, winBars, LEVERAGE);
                decimal pctNet = pctRaw - (decimal)(feeRate * 2m * 100m) - (slippagePct * 2m);
                decimal pnlUsd = notional * pctNet / 100m;
                totalPnl += pnlUsd;
                n++; holdSum += hold;
                if (kind == "TP") tpN++;
                else if (kind == "SL") slN++;
                else if (kind == "RSI_EXIT") rsiN++;
                else if (kind == "BE") beN++;
                else toN++;
                int endBar = Math.Min(c.barIdx + hold, fullData[c.sym].Count - 1);
                DateTime endTime = fullData[c.sym][endBar].OpenTime;
                if (c.isMajor) majorActive.Add(endTime); else altActive.Add(endTime);

                DateTime day = c.time.Date;
                byDay[day] = byDay.TryGetValue(day, out var v) ? v + pnlUsd : pnlUsd;
            }

            decimal cum = 0m, peak = 0m, mdd = 0m;
            foreach (var kv in byDay)
            {
                cum += kv.Value;
                if (cum > peak) peak = cum;
                decimal dd = peak - cum;
                if (dd > mdd) mdd = dd;
            }
            decimal mddPct = peak > 0 ? mdd / (seed + peak) * 100m : 0m;
            decimal avgHoldBars = n > 0 ? (decimal)holdSum / n : 0m;
            return (totalPnl, n, tpN, slN, rsiN, beN, toN, mdd, mddPct, avgHoldBars);
        }

        Console.WriteLine();
        Console.WriteLine($"  TP+{tpPct}% / SL-{slPct}% (1:1) / vol×{volMult} / 메이저 {majorWinBars}봉(30분) / 알트 {altWinBars}봉(60분)");
        Console.WriteLine();
        Console.WriteLine($"{"기간",-7} {"진입",6} {"TP",5} {"SL",5} {"RSI",5} {"BE",5} {"타임",5} {"평균보유",10} {"PnL",10} {"ROI",10} {"MDD$",10} {"MDD%",8}");
        Console.WriteLine(new string('-', 110));
        int[] periods = { 1, 10, 30, 60, 90, 180 };
        foreach (int days in periods)
        {
            var r = Eval(days);
            decimal roi = r.pnl / seed * 100m;
            Console.WriteLine($"{days,-7}일 {r.n,6} {r.tpN,5} {r.slN,5} {r.rsiN,5} {r.beN,5} {r.toN,5} {r.avgHold,9:F1}봉 {r.pnl,9:F2} {roi,9:F2}% {r.mdd,9:F2} {r.mddPct,7:F2}%");
        }
        Console.WriteLine(new string('-', 110));
    }

    // [v5.22.53 SMC 1단계] FVG 가드 백테스트 — 현 v5.22.52 5중 가드 + FVG 가드
    //   FVG (Fair Value Gap) 정의:
    //     Bearish FVG = 봉 i-2의 low > 봉 i의 high  (impulse 캔들 i-1로 갭다운)
    //                   → 가격이 갭 메우러 다시 올라올 가능성 = 저항대
    //   가드 룰: 현재가 위 N봉 이내 미충족 Bearish FVG 존재 → LONG 진입 차단
    //   비교: 가드 있음 vs 없음 — 180일 진짜 모델 (수수료+슬리피지+미체결PnL)
    private static async Task RunSmcFvgAsync()
    {
        Console.WriteLine("================================================================");
        Console.WriteLine("  SMC 1단계 — FVG 가드 백테스트 (Bearish FVG 위 진입 차단)");
        Console.WriteLine("  베이스: v5.22.52 5중 가드 (15m EMA20 + 이격도 + BBW + 돌파+vol×2 + RSI<75)");
        Console.WriteLine("================================================================");

        const decimal seed = 400m;
        const decimal margin = 100m;
        const int maxSlots = 3;
        const decimal tpPct = 2.0m;
        const decimal slPct = 1.5m;
        const int winBars = 24;            // 2h 강제 청산 (5m × 24)
        const decimal slippagePct = 0.05m;
        const int fetchPages = 36;         // 180일
        const int fvgLookback = 20;        // FVG 탐색 윈도우

        var fullData = new Dictionary<string, List<IBinanceKline>>();
        Console.WriteLine($"\n[fetch 180일 — {symbols.Length}개 심볼]");
        int idx = 0;
        foreach (var sym in symbols)
        {
            idx++;
            Console.Write($"[{idx}/{symbols.Length}] {sym} ");
            try
            {
                var kl = await FetchKlinesAsync(sym, fetchPages);
                if (kl.Count < 400) { Console.WriteLine("skip"); continue; }
                fullData[sym] = kl;
                Console.WriteLine($"ok ({kl.Count} bars)");
            }
            catch (Exception ex) { Console.WriteLine("fail: " + ex.Message); }
        }

        // 5중 가드 진입 조건 (v5.22.52 라이브 동일) — 5m kline 기준
        bool ShouldEnter(List<IBinanceKline> kl, int i)
        {
            if (i < 25) return false;
            // 1. EMA20 5봉 상승 (백테스트 표현 — 라이브는 15m close > 15m EMA20 인데 5m로 근사)
            decimal e1 = Ema(kl, i, 20);
            decimal e0 = Ema(kl, i - 5, 20);
            if (e1 <= e0) return false;
            // 종가 > EMA20
            if (kl[i].ClosePrice <= e1) return false;
            // 2. BB(20,2) 이격도 / BBW / 상단 돌파
            double sum = 0;
            for (int q = i - 19; q <= i; q++) sum += (double)kl[q].ClosePrice;
            double mean = sum / 20.0;
            double sq = 0;
            for (int q = i - 19; q <= i; q++) { double d = (double)kl[q].ClosePrice - mean; sq += d * d; }
            double sd = Math.Sqrt(sq / 20.0);
            decimal mid = (decimal)mean;
            decimal upper = (decimal)(mean + 2 * sd);
            decimal lower = (decimal)(mean - 2 * sd);
            if (mid <= 0) return false;
            decimal distMid = (kl[i].ClosePrice - mid) / mid * 100m;
            if (distMid > 2.5m) return false;
            decimal bbw = (upper - lower) / mid * 100m;
            if (bbw >= 5.0m) return false;
            if (kl[i].ClosePrice <= upper) return false;
            // 3. 돌파 봉 거래량 > 직전 5봉 평균 × 2
            decimal volAvg5 = 0m;
            for (int q = i - 5; q <= i - 1; q++) volAvg5 += kl[q].Volume;
            volAvg5 /= 5m;
            if (volAvg5 <= 0m || kl[i].Volume < volAvg5 * 2m) return false;
            // 4. RSI < 75
            double rsi = CalcRsi14(kl, i);
            if (rsi >= 75) return false;
            return true;
        }

        // FVG 가드 — i 시점 기준 직전 lookback 봉 내 미충족 Bearish FVG 가 현재가 위에 존재?
        //   Bearish FVG: kl[k-2].LowPrice > kl[k].HighPrice (k-2..k 3봉으로 형성)
        //   현재가 이상에 있어야 저항으로 작용 (가격이 메우러 다시 올라가야 함)
        //   미충족 = i 시점까지 가격이 갭 영역에 진입한 적 없음
        bool HasBearishFvgAbove(List<IBinanceKline> kl, int i)
        {
            decimal curPx = kl[i].ClosePrice;
            int from = Math.Max(2, i - fvgLookback);
            for (int k = from; k <= i - 1; k++)
            {
                if (k - 2 < 0) continue;
                decimal gapTop = kl[k - 2].LowPrice;
                decimal gapBot = kl[k].HighPrice;
                if (gapTop <= gapBot) continue;          // FVG 없음
                if (gapBot <= curPx) continue;           // 갭이 현재가 위에 있어야 저항
                // 미충족 검사: k+1 ~ i 봉 중 갭 영역(gapBot..gapTop) 진입했나?
                bool filled = false;
                for (int q = k + 1; q <= i; q++)
                {
                    if (kl[q].HighPrice >= gapBot)        // 갭 하단 터치 = 메움 시작
                    {
                        filled = true;
                        break;
                    }
                }
                if (!filled) return true;                 // 미충족 + 위에 있음 = 저항
            }
            return false;
        }

        (string kind, decimal pctRaw) Outcome(List<IBinanceKline> kl, int i)
        {
            decimal entry = kl[i].ClosePrice;
            decimal tpPx = entry * (1 + tpPct / 100m);
            decimal slPx = entry * (1 - slPct / 100m);
            for (int k = 1; k <= winBars && i + k < kl.Count; k++)
            {
                var b = kl[i + k];
                if (b.HighPrice >= tpPx && b.LowPrice <= slPx) return ("SL", -slPct);
                if (b.HighPrice >= tpPx) return ("TP", tpPct);
                if (b.LowPrice <= slPx) return ("SL", -slPct);
            }
            int idxClose = Math.Min(i + winBars, kl.Count - 1);
            decimal pct = (kl[idxClose].ClosePrice - entry) / entry * 100m;
            return (Math.Abs(pct) < 0.5m ? "BE" : "TIMEOUT", pct);
        }

        // 두 모드 동시 시뮬: with/without FVG 가드
        (decimal pnl, int n, int tpN, int slN, int beN, int toN, decimal mdd, decimal mddPct) Eval(int days, bool useFvg)
        {
            DateTime since = DateTime.UtcNow.AddDays(-days);
            decimal feeRate = FEE_RATE;
            const int cooldownBars = 6;

            var candidates = new List<(DateTime time, string sym, int barIdx)>();
            foreach (var kv in fullData)
            {
                var kl = kv.Value; var sym = kv.Key;
                int lastFire = -1000;
                for (int i = 50; i < kl.Count - winBars; i++)
                {
                    if (kl[i].OpenTime < since) continue;
                    if (i - lastFire < cooldownBars) continue;
                    if (!ShouldEnter(kl, i)) continue;
                    if (useFvg && HasBearishFvgAbove(kl, i)) continue;
                    candidates.Add((kl[i].OpenTime, sym, i));
                    lastFire = i;
                }
            }
            candidates.Sort((a, b) => a.time.CompareTo(b.time));

            var active = new List<DateTime>();
            decimal totalPnl = 0m;
            int n = 0, tpN = 0, slN = 0, beN = 0, toN = 0;
            var byDay = new SortedDictionary<DateTime, decimal>();

            foreach (var c in candidates)
            {
                active.RemoveAll(t => t <= c.time);
                if (active.Count >= maxSlots) continue;
                decimal notional = margin * LEVERAGE;
                var (kind, pctRaw) = Outcome(fullData[c.sym], c.barIdx);
                decimal pctNet = pctRaw - (decimal)(feeRate * 2m * 100m) - (slippagePct * 2m);
                decimal pnlUsd = notional * pctNet / 100m;
                totalPnl += pnlUsd;
                n++;
                if (kind == "TP") tpN++;
                else if (kind == "SL") slN++;
                else if (kind == "BE") beN++;
                else toN++;
                int endBar = Math.Min(c.barIdx + winBars / 2, fullData[c.sym].Count - 1);
                active.Add(fullData[c.sym][endBar].OpenTime);
                DateTime day = c.time.Date;
                byDay[day] = byDay.TryGetValue(day, out var v) ? v + pnlUsd : pnlUsd;
            }

            decimal cum = 0m, peak = 0m, mdd = 0m;
            foreach (var kv in byDay)
            {
                cum += kv.Value;
                if (cum > peak) peak = cum;
                decimal dd = peak - cum;
                if (dd > mdd) mdd = dd;
            }
            decimal mddPct = peak > 0 ? mdd / (seed + peak) * 100m : 0m;
            return (totalPnl, n, tpN, slN, beN, toN, mdd, mddPct);
        }

        Console.WriteLine();
        Console.WriteLine($"  마진 ${margin}/슬롯 × {maxSlots}슬롯 × {LEVERAGE:F0}x | TP+{tpPct}% / SL-{slPct}% / win{winBars}봉 / FVG lookback {fvgLookback}봉");
        Console.WriteLine();
        Console.WriteLine($"{"기간",-7} {"모드",-12} {"진입",6} {"TP",5} {"SL",5} {"BE",5} {"타임",5} {"PnL",10} {"ROI",10} {"MDD$",10} {"MDD%",8}");
        Console.WriteLine(new string('-', 110));
        int[] periods = { 30, 60, 90, 180 };
        foreach (int days in periods)
        {
            var rA = Eval(days, false);   // 가드 없음
            var rB = Eval(days, true);    // FVG 가드 ON
            decimal roiA = rA.pnl / seed * 100m;
            decimal roiB = rB.pnl / seed * 100m;
            Console.WriteLine($"{days,-7}일 {"baseline",-12} {rA.n,6} {rA.tpN,5} {rA.slN,5} {rA.beN,5} {rA.toN,5} {rA.pnl,9:F2} {roiA,9:F2}% {rA.mdd,9:F2} {rA.mddPct,7:F2}%");
            Console.WriteLine($"{days,-7}일 {"+FVG가드",-12} {rB.n,6} {rB.tpN,5} {rB.slN,5} {rB.beN,5} {rB.toN,5} {rB.pnl,9:F2} {roiB,9:F2}% {rB.mdd,9:F2} {rB.mddPct,7:F2}%");
            decimal deltaPct = (rB.pnl - rA.pnl);
            Console.WriteLine($"        {"Δ",-12} {rB.n - rA.n,+6} {"",5} {"",5} {"",5} {"",5} {deltaPct,+9:F2}");
            Console.WriteLine();
        }
        Console.WriteLine("[해석] FVG 가드가 PnL 개선 / 진입 감소 비율 확인 — 흑자 전환 시 라이브 적용 후보");
    }

    // [v5.22.51] 사용자 청정 로직 — "단순함이 복잡함을 이긴다"
    //   1. 스캐너:  최근 24h quoteVolume 상위 15개 종목만 (시점별 동적)
    //   2. 추세 가드: 15m EMA50 위에 있을 때만 LONG
    //   3. 진입:   5m vol[i] >= vol[i-1] × 1.5  AND  high[i] > 직전 5봉 고점
    //   4. 강제 퇴출: 6봉(30분) 내 수익 없으면 본절 탈출
    //   진짜 모델 (수수료 0.08% + 슬리피지 0.10% + 미체결 PnL + MDD)
    private static async Task RunCleanLogicAsync()
    {
        Console.WriteLine("================================================================");
        Console.WriteLine("  v5.22.51 청정 로직 — \"단순함이 복잡함을 이긴다\"");
        Console.WriteLine("  스캐너(top15 거래대금) → 15m EMA50 위 → 5m Vol×1.5 + 5봉고점돌파");
        Console.WriteLine("  → 30분 내 수익 없으면 본절 탈출");
        Console.WriteLine("================================================================");

        const decimal seed = 400m;
        const decimal margin = 100m;        // 슬롯당 마진
        const int maxSlots = 3;             // 동시 진입 3개
        const decimal tpPct = 2.0m;         // 익절 +2%
        const decimal slPct = 1.5m;         // 손절 -1.5%
        const int timeCutBars = 6;          // 30분 (5m × 6)
        const int maxHoldBars = 24;         // 2시간 강제 청산
        const int breakoutLook = 5;         // 직전 N봉 고점 돌파
        const decimal slippagePct = 0.05m;  // 0.05% × 2 = 0.10%
        const int fetchPages = 36;          // 180일

        var fullData = new Dictionary<string, List<IBinanceKline>>();
        Console.WriteLine($"\n[fetch 180일 — {symbols.Length}개 심볼]");
        int idx = 0;
        foreach (var sym in symbols)
        {
            idx++;
            Console.Write($"[{idx}/{symbols.Length}] {sym} ");
            try
            {
                var kl = await FetchKlinesAsync(sym, fetchPages);
                if (kl.Count < 400) { Console.WriteLine("skip"); continue; }
                fullData[sym] = kl;
                Console.WriteLine($"ok ({kl.Count} bars)");
            }
            catch (Exception ex) { Console.WriteLine("fail: " + ex.Message); }
        }

        // 15m EMA50 시리즈 사전 계산 — 5m 3개 → 15m 1개로 묶고 종가 EMA50
        // emaAt[symbol][5m_index] = 해당 시점 직전 완성된 15m 캔들의 EMA50 값
        var emaAt = new Dictionary<string, decimal[]>();
        var qVolAt = new Dictionary<string, decimal[]>();   // 24h 누적 거래대금 (288봉 합)
        foreach (var kv in fullData)
        {
            var kl = kv.Value;
            int n = kl.Count;
            var ema = new decimal[n];
            var qv = new decimal[n];

            // 15m 종가 시리즈 만들기 (3개씩 묶음)
            var closes15m = new List<decimal>(n / 3 + 1);
            var idx15m = new List<int>(n / 3 + 1);   // 해당 15m 캔들이 닫힌 5m 인덱스
            for (int i = 2; i < n; i += 3)
            {
                closes15m.Add(kl[i].ClosePrice);
                idx15m.Add(i);
            }
            // EMA50 (15m)
            var ema15 = new decimal[closes15m.Count];
            decimal kEma = 2m / (50m + 1m);
            decimal prev = closes15m.Count > 0 ? closes15m[0] : 0m;
            for (int j = 0; j < closes15m.Count; j++)
            {
                prev = closes15m[j] * kEma + prev * (1 - kEma);
                ema15[j] = prev;
            }
            // 각 5m 인덱스 i에 대해, i보다 같거나 이전에 닫힌 마지막 15m 의 ema 값 매핑
            int j15 = -1;
            for (int i = 0; i < n; i++)
            {
                while (j15 + 1 < idx15m.Count && idx15m[j15 + 1] <= i) j15++;
                ema[i] = j15 >= 0 ? ema15[j15] : 0m;
            }
            // 24h quoteVolume 슬라이딩 합 — quoteVolume 미존재 시 close*volume 으로 근사
            decimal sum = 0m;
            const int win24h = 288;
            for (int i = 0; i < n; i++)
            {
                decimal q = kl[i].QuoteVolume > 0 ? kl[i].QuoteVolume : kl[i].ClosePrice * kl[i].Volume;
                sum += q;
                if (i >= win24h)
                {
                    decimal qOld = kl[i - win24h].QuoteVolume > 0
                        ? kl[i - win24h].QuoteVolume
                        : kl[i - win24h].ClosePrice * kl[i - win24h].Volume;
                    sum -= qOld;
                }
                qv[i] = sum;
            }
            emaAt[kv.Key] = ema;
            qVolAt[kv.Key] = qv;
        }

        // 시점별 top-15 거래대금 — 매 5m 마다 다시 계산하면 느림. 1시간(12봉) 단위로 갱신.
        // 갱신 시점에 모든 심볼의 qVolAt[i] 기준으로 상위 15 추출.
        // 결과: barIdxBucket → HashSet<string>
        // 단순화: 각 심볼 캔들 시간을 기준으로 동기화하기 어려우므로 시간 기반 버킷 사용
        const int rescanBars = 12;   // 1시간마다 스캐너 갱신
        var symList = fullData.Keys.ToList();
        // 모든 심볼 공통 시간축 (UTC 5m 그리드) — 첫/마지막 시각 교집합
        DateTime tStart = fullData.Values.Max(v => v[0].OpenTime);
        DateTime tEnd = fullData.Values.Min(v => v[^1].OpenTime);
        // 심볼별 OpenTime → 인덱스 dict
        var timeIdx = new Dictionary<string, Dictionary<DateTime, int>>();
        foreach (var kv in fullData)
        {
            var d = new Dictionary<DateTime, int>(kv.Value.Count);
            for (int i = 0; i < kv.Value.Count; i++) d[kv.Value[i].OpenTime] = i;
            timeIdx[kv.Key] = d;
        }
        // top15 캐시: 갱신 시각 → 심볼 셋
        var topCache = new SortedDictionary<DateTime, HashSet<string>>();
        for (DateTime t = tStart; t <= tEnd; t = t.AddMinutes(5 * rescanBars))
        {
            var ranked = new List<(string sym, decimal qv)>();
            foreach (var s in symList)
            {
                if (!timeIdx[s].TryGetValue(t, out int i)) continue;
                ranked.Add((s, qVolAt[s][i]));
            }
            var top = ranked.OrderByDescending(r => r.qv).Take(15).Select(r => r.sym).ToHashSet();
            topCache[t] = top;
        }
        HashSet<string> TopAt(DateTime t)
        {
            // 가장 최근(이전) 갱신 시각의 캐시 반환
            DateTime k = t;
            // 5분 단위 + rescanBars 정렬
            int totalMin = (int)(t - tStart).TotalMinutes;
            int bucket = totalMin / (5 * rescanBars);
            DateTime kk = tStart.AddMinutes(bucket * 5 * rescanBars);
            return topCache.TryGetValue(kk, out var set) ? set : new HashSet<string>();
        }

        bool ShouldEnter(string sym, int i)
        {
            var kl = fullData[sym];
            if (i < breakoutLook + 1) return false;
            // 추세 가드: 15m EMA50 위
            if (emaAt[sym][i] <= 0m) return false;
            if (kl[i].ClosePrice <= emaAt[sym][i]) return false;
            // 거래량 폭증
            if (kl[i - 1].Volume <= 0m) return false;
            if (kl[i].Volume < kl[i - 1].Volume * 1.5m) return false;
            // 직전 5봉 고점 돌파
            decimal prevHigh = 0m;
            for (int j = i - breakoutLook; j <= i - 1; j++)
                if (kl[j].HighPrice > prevHigh) prevHigh = kl[j].HighPrice;
            if (kl[i].HighPrice <= prevHigh) return false;
            // 스캐너 가드
            if (!TopAt(kl[i].OpenTime).Contains(sym)) return false;
            return true;
        }

        // 결과: TP / SL / BE(본절) / TIMEOUT
        (string kind, decimal pctRaw, int holdBars) Outcome(List<IBinanceKline> kl, int i)
        {
            decimal entry = kl[i].ClosePrice;
            decimal tpPx = entry * (1 + tpPct / 100m);
            decimal slPx = entry * (1 - slPct / 100m);
            for (int k = 1; k <= maxHoldBars && i + k < kl.Count; k++)
            {
                var b = kl[i + k];
                // 30분 본절 탈출 — 도달 시 현재가 <= entry 면 즉시 종가로 탈출
                if (k == timeCutBars)
                {
                    if (b.ClosePrice <= entry)
                    {
                        decimal pct = (b.ClosePrice - entry) / entry * 100m;
                        return ("BE", pct, k);
                    }
                }
                if (b.HighPrice >= tpPx && b.LowPrice <= slPx) return ("SL", -slPct, k);
                if (b.HighPrice >= tpPx) return ("TP", tpPct, k);
                if (b.LowPrice <= slPx) return ("SL", -slPct, k);
            }
            int idxClose = Math.Min(i + maxHoldBars, kl.Count - 1);
            decimal pctTo = (kl[idxClose].ClosePrice - entry) / entry * 100m;
            return ("TIMEOUT", pctTo, maxHoldBars);
        }

        (decimal pnl, int n, int tpN, int slN, int beN, int toN, decimal mdd, decimal mddPct, decimal avgHold)
            Eval(int days)
        {
            DateTime since = DateTime.UtcNow.AddDays(-days);
            decimal feeRate = FEE_RATE;
            const int cooldownBars = 6;

            var candidates = new List<(DateTime time, string sym, int barIdx)>();
            foreach (var kv in fullData)
            {
                var kl = kv.Value; var sym = kv.Key;
                int lastFire = -1000;
                for (int i = 50; i < kl.Count - maxHoldBars; i++)
                {
                    if (kl[i].OpenTime < since) continue;
                    if (i - lastFire < cooldownBars) continue;
                    if (!ShouldEnter(sym, i)) continue;
                    candidates.Add((kl[i].OpenTime, sym, i));
                    lastFire = i;
                }
            }
            candidates.Sort((a, b) => a.time.CompareTo(b.time));

            var active = new List<DateTime>();
            decimal totalPnl = 0m;
            int n = 0, tpN = 0, slN = 0, beN = 0, toN = 0;
            int holdSum = 0;
            var byDay = new SortedDictionary<DateTime, decimal>();

            foreach (var c in candidates)
            {
                active.RemoveAll(t => t <= c.time);
                if (active.Count >= maxSlots) continue;
                decimal notional = margin * LEVERAGE;
                var (kind, pctRaw, hold) = Outcome(fullData[c.sym], c.barIdx);
                decimal pctNet = pctRaw - (decimal)(feeRate * 2m * 100m) - (slippagePct * 2m);
                decimal pnlUsd = notional * pctNet / 100m;
                totalPnl += pnlUsd;
                n++; holdSum += hold;
                if (kind == "TP") tpN++;
                else if (kind == "SL") slN++;
                else if (kind == "BE") beN++;
                else toN++;
                int endBar = Math.Min(c.barIdx + hold, fullData[c.sym].Count - 1);
                active.Add(fullData[c.sym][endBar].OpenTime);
                DateTime day = c.time.Date;
                byDay[day] = byDay.TryGetValue(day, out var v) ? v + pnlUsd : pnlUsd;
            }

            decimal cum = 0m, peak = 0m, mdd = 0m;
            foreach (var kv in byDay)
            {
                cum += kv.Value;
                if (cum > peak) peak = cum;
                decimal dd = peak - cum;
                if (dd > mdd) mdd = dd;
            }
            decimal mddPct = peak > 0 ? mdd / (seed + peak) * 100m : 0m;
            decimal avgHoldBars = n > 0 ? (decimal)holdSum / n : 0m;
            return (totalPnl, n, tpN, slN, beN, toN, mdd, mddPct, avgHoldBars);
        }

        Console.WriteLine();
        Console.WriteLine($"  마진 ${margin}/슬롯 × {maxSlots}슬롯 × {LEVERAGE:F0}x = max notional ${margin * maxSlots * LEVERAGE:F0}");
        Console.WriteLine($"  TP +{tpPct}% / SL -{slPct}% / 본절컷 {timeCutBars}봉(30분) / 강제청산 {maxHoldBars}봉(2h)");
        Console.WriteLine();
        Console.WriteLine($"{"기간",-7} {"진입",6} {"TP",5} {"SL",5} {"BE",5} {"타임",5} {"평균보유",10} {"PnL",10} {"ROI(시드$400)",16} {"MDD$",10} {"MDD%",8}");
        Console.WriteLine(new string('-', 110));
        int[] periods = { 1, 10, 30, 60, 90, 180 };
        foreach (int days in periods)
        {
            var r = Eval(days);
            decimal roi = r.pnl / seed * 100m;
            Console.WriteLine($"{days,-7}일 {r.n,6} {r.tpN,5} {r.slN,5} {r.beN,5} {r.toN,5} {r.avgHold,9:F1}봉 {r.pnl,9:F2} {roi,15:F2}% {r.mdd,9:F2} {r.mddPct,7:F2}%");
        }
        Console.WriteLine(new string('-', 110));
        Console.WriteLine();
        Console.WriteLine("[해석] TP=익절도달 / SL=손절도달 / BE=30분 본절컷 / 타임=2h 강제청산");
        Console.WriteLine("       수수료 0.08% + 슬리피지 0.10% = 라운드트립 0.18% 차감");
        Console.WriteLine("       스캐너 갱신 1시간(12봉) / 동시 진입 3슬롯 / 쿨다운 6봉");
    }

    // [v5.22.41] 사용자 실제 설정 시뮬 — 시드 $400, 마진 메이저 $150/슬롯 1, 알트 $100/슬롯 2
    //   슬롯 제한: 메이저 활성 1 초과 / 알트 활성 2 초과 시 진입 차단
    //   활성 = 진입 후 win 봉 (TP/SL 도달 시점) 동안 점유
    private static async Task RunLiveStatsV2Async()
    {
        Console.WriteLine("================================================================");
        Console.WriteLine("  v5.22.40 라이브 시뮬 — 시드 \\$400, 메이저 마진 \\$150/슬롯 1, 알트 \\$100/슬롯 2");
        Console.WriteLine("================================================================");

        const decimal seed = 400m;
        const decimal majorMargin = 150m;
        const decimal altMargin = 100m;
        const int majorSlot = 1;
        const int altSlot = 2;
        const int fetchPages = 36;

        var fullData = new Dictionary<string, List<IBinanceKline>>();
        Console.WriteLine($"\n[fetch 180일 — {symbols.Length}개 심볼]");
        int idx = 0;
        foreach (var sym in symbols)
        {
            idx++;
            Console.Write($"[{idx}/{symbols.Length}] {sym} ");
            try
            {
                var kl = await FetchKlinesAsync(sym, fetchPages);
                if (kl.Count < 400) { Console.WriteLine("skip"); continue; }
                fullData[sym] = kl;
                Console.WriteLine($"ok ({kl.Count} bars)");
            }
            catch (Exception ex) { Console.WriteLine("fail: " + ex.Message); }
        }

        var majors = new HashSet<string> { "BTCUSDT", "ETHUSDT", "SOLUSDT", "XRPUSDT", "BNBUSDT" };

        // 시간 정렬된 모든 진입 후보 한꺼번에 시뮬 (슬롯 제한 시뮬)
        (int n, int w, decimal pnl) Eval(int days)
        {
            DateTime since = DateTime.UtcNow.AddDays(-days);
            // 슬롯 추적 — Major/Alt 분리
            // 활성 슬롯 [심볼별 종료 시각 (kline 인덱스)]
            // 시뮬 흐름: 모든 (sym, i) 후보 시간순 → 슬롯 통과 → win 봉까지 점유
            const int cooldownBars = 6; // 30분
            decimal feeRate = FEE_RATE;

            // 모든 후보 모음 (timeIndex, sym, isMajor)
            var candidates = new List<(DateTime time, string sym, bool isMajor, int barIdx, decimal entryPrice, decimal high, decimal low)>();
            foreach (var kv in fullData)
            {
                var kl = kv.Value; var sym = kv.Key;
                bool isMajor = majors.Contains(sym);
                int win = isMajor ? 12 : 24;
                int lastFire = -1000;
                for (int i = 50; i < kl.Count - win; i++)
                {
                    if (kl[i].OpenTime < since) continue;
                    if (i - lastFire < cooldownBars) continue;
                    bool fire = isMajor
                        ? LiveMajorEvaluator.ShouldEnterLong(kl, i, kl[i].ClosePrice)
                        : LiveAltEvaluator.ShouldEnterLong(kl, i);
                    if (!fire) continue;
                    candidates.Add((kl[i].OpenTime, sym, isMajor, i, kl[i].ClosePrice, 0m, 0m));
                    lastFire = i;
                }
            }
            // 시간 정렬
            candidates.Sort((a, b) => a.time.CompareTo(b.time));

            // 슬롯 시뮬 — Major/Alt 별 활성 종료 시각 풀
            var majorActive = new List<DateTime>();  // 각 활성 포지션 종료 시각
            var altActive = new List<DateTime>();
            int totalN = 0, totalW = 0; decimal totalPnl = 0m;

            foreach (var c in candidates)
            {
                // 활성 슬롯 정리 (현재 시각 ≥ 종료시각인 거 제거)
                majorActive.RemoveAll(t => t <= c.time);
                altActive.RemoveAll(t => t <= c.time);

                bool slotOk = c.isMajor ? majorActive.Count < majorSlot : altActive.Count < altSlot;
                if (!slotOk) continue;

                // TP/SL 평가
                decimal tpPct = c.isMajor ? 0.5m : 1.0m;
                decimal slPct = c.isMajor ? 1.5m : 3.0m;
                int win = c.isMajor ? 12 : 24;
                decimal margin = c.isMajor ? majorMargin : altMargin;
                decimal lev = LEVERAGE;
                decimal notional = margin * lev;
                decimal trigFee = notional * feeRate * 2m;
                decimal tpUsd = notional * tpPct / 100m - trigFee;
                decimal slUsd = notional * slPct / 100m + trigFee;

                var kl = fullData[c.sym];
                var (tp, sl) = OutcomeIn(kl, c.barIdx, tpPct, slPct, win);
                if (!(tp || sl))
                {
                    // 미체결 — win 봉까지 점유 후 청산 (PnL 0)
                    DateTime closeT = kl[Math.Min(c.barIdx + win, kl.Count - 1)].OpenTime;
                    if (c.isMajor) majorActive.Add(closeT); else altActive.Add(closeT);
                    continue;
                }

                totalN++;
                if (tp) { totalW++; totalPnl += tpUsd; } else { totalPnl -= slUsd; }
                // 종료 시각 = TP/SL 도달 봉 — 단순화: c.barIdx + win/2 (평균 절반)
                int endBar = Math.Min(c.barIdx + win / 2, kl.Count - 1);
                DateTime endTime = kl[endBar].OpenTime;
                if (c.isMajor) majorActive.Add(endTime); else altActive.Add(endTime);
            }
            return (totalN, totalW, totalPnl);
        }

        // 메이저 / 알트 분리 통계는 슬롯 시뮬과 별개 — 독립 평가도 추가로
        (int n, int w, decimal pnl) EvalCategory(int days, bool majorMode)
        {
            int totalN = 0, totalW = 0; decimal totalPnl = 0m;
            DateTime since = DateTime.UtcNow.AddDays(-days);
            const int cooldownBars = 6;
            decimal margin = majorMode ? majorMargin : altMargin;
